window.addEventListener("error", (event) => {
  try {
    const err = event?.error;
    const message =
      err && err.stack
        ? err.stack
        : String(event?.message || "Unknown renderer error");
    console.error("Global renderer error:", message);
  } catch {}
});
window.addEventListener("unhandledrejection", (event) => {
  try {
    const reason = event?.reason;
    const message =
      reason && reason.stack
        ? reason.stack
        : String(reason || "Unknown promise rejection");
    console.error("Unhandled promise rejection:", message);
  } catch {}
});

/* Local note: version 01.02.08 was the last version to include online features. */
/* =========================================================
       Core model
       ========================================================= */

const imgRE = /\.(jpe?g|png|gif|webp|tiff|bmp|avif)$/i;
const vidRE = /\.(mp4|m4v|mov|wmv|flv|avi|webm|mkv)$/i;
const indexPrefixRE = /^(\d+)\s-\s/;

const FAVORITE_TAG = "__favorite__";
const HIDDEN_TAG = "__hidden__";
const LEGACY_PROCESSING_DISABLED_TAG = "__processing_disabled__";
const FOLDER_THUMB_NONE_SENTINEL = "__thumb_none__";
const FOLDER_THUMB_ROTATE_SENTINEL = "__thumb_rotate__";
const INTERNAL_TRASH_DIR_NAME = "__LOCAL_GALLERY_TRASH__";
const TRASH_UI_LABEL = "Trash";
// Legacy thumbnail style switch. "aspect" mode remains in code for future reactivation,
// but the app currently runs cropped thumbnails only.
const ENABLE_ASPECT_RATIO_THUMBNAIL_STYLE = false;
// Keep quad thumbnail logic in code, but force it off in the shipped UI/runtime path.
const ENABLE_QUAD_THUMBNAILS = false;
const GRID_CROPPED_COLS_BY_SCALE = Object.freeze({
  small: 7,
  medium: 6,
  large: 5,
  xl: 4,
  xxl: 3,
  xxxl: 2,
});

function isInternalTrashDirName(name) {
  return String(name || "") === INTERNAL_TRASH_DIR_NAME;
}

function isInternalTrashPath(path) {
  return String(path || "") === INTERNAL_TRASH_DIR_NAME;
}

function isPathInsideInternalTrash(path) {
  const normalized = String(path || "");
  return (
    normalized === INTERNAL_TRASH_DIR_NAME ||
    normalized.startsWith(INTERNAL_TRASH_DIR_NAME + "/")
  );
}

function isInternalTrashDirNode(node) {
  return !!node && isInternalTrashPath(node.path || node.name || "");
}

function isDirectChildOfInternalTrash(path) {
  const normalized = String(path || "");
  if (!normalized.startsWith(INTERNAL_TRASH_DIR_NAME + "/")) return false;
  return normalized.slice(INTERNAL_TRASH_DIR_NAME.length + 1).split("/").length === 1;
}

function displayFolderSegmentName(name) {
  return isInternalTrashDirName(name) ? TRASH_UI_LABEL : displayName(name);
}
function isImageName(name) {
  return imgRE.test((name || "").toLowerCase());
}
function isVideoName(name) {
  return vidRE.test((name || "").toLowerCase());
}

function fileKey(file, relPathOverride) {
  const rp = relPathOverride || file.webkitRelativePath || "";
  return file.name + "::" + file.lastModified + "::" + file.size + "::" + rp;
}

function fileKeyForRecord(rec, relPathOverride) {
  const relPath = String(
    relPathOverride != null ? relPathOverride : rec?.relPath || "",
  );
  const name = String(rec?.name || rec?.file?.name || "");
  const lastModified = Number.isFinite(Number(rec?.lastModified))
    ? Number(rec.lastModified)
    : Number(rec?.file?.lastModified || 0);
  const size = Number.isFinite(Number(rec?.size))
    ? Number(rec.size)
    : Number(rec?.file?.size || 0);
  return `${name}::${lastModified}::${size}::${relPath}`;
}

function splitIndexPrefix(name) {
  const s = String(name || "");
  const m = s.match(indexPrefixRE);
  if (!m) return { idx: null, clean: s };
  return { idx: parseInt(m[1], 10), clean: s.slice(m[0].length) };
}

function displayName(name) {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return applyDisplayNameRules(name, opt, { isFile: false });
}

function displayTagFolderLabel(name) {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  let out = String(name || "");
  if (opt && opt.forceTitleCaps) out = toTitleCaps(out);
  return out;
}

function splitNameExt(name) {
  const raw = String(name || "");
  const i = raw.lastIndexOf(".");
  if (i <= 0) return { base: raw, ext: "" };
  return { base: raw.slice(0, i), ext: raw.slice(i) };
}

function toTitleCaps(str) {
  return String(str || "").replace(/\w\S*/g, (txt) => {
    return txt.charAt(0).toUpperCase() + txt.slice(1).toLowerCase();
  });
}

function applyDisplayNameRules(name, opt, ctx = null) {
  let out = String(name || "");
  const isFile = !!(ctx && ctx.isFile);
  if (opt && opt.hideBeforeLastDashInFileNames) {
    const idx = out.lastIndexOf(" - ");
    if (idx >= 0) out = out.slice(idx + 3);
  }
  if (isFile && opt && opt.hideUnderscoresInFileNames) {
    out = out.replace(/_/g, " ");
  }
  if (isFile && opt && opt.hideAfterFirstUnderscoreInFileNames) {
    const idx = out.indexOf("_");
    if (idx >= 0) out = out.slice(0, idx);
  }
  if (opt && opt.forceTitleCaps) out = toTitleCaps(out);
  return out;
}

function compareIndexedNames(a, b) {
  const A = splitIndexPrefix(a);
  const B = splitIndexPrefix(b);
  const ai = A.idx === null || !Number.isFinite(A.idx) ? Infinity : A.idx;
  const bi = B.idx === null || !Number.isFinite(B.idx) ? Infinity : B.idx;
  if (ai !== bi) return ai - bi;
  const ac = (A.clean || "").toLowerCase();
  const bc = (B.clean || "").toLowerCase();
  const c = ac.localeCompare(bc);
  if (c) return c;
  return String(a || "").localeCompare(String(b || ""));
}

function displayPath(path) {
  const p = String(path || "");
  try {
    if (typeof WS !== "undefined" && WS.dirByPath && WS.dirByPath.has(p)) {
      const node = WS.dirByPath.get(p);
      if (node) {
        const parts = [];
        let cur = node;
        while (cur) {
          parts.push(dirDisplayName(cur));
          cur = cur.parent;
        }
        parts.reverse();
        return parts.join("/") || "";
      }
    }
  } catch {}
  const parts = p.split("/").filter(Boolean);
  const out = parts.map((seg) => displayFolderSegmentName(seg));
  return out.join("/") || "";
}

function displayRelPath(relPath) {
  const parts = String(relPath || "")
    .split("/")
    .filter(Boolean);
  const out = parts.map((seg) => displayFolderSegmentName(seg));
  return out.join("/") || "";
}

function normalizeFolderNameInput(name) {
  return String(name || "").trim();
}

function isValidFolderName(name) {
  if (!name) return false;
  if (name === "." || name === "..") return false;
  if (/[\/\\]/.test(name)) return false;
  return true;
}

function isValidFileName(name) {
  if (!name) return false;
  if (name === "." || name === "..") return false;
  if (/[\/\\]/.test(name)) return false;
  return true;
}

function remapPathPrefix(oldPrefix, newPrefix, path) {
  const p = String(path || "");
  if (!oldPrefix) return p;
  if (p === oldPrefix) return newPrefix;
  if (p.startsWith(oldPrefix + "/"))
    return newPrefix + p.slice(oldPrefix.length);
  return p;
}

function remapPathSet(src, oldPrefix, newPrefix) {
  const next = new Set();
  for (const p of src || []) next.add(remapPathPrefix(oldPrefix, newPrefix, p));
  return next;
}

function remapPathMapKeys(src, oldPrefix, newPrefix) {
  const next = new Map();
  for (const [key, value] of src || []) {
    next.set(remapPathPrefix(oldPrefix, newPrefix, key), value);
  }
  return next;
}

function remapPathMapValues(src, oldPrefix, newPrefix) {
  const next = new Map();
  for (const [key, value] of src || []) {
    next.set(key, remapPathPrefix(oldPrefix, newPrefix, value));
  }
  return next;
}

function makeDirNode(name, parent) {
  return {
    type: "dir",
    name,
    parent,
    childrenDirs: [],
    childrenFiles: [],
    lastIndex: 0,
    path: "",
  };
}

/* =========================================================
       Local-only mode
       ========================================================= */

function dirDisplayName(node) {
  return displayFolderSegmentName(node?.name || "folder") || "folder";
}

function fileDisplayNameForRecord(rec) {
  return fileDisplayName(rec?.name || "file") || "file";
}

function clampNumber(value, min, max, fallback) {
  const n = typeof value === "number" ? value : parseFloat(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}

function normalizeAnimatedMediaFiltersValue(value, fallback = "on") {
  if (value === true) return "on";
  if (value === false) return "off";
  const raw = String(value == null ? "" : value)
    .trim()
    .toLowerCase();
  if (raw === "on" || raw === "off") return raw;
  if (
    raw === "videos" ||
    raw === "video" ||
    raw === "video-only" ||
    raw === "videos-only" ||
    raw === "video_only" ||
    raw === "videos_only"
  ) {
    return "videos";
  }
  return fallback;
}

function normalizeFolderBehavior(value, fallback = "slide") {
  const raw = String(value == null ? "" : value)
    .trim()
    .toLowerCase();
  if (raw === "slide" || raw === "stop") return raw;
  // Legacy "loop" mode is retired for item navigation; map to slide.
  if (raw === "loop") return "slide";
  return fallback;
}

function normalizeColorSchemeValue(value, fallback = "retro") {
  const raw = String(value == null ? "" : value)
    .trim()
    .toLowerCase();
  if (
    raw === "retro" ||
    raw === "ibn" ||
    raw === "retro90s" ||
    raw === "retro90s-dark"
  )
    return "retro";
  return "retro";
}

function normalizeThumbRenderModeValue(value, fallback = "medium") {
  const raw = String(value == null ? "" : value)
    .trim()
    .toLowerCase();
  if (
    raw === "small" ||
    raw === "medium" ||
    raw === "high" ||
    raw === "native" ||
    raw === "placeholder"
  )
    return raw;
  return fallback;
}

function normalizeDisplaySizeValue(value, fallback = "medium") {
  const raw = String(value == null ? "" : value)
    .trim()
    .toLowerCase();
  if (raw === "small" || raw === "medium" || raw === "large") return raw;
  return fallback;
}

function normalizeThumbnailScaleValue(value, fallback = "medium") {
  const raw = String(value == null ? "" : value)
    .trim()
    .toLowerCase();
  if (
    raw === "small" ||
    raw === "medium" ||
    raw === "large" ||
    raw === "xl" ||
    raw === "xxl" ||
    raw === "xxxl"
  )
    return raw;
  return fallback;
}

function thumbnailVisibilityKindSpecs() {
  return [
    {
      kind: "file",
      label: "File thumbnails",
      directoriesLabel: "File cards in list pane",
      previewPrefix: "previewFileThumbnail",
      directoriesPrefix: "directoriesFileCard",
      legacyTitleKey: "showFileThumbnailTitles",
      legacyMenuHiddenKey: "hideFileThumbnailMenuButton",
    },
    {
      kind: "rootFolder",
      label: "Root folder thumbnails",
      directoriesLabel: "Root folder cards in list pane",
      previewPrefix: "previewRootFolderThumbnail",
      directoriesPrefix: "directoriesRootFolderCard",
      legacyTitleKey: "showRootFolderThumbnailTitles",
      legacyMenuHiddenKey: "hideRootFolderThumbnailMenuButton",
    },
    {
      kind: "subfolder",
      label: "Subfolder thumbnails",
      directoriesLabel: "Subfolder cards in list pane",
      previewPrefix: "previewSubfolderThumbnail",
      directoriesPrefix: "directoriesSubfolderCard",
      legacyTitleKey: "showSubfolderThumbnailTitles",
      legacyMenuHiddenKey: "hideSubfolderThumbnailMenuButton",
    },
    {
      kind: "tag",
      label: "Tag thumbnails",
      directoriesLabel: "Tag cards in list pane",
      previewPrefix: "previewTagThumbnail",
      directoriesPrefix: "directoriesTagCard",
      legacyTitleKey: "showTagThumbnailTitles",
      legacyMenuHiddenKey: "hideTagAndRootFolderThumbnailMenuButton",
    },
  ];
}

function thumbnailVisibilityKindSpec(kind) {
  const target = String(kind || "");
  const specs = thumbnailVisibilityKindSpecs();
  for (let i = 0; i < specs.length; i++) {
    if (specs[i].kind === target) return specs[i];
  }
  return specs[0];
}

function thumbnailVisibilitySupportedFields(surface, kind) {
  const targetSurface = surface === "directories" ? "directories" : "preview";
  const targetKind = thumbnailVisibilityKindSpec(kind).kind;
  const support = {
    preview: {
      file: ["size", "score", "title", "menuButton", "itemType"],
      rootFolder: ["itemCount", "size", "score", "title", "menuButton"],
      subfolder: ["itemCount", "size", "score", "title", "menuButton"],
      tag: ["itemCount", "title", "menuButton"],
    },
    directories: {
      file: ["size", "score", "itemType"],
      rootFolder: ["itemCount", "size", "score"],
      subfolder: ["itemCount", "size", "score"],
      tag: ["itemCount"],
    },
  };
  return Array.isArray(support[targetSurface]?.[targetKind])
    ? support[targetSurface][targetKind].slice()
    : [];
}

function thumbnailVisibilityFieldSupported(surface, kind, field) {
  return thumbnailVisibilitySupportedFields(surface, kind).includes(
    String(field || ""),
  );
}

function thumbnailVisibilityFieldSuffix(field) {
  if (field === "itemCount") return "ShowItemCount";
  if (field === "size") return "ShowSize";
  if (field === "score") return "ShowScore";
  if (field === "title") return "ShowTitle";
  if (field === "menuButton") return "ShowMenuButton";
  if (field === "itemType") return "ShowItemType";
  return "";
}

function thumbnailVisibilityPreviewOptionKey(kind, field) {
  if (!thumbnailVisibilityFieldSupported("preview", kind, field)) return "";
  const spec = thumbnailVisibilityKindSpec(kind);
  const suffix = thumbnailVisibilityFieldSuffix(field);
  return suffix ? `${spec.previewPrefix}${suffix}` : "";
}

function thumbnailVisibilityDirectoriesOptionKey(kind, field) {
  if (!thumbnailVisibilityFieldSupported("directories", kind, field)) return "";
  if (field === "title" || field === "menuButton") return "";
  const spec = thumbnailVisibilityKindSpec(kind);
  const suffix = thumbnailVisibilityFieldSuffix(field);
  return suffix ? `${spec.directoriesPrefix}${suffix}` : "";
}

function thumbnailVisibilityOptionKeys() {
  const out = [];
  const specs = thumbnailVisibilityKindSpecs();
  const previewFields = [
    "itemCount",
    "size",
    "score",
    "title",
    "menuButton",
    "itemType",
  ];
  const directoriesFields = ["itemCount", "size", "score", "itemType"];
  for (let i = 0; i < specs.length; i++) {
    const spec = specs[i];
    for (let j = 0; j < previewFields.length; j++) {
      out.push(
        thumbnailVisibilityPreviewOptionKey(spec.kind, previewFields[j]),
      );
    }
    for (let j = 0; j < directoriesFields.length; j++) {
      out.push(
        thumbnailVisibilityDirectoriesOptionKey(
          spec.kind,
          directoriesFields[j],
        ),
      );
    }
  }
  return out.filter(Boolean);
}

function thumbnailVisibilityInputId(optionKey) {
  return optionKey ? `opt_${String(optionKey)}` : "";
}

function buildDefaultThumbnailVisibilityOptions() {
  const out = {};
  const setPreview = (kind, field, value) => {
    const key = thumbnailVisibilityPreviewOptionKey(kind, field);
    if (key) out[key] = !!value;
  };
  const setDirectories = (kind, field, value) => {
    const key = thumbnailVisibilityDirectoriesOptionKey(kind, field);
    if (key) out[key] = !!value;
  };
  const specs = thumbnailVisibilityKindSpecs();
  const previewFields = [
    "itemCount",
    "size",
    "score",
    "title",
    "menuButton",
    "itemType",
  ];
  const directoriesFields = ["itemCount", "size", "score", "itemType"];
  for (let i = 0; i < specs.length; i++) {
    const spec = specs[i];
    for (let j = 0; j < previewFields.length; j++) {
      out[thumbnailVisibilityPreviewOptionKey(spec.kind, previewFields[j])] =
        true;
    }
    for (let j = 0; j < directoriesFields.length; j++) {
      out[
        thumbnailVisibilityDirectoriesOptionKey(spec.kind, directoriesFields[j])
      ] = true;
    }
  }

  // Baseline defaults aligned to workspace thumbnail preference defaults.
  setPreview("file", "size", false);
  setPreview("file", "score", false);
  setPreview("file", "title", false);
  setPreview("file", "menuButton", false);
  setPreview("file", "itemType", true);
  setDirectories("file", "size", false);
  setDirectories("file", "score", true);
  setDirectories("file", "itemType", false);

  setPreview("rootFolder", "itemCount", false);
  setPreview("rootFolder", "size", true);
  setPreview("rootFolder", "score", false);
  setPreview("rootFolder", "title", true);
  setPreview("rootFolder", "menuButton", true);
  setDirectories("rootFolder", "itemCount", false);
  setDirectories("rootFolder", "size", false);
  setDirectories("rootFolder", "score", true);

  setPreview("subfolder", "itemCount", false);
  setPreview("subfolder", "size", false);
  setPreview("subfolder", "score", false);
  setPreview("subfolder", "title", true);
  setPreview("subfolder", "menuButton", false);
  setDirectories("subfolder", "itemCount", false);
  setDirectories("subfolder", "size", false);
  setDirectories("subfolder", "score", true);

  setPreview("tag", "itemCount", true);
  setPreview("tag", "title", true);
  setPreview("tag", "menuButton", false);
  setDirectories("tag", "itemCount", true);

  return out;
}

function normalizeThumbnailVisibilityOptions(src, fallbacks) {
  const source = src && typeof src === "object" ? src : {};
  const fallbackState =
    fallbacks && typeof fallbacks === "object" ? fallbacks : {};
  const previewTitleFallbacks = fallbackState.previewTitles || {};
  const previewMenuFallbacks = fallbackState.previewMenuButtons || {};
  const out = {};
  const specs = thumbnailVisibilityKindSpecs();
  const previewFields = [
    "itemCount",
    "size",
    "score",
    "title",
    "menuButton",
    "itemType",
  ];
  const directoriesFields = ["itemCount", "size", "score", "itemType"];

  const genericFallbackForField = (field) => {
    if (field === "itemCount") return !!fallbackState.itemCount;
    if (field === "size") return !!fallbackState.size;
    if (field === "score") return !!fallbackState.score;
    if (field === "itemType") return !!fallbackState.itemType;
    return true;
  };

  for (let i = 0; i < specs.length; i++) {
    const spec = specs[i];
    for (let j = 0; j < previewFields.length; j++) {
      const field = previewFields[j];
      const key = thumbnailVisibilityPreviewOptionKey(spec.kind, field);
      if (!key) continue;
      if (typeof source[key] === "boolean") {
        out[key] = source[key];
        continue;
      }
      if (field === "title") {
        out[key] = !(previewTitleFallbacks[spec.kind] === false);
        continue;
      }
      if (field === "menuButton") {
        out[key] = !(previewMenuFallbacks[spec.kind] === false);
        continue;
      }
      out[key] = genericFallbackForField(field);
    }
    for (let j = 0; j < directoriesFields.length; j++) {
      const field = directoriesFields[j];
      const key = thumbnailVisibilityDirectoriesOptionKey(spec.kind, field);
      if (!key) continue;
      out[key] =
        typeof source[key] === "boolean"
          ? source[key]
          : genericFallbackForField(field);
    }
  }
  return out;
}

