const META_PREFERENCE_DOC_BY_OPTION_KEY = (() => {
  const out = new Map();
  const pairs = [
    [
      META_DOC_IDS.prefNotifications,
      META_PREFERENCE_SECTION_OPTION_KEYS.notifications,
    ],
    [
      META_DOC_IDS.prefAppearance,
      META_PREFERENCE_SECTION_OPTION_KEYS.appearance,
    ],
    [META_DOC_IDS.prefPlayback, META_PREFERENCE_SECTION_OPTION_KEYS.playback],
    [
      META_DOC_IDS.prefThumbnails,
      META_PREFERENCE_SECTION_OPTION_KEYS.thumbnails,
    ],
    [META_DOC_IDS.prefFilenames, META_PREFERENCE_SECTION_OPTION_KEYS.filenames],
    [META_DOC_IDS.prefControls, META_PREFERENCE_SECTION_OPTION_KEYS.controls],
  ];
  for (let i = 0; i < pairs.length; i++) {
    const [docId, keys] = pairs[i];
    for (let j = 0; j < keys.length; j++) out.set(String(keys[j] || ""), docId);
  }
  return out;
})();

const META_GENERAL_PREFERENCE_OPTION_KEYS = Object.freeze(
  Object.keys(normalizeOptions(defaultOptions())).filter(
    (key) => !META_PREFERENCE_DOC_BY_OPTION_KEY.has(String(key || "")),
  ),
);

function metaPreferenceDocIdForOptionKey(key) {
  const normalizedKey = String(key || "");
  return (
    META_PREFERENCE_DOC_BY_OPTION_KEY.get(normalizedKey) ||
    META_DOC_IDS.prefGeneral
  );
}

function metaPreferenceDocIdsForOptionKeys(keys) {
  const out = new Set();
  const list = Array.isArray(keys) ? keys : Array.from(keys || []);
  for (let i = 0; i < list.length; i++) {
    out.add(metaPreferenceDocIdForOptionKey(list[i]));
  }
  return Array.from(out);
}

function normalizeAppearancePresetIdValue(value) {
  return String(value || "").trim() || "";
}

function normalizeAppearancePresetName(name, fallback = "Preset") {
  const text = String(name || "")
    .replace(/\s+/g, " ")
    .trim();
  return text || fallback;
}

function normalizeAppearancePresetValues(values) {
  const normalized = normalizeOptions(Object.assign({}, values || {}));
  const out = {};
  for (let i = 0; i < APPEARANCE_SLIDER_OPTION_KEYS.length; i++) {
    const key = APPEARANCE_SLIDER_OPTION_KEYS[i];
    out[key] = normalized[key] == null ? null : normalized[key];
  }
  return out;
}

function cloneAppearancePreset(preset) {
  const src = preset && typeof preset === "object" ? preset : {};
  return {
    id: normalizeAppearancePresetIdValue(src.id),
    name: normalizeAppearancePresetName(src.name),
    locked: !!src.locked,
    values: normalizeAppearancePresetValues(src.values || {}),
  };
}

function defaultAppearancePresets() {
  return DEFAULT_APPEARANCE_PRESETS.map((preset) =>
    cloneAppearancePreset(preset),
  );
}

function normalizeAppearancePresetList(rawList, useDefaultsIfMissing = true) {
  const source = Array.isArray(rawList)
    ? rawList
    : useDefaultsIfMissing
      ? defaultAppearancePresets()
      : [];
  const out = [];
  const seenIds = new Set();
  const seenNames = new Set();
  const pushPreset = (preset, fallbackName = "Preset") => {
    const cloned = cloneAppearancePreset(preset);
    let id = normalizeAppearancePresetIdValue(cloned.id);
    if (!id)
      id = `preset-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
    if (seenIds.has(id)) return;
    let name = normalizeAppearancePresetName(cloned.name, fallbackName);
    let suffix = 2;
    let uniqueName = name;
    while (seenNames.has(uniqueName.toLowerCase())) {
      uniqueName = `${name} ${suffix++}`;
    }
    cloned.id = id;
    cloned.name = uniqueName;
    seenIds.add(id);
    seenNames.add(uniqueName.toLowerCase());
    out.push(cloned);
  };
  let sawDefault = false;
  for (let i = 0; i < source.length; i++) {
    const preset = source[i];
    const id = normalizeAppearancePresetIdValue(preset && preset.id);
    if (id === BUILTIN_NULL_APPEARANCE_PRESET_ID) {
      sawDefault = true;
      pushPreset(
        Object.assign({}, preset, {
          id: BUILTIN_NULL_APPEARANCE_PRESET_ID,
          name: "Default",
          locked: true,
        }),
      );
      continue;
    }
    if (id.startsWith("builtin-")) {
      continue;
    }
    pushPreset(preset, `Preset ${out.length + 1}`);
  }
  if (!sawDefault) {
    pushPreset(DEFAULT_APPEARANCE_PRESETS[0], "Default");
  }
  out.sort((a, b) => {
    if (a.id === BUILTIN_NULL_APPEARANCE_PRESET_ID) return -1;
    if (b.id === BUILTIN_NULL_APPEARANCE_PRESET_ID) return 1;
    return String(a.name || "").localeCompare(String(b.name || ""), undefined, {
      sensitivity: "base",
    });
  });
  return out;
}

function currentAppearanceValuesFromOptions(opt = null) {
  const source = opt || (WS.meta && WS.meta.options ? WS.meta.options : null);
  const out = {};
  const normalized = source ? normalizeOptions(source) : normalizeOptions(null);
  for (let i = 0; i < APPEARANCE_SLIDER_OPTION_KEYS.length; i++) {
    const key = APPEARANCE_SLIDER_OPTION_KEYS[i];
    out[key] = normalized[key] == null ? null : normalized[key];
  }
  return out;
}

function appearanceValuesEqual(a, b) {
  for (let i = 0; i < APPEARANCE_SLIDER_OPTION_KEYS.length; i++) {
    const key = APPEARANCE_SLIDER_OPTION_KEYS[i];
    const av =
      a && Object.prototype.hasOwnProperty.call(a, key) ? a[key] : null;
    const bv =
      b && Object.prototype.hasOwnProperty.call(b, key) ? b[key] : null;
    if (av == null && bv == null) continue;
    if (Number(av) !== Number(bv)) return false;
  }
  return true;
}

function getAppearancePresetById(id) {
  const presetId = normalizeAppearancePresetIdValue(id);
  if (!presetId || !WS.meta || !Array.isArray(WS.meta.appearancePresets))
    return null;
  for (let i = 0; i < WS.meta.appearancePresets.length; i++) {
    const preset = WS.meta.appearancePresets[i];
    if (normalizeAppearancePresetIdValue(preset && preset.id) === presetId)
      return preset;
  }
  return null;
}

function findAppearancePresetByName(name) {
  const normalizedName = normalizeAppearancePresetName(name, "").toLowerCase();
  if (!normalizedName || !WS.meta || !Array.isArray(WS.meta.appearancePresets))
    return null;
  for (let i = 0; i < WS.meta.appearancePresets.length; i++) {
    const preset = WS.meta.appearancePresets[i];
    if (
      normalizeAppearancePresetName(preset && preset.name, "").toLowerCase() ===
      normalizedName
    )
      return preset;
  }
  return null;
}

function effectiveActiveAppearancePresetId() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  const raw = normalizeAppearancePresetIdValue(
    opt && opt.activeAppearancePresetId,
  );
  if (!raw) return "";
  return getAppearancePresetById(raw) ? raw : "";
}

function buildOptionsWithAppearanceValues(
  values,
  activePresetId = null,
  baseOptions = null,
) {
  const base = Object.assign(
    {},
    baseOptions || (WS.meta && WS.meta.options ? WS.meta.options : {}),
  );
  const next = {};
  for (let i = 0; i < APPEARANCE_SLIDER_OPTION_KEYS.length; i++) {
    const key = APPEARANCE_SLIDER_OPTION_KEYS[i];
    next[key] =
      values && Object.prototype.hasOwnProperty.call(values, key)
        ? values[key]
        : null;
  }
  next.activeAppearancePresetId =
    normalizeAppearancePresetIdValue(activePresetId) || null;
  return normalizeOptions(Object.assign(base, next));
}

function syncActiveAppearancePresetSelection(options = null) {
  if (!WS.meta) return "";
  const opt = options || WS.meta.options || normalizeOptions(null);
  const values = currentAppearanceValuesFromOptions(opt);
  let nextId = "";
  const presets = Array.isArray(WS.meta.appearancePresets)
    ? WS.meta.appearancePresets
    : [];
  for (let i = 0; i < presets.length; i++) {
    const preset = presets[i];
    if (!preset || !preset.values) continue;
    if (appearanceValuesEqual(values, preset.values)) {
      nextId = normalizeAppearancePresetIdValue(preset.id);
      break;
    }
  }
  const currentId = normalizeAppearancePresetIdValue(
    opt.activeAppearancePresetId,
  );
  if (currentId === nextId) return nextId;
  opt.activeAppearancePresetId = nextId || null;
  return nextId;
}

function currentAppearanceBucket(options = null) {
  const rawActiveId = normalizeAppearancePresetIdValue(
    (options || (WS.meta && WS.meta.options) || {}).activeAppearancePresetId,
  );
  const activeId = getAppearancePresetById(rawActiveId) ? rawActiveId : "";
  if (activeId === BUILTIN_NULL_APPEARANCE_PRESET_ID) return "default";
  if (activeId) return "saved";
  return "editing";
}

function currentAppearanceEditingTargetId() {
  const activeId = effectiveActiveAppearancePresetId();
  if (activeId) return activeId;
  const raw = normalizeAppearancePresetIdValue(
    WS.view && WS.view.appearancePresetEditingId,
  );
  if (raw && getAppearancePresetById(raw)) return raw;
  return BUILTIN_NULL_APPEARANCE_PRESET_ID;
}

function createAppearancePresetId() {
  return `preset-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function appearancePresetDisplayName(id, fallback = "Custom") {
  const preset = getAppearancePresetById(id);
  return preset ? String(preset.name || "") : fallback;
}

function currentAppearanceStatusLabel(options = null) {
  const bucket = currentAppearanceBucket(options);
  const activeId = effectiveActiveAppearancePresetId();
  if (bucket !== "editing")
    return appearancePresetDisplayName(activeId, "Default");
  const editingId = currentAppearanceEditingTargetId();
  return `${appearancePresetDisplayName(editingId, "Default")} (unsaved changes)`;
}

function buildAppearancePresetChoiceMenu(menuEl, options = {}) {
  if (!menuEl) return;
  const currentPresetId = normalizeAppearancePresetIdValue(
    options.currentPresetId,
  );
  const presets = Array.isArray(
    WS.meta && WS.meta.appearancePresets ? WS.meta.appearancePresets : null,
  )
    ? WS.meta.appearancePresets
    : defaultAppearancePresets();
  menuEl.innerHTML = "";
  const appendButton = (label, onClick, disabled = false) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.textContent = String(label || "");
    btn.disabled = !!disabled;
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      if (btn.disabled) return;
      if (typeof onClick === "function") onClick();
    });
    menuEl.appendChild(btn);
    return btn;
  };
  if (typeof options.onBack === "function") {
    appendButton("Back", options.onBack);
  }
  for (let i = 0; i < presets.length; i++) {
    const preset = presets[i];
    const presetId = normalizeAppearancePresetIdValue(preset && preset.id);
    if (!presetId) continue;
    const label =
      presetId === currentPresetId
        ? `Current: ${String(preset.name || "Preset")}`
        : String(preset.name || "Preset");
    appendButton(label, () => {
      if (typeof options.onChoosePreset === "function")
        options.onChoosePreset(presetId);
    });
  }
  if (typeof options.onRendered === "function") {
    requestAnimationFrame(() => options.onRendered());
  }
}

const GIF_EXPORT_MODE_BY_ASPECT_RATIO = "by-aspect-ratio";
const GIF_EXPORT_MODE_ALL_IN_ONE = "all-in-one";
const GIF_EXPORT_ORDER_SORT = "sort";
const GIF_EXPORT_ORDER_ASPECT_RATIO = "aspect-ratio";
const GIF_EXPORT_FRAME_DELAY_OPTIONS_CS = [1, 2, 4, 8, 12, 16, 20, 24];
const GIF_EXPORT_DEFAULT_FRAME_DELAY_CS = 12;

function appendChoiceMenuButton(menuEl, label, onClick, disabled = false) {
  if (!menuEl) return null;
  const btn = document.createElement("button");
  btn.type = "button";
  btn.textContent = String(label || "");
  btn.disabled = !!disabled;
  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    if (btn.disabled) return;
    if (typeof onClick === "function") onClick();
  });
  menuEl.appendChild(btn);
  return btn;
}

function normalizeGifExportMode(value) {
  return String(value || "") === GIF_EXPORT_MODE_ALL_IN_ONE
    ? GIF_EXPORT_MODE_ALL_IN_ONE
    : GIF_EXPORT_MODE_BY_ASPECT_RATIO;
}

function normalizeGifExportOrder(value) {
  return String(value || "") === GIF_EXPORT_ORDER_ASPECT_RATIO
    ? GIF_EXPORT_ORDER_ASPECT_RATIO
    : GIF_EXPORT_ORDER_SORT;
}

function normalizeGifExportFrameDelayCs(value) {
  const n = Math.round(Number(value) || 0);
  return GIF_EXPORT_FRAME_DELAY_OPTIONS_CS.includes(n)
    ? n
    : GIF_EXPORT_DEFAULT_FRAME_DELAY_CS;
}

function buildGifFrameDelayChoiceMenu(menuEl, options = {}) {
  if (!menuEl) return;
  menuEl.innerHTML = "";
  if (typeof options.onBack === "function") {
    appendChoiceMenuButton(menuEl, "Back", options.onBack);
  }
  for (let i = 0; i < GIF_EXPORT_FRAME_DELAY_OPTIONS_CS.length; i++) {
    const delayCs = GIF_EXPORT_FRAME_DELAY_OPTIONS_CS[i];
    appendChoiceMenuButton(menuEl, `${delayCs} cs`, () => {
      if (typeof options.onChooseDelay === "function") {
        options.onChooseDelay(delayCs);
      }
    });
  }
  if (typeof options.onRendered === "function") {
    requestAnimationFrame(() => options.onRendered());
  }
}

function buildGifAllInOneOrderChoiceMenu(menuEl, options = {}) {
  if (!menuEl) return;
  menuEl.innerHTML = "";
  if (typeof options.onBack === "function") {
    appendChoiceMenuButton(menuEl, "Back", options.onBack);
  }
  appendChoiceMenuButton(menuEl, "Ordered by Sort", () => {
    buildGifFrameDelayChoiceMenu(menuEl, {
      onBack: () => buildGifAllInOneOrderChoiceMenu(menuEl, options),
      onChooseDelay: (frameDelayCs) => {
        if (typeof options.onChooseConfig === "function") {
          options.onChooseConfig({
            mode: GIF_EXPORT_MODE_ALL_IN_ONE,
            order: GIF_EXPORT_ORDER_SORT,
            frameDelayCs: normalizeGifExportFrameDelayCs(frameDelayCs),
          });
        }
      },
      onRendered: options.onRendered,
    });
  });
  appendChoiceMenuButton(menuEl, "Ordered by Aspect Ratio", () => {
    buildGifFrameDelayChoiceMenu(menuEl, {
      onBack: () => buildGifAllInOneOrderChoiceMenu(menuEl, options),
      onChooseDelay: (frameDelayCs) => {
        if (typeof options.onChooseConfig === "function") {
          options.onChooseConfig({
            mode: GIF_EXPORT_MODE_ALL_IN_ONE,
            order: GIF_EXPORT_ORDER_ASPECT_RATIO,
            frameDelayCs: normalizeGifExportFrameDelayCs(frameDelayCs),
          });
        }
      },
      onRendered: options.onRendered,
    });
  });
  if (typeof options.onRendered === "function") {
    requestAnimationFrame(() => options.onRendered());
  }
}

function buildGifExportChoiceMenu(menuEl, options = {}) {
  if (!menuEl) return;
  menuEl.innerHTML = "";
  if (typeof options.onBack === "function") {
    appendChoiceMenuButton(menuEl, "Back", options.onBack);
  }
  appendChoiceMenuButton(menuEl, "By Aspect Ratio", () => {
    buildGifFrameDelayChoiceMenu(menuEl, {
      onBack: () => buildGifExportChoiceMenu(menuEl, options),
      onChooseDelay: (frameDelayCs) => {
        if (typeof options.onChooseConfig === "function") {
          options.onChooseConfig({
            mode: GIF_EXPORT_MODE_BY_ASPECT_RATIO,
            order: GIF_EXPORT_ORDER_SORT,
            frameDelayCs: normalizeGifExportFrameDelayCs(frameDelayCs),
          });
        }
      },
      onRendered: options.onRendered,
    });
  });
  appendChoiceMenuButton(menuEl, "All-In-One", () => {
    buildGifAllInOneOrderChoiceMenu(menuEl, {
      onBack: () => buildGifExportChoiceMenu(menuEl, options),
      onChooseConfig: options.onChooseConfig,
      onRendered: options.onRendered,
    });
  });
  if (typeof options.onRendered === "function") {
    requestAnimationFrame(() => options.onRendered());
  }
}

function effectiveAppearancePresetIdForMenuPath(path) {
  const normalized = normalizeDirPathValue(path);
  if (normalized === "" && WS.root) return effectiveActiveAppearancePresetId();
  return nearestFolderAppearancePresetIdForPath(normalized);
}

function updateAppearancePresetUiState() {
  const bucket = currentAppearanceBucket();
  const activeId = effectiveActiveAppearancePresetId();
  const uiTargetId =
    bucket === "editing"
      ? currentAppearanceEditingTargetId()
      : activeId || BUILTIN_NULL_APPEARANCE_PRESET_ID;
  if (bucket !== "editing" && WS.view) {
    WS.view.appearancePresetEditingId = uiTargetId;
  }
  const presetSelectEl = $("opt_appearancePresetLibrary");
  if (presetSelectEl && presetSelectEl.value !== uiTargetId) {
    presetSelectEl.value = uiTargetId;
  }
  const disablePresetDelete = uiTargetId === BUILTIN_NULL_APPEARANCE_PRESET_ID;
  const saveBtn = $("opt_appearancePreset_save");
  const deleteBtn = $("opt_appearancePreset_delete");
  if (saveBtn) saveBtn.disabled = false;
  if (deleteBtn) deleteBtn.disabled = disablePresetDelete;
}

function markAppearanceStateChanged(invalidateThumbs = true) {
  if (!WS.meta) return;
  syncActiveAppearancePresetSelection(WS.meta.options);
  metaMarkDirty(META_DOC_IDS.prefAppearance);
  setOptionsStatus("Saved");
  applyOptionsEverywhere(!!invalidateThumbs);
  updateAppearancePresetUiState();
}

function applyAppearancePresetById(presetId, options = {}) {
  const id = normalizeAppearancePresetIdValue(presetId);
  const preset = getAppearancePresetById(id);
  if (!preset) return false;
  WS.meta.options = buildOptionsWithAppearanceValues(preset.values || {}, id);
  if (WS.view) {
    WS.view.appearancePresetEditingId = id;
    WS.view.appearancePresetPromptMode = "";
    WS.view.appearancePresetDraftName =
      id === BUILTIN_NULL_APPEARANCE_PRESET_ID ? "" : String(preset.name || "");
  }
  markAppearanceStateChanged(options.invalidateThumbs !== false);
  return true;
}

function saveAppearancePresetFromCurrent(name) {
  if (!WS.meta) return { ok: false, reason: "missing-meta" };
  const presetName = normalizeAppearancePresetName(name, "");
  if (!presetName) return { ok: false, reason: "missing-name" };
  if (presetName.toLowerCase() === "default")
    return { ok: false, reason: "reserved-name" };
  const values = currentAppearanceValuesFromOptions(WS.meta.options);
  const existing = findAppearancePresetByName(presetName);
  let presetId = "";
  let replaced = false;
  if (
    existing &&
    normalizeAppearancePresetIdValue(existing.id) !==
      BUILTIN_NULL_APPEARANCE_PRESET_ID
  ) {
    presetId = normalizeAppearancePresetIdValue(existing.id);
    WS.meta.appearancePresets = (WS.meta.appearancePresets || []).map(
      (preset) => {
        if (normalizeAppearancePresetIdValue(preset && preset.id) !== presetId)
          return preset;
        return Object.assign({}, preset, {
          name: presetName,
          values,
        });
      },
    );
    replaced = true;
  } else {
    presetId = createAppearancePresetId();
    WS.meta.appearancePresets = [].concat(WS.meta.appearancePresets || [], [
      {
        id: presetId,
        name: presetName,
        locked: false,
        values,
      },
    ]);
  }
  WS.meta.appearancePresets = normalizeAppearancePresetList(
    WS.meta.appearancePresets,
    false,
  );
  syncPaneKeybindBindingsWithCurrentActions(false);
  rebuildKeybindIndex();
  if (MENU_OPEN && MENU_ACTIVE_TAB === "controls") renderKeybindsUi("pane");
  const savedPreset = findAppearancePresetByName(presetName);
  const nextId =
    normalizeAppearancePresetIdValue(savedPreset && savedPreset.id) || presetId;
  if (WS.meta.options) WS.meta.options.activeAppearancePresetId = nextId;
  if (WS.view) {
    WS.view.appearancePresetEditingId = nextId;
    WS.view.appearancePresetPromptMode = "";
    WS.view.appearancePresetDraftName = presetName;
  }
  metaMarkDirty(
    META_DOC_IDS.appearancePresets,
    META_DOC_IDS.keybinds,
    META_DOC_IDS.prefAppearance,
  );
  setOptionsStatus("Saved");
  applyOptionsEverywhere(true);
  updateAppearancePresetUiState();
  return {
    ok: true,
    replaced,
    preset: getAppearancePresetById(nextId),
  };
}

function createAppearancePresetFromCurrent(name) {
  if (!WS.meta) return null;
  const presetName = normalizeAppearancePresetName(name, "Preset");
  const preset = {
    id: createAppearancePresetId(),
    name: presetName,
    locked: false,
    values: currentAppearanceValuesFromOptions(WS.meta.options),
  };
  WS.meta.appearancePresets = normalizeAppearancePresetList(
    [].concat(WS.meta.appearancePresets || [], [preset]),
    false,
  );
  syncPaneKeybindBindingsWithCurrentActions(false);
  rebuildKeybindIndex();
  if (WS.view) WS.view.appearancePresetEditingId = preset.id;
  if (WS.meta.options) WS.meta.options.activeAppearancePresetId = preset.id;
  metaMarkDirty(
    META_DOC_IDS.appearancePresets,
    META_DOC_IDS.keybinds,
    META_DOC_IDS.prefAppearance,
  );
  setOptionsStatus("Saved");
  return getAppearancePresetById(preset.id);
}

function updateAppearancePresetFromCurrent(presetId) {
  const id = normalizeAppearancePresetIdValue(presetId);
  if (!id || id === BUILTIN_NULL_APPEARANCE_PRESET_ID) return false;
  const presets = Array.isArray(
    WS.meta && WS.meta.appearancePresets ? WS.meta.appearancePresets : null,
  )
    ? WS.meta.appearancePresets
    : [];
  let changed = false;
  WS.meta.appearancePresets = presets.map((preset) => {
    if (normalizeAppearancePresetIdValue(preset && preset.id) !== id)
      return preset;
    changed = true;
    return Object.assign({}, preset, {
      values: currentAppearanceValuesFromOptions(WS.meta.options),
    });
  });
  if (!changed) return false;
  if (WS.meta.options) WS.meta.options.activeAppearancePresetId = id;
  if (WS.view) WS.view.appearancePresetEditingId = id;
  if (WS.view)
    WS.view.appearancePresetDraftName = String(
      (getAppearancePresetById(id) || {}).name || "",
    );
  metaMarkDirty(META_DOC_IDS.appearancePresets, META_DOC_IDS.prefAppearance);
  setOptionsStatus("Saved");
  return true;
}

function renameAppearancePresetById(presetId, nextName) {
  const id = normalizeAppearancePresetIdValue(presetId);
  if (!id || id === BUILTIN_NULL_APPEARANCE_PRESET_ID) return false;
  const normalizedName = normalizeAppearancePresetName(nextName, "Preset");
  const existing = Array.isArray(
    WS.meta && WS.meta.appearancePresets ? WS.meta.appearancePresets : null,
  )
    ? WS.meta.appearancePresets
    : [];
  let changed = false;
  WS.meta.appearancePresets = existing.map((preset) => {
    if (normalizeAppearancePresetIdValue(preset && preset.id) !== id)
      return preset;
    if (String(preset.name || "") === normalizedName) return preset;
    changed = true;
    return Object.assign({}, preset, { name: normalizedName });
  });
  if (!changed) return false;
  WS.meta.appearancePresets = normalizeAppearancePresetList(
    WS.meta.appearancePresets,
    false,
  );
  syncPaneKeybindBindingsWithCurrentActions(false);
  rebuildKeybindIndex();
  if (MENU_OPEN && MENU_ACTIVE_TAB === "controls") renderKeybindsUi("pane");
  metaMarkDirty(META_DOC_IDS.appearancePresets, META_DOC_IDS.keybinds);
  setOptionsStatus("Saved");
  return true;
}

function clearDeletedAppearancePresetReferences(presetId) {
  const id = normalizeAppearancePresetIdValue(presetId);
  if (!id || !WS.meta) return false;
  let changed = false;
  if (WS.meta.dirAppearancePresetIds) {
    for (const [path, assignedId] of Array.from(
      WS.meta.dirAppearancePresetIds.entries(),
    )) {
      if (normalizeAppearancePresetIdValue(assignedId) !== id) continue;
      WS.meta.dirAppearancePresetIds.delete(path);
      changed = true;
    }
  }
  if (WS.meta.tagAppearancePresetIds) {
    for (const [tagKey, assignedId] of Array.from(
      WS.meta.tagAppearancePresetIds.entries(),
    )) {
      if (normalizeAppearancePresetIdValue(assignedId) !== id) continue;
      WS.meta.tagAppearancePresetIds.delete(tagKey);
      changed = true;
    }
  }
  if (
    WS.meta.options &&
    normalizeAppearancePresetIdValue(
      WS.meta.options.activeAppearancePresetId,
    ) === id
  ) {
    WS.meta.options.activeAppearancePresetId = null;
    changed = true;
  }
  return changed;
}

function deleteAppearancePresetById(presetId) {
  const id = normalizeAppearancePresetIdValue(presetId);
  if (!id || id === BUILTIN_NULL_APPEARANCE_PRESET_ID || !WS.meta) return false;
  const before = Array.isArray(WS.meta.appearancePresets)
    ? WS.meta.appearancePresets.length
    : 0;
  WS.meta.appearancePresets = (WS.meta.appearancePresets || []).filter(
    (preset) => normalizeAppearancePresetIdValue(preset && preset.id) !== id,
  );
  if (WS.meta.appearancePresets.length === before) return false;
  clearDeletedAppearancePresetReferences(id);
  syncActiveAppearancePresetSelection(WS.meta.options);
  if (
    WS.view &&
    normalizeAppearancePresetIdValue(WS.view.appearancePresetEditingId) === id
  ) {
    WS.view.appearancePresetEditingId =
      effectiveActiveAppearancePresetId() || BUILTIN_NULL_APPEARANCE_PRESET_ID;
  }
  if (WS.view) {
    WS.view.appearancePresetPromptMode = "";
    if (
      normalizeAppearancePresetIdValue(WS.view.appearancePresetEditingId) ===
      BUILTIN_NULL_APPEARANCE_PRESET_ID
    ) {
      WS.view.appearancePresetDraftName = "";
    }
  }
  syncPaneKeybindBindingsWithCurrentActions(false);
  rebuildKeybindIndex();
  if (MENU_OPEN && MENU_ACTIVE_TAB === "controls") renderKeybindsUi("pane");
  metaMarkDirty(
    META_DOC_IDS.appearancePresets,
    META_DOC_IDS.appearanceAssignments,
    META_DOC_IDS.prefAppearance,
    META_DOC_IDS.keybinds,
  );
  setOptionsStatus("Saved");
  return true;
}

function addColorFilter(filters, filterText) {
  const text = String(filterText || "").trim();
  if (!text || text === "none") return;
  filters.push(text);
}

function optionalOverlayAmount(value, min, max) {
  if (value == null || value === "") return null;
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return null;
  return clampNumber(parsed, min, max, 0);
}

function buildMediaOverlayConfigFromOptions(opt) {
  if (!opt) return null;
  const colorFilters = [];
  const hueShiftAmount = optionalOverlayAmount(
    opt.hueShiftOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.hueShift.min,
    OVERLAY_SLIDER_LIMITS.hueShift.max,
  );
  if (hueShiftAmount != null && Math.abs(hueShiftAmount) > 0.0001)
    addColorFilter(colorFilters, `hue-rotate(${hueShiftAmount.toFixed(1)}deg)`);
  const saturationAmount = optionalOverlayAmount(
    opt.saturationOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.saturation.min,
    OVERLAY_SLIDER_LIMITS.saturation.max,
  );
  if (saturationAmount != null && Math.abs(saturationAmount) > 0.0001) {
    const amount = saturationAmount;
    addColorFilter(
      colorFilters,
      `saturate(${Math.max(0, 1 + amount).toFixed(3)})`,
    );
  }
  const contrastAmount = optionalOverlayAmount(
    opt.contrastOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.contrast.min,
    OVERLAY_SLIDER_LIMITS.contrast.max,
  );
  if (contrastAmount != null && Math.abs(contrastAmount) > 0.0001) {
    const amount = contrastAmount;
    addColorFilter(
      colorFilters,
      `contrast(${Math.max(0, 1 + amount).toFixed(3)})`,
    );
  }
  const brightnessAmount = optionalOverlayAmount(
    opt.brightnessOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.brightness.min,
    OVERLAY_SLIDER_LIMITS.brightness.max,
  );
  if (brightnessAmount != null && Math.abs(brightnessAmount) > 0.0001) {
    const amount = brightnessAmount;
    addColorFilter(
      colorFilters,
      `brightness(${Math.max(0, 1 + amount).toFixed(3)})`,
    );
  }
  const temperatureAmount = optionalOverlayAmount(
    opt.warmthOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.warmth.min,
    OVERLAY_SLIDER_LIMITS.warmth.max,
  );
  const temperature =
    temperatureAmount != null && Math.abs(temperatureAmount) > 0.0001
      ? temperatureAmount
      : 0;

  const colorCrushAmount = optionalOverlayAmount(
    opt.colorCrushOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.colorCrush.min,
    OVERLAY_SLIDER_LIMITS.colorCrush.max,
  );
  const colorCrush =
    colorCrushAmount != null && colorCrushAmount > 0.0001
      ? colorCrushAmount
      : 0;
  const blackCrushAmount = optionalOverlayAmount(
    opt.blackCrushOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.blackCrush.min,
    OVERLAY_SLIDER_LIMITS.blackCrush.max,
  );
  const blackCrush =
    blackCrushAmount != null && blackCrushAmount > 0.0001
      ? blackCrushAmount
      : 0;
  const whiteCrushAmount = optionalOverlayAmount(
    opt.whiteCrushOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.whiteCrush.min,
    OVERLAY_SLIDER_LIMITS.whiteCrush.max,
  );
  const whiteCrush =
    whiteCrushAmount != null && whiteCrushAmount > 0.0001
      ? whiteCrushAmount
      : 0;
  const halationAmount = optionalOverlayAmount(
    opt.halationOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.halation.min,
    OVERLAY_SLIDER_LIMITS.halation.max,
  );
  const halation =
    halationAmount != null && halationAmount > 0.0001 ? halationAmount : 0;
  const ghostingAmount = optionalOverlayAmount(
    opt.ghostingOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.ghosting.min,
    OVERLAY_SLIDER_LIMITS.ghosting.max,
  );
  const ghosting =
    ghostingAmount != null && ghostingAmount > 0.0001 ? ghostingAmount : 0;
  const lineDamageAmount = optionalOverlayAmount(
    opt.lineDamageOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.lineDamage.min,
    OVERLAY_SLIDER_LIMITS.lineDamage.max,
  );
  const lineDamage =
    lineDamageAmount != null && lineDamageAmount > 0.0001
      ? lineDamageAmount
      : 0;
  const pixelateAmount = optionalOverlayAmount(
    opt.pixelateOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.pixelate.min,
    OVERLAY_SLIDER_LIMITS.pixelate.max,
  );
  const pixelate =
    pixelateAmount != null &&
    pixelateAmount > OVERLAY_SLIDER_LIMITS.pixelate.min + 0.0001
      ? pixelateAmount
      : 0;
  const blurAmount = optionalOverlayAmount(
    opt.blurOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.blur.min,
    OVERLAY_SLIDER_LIMITS.blur.max,
  );
  const blur = blurAmount != null && blurAmount > 0.0001 ? blurAmount : 0;
  const chromaAmount = optionalOverlayAmount(
    opt.chromaOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.chroma.min,
    OVERLAY_SLIDER_LIMITS.chroma.max,
  );
  const chroma =
    chromaAmount != null && chromaAmount > 0.0001 ? chromaAmount : 0;
  const grainAmount = optionalOverlayAmount(
    opt.grainOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.grain.min,
    OVERLAY_SLIDER_LIMITS.grain.max,
  );
  const grain = grainAmount != null && grainAmount > 0.0001 ? grainAmount : 0;
  const vignetteAmount = optionalOverlayAmount(
    opt.vignetteOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.vignette.min,
    OVERLAY_SLIDER_LIMITS.vignette.max,
  );
  const vignette =
    vignetteAmount != null && vignetteAmount > 0.0001 ? vignetteAmount : 0;
  const cornerAmount = optionalOverlayAmount(
    opt.filmCornerOverlayIntensity,
    OVERLAY_SLIDER_LIMITS.filmCorner.min,
    OVERLAY_SLIDER_LIMITS.filmCorner.max,
  );
  const cornerRadius =
    cornerAmount != null && cornerAmount > 0.0001 ? cornerAmount : 0;

  if (
    !colorFilters.length &&
    !temperature &&
    !colorCrush &&
    !blackCrush &&
    !whiteCrush &&
    !halation &&
    !ghosting &&
    !lineDamage &&
    !pixelate &&
    !blur &&
    !chroma &&
    !grain &&
    !vignette &&
    !cornerRadius
  ) {
    return null;
  }
  return {
    colorFilters,
    temperature,
    colorCrush,
    blackCrush,
    whiteCrush,
    halation,
    ghosting,
    lineDamage,
    pixelate,
    blur,
    chroma,
    grain,
    vignette,
    cornerRadius,
  };
}

function serializeAppearanceValues(values) {
  const parts = [];
  for (let i = 0; i < APPEARANCE_SLIDER_OPTION_KEYS.length; i++) {
    const key = APPEARANCE_SLIDER_OPTION_KEYS[i];
    const value =
      values && Object.prototype.hasOwnProperty.call(values, key)
        ? values[key]
        : null;
    parts.push(`${key}:${value == null ? "null" : String(value)}`);
  }
  return parts.join("|");
}

function buildAppearancePresetCacheKey() {
  const currentValues = currentAppearanceValuesFromOptions(
    WS.meta && WS.meta.options ? WS.meta.options : null,
  );
  const presetSig = Array.isArray(
    WS.meta && WS.meta.appearancePresets ? WS.meta.appearancePresets : null,
  )
    ? WS.meta.appearancePresets
        .map((preset) => {
          const id = normalizeAppearancePresetIdValue(preset && preset.id);
          return `${id}:${serializeAppearanceValues(preset && preset.values ? preset.values : {})}`;
        })
        .join("||")
    : "";
  const folderSig =
    WS.meta && WS.meta.dirAppearancePresetIds
      ? Array.from(WS.meta.dirAppearancePresetIds.entries())
          .map(
            ([path, presetId]) =>
              `${normalizeDirPathValue(path)}=>${normalizeAppearancePresetIdValue(presetId)}`,
          )
          .sort()
          .join("||")
      : "";
  const tagSig =
    WS.meta && WS.meta.tagAppearancePresetIds
      ? Array.from(WS.meta.tagAppearancePresetIds.entries())
          .map(
            ([tagKey, presetId]) =>
              `${String(tagKey || "")}=>${normalizeAppearancePresetIdValue(presetId)}`,
          )
          .sort()
          .join("||")
      : "";
  const tagFilterSig =
    WS.meta && WS.meta.tagMediaFilterByKey
      ? Array.from(WS.meta.tagMediaFilterByKey.entries())
          .map(
            ([tagKey, filterValue]) =>
              `${String(tagKey || "")}=>${normalizeTagMediaFilterValue(filterValue).join(",")}`,
          )
          .sort()
          .join("||")
      : "";
  const activeContextSig = (() => {
    const direct = [
      String((WS.view && WS.view.tagFolderActiveMode) || ""),
      String((WS.view && WS.view.tagFolderActiveTag) || ""),
      String((WS.view && WS.view.tagFolderActiveAlbum) || ""),
      String((WS.view && WS.view.tagFolderOriginPath) || ""),
    ].join("|");
    const stackSig = Array.isArray(WS.view && WS.view.tagNavStack)
      ? WS.view.tagNavStack
          .map((frame) => {
            if (!frame || frame.type !== "tag-view") return "";
            return [
              "tag-view",
              String(frame.mode || ""),
              String(frame.tag || ""),
              String(frame.album || ""),
              String(frame.originPath || ""),
              String(frame.selectedDirPath || ""),
            ].join("|");
          })
          .filter(Boolean)
          .join("||")
      : "";
    return `${direct}###${stackSig}`;
  })();
  const gifsIgnore = gifsIgnoreProcessingEnabled() ? "gif:1" : "gif:0";
  return `${serializeAppearanceValues(currentValues)}###${presetSig}###${folderSig}###${tagSig}###${tagFilterSig}###${activeContextSig}###${gifsIgnore}`;
}

function resolveDirPathForAppearanceTarget(target) {
  if (typeof target === "string") return normalizeDirPathValue(target);
  if (target && typeof target === "object") {
    if (typeof target.dirPath === "string")
      return normalizeDirPathValue(target.dirPath);
    if (typeof target.path === "string")
      return normalizeDirPathValue(target.path);
  }
  return "";
}

function contextualAppearancePresetIdForTagContext(
  mode,
  tag,
  album,
  originPath,
) {
  const contextMode = String(mode || "");
  const contextTag = normalizeTag(tag || "");
  const contextAlbum = normalizeTagAlbumName(album || "");
  const scopePath = normalizeDirPathValue(originPath);
  if (contextMode === "tag" && contextTag) {
    const tagPresetId = metaGetTagAppearancePresetIdByKey(
      tagThumbnailKeyForTag(contextTag, scopePath),
    );
    if (tagPresetId) return tagPresetId;
    if (contextAlbum) {
      const albumPresetId = metaGetTagAppearancePresetIdByKey(
        tagThumbnailKeyForAlbum(contextAlbum, scopePath),
      );
      if (albumPresetId) return albumPresetId;
    }
    return "";
  }
  if (contextMode === "album" && contextAlbum) {
    return metaGetTagAppearancePresetIdByKey(
      tagThumbnailKeyForAlbum(contextAlbum, scopePath),
    );
  }
  return "";
}

function contextualTagMediaFilterForTagContext(mode, tag, album, originPath) {
  const contextMode = String(mode || "");
  const contextTag = normalizeTag(tag || "");
  const contextAlbum = normalizeTagAlbumName(album || "");
  const scopePath = normalizeDirPathValue(originPath);
  if (contextMode === "tag" && contextTag) {
    const directFilter = metaGetTagMediaFilterByKey(
      tagThumbnailKeyForTag(contextTag, scopePath),
    );
    if (directFilter.length) return directFilter;
    if (contextAlbum) {
      const albumFilter = metaGetTagMediaFilterByKey(
        tagThumbnailKeyForAlbum(contextAlbum, scopePath),
      );
      if (albumFilter.length) return albumFilter;
    }
    return [];
  }
  if (contextMode === "album" && contextAlbum) {
    return metaGetTagMediaFilterByKey(
      tagThumbnailKeyForAlbum(contextAlbum, scopePath),
    );
  }
  return [];
}

function contextualTagMediaFilterForDirPath(dirPath) {
  const normalized = normalizeDirPathValue(dirPath);
  if (!normalized) return [];
  const activeMode = String((WS.view && WS.view.tagFolderActiveMode) || "");
  if (activeMode === "tag" || activeMode === "album") {
    const originPath = String((WS.view && WS.view.tagFolderOriginPath) || "");
    const rootPaths = getPortalRootPathsForTagContext(
      activeMode,
      WS.view && WS.view.tagFolderActiveTag,
      WS.view && WS.view.tagFolderActiveAlbum,
      originPath,
    );
    if (
      rootPaths.some((rootPath) => isSameOrDescendantPath(normalized, rootPath))
    ) {
      const filterValue = contextualTagMediaFilterForTagContext(
        activeMode,
        WS.view && WS.view.tagFolderActiveTag,
        WS.view && WS.view.tagFolderActiveAlbum,
        originPath,
      );
      if (filterValue.length) return filterValue;
    }
  }
  const stack = Array.isArray(WS.view && WS.view.tagNavStack)
    ? WS.view.tagNavStack
    : [];
  for (let i = stack.length - 1; i >= 0; i--) {
    const frame = stack[i];
    if (!frame || frame.type !== "tag-view") continue;
    const rootPath = findMatchingVirtualPortalRootPath(frame, normalized);
    if (!rootPath) continue;
    const filterValue = contextualTagMediaFilterForTagContext(
      frame.mode,
      frame.tag,
      frame.album,
      frame.originPath,
    );
    if (filterValue.length) return filterValue;
  }
  return [];
}

function currentContextualTagMediaFilterValue() {
  if (isViewingTagFolder()) {
    const direct = contextualTagMediaFilterForTagContext(
      WS.view && WS.view.tagFolderActiveMode,
      WS.view && WS.view.tagFolderActiveTag,
      WS.view && WS.view.tagFolderActiveAlbum,
      WS.view && WS.view.tagFolderOriginPath,
    );
    if (direct.length) return direct;
  }
  return contextualTagMediaFilterForDirPath(
    String(WS.nav && WS.nav.dirNode ? WS.nav.dirNode.path || "" : ""),
  );
}

function getPortalRootPathsForTagContext(mode, tag, album, originPath) {
  const contextMode = String(mode || "");
  const contextTag = normalizeTag(tag || "");
  const contextAlbum = normalizeTagAlbumName(album || "");
  const scopePath = normalizeDirPathValue(originPath);
  const baseNode = WS.dirByPath.get(scopePath) || null;
  if (!baseNode) return [];
  const showHidden =
    WS.view.hiddenMode ||
    showHiddenFolderEnabled() ||
    (isViewingTagFolder() && WS.view.tagFolderActiveMode === "hidden");
  const children = sortDirsForDisplay(baseNode.childrenDirs)
    .filter((child) => child && child.type === "dir")
    .filter((child) => (showHidden ? true : !isDirOrAncestorHidden(child)));
  if (contextMode === "tag" && contextTag) {
    return children
      .filter((child) => metaGetUserTags(child.path || "").includes(contextTag))
      .map((child) => String(child.path || ""))
      .filter(Boolean);
  }
  if (contextMode === "album" && contextAlbum) {
    return children
      .filter((child) => {
        const tags = metaGetUserTags(child.path || "");
        for (let i = 0; i < tags.length; i++) {
          if (metaGetTagAlbumForTag(tags[i], scopePath) === contextAlbum)
            return true;
        }
        return false;
      })
      .map((child) => String(child.path || ""))
      .filter(Boolean);
  }
  return [];
}

function contextualAppearancePresetIdForDirPath(dirPath) {
  const normalized = normalizeDirPathValue(dirPath);
  if (!normalized) return "";
  const activeMode = String((WS.view && WS.view.tagFolderActiveMode) || "");
  if (activeMode === "tag") {
    const originPath = String((WS.view && WS.view.tagFolderOriginPath) || "");
    const node = WS.dirByPath.get(normalized) || null;
    if (node && String(node.parent?.path || "") === originPath) {
      const activeTag = normalizeTag(
        (WS.view && WS.view.tagFolderActiveTag) || "",
      );
      if (activeTag) {
        const userTags = metaGetUserTags(normalized);
        if (userTags.includes(activeTag)) {
          const directPresetId = contextualAppearancePresetIdForTagContext(
            activeMode,
            activeTag,
            WS.view && WS.view.tagFolderActiveAlbum,
            originPath,
          );
          if (directPresetId) return directPresetId;
        }
      }
    }
  }
  const stack = Array.isArray(WS.view && WS.view.tagNavStack)
    ? WS.view.tagNavStack
    : [];
  for (let i = stack.length - 1; i >= 0; i--) {
    const frame = stack[i];
    if (!frame || frame.type !== "tag-view") continue;
    const rootPath = findMatchingVirtualPortalRootPath(frame, normalized);
    if (!rootPath) continue;
    const presetId = contextualAppearancePresetIdForTagContext(
      frame.mode,
      frame.tag,
      frame.album,
      frame.originPath,
    );
    if (presetId) return presetId;
  }
  return "";
}

function resolveAppearancePresetIdForTarget(target) {
  const dirPath = resolveDirPathForAppearanceTarget(target);
  const contextualPresetId = contextualAppearancePresetIdForDirPath(dirPath);
  if (contextualPresetId) return contextualPresetId;
  return nearestFolderAppearancePresetIdForPath(dirPath);
}

function resolveAppearanceValuesForTarget(target) {
  const presetId = resolveAppearancePresetIdForTarget(target);
  if (presetId) {
    const preset = getAppearancePresetById(presetId);
    if (!preset || !preset.values) return {};
    return preset.values;
  }
  return currentAppearanceValuesFromOptions(
    WS.meta && WS.meta.options ? WS.meta.options : null,
  );
}

function resolveMediaOverlayConfigForTarget(target) {
  if (!mediaProcessingEnabledForTarget(target)) return null;
  const presetId = resolveAppearancePresetIdForTarget(target);
  if (presetId) {
    const preset = getAppearancePresetById(presetId);
    if (preset)
      return buildMediaOverlayConfigFromOptions(preset.values || null);
  }
  return (
    MEDIA_OVERLAY_STATE ||
    buildMediaOverlayConfigFromOptions(
      WS.meta && WS.meta.options ? WS.meta.options : null,
    )
  );
}

function resolveFolderOnlyMediaOverlayConfigForTarget(target) {
  if (!mediaProcessingEnabledForTarget(target)) return null;
  const dirPath = resolveDirPathForAppearanceTarget(target);
  const folderPresetId = nearestFolderAppearancePresetIdForPath(dirPath);
  if (folderPresetId) {
    const preset = getAppearancePresetById(folderPresetId);
    if (preset)
      return buildMediaOverlayConfigFromOptions(preset.values || null);
  }
  return buildMediaOverlayConfigFromOptions(
    WS.meta && WS.meta.options ? WS.meta.options : null,
  );
}

function anyMediaFilterEnabled() {
  if (
    MEDIA_OVERLAY_STATE ||
    buildMediaOverlayConfigFromOptions(
      WS.meta && WS.meta.options ? WS.meta.options : null,
    )
  )
    return true;
  if (WS.meta && WS.meta.dirAppearancePresetIds) {
    for (const presetId of WS.meta.dirAppearancePresetIds.values()) {
      const preset = getAppearancePresetById(presetId);
      if (preset && buildMediaOverlayConfigFromOptions(preset.values || null))
        return true;
    }
  }
  if (WS.meta && WS.meta.tagAppearancePresetIds) {
    for (const presetId of WS.meta.tagAppearancePresetIds.values()) {
      const preset = getAppearancePresetById(presetId);
      if (preset && buildMediaOverlayConfigFromOptions(preset.values || null))
        return true;
    }
  }
  return false;
}

function computeContainRect(srcW, srcH, dstW, dstH) {
  if (!srcW || !srcH || !dstW || !dstH) return { x: 0, y: 0, w: dstW, h: dstH };
  const srcRatio = srcW / srcH;
  const dstRatio = dstW / dstH;
  let w = dstW;
  let h = dstH;
  if (srcRatio > dstRatio) {
    h = dstW / srcRatio;
  } else {
    w = dstH * srcRatio;
  }
  const x = (dstW - w) * 0.5;
  const y = (dstH - h) * 0.5;
  return { x, y, w, h };
}

function expandRectFromCenter(rect, pad) {
  const p = Math.max(0, Number(pad) || 0);
  return {
    x: rect.x - p,
    y: rect.y - p,
    w: rect.w + p * 2,
    h: rect.h + p * 2,
  };
}

function computeCoverRect(srcW, srcH, dstW, dstH) {
  if (!srcW || !srcH || !dstW || !dstH) return { x: 0, y: 0, w: dstW, h: dstH };
  const srcRatio = srcW / srcH;
  const dstRatio = dstW / dstH;
  let w = dstW;
  let h = dstH;
  if (srcRatio > dstRatio) {
    w = dstH * srcRatio;
  } else {
    h = dstW / srcRatio;
  }
  const x = (dstW - w) * 0.5;
  const y = (dstH - h) * 0.5;
  return { x, y, w, h };
}

function roundedRectPath(ctx, x, y, w, h, r) {
  const radius = Math.max(0, Math.min(r, Math.min(w, h) * 0.5));
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function applyRoundedCornerMask(ctx, rect, radius) {
  if (!radius) return;
  ctx.save();
  ctx.globalCompositeOperation = "destination-in";
  roundedRectPath(ctx, rect.x, rect.y, rect.w, rect.h, radius);
  ctx.fillStyle = "#000";
  ctx.fill();
  ctx.restore();
}

const VIDEO_BLACK_BAR_DETECT = Object.freeze({
  sampleMax: 320,
  nearBlackMax: 24,
  blackRatioMin: 0.985,
  maxSideFrac: 0.42,
  minSideFrac: 0.05,
  symmetryTolFrac: 0.04,
  centerMinLuma: 24,
  contrastMinLuma: 10,
});

function normalizeVideoCrop(crop) {
  if (!crop || typeof crop !== "object") return null;
  const left = clampNumber(crop.left, 0, 0.49, 0);
  const right = clampNumber(crop.right, 0, 0.49, 0);
  const top = clampNumber(crop.top, 0, 0.49, 0);
  const bottom = clampNumber(crop.bottom, 0, 0.49, 0);
  if (left + right >= 0.92) return null;
  if (top + bottom >= 0.92) return null;
  if (!(left > 0 || right > 0 || top > 0 || bottom > 0)) return null;
  return { left, right, top, bottom };
}

function hasVideoCrop(crop) {
  const c = normalizeVideoCrop(crop);
  return !!c;
}

function videoAutoBlackBarTrimEnabled(opt = null) {
  return false;
}

function getVideoCropForRecord(rec) {
  return null;
}

function getVideoCropForTarget(target) {
  if (!target || typeof target !== "object") return null;
  return getVideoCropForRecord(target);
}

function computeCroppedSourceRect(srcW, srcH, crop) {
  const c = normalizeVideoCrop(crop);
  if (!c || !(srcW > 0) || !(srcH > 0)) {
    return { sx: 0, sy: 0, sw: srcW, sh: srcH };
  }
  const sx = Math.max(0, Math.min(srcW - 1, Math.round(srcW * c.left)));
  const sy = Math.max(0, Math.min(srcH - 1, Math.round(srcH * c.top)));
  const ex = Math.max(sx + 1, Math.min(srcW, Math.round(srcW * (1 - c.right))));
  const ey = Math.max(
    sy + 1,
    Math.min(srcH, Math.round(srcH * (1 - c.bottom))),
  );
  return {
    sx,
    sy,
    sw: Math.max(1, ex - sx),
    sh: Math.max(1, ey - sy),
  };
}

function detectStaticVideoBlackBars(videoEl) {
  const w = Number(videoEl?.videoWidth || 0);
  const h = Number(videoEl?.videoHeight || 0);
  if (!(w > 32 && h > 32)) return null;

  const maxDim = VIDEO_BLACK_BAR_DETECT.sampleMax;
  const scale = Math.min(1, maxDim / Math.max(w, h));
  const sw = Math.max(32, Math.round(w * scale));
  const sh = Math.max(32, Math.round(h * scale));

  const canvas = document.createElement("canvas");
  canvas.width = sw;
  canvas.height = sh;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) return null;
  try {
    ctx.drawImage(videoEl, 0, 0, sw, sh);
  } catch {
    return null;
  }

  let imageData = null;
  try {
    imageData = ctx.getImageData(0, 0, sw, sh);
  } catch {
    return null;
  }
  const data = imageData.data;
  const nearBlackMax = VIDEO_BLACK_BAR_DETECT.nearBlackMax;
  const ratioMin = VIDEO_BLACK_BAR_DETECT.blackRatioMin;

  const rowStats = (y) => {
    let nearBlack = 0;
    let lumaSum = 0;
    const base = y * sw * 4;
    for (let x = 0; x < sw; x++) {
      const i = base + x * 4;
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const maxC = Math.max(r, g, b);
      if (maxC <= nearBlackMax) nearBlack++;
      lumaSum += 0.2126 * r + 0.7152 * g + 0.0722 * b;
    }
    return {
      ratio: nearBlack / sw,
      luma: lumaSum / sw,
    };
  };

  const colStats = (x) => {
    let nearBlack = 0;
    let lumaSum = 0;
    for (let y = 0; y < sh; y++) {
      const i = (y * sw + x) * 4;
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const maxC = Math.max(r, g, b);
      if (maxC <= nearBlackMax) nearBlack++;
      lumaSum += 0.2126 * r + 0.7152 * g + 0.0722 * b;
    }
    return {
      ratio: nearBlack / sh,
      luma: lumaSum / sh,
    };
  };

  const limitTopBottom = Math.max(
    1,
    Math.floor(sh * VIDEO_BLACK_BAR_DETECT.maxSideFrac),
  );
  const limitLeftRight = Math.max(
    1,
    Math.floor(sw * VIDEO_BLACK_BAR_DETECT.maxSideFrac),
  );

  let topPx = 0;
  while (topPx < limitTopBottom) {
    const s = rowStats(topPx);
    if (s.ratio >= ratioMin && s.luma <= nearBlackMax) topPx++;
    else break;
  }
  let bottomPx = 0;
  while (bottomPx < limitTopBottom) {
    const s = rowStats(sh - 1 - bottomPx);
    if (s.ratio >= ratioMin && s.luma <= nearBlackMax) bottomPx++;
    else break;
  }
  let leftPx = 0;
  while (leftPx < limitLeftRight) {
    const s = colStats(leftPx);
    if (s.ratio >= ratioMin && s.luma <= nearBlackMax) leftPx++;
    else break;
  }
  let rightPx = 0;
  while (rightPx < limitLeftRight) {
    const s = colStats(sw - 1 - rightPx);
    if (s.ratio >= ratioMin && s.luma <= nearBlackMax) rightPx++;
    else break;
  }

  const minTopBottom = Math.max(
    4,
    Math.round(sh * VIDEO_BLACK_BAR_DETECT.minSideFrac),
  );
  const minLeftRight = Math.max(
    4,
    Math.round(sw * VIDEO_BLACK_BAR_DETECT.minSideFrac),
  );
  const symY = Math.max(
    4,
    Math.round(sh * VIDEO_BLACK_BAR_DETECT.symmetryTolFrac),
  );
  const symX = Math.max(
    4,
    Math.round(sw * VIDEO_BLACK_BAR_DETECT.symmetryTolFrac),
  );

  if (
    topPx < minTopBottom ||
    bottomPx < minTopBottom ||
    Math.abs(topPx - bottomPx) > symY
  ) {
    topPx = 0;
    bottomPx = 0;
  }
  if (
    leftPx < minLeftRight ||
    rightPx < minLeftRight ||
    Math.abs(leftPx - rightPx) > symX
  ) {
    leftPx = 0;
    rightPx = 0;
  }

  if (!(topPx || bottomPx || leftPx || rightPx)) return null;

  const contentX = leftPx;
  const contentY = topPx;
  const contentW = sw - leftPx - rightPx;
  const contentH = sh - topPx - bottomPx;
  if (contentW < 16 || contentH < 16) return null;

  let contentLumaSum = 0;
  let contentSamples = 0;
  const xStep = Math.max(1, Math.floor(contentW / 64));
  const yStep = Math.max(1, Math.floor(contentH / 64));
  for (let y = contentY; y < contentY + contentH; y += yStep) {
    for (let x = contentX; x < contentX + contentW; x += xStep) {
      const i = (y * sw + x) * 4;
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      contentLumaSum += 0.2126 * r + 0.7152 * g + 0.0722 * b;
      contentSamples++;
    }
  }
  const contentLuma = contentSamples ? contentLumaSum / contentSamples : 0;
  if (contentLuma < VIDEO_BLACK_BAR_DETECT.centerMinLuma) return null;
  if (contentLuma - nearBlackMax < VIDEO_BLACK_BAR_DETECT.contrastMinLuma)
    return null;

  return normalizeVideoCrop({
    left: leftPx / sw,
    right: rightPx / sw,
    top: topPx / sh,
    bottom: bottomPx / sh,
  });
}

function updateVideoCropFromElement(rec, videoEl) {
  return false;
}

function applyVideoCropToElement(videoEl, rec) {
  if (!videoEl) return;
  videoEl.style.removeProperty("clip-path");
  videoEl.style.removeProperty("-webkit-clip-path");
  videoEl.style.removeProperty("transform-origin");
  videoEl.style.removeProperty("transform");
}

function getMediaFilterForType(target = undefined) {
  const cfg = resolveMediaOverlayConfigForTarget(target);
  return cfg ? "custom" : "off";
}

function getMediaFilterIntensity() {
  return 1;
}

function parseFilterNumberWithUnit(raw) {
  const m = String(raw || "")
    .trim()
    .match(/^(-?\d*\.?\d+)([a-z%]*)$/i);
  if (!m) return null;
  const value = parseFloat(m[1]);
  if (!Number.isFinite(value)) return null;
  return { value, unit: String(m[2] || "") };
}

function scaleCssFilterString(filterText, intensity) {
  const t = Math.max(
    0,
    Number.isFinite(Number(intensity)) ? Number(intensity) : 1,
  );
  const src = String(filterText || "").trim();
  if (!src || src === "none") return "none";
  if (t <= 0) return "none";
  if (t >= 1) return src;
  const re = /([a-z-]+)\(([^)]+)\)/gi;
  const out = [];
  let matched = false;
  let m = null;
  while ((m = re.exec(src)) !== null) {
    matched = true;
    const fn = String(m[1] || "").toLowerCase();
    const argRaw = String(m[2] || "").trim();
    const parsed = parseFilterNumberWithUnit(argRaw);
    if (!parsed) {
      out.push(`${fn}(${argRaw})`);
      continue;
    }
    const unit = parsed.unit;
    const target = parsed.value;
    let ident = null;
    if (fn === "saturate" || fn === "contrast" || fn === "brightness")
      ident = unit === "%" ? 100 : 1;
    else if (fn === "hue-rotate") ident = 0;
    else if (fn === "grayscale" || fn === "sepia" || fn === "invert") ident = 0;
    if (ident === null) {
      out.push(`${fn}(${argRaw})`);
      continue;
    }
    const next = ident + (target - ident) * t;
    const shown =
      Math.abs(next) >= 100 || Number.isInteger(next)
        ? String(Math.round(next))
        : next.toFixed(3).replace(/0+$/, "").replace(/\.$/, "");
    out.push(`${fn}(${shown}${unit})`);
  }
  if (!matched) return src;
  return out.length ? out.join(" ") : "none";
}

function scaleBaseFilterConfig(baseCfg, intensity) {
  if (!baseCfg) return null;
  const t = clampNumber(intensity, 0, 1, 1);
  if (!(t > 0)) return null;
  const out = {};
  for (const key of Object.keys(baseCfg)) {
    const value = baseCfg[key];
    if (key === "color") {
      const scaled = scaleCssFilterString(value, t);
      if (scaled && scaled !== "none") out.color = scaled;
      continue;
    }
    if (key === "forceMonochrome") {
      out.forceMonochrome = !!value && t >= 0.999;
      continue;
    }
    if (typeof value === "number" && Number.isFinite(value)) {
      out[key] = value * t;
      continue;
    }
    out[key] = value;
  }
  return out;
}

function buildCanvasFilterValue(colorFilter, blurPx = 0) {
  const color = String(colorFilter || "").trim();
  const hasColor = !!color && color !== "none";
  const blur = Number(blurPx);
  const hasBlur = Number.isFinite(blur) && blur > 0;
  if (hasColor && hasBlur) return `${color} blur(${blur}px)`;
  if (hasColor) return color;
  if (hasBlur) return `blur(${blur}px)`;
  return "none";
}

function animatedMediaFiltersMode() {
  return normalizeAnimatedMediaFiltersValue(
    MEDIA_FILTER_STATE.animatedMode,
    "on",
  );
}

function animatedMediaFiltersEnabledForType(type) {
  const mode = animatedMediaFiltersMode();
  if (mode === "off") return false;
  if (mode === "videos") return type === "video";
  return true;
}

function thumbFiltersEnabled() {
  return false;
}

function gifsIgnoreProcessingEnabled() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return !!(opt && opt.gifsIgnoreProcessing);
}

function isGifRecord(rec) {
  const ext = String(rec?.ext || "").toLowerCase();
  if (ext === ".gif") return true;
  const mime = String(rec?.file?.type || "").toLowerCase();
  return mime === "image/gif";
}

function mediaProcessingEnabledForTarget(target) {
  if (typeof target === "undefined" || target === null) return true;
  if (target && typeof target === "object") {
    if (isGifRecord(target) && gifsIgnoreProcessingEnabled()) return false;
  }
  return true;
}

function thumbFiltersActive(target) {
  if (!thumbFiltersEnabled()) return false;
  return !!resolveMediaOverlayConfigForTarget(target);
}

function buildThumbFilterKey() {
  return "nav-neutral";
}

function resizeCanvasBuffer(canvas, width, height) {
  if (!canvas) return;
  const w = Math.max(1, Math.round(width || 1));
  const h = Math.max(1, Math.round(height || 1));
  if (canvas.width !== w) canvas.width = w;
  if (canvas.height !== h) canvas.height = h;
}

function hashNoise1(seed) {
  const x = Math.sin(Number(seed || 0) * 12.9898) * 43758.5453123;
  return x - Math.floor(x);
}

function ensureEffectWorkCanvas(
  host,
  canvasKey,
  ctxKey,
  width,
  height,
  ctxOptions = undefined,
) {
  if (!host[canvasKey]) host[canvasKey] = document.createElement("canvas");
  const canvas = host[canvasKey];
  if (!host[ctxKey]) host[ctxKey] = canvas.getContext("2d", ctxOptions);
  const ctx = host[ctxKey];
  resizeCanvasBuffer(canvas, width, height);
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.imageSmoothingEnabled = true;
  ctx.filter = "none";
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  return { canvas, ctx };
}

function drawActualScanlinesToContext(ctx, rect, amount, options = null) {
  if (!ctx || !rect || !(amount > 0.0001)) return;
  const dpr = Math.max(1, Number(options && options.dpr) || 1);
  const alpha = clampNumber(0.16 + amount * 0.68, 0, 0.92);
  const glowAlpha = clampNumber(alpha * 0.24, 0, 0.22);
  const lineWidth = 1 / dpr;
  const x0 = Number(rect.x || 0);
  const x1 = x0 + Math.max(0, Number(rect.w || 0));
  const yStartPx = Math.floor(Number(rect.y || 0) * dpr);
  const yEndPx = Math.ceil(
    (Number(rect.y || 0) + Math.max(0, Number(rect.h || 0))) * dpr,
  );
  if (x1 <= x0 || yEndPx <= yStartPx) return;

  ctx.save();
  ctx.beginPath();
  ctx.rect(rect.x, rect.y, rect.w, rect.h);
  ctx.clip();
  ctx.globalCompositeOperation = "multiply";
  ctx.strokeStyle = `rgba(0,0,0,${alpha.toFixed(3)})`;
  ctx.lineWidth = lineWidth;
  ctx.beginPath();
  for (let yPx = yStartPx; yPx < yEndPx; yPx += 2) {
    const y = (yPx + 0.5) / dpr;
    ctx.moveTo(x0, y);
    ctx.lineTo(x1, y);
  }
  ctx.stroke();
  if (glowAlpha > 0.0001) {
    ctx.globalCompositeOperation = "screen";
    ctx.strokeStyle = `rgba(255,255,255,${glowAlpha.toFixed(3)})`;
    ctx.lineWidth = lineWidth;
    ctx.beginPath();
    for (let yPx = yStartPx + 1; yPx < yEndPx; yPx += 2) {
      const y = (yPx + 0.5) / dpr;
      ctx.moveTo(x0, y);
      ctx.lineTo(x1, y);
    }
    ctx.stroke();
  }
  ctx.restore();
}

function buildHalationMaskCanvas(sourceCanvas, amount, host) {
  if (!sourceCanvas || !(amount > 0.0001) || !host) return null;
  const srcW = Math.max(1, sourceCanvas.width || 1);
  const srcH = Math.max(1, sourceCanvas.height || 1);
  const sampleScale = clampNumber(0.16 + amount * 0.12, 0.16, 0.3);
  const sampleW = Math.max(12, Math.round(srcW * sampleScale));
  const sampleH = Math.max(12, Math.round(srcH * sampleScale));
  const extract = ensureEffectWorkCanvas(
    host,
    "halationExtractCanvas",
    "halationExtractCtx",
    sampleW,
    sampleH,
    { willReadFrequently: true },
  );
  extract.ctx.drawImage(sourceCanvas, 0, 0, sampleW, sampleH);
  let imageData = null;
  try {
    imageData = extract.ctx.getImageData(0, 0, sampleW, sampleH);
  } catch {
    imageData = null;
  }
  if (!imageData) return null;
  const data = imageData.data;
  const lumas = new Float32Array(sampleW * sampleH);
  for (let i = 0, px = 0; i < data.length; i += 4, px++) {
    lumas[px] =
      (data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114) / 255;
  }
  const threshold = clampNumber(0.68 - amount * 0.12, 0.5, 0.74);
  const highlightSoftness = 0.15 + amount * 0.08;
  const localSoftness = Math.max(0.05, 0.11 - amount * 0.03);
  for (let y = 0; y < sampleH; y++) {
    const yOff = y * sampleW;
    const yPrev = (y > 0 ? y - 1 : y) * sampleW;
    const yNext = (y + 1 < sampleH ? y + 1 : y) * sampleW;
    for (let x = 0; x < sampleW; x++) {
      const idx = yOff + x;
      const i = idx * 4;
      const luma = lumas[idx];
      const left = lumas[yOff + (x > 0 ? x - 1 : x)];
      const right = lumas[yOff + (x + 1 < sampleW ? x + 1 : x)];
      const up = lumas[yPrev + x];
      const down = lumas[yNext + x];
      const localAvg = (left + right + up + down) * 0.25;
      const localPeak = luma - localAvg;
      const localEdge = Math.max(
        Math.abs(luma - left),
        Math.abs(luma - right),
        Math.abs(luma - up),
        Math.abs(luma - down),
      );
      const peakMask = clampNumber(
        (luma - threshold) / highlightSoftness,
        0,
        1,
      );
      const isolationMask = clampNumber(
        (localPeak + localEdge * 0.55 - 0.015) / localSoftness,
        0,
        1,
      );
      const coreMask = clampNumber((luma - 0.9) / 0.07, 0, 1);
      const mask = clampNumber(
        peakMask * (0.25 + isolationMask * 1.05) + coreMask * 0.35,
        0,
        1,
      );
      if (mask <= 0.0001) {
        data[i] = 255;
        data[i + 1] = 255;
        data[i + 2] = 255;
        data[i + 3] = 0;
        continue;
      }
      const warm = clampNumber(isolationMask * (0.5 + amount * 0.18), 0, 0.72);
      const whiteLift = clampNumber(coreMask * 0.9, 0, 0.9);
      data[i] = 255;
      data[i + 1] = clampNumber(
        Math.round(228 + warm * 16 + whiteLift * 18),
        0,
        255,
        255,
      );
      data[i + 2] = clampNumber(
        Math.round(196 + whiteLift * 56 - warm * 24),
        0,
        255,
        255,
      );
      data[i + 3] = Math.round(255 * Math.pow(mask, 0.76));
    }
  }
  extract.ctx.putImageData(imageData, 0, 0);
  return extract;
}

function drawHalationToContext(ctx, sourceCanvas, rect, amount, host) {
  if (!ctx || !sourceCanvas || !rect || !(amount > 0.0001) || !host) return;
  const extract = buildHalationMaskCanvas(sourceCanvas, amount, host);
  if (!extract) return;
  const minSide = Math.max(1, Math.min(rect.w, rect.h));
  const workW = Math.max(12, Math.round(rect.w * 0.38));
  const workH = Math.max(12, Math.round(rect.h * 0.38));
  const work = ensureEffectWorkCanvas(
    host,
    "halationWorkCanvas",
    "halationWorkCtx",
    workW,
    workH,
  );
  const bloomBlur = 0.6 + amount * 2.2;
  const coreBlur = 0.3 + amount * 0.95;
  const smearPx = Math.max(
    1,
    (minSide * 0.004 + amount * 7) * (workH / Math.max(1, rect.h)),
  );
  const steps = Math.max(1, Math.round(2 + amount * 2));
  work.ctx.imageSmoothingEnabled = true;
  work.ctx.filter = `blur(${bloomBlur.toFixed(2)}px)`;
  work.ctx.globalCompositeOperation = "source-over";
  work.ctx.globalAlpha = 1;
  work.ctx.drawImage(extract.canvas, 0, 0, workW, workH);
  work.ctx.globalCompositeOperation = "lighter";
  for (let step = 1; step <= steps; step++) {
    const falloff = 1 - step / (steps + 1);
    const offset = smearPx * step;
    work.ctx.globalAlpha = clampNumber(
      (0.12 + amount * 0.16) * falloff,
      0,
      0.32,
    );
    work.ctx.drawImage(extract.canvas, 0, offset, workW, workH);
    work.ctx.drawImage(extract.canvas, 0, -(offset * 0.55), workW, workH);
  }
  work.ctx.globalCompositeOperation = "screen";
  work.ctx.globalAlpha = clampNumber(0.25 + amount * 0.18, 0, 0.42);
  work.ctx.filter = `blur(${coreBlur.toFixed(2)}px)`;
  work.ctx.drawImage(extract.canvas, 0, 0, workW, workH);
  work.ctx.filter = "none";
  work.ctx.globalAlpha = 1;
  work.ctx.globalCompositeOperation = "source-over";
  ctx.save();
  ctx.beginPath();
  ctx.rect(rect.x, rect.y, rect.w, rect.h);
  ctx.clip();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = clampNumber(0.12 + amount * 0.26, 0, 0.42);
  ctx.filter = "none";
  ctx.drawImage(work.canvas, rect.x, rect.y, rect.w, rect.h);
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = clampNumber(0.04 + amount * 0.08, 0, 0.14);
  ctx.drawImage(extract.canvas, rect.x, rect.y, rect.w, rect.h);
  ctx.restore();
}

function drawTemporalGhostingToContext(
  ctx,
  sourceCanvas,
  rect,
  amount,
  time,
  host,
  options = null,
) {
  if (!ctx || !sourceCanvas || !rect || !(amount > 0.0001) || !host) return;
  const w = Math.max(1, Math.round(rect.w));
  const h = Math.max(1, Math.round(rect.h));
  const animated = !!(options && options.animated);
  const ghostScale = clampNumber(0.58 - amount * 0.18, 0.34, 0.58);
  const ghostW = Math.max(12, Math.round(w * ghostScale));
  const ghostH = Math.max(12, Math.round(h * ghostScale));
  if (!host.ghostPrevCanvas)
    host.ghostPrevCanvas = document.createElement("canvas");
  if (!host.ghostPrevCtx)
    host.ghostPrevCtx = host.ghostPrevCanvas.getContext("2d");
  if (!host.ghostWorkCanvas)
    host.ghostWorkCanvas = document.createElement("canvas");
  if (!host.ghostWorkCtx)
    host.ghostWorkCtx = host.ghostWorkCanvas.getContext("2d");
  resizeCanvasBuffer(host.ghostPrevCanvas, ghostW, ghostH);
  resizeCanvasBuffer(host.ghostWorkCanvas, ghostW, ghostH);
  const prevCtx = host.ghostPrevCtx;
  const workCtx = host.ghostWorkCtx;
  const hasPrev = animated && !!host.ghostHasFrame;
  workCtx.setTransform(1, 0, 0, 1, 0, 0);
  workCtx.clearRect(0, 0, ghostW, ghostH);
  workCtx.imageSmoothingEnabled = true;
  const shiftX =
    (animated ? Math.sin((time || 0) * 0.0031) : 0.75) *
    (0.9 + amount * 5.4) *
    (ghostW / Math.max(1, w));
  const shiftY =
    (animated ? Math.cos((time || 0) * 0.0022) * 0.35 * amount : 0) *
    (ghostH / Math.max(1, h));
  workCtx.filter = `blur(${Math.max(0.35, 0.45 + amount * 0.85).toFixed(2)}px)`;
  if (hasPrev) {
    workCtx.drawImage(host.ghostPrevCanvas, shiftX, shiftY, ghostW, ghostH);
  } else {
    workCtx.drawImage(sourceCanvas, shiftX, shiftY, ghostW, ghostH);
  }
  workCtx.filter = "none";

  ctx.save();
  ctx.beginPath();
  ctx.rect(rect.x, rect.y, rect.w, rect.h);
  ctx.clip();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = clampNumber(0.08 + amount * 0.26, 0, 0.38);
  ctx.drawImage(host.ghostWorkCanvas, rect.x, rect.y, rect.w, rect.h);
  ctx.restore();

  if (animated) {
    prevCtx.setTransform(1, 0, 0, 1, 0, 0);
    prevCtx.clearRect(0, 0, ghostW, ghostH);
    prevCtx.imageSmoothingEnabled = true;
    prevCtx.filter = "none";
    prevCtx.drawImage(sourceCanvas, 0, 0, ghostW, ghostH);
    host.ghostHasFrame = true;
  } else {
    host.ghostHasFrame = false;
  }
}

function drawLineDamageToContext(
  ctx,
  sourceCanvas,
  rect,
  amount,
  time,
  host,
  options = null,
) {
  if (!ctx || !sourceCanvas || !rect || !(amount > 0.0001) || !host) return;
  const w = Math.max(1, Math.round(rect.w));
  const h = Math.max(1, Math.round(rect.h));
  const animated = !!(options && options.animated);
  const baseSeed = animated ? Number(time || 0) * 0.0027 : 13.25;
  const layerScale = clampNumber(0.52 - amount * 0.12, 0.34, 0.52);
  const layerW = Math.max(24, Math.round(w * layerScale));
  const layerH = Math.max(24, Math.round(h * layerScale));
  const layer = ensureEffectWorkCanvas(
    host,
    "lineDamageCanvas",
    "lineDamageCtx",
    layerW,
    layerH,
  );
  const lctx = layer.ctx;
  const targetBands = Math.max(48, Math.round(70 + amount * 80));
  const stripH = Math.max(1, Math.ceil(layerH / targetBands));
  for (let y = 0; y < layerH; y += stripH) {
    const seed = baseSeed + y * 0.091;
    let shift = (hashNoise1(seed) - 0.5) * amount * 5.2;
    if (hashNoise1(seed * 1.8) > 0.958) {
      shift += (hashNoise1(seed * 3.4) > 0.5 ? 1 : -1) * (1 + amount * 5.5);
    }
    lctx.globalAlpha = clampNumber(0.18 + amount * 0.26, 0, 0.42);
    const srcY = Math.floor((y / layerH) * sourceCanvas.height);
    const srcH = Math.max(
      1,
      Math.ceil((Math.min(stripH, layerH - y) / layerH) * sourceCanvas.height),
    );
    lctx.drawImage(
      sourceCanvas,
      0,
      srcY,
      sourceCanvas.width,
      srcH,
      shift,
      y,
      layerW,
      Math.min(stripH, layerH - y),
    );
    if (hashNoise1(seed * 2.7) > 0.88) {
      const alpha = clampNumber(0.02 + amount * 0.08, 0, 0.14);
      lctx.fillStyle =
        hashNoise1(seed * 4.1) > 0.5
          ? `rgba(255,255,255,${alpha.toFixed(3)})`
          : `rgba(0,0,0,${alpha.toFixed(3)})`;
      lctx.fillRect(0, y, layerW, Math.max(1, Math.round(stripH * 0.5)));
    }
  }
  lctx.globalAlpha = 1;

  ctx.save();
  ctx.beginPath();
  ctx.rect(rect.x, rect.y, rect.w, rect.h);
  ctx.clip();
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = clampNumber(0.34 + amount * 0.22, 0, 0.62);
  ctx.drawImage(layer.canvas, rect.x, rect.y, rect.w, rect.h);
  ctx.restore();
}

function drawJitterWarpToCanvas(
  targetCtx,
  sourceCanvas,
  amount,
  time,
  options = null,
) {
  if (!targetCtx || !sourceCanvas || !(amount > 0.0001)) return false;
  const w = Math.max(1, sourceCanvas.width || 0);
  const h = Math.max(1, sourceCanvas.height || 0);
  if (!w || !h) return false;
  const animated = !!(options && options.animated);
  const speed = clampNumber(0.05 + amount * 0.95, 0.05, 1, 0.05);
  const t = animated ? Number(time || 0) * 0.001 * speed : 12.75;
  const amplitude = Math.min(Math.max(0.9, 0.75 * 2.8), Math.max(3, w * 0.04));
  const bandCount = Math.max(18, Math.round(18 + 0.75 * 11));
  const stripH = Math.max(1, Math.ceil(h / bandCount));
  targetCtx.setTransform(1, 0, 0, 1, 0, 0);
  targetCtx.clearRect(0, 0, w, h);
  targetCtx.imageSmoothingEnabled = true;
  if ("imageSmoothingQuality" in targetCtx)
    targetCtx.imageSmoothingQuality = "high";
  targetCtx.filter = "none";
  targetCtx.globalCompositeOperation = "source-over";
  targetCtx.globalAlpha = 1;
  const drawStripWithExtrudedEdges = (
    stripY,
    stripH,
    drawOffset,
    alpha = 1,
  ) => {
    targetCtx.globalAlpha = alpha;
    targetCtx.drawImage(
      sourceCanvas,
      0,
      stripY,
      w,
      stripH,
      drawOffset,
      stripY,
      w,
      stripH,
    );
    targetCtx.globalAlpha = 1;
    if (drawOffset > 0.0001) {
      targetCtx.drawImage(
        sourceCanvas,
        0,
        stripY,
        1,
        stripH,
        0,
        stripY,
        drawOffset,
        stripH,
      );
    } else if (drawOffset < -0.0001) {
      const gapW = -drawOffset;
      targetCtx.drawImage(
        sourceCanvas,
        w - 1,
        stripY,
        1,
        stripH,
        w - gapW,
        stripY,
        gapW,
        stripH,
      );
    }
  };

  for (let y = 0; y < h; y += stripH) {
    const sh = Math.min(stripH, h - y);
    const yNorm = y / Math.max(1, h);
    const phaseA = yNorm * 12.5 + t * 6.3;
    const phaseB =
      yNorm * 31.5 - t * 10.1 + hashNoise1((y + 1) * 0.173) * Math.PI * 2;
    const phaseC =
      yNorm * 8.4 + t * 3.4 + hashNoise1((y + 7) * 0.067) * Math.PI * 2;
    const offset =
      (Math.sin(phaseA) * 0.58 +
        Math.sin(phaseB) * 0.27 +
        Math.sin(phaseC) * 0.15) *
      amplitude;
    drawStripWithExtrudedEdges(y, sh, offset);
    if (animated) {
      const shimmerAlpha = clampNumber(0.018 + 0.75 * 0.018, 0, 0.08);
      if (shimmerAlpha > 0.0001) {
        drawStripWithExtrudedEdges(
          y,
          sh,
          offset + Math.sin(phaseB * 1.7) * (0.35 + 0.75 * 0.3),
          shimmerAlpha,
        );
      }
    }
  }
  targetCtx.globalAlpha = 1;
  targetCtx.filter = "none";
  return true;
}

function drawVhsFuzzToContext(
  ctx,
  sourceCanvas,
  rect,
  amount,
  time,
  host,
  options = null,
) {
  if (!ctx || !sourceCanvas || !rect || !(amount > 0.0001) || !host) return;
  const w = Math.max(1, Math.round(rect.w));
  const h = Math.max(1, Math.round(rect.h));
  if (!w || !h) return;
  const animated = !!(options && options.animated);
  const baseSeed = animated ? Number(time || 0) * 0.0014 : 47.35;
  const lowScale = clampNumber(0.58 - amount * 0.22, 0.28, 0.58);
  const lowW = Math.max(8, Math.round(w * lowScale));
  const lowH = Math.max(8, Math.round(h * lowScale));
  const lowLayer = ensureEffectWorkCanvas(
    host,
    "vhsFuzzLowCanvas",
    "vhsFuzzLowCtx",
    lowW,
    lowH,
  );
  const stripLayer = ensureEffectWorkCanvas(
    host,
    "vhsFuzzStripCanvas",
    "vhsFuzzStripCtx",
    w,
    h,
  );
  const fuzzLayer = ensureEffectWorkCanvas(
    host,
    "vhsFuzzCanvas",
    "vhsFuzzCtx",
    lowW,
    lowH,
  );
  const lowCtx = lowLayer.ctx;
  const stripCtx = stripLayer.ctx;
  const fuzzCtx = fuzzLayer.ctx;
  lowCtx.imageSmoothingEnabled = true;
  lowCtx.filter = "none";
  lowCtx.drawImage(sourceCanvas, 0, 0, lowW, lowH);

  stripCtx.imageSmoothingEnabled = true;
  stripCtx.filter = `blur(${(0.25 + amount * 0.45).toFixed(2)}px)`;
  stripCtx.drawImage(lowLayer.canvas, 0, 0, w, h);
  stripCtx.filter = "none";

  const targetBands = Math.max(44, Math.round(56 + amount * 52));
  const stripH = Math.max(2, Math.ceil(h / targetBands));
  for (let y = 0; y < h; y += stripH) {
    const seed = baseSeed + y * 0.071;
    const sy = Math.max(0, Math.floor((y / h) * lowH));
    const sh = Math.max(1, Math.ceil((Math.min(stripH, h - y) / h) * lowH));
    let offset = (hashNoise1(seed) - 0.5) * (0.45 + amount * 2);
    offset +=
      Math.sin(seed * 7.3 + (animated ? time * 0.0012 : 0)) *
      (0.12 + amount * 0.45);
    stripCtx.globalAlpha = clampNumber(0.05 + amount * 0.08, 0, 0.12);
    stripCtx.drawImage(
      lowLayer.canvas,
      0,
      sy,
      lowW,
      sh,
      offset,
      y,
      w,
      Math.min(stripH, h - y),
    );
  }
  stripCtx.globalAlpha = 1;

  fuzzCtx.imageSmoothingEnabled = true;
  fuzzCtx.drawImage(stripLayer.canvas, 0, 0, lowW, lowH);
  fuzzCtx.globalCompositeOperation = "screen";
  fuzzCtx.globalAlpha = clampNumber(0.02 + amount * 0.05, 0, 0.08);
  fuzzCtx.drawImage(stripLayer.canvas, 0.2 + amount * 0.55, 0, lowW, lowH);
  fuzzCtx.globalCompositeOperation = "multiply";
  fuzzCtx.globalAlpha = clampNumber(0.025 + amount * 0.04, 0, 0.07);
  fuzzCtx.drawImage(stripLayer.canvas, -(0.15 + amount * 0.35), 0, lowW, lowH);
  fuzzCtx.globalCompositeOperation = "source-over";
  fuzzCtx.globalAlpha = 1;

  const hazeCount = Math.max(1, Math.round(1 + amount * 2));
  for (let i = 0; i < hazeCount; i++) {
    const seed = baseSeed + 100 + i * 19.37;
    const bandY = Math.floor(hashNoise1(seed) * lowH);
    const bandH = Math.max(
      4,
      Math.round(4 + hashNoise1(seed * 1.4) * (6 + amount * 8)),
    );
    const alpha = clampNumber(
      (0.012 + amount * 0.022) * (0.7 + hashNoise1(seed * 2.1) * 0.6),
      0,
      0.05,
    );
    fuzzCtx.fillStyle =
      hashNoise1(seed * 2.8) > 0.5
        ? `rgba(255,255,255,${alpha.toFixed(3)})`
        : `rgba(0,0,0,${(alpha * 0.9).toFixed(3)})`;
    fuzzCtx.fillRect(0, bandY, lowW, Math.min(bandH, lowH - bandY));
  }

  ctx.save();
  ctx.beginPath();
  ctx.rect(rect.x, rect.y, rect.w, rect.h);
  ctx.clip();
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = clampNumber(0.14 + amount * 0.18, 0, 0.32);
  ctx.filter = `blur(${Math.max(0.2, 0.25 + amount * 0.35).toFixed(2)}px)`;
  ctx.drawImage(fuzzLayer.canvas, rect.x, rect.y, rect.w, rect.h);
  ctx.globalAlpha = clampNumber(0.04 + amount * 0.1, 0, 0.14);
  ctx.filter = `blur(${Math.max(0.25, 0.35 + amount * 0.45).toFixed(2)}px)`;
  ctx.drawImage(lowLayer.canvas, rect.x, rect.y, rect.w, rect.h);
  ctx.filter = "none";
  ctx.restore();
}

function applyPixelOpsToCanvas(canvas, config) {
  if (!canvas || !config) return;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) return;
  const width = canvas.width || 0;
  const height = canvas.height || 0;
  if (!width || !height) return;
  const temperature = clampNumber(
    config.temperature,
    OVERLAY_SLIDER_LIMITS.warmth.min,
    OVERLAY_SLIDER_LIMITS.warmth.max,
    0,
  );
  const colorCrush = clampNumber(
    config.colorCrush,
    0,
    OVERLAY_SLIDER_LIMITS.colorCrush.max,
    0,
  );
  const blackCrush = clampNumber(
    config.blackCrush,
    0,
    OVERLAY_SLIDER_LIMITS.blackCrush.max,
    0,
  );
  const whiteCrush = clampNumber(
    config.whiteCrush,
    0,
    OVERLAY_SLIDER_LIMITS.whiteCrush.max,
    0,
  );
  if (
    !(
      Math.abs(temperature) > 0.0001 ||
      colorCrush > 0 ||
      blackCrush > 0 ||
      whiteCrush > 0
    )
  )
    return;
  let imageData = null;
  try {
    imageData = ctx.getImageData(0, 0, width, height);
  } catch {
    imageData = null;
  }
  if (!imageData) return;
  const data = imageData.data;
  const crushLevels =
    colorCrush > 0 ? Math.max(2, Math.round(24 - colorCrush * 10)) : 0;
  const blackFloor = blackCrush > 0 ? blackCrush * 255 : 0;
  const whiteCeil = whiteCrush > 0 ? 255 - whiteCrush * 255 : 255;
  for (let i = 0; i < data.length; i += 4) {
    let r = data[i];
    let g = data[i + 1];
    let b = data[i + 2];

    if (Math.abs(temperature) > 0.0001) {
      const prevLuma = 0.2126 * r + 0.7152 * g + 0.0722 * b;
      const redMul = 1 + temperature * 0.22;
      const greenMul = 1 + temperature * 0.05;
      const blueMul = 1 - temperature * 0.24;
      r *= redMul;
      g *= greenMul;
      b *= blueMul;
      const nextLuma = 0.2126 * r + 0.7152 * g + 0.0722 * b;
      const lumaOffset = prevLuma - nextLuma;
      r += lumaOffset;
      g += lumaOffset;
      b += lumaOffset;
    }

    if (colorCrush > 0 && crushLevels > 1) {
      const snap = 255 / (crushLevels - 1);
      r = Math.round(r / snap) * snap;
      g = Math.round(g / snap) * snap;
      b = Math.round(b / snap) * snap;
    }

    if (blackFloor > 0) {
      r =
        r <= blackFloor
          ? 0
          : ((r - blackFloor) / Math.max(1, 255 - blackFloor)) * 255;
      g =
        g <= blackFloor
          ? 0
          : ((g - blackFloor) / Math.max(1, 255 - blackFloor)) * 255;
      b =
        b <= blackFloor
          ? 0
          : ((b - blackFloor) / Math.max(1, 255 - blackFloor)) * 255;
    }
    if (whiteCeil < 255) {
      r = r >= whiteCeil ? 255 : (r / Math.max(1, whiteCeil)) * 255;
      g = g >= whiteCeil ? 255 : (g / Math.max(1, whiteCeil)) * 255;
      b = b >= whiteCeil ? 255 : (b / Math.max(1, whiteCeil)) * 255;
    }

    data[i] = clampNumber(r, 0, 255, 0);
    data[i + 1] = clampNumber(g, 0, 255, 0);
    data[i + 2] = clampNumber(b, 0, 255, 0);
  }
  ctx.putImageData(imageData, 0, 0);
}

function drawChannelIsolatedCanvas(targetCtx, sourceCanvas, tint) {
  if (!targetCtx || !sourceCanvas) return;
  const width = sourceCanvas.width || 0;
  const height = sourceCanvas.height || 0;
  if (!width || !height) return;
  targetCtx.setTransform(1, 0, 0, 1, 0, 0);
  targetCtx.clearRect(0, 0, width, height);
  targetCtx.globalCompositeOperation = "copy";
  targetCtx.drawImage(sourceCanvas, 0, 0, width, height);
  targetCtx.globalCompositeOperation = "multiply";
  targetCtx.fillStyle = tint;
  targetCtx.fillRect(0, 0, width, height);
  targetCtx.globalCompositeOperation = "source-over";
}

function drawChromaticAberrationToContext(
  targetCtx,
  sourceCanvas,
  dx,
  dy,
  dw,
  dh,
  amount,
  buffers = null,
) {
  if (!targetCtx || !sourceCanvas) return false;
  const shift = Number(amount);
  if (!Number.isFinite(shift) || shift <= 0.0001) return false;
  const width = sourceCanvas.width || 0;
  const height = sourceCanvas.height || 0;
  if (!width || !height) return false;
  const compositeCanvas =
    buffers && buffers.compositeCanvas
      ? buffers.compositeCanvas
      : document.createElement("canvas");
  const channelCanvas =
    buffers && buffers.channelCanvas
      ? buffers.channelCanvas
      : document.createElement("canvas");
  resizeCanvasBuffer(compositeCanvas, width, height);
  resizeCanvasBuffer(channelCanvas, width, height);
  const compositeCtx =
    buffers && buffers.compositeCtx
      ? buffers.compositeCtx
      : compositeCanvas.getContext("2d");
  const channelCtx =
    buffers && buffers.channelCtx
      ? buffers.channelCtx
      : channelCanvas.getContext("2d");
  if (!compositeCtx || !channelCtx) return false;
  const xShift = shift;
  const yShift = shift * 0.18;

  compositeCtx.setTransform(1, 0, 0, 1, 0, 0);
  compositeCtx.clearRect(0, 0, width, height);

  drawChannelIsolatedCanvas(channelCtx, sourceCanvas, "rgb(255, 0, 0)");
  compositeCtx.globalCompositeOperation = "copy";
  compositeCtx.drawImage(channelCanvas, -xShift, -yShift, width, height);

  drawChannelIsolatedCanvas(channelCtx, sourceCanvas, "rgb(0, 255, 0)");
  compositeCtx.globalCompositeOperation = "lighter";
  compositeCtx.drawImage(channelCanvas, 0, 0, width, height);

  drawChannelIsolatedCanvas(channelCtx, sourceCanvas, "rgb(0, 0, 255)");
  compositeCtx.drawImage(channelCanvas, xShift, yShift, width, height);

  compositeCtx.globalCompositeOperation = "destination-in";
  compositeCtx.drawImage(sourceCanvas, 0, 0, width, height);
  compositeCtx.globalCompositeOperation = "source-over";

  targetCtx.drawImage(compositeCanvas, dx, dy, dw, dh);
  return true;
}

function crtOverlayEnabled(target = undefined) {
  if (typeof target !== "undefined")
    return !!resolveMediaOverlayConfigForTarget(target);
  return anyMediaFilterEnabled();
}

const THUMB_FILTER_CACHE = {
  noiseCanvas: null,
  noiseCtx: null,
  scanCanvas: null,
  scanPattern: null,
  halationExtractCanvas: null,
  halationExtractCtx: null,
  vhsFuzzCanvas: null,
  vhsFuzzCtx: null,
  vhsFuzzStripCanvas: null,
  vhsFuzzStripCtx: null,
  vhsFuzzLowCanvas: null,
  vhsFuzzLowCtx: null,
  lastNoise: 0,
};

function ensureThumbNoiseCanvas() {
  if (!THUMB_FILTER_CACHE.noiseCanvas) {
    const c = document.createElement("canvas");
    c.width = 128;
    c.height = 128;
    THUMB_FILTER_CACHE.noiseCanvas = c;
    THUMB_FILTER_CACHE.noiseCtx = c.getContext("2d");
  }
  return THUMB_FILTER_CACHE.noiseCanvas;
}

function updateThumbNoiseCanvas() {
  const c = ensureThumbNoiseCanvas();
  const ctx = THUMB_FILTER_CACHE.noiseCtx;
  const imageData = ctx.createImageData(c.width, c.height);
  const data = imageData.data;
  for (let i = 0; i < data.length; i += 4) {
    const v = Math.floor(Math.random() * 255);
    data[i] = v;
    data[i + 1] = v;
    data[i + 2] = v;
    data[i + 3] = 255;
  }
  ctx.putImageData(imageData, 0, 0);
  THUMB_FILTER_CACHE.lastNoise = Date.now();
}

function ensureThumbScanlinePattern(ctx) {
  if (!THUMB_FILTER_CACHE.scanCanvas) {
    const c = document.createElement("canvas");
    c.width = 1;
    c.height = 2;
    const sctx = c.getContext("2d");
    sctx.clearRect(0, 0, 1, 2);
    sctx.fillStyle = "rgba(0,0,0,0.82)";
    sctx.fillRect(0, 0, 1, 1);
    THUMB_FILTER_CACHE.scanCanvas = c;
    THUMB_FILTER_CACHE.scanPattern = null;
  }
  if (
    !THUMB_FILTER_CACHE.scanPattern ||
    THUMB_FILTER_CACHE.scanPattern._ctx !== ctx
  ) {
    const pattern = ctx.createPattern(THUMB_FILTER_CACHE.scanCanvas, "repeat");
    if (pattern) pattern._ctx = ctx;
    THUMB_FILTER_CACHE.scanPattern = pattern;
  }
  return THUMB_FILTER_CACHE.scanPattern;
}

function renderFilteredToCanvas(
  ctx,
  source,
  srcW,
  srcH,
  dstW,
  dstH,
  mode,
  cover = true,
  target = undefined,
  options = null,
) {
  const forceOverlayConfig =
    options && Object.prototype.hasOwnProperty.call(options, "overlayConfig")
      ? options.overlayConfig
      : undefined;
  const allowFilters =
    typeof forceOverlayConfig !== "undefined"
      ? true
      : thumbFiltersActive(target);
  const overlayCfg =
    typeof forceOverlayConfig !== "undefined"
      ? forceOverlayConfig
      : allowFilters
        ? resolveMediaOverlayConfigForTarget(target)
        : null;
  const sourceCrop = computeCroppedSourceRect(
    srcW,
    srcH,
    getVideoCropForTarget(target),
  );
  const croppedSrcW = Math.max(1, Number(sourceCrop.sw || srcW || 1));
  const croppedSrcH = Math.max(1, Number(sourceCrop.sh || srcH || 1));
  const drawCropped = (targetCtx, dx, dy, dw, dh) => {
    if (sourceCrop.sw > 0 && sourceCrop.sh > 0) {
      targetCtx.drawImage(
        source,
        sourceCrop.sx,
        sourceCrop.sy,
        sourceCrop.sw,
        sourceCrop.sh,
        dx,
        dy,
        dw,
        dh,
      );
      return;
    }
    targetCtx.drawImage(source, dx, dy, dw, dh);
  };
  if (!overlayCfg) {
    const rect = cover
      ? computeCoverRect(croppedSrcW, croppedSrcH, dstW, dstH)
      : computeContainRect(croppedSrcW, croppedSrcH, dstW, dstH);
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, dstW, dstH);
    ctx.filter = "none";
    ctx.imageSmoothingEnabled = true;
    drawCropped(ctx, rect.x, rect.y, rect.w, rect.h);
    return;
  }
  const rect = cover
    ? computeCoverRect(croppedSrcW, croppedSrcH, dstW, dstH)
    : computeContainRect(croppedSrcW, croppedSrcH, dstW, dstH);
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, dstW, dstH);

  const work = document.createElement("canvas");
  const scratch = document.createElement("canvas");
  const off = document.createElement("canvas");
  resizeCanvasBuffer(work, rect.w, rect.h);
  resizeCanvasBuffer(scratch, rect.w, rect.h);
  const workctx = work.getContext("2d");
  const scratchctx = scratch.getContext("2d", { willReadFrequently: true });
  const fitRect = cover
    ? computeCoverRect(croppedSrcW, croppedSrcH, work.width, work.height)
    : computeContainRect(croppedSrcW, croppedSrcH, work.width, work.height);
  workctx.setTransform(1, 0, 0, 1, 0, 0);
  workctx.clearRect(0, 0, work.width, work.height);
  workctx.imageSmoothingEnabled = true;
  workctx.filter = "none";
  drawCropped(workctx, fitRect.x, fitRect.y, fitRect.w, fitRect.h);

  let currentCanvas = work;
  let currentCtx = workctx;
  let scratchCanvas = scratch;
  let scratchCtx = scratchctx;
  const swapBuffers = () => {
    const oldCanvas = currentCanvas;
    const oldCtx = currentCtx;
    currentCanvas = scratchCanvas;
    currentCtx = scratchCtx;
    scratchCanvas = oldCanvas;
    scratchCtx = oldCtx;
  };
  const colorFilter =
    Array.isArray(overlayCfg.colorFilters) && overlayCfg.colorFilters.length
      ? overlayCfg.colorFilters.join(" ")
      : "none";
  if (colorFilter !== "none") {
    resizeCanvasBuffer(
      scratchCanvas,
      currentCanvas.width,
      currentCanvas.height,
    );
    scratchCtx.setTransform(1, 0, 0, 1, 0, 0);
    scratchCtx.clearRect(0, 0, scratchCanvas.width, scratchCanvas.height);
    scratchCtx.imageSmoothingEnabled = true;
    scratchCtx.filter = colorFilter;
    scratchCtx.drawImage(
      currentCanvas,
      0,
      0,
      scratchCanvas.width,
      scratchCanvas.height,
    );
    scratchCtx.filter = "none";
    swapBuffers();
  }
  applyPixelOpsToCanvas(currentCanvas, overlayCfg);
  if (overlayCfg.pixelate > 0) {
    const scale = Math.max(1, overlayCfg.pixelate);
    resizeCanvasBuffer(
      off,
      Math.max(1, Math.round(currentCanvas.width / scale)),
      Math.max(1, Math.round(currentCanvas.height / scale)),
    );
    const offctx = off.getContext("2d");
    offctx.setTransform(1, 0, 0, 1, 0, 0);
    offctx.clearRect(0, 0, off.width, off.height);
    offctx.imageSmoothingEnabled = true;
    offctx.filter = "none";
    offctx.drawImage(currentCanvas, 0, 0, off.width, off.height);
    resizeCanvasBuffer(
      scratchCanvas,
      currentCanvas.width,
      currentCanvas.height,
    );
    scratchCtx.setTransform(1, 0, 0, 1, 0, 0);
    scratchCtx.clearRect(0, 0, scratchCanvas.width, scratchCanvas.height);
    scratchCtx.imageSmoothingEnabled = false;
    scratchCtx.filter = "none";
    scratchCtx.drawImage(off, 0, 0, scratchCanvas.width, scratchCanvas.height);
    swapBuffers();
  }
  if (overlayCfg.blur > 0) {
    resizeCanvasBuffer(
      scratchCanvas,
      currentCanvas.width,
      currentCanvas.height,
    );
    scratchCtx.setTransform(1, 0, 0, 1, 0, 0);
    scratchCtx.clearRect(0, 0, scratchCanvas.width, scratchCanvas.height);
    scratchCtx.imageSmoothingEnabled = true;
    scratchCtx.filter = `blur(${overlayCfg.blur}px)`;
    scratchCtx.drawImage(
      currentCanvas,
      0,
      0,
      scratchCanvas.width,
      scratchCanvas.height,
    );
    scratchCtx.filter = "none";
    swapBuffers();
  }
  const outputRect = rect;
  ctx.imageSmoothingEnabled = true;
  ctx.filter = "none";
  if (
    !drawChromaticAberrationToContext(
      ctx,
      currentCanvas,
      outputRect.x,
      outputRect.y,
      outputRect.w,
      outputRect.h,
      overlayCfg.chroma,
    )
  ) {
    ctx.drawImage(
      currentCanvas,
      outputRect.x,
      outputRect.y,
      outputRect.w,
      outputRect.h,
    );
  }

  if (overlayCfg.halation) {
    drawHalationToContext(
      ctx,
      currentCanvas,
      outputRect,
      overlayCfg.halation,
      THUMB_FILTER_CACHE,
    );
  }

  if (overlayCfg.ghosting) {
    drawTemporalGhostingToContext(
      ctx,
      currentCanvas,
      outputRect,
      overlayCfg.ghosting,
      0,
      THUMB_FILTER_CACHE,
      { animated: false },
    );
  }

  if (overlayCfg.lineDamage) {
    drawLineDamageToContext(
      ctx,
      currentCanvas,
      outputRect,
      overlayCfg.lineDamage,
      0,
      THUMB_FILTER_CACHE,
      { animated: false },
    );
  }

  if (overlayCfg.grain) {
    ctx.save();
    ctx.beginPath();
    ctx.rect(outputRect.x, outputRect.y, outputRect.w, outputRect.h);
    ctx.clip();
    if (!THUMB_FILTER_CACHE.lastNoise) updateThumbNoiseCanvas();
    const noiseCanvas = ensureThumbNoiseCanvas();
    const pattern = ctx.createPattern(noiseCanvas, "repeat");
    if (pattern) {
      ctx.globalAlpha = overlayCfg.grain;
      ctx.globalCompositeOperation = "overlay";
      ctx.fillStyle = pattern;
      ctx.fillRect(outputRect.x, outputRect.y, outputRect.w, outputRect.h);
    }
    ctx.restore();
  }

  if (overlayCfg.vignette) {
    ctx.save();
    ctx.beginPath();
    ctx.rect(outputRect.x, outputRect.y, outputRect.w, outputRect.h);
    ctx.clip();
    const cx = outputRect.x + outputRect.w * 0.5;
    const cy = outputRect.y + outputRect.h * 0.5;
    const g = ctx.createRadialGradient(
      cx,
      cy,
      Math.min(outputRect.w, outputRect.h) * 0.2,
      cx,
      cy,
      Math.max(outputRect.w, outputRect.h) * 0.7,
    );
    g.addColorStop(0, "rgba(0,0,0,0)");
    g.addColorStop(1, `rgba(0,0,0,${overlayCfg.vignette})`);
    ctx.fillStyle = g;
    ctx.fillRect(outputRect.x, outputRect.y, outputRect.w, outputRect.h);
    ctx.restore();
  }

  if (overlayCfg.cornerRadius) {
    const radius = Math.max(
      0,
      Math.min(outputRect.w, outputRect.h) * overlayCfg.cornerRadius,
    );
    applyRoundedCornerMask(ctx, outputRect, radius);
  }
}

const MediaFilterEngine = (() => {
  const surfaces = new Map();
  let rafId = null;
  const noise = { canvas: null, ctx: null, size: 128, lastTime: 0 };
  const GIF_FRAME_FALLBACK_MS = 100;

  function ensureNoiseCanvas() {
    if (!noise.canvas) {
      noise.canvas = document.createElement("canvas");
      noise.canvas.width = noise.size;
      noise.canvas.height = noise.size;
      noise.ctx = noise.canvas.getContext("2d");
    }
    return noise.canvas;
  }

  function updateNoiseCanvas() {
    ensureNoiseCanvas();
    const ctx = noise.ctx;
    const imageData = ctx.createImageData(noise.size, noise.size);
    const data = imageData.data;
    for (let i = 0; i < data.length; i += 4) {
      const v = Math.floor(Math.random() * 255);
      data[i] = v;
      data[i + 1] = v;
      data[i + 2] = v;
      data[i + 3] = 255;
    }
    ctx.putImageData(imageData, 0, 0);
  }

  function gifDecodeSupported() {
    return (
      typeof ImageDecoder === "function" &&
      typeof fetch === "function" &&
      typeof createImageBitmap === "function"
    );
  }

  function closeGifBitmap(bitmap) {
    if (!bitmap) return;
    try {
      if (typeof bitmap.close === "function") bitmap.close();
    } catch {}
  }

  function clearGifState(surface) {
    if (!surface || !surface.gifState) return;
    const state = surface.gifState;
    surface.gifState = null;
    closeGifBitmap(state.bitmap);
    state.bitmap = null;
    try {
      if (state.decoder && typeof state.decoder.close === "function")
        state.decoder.close();
    } catch {}
    state.decoder = null;
  }

  function ensureGifState(surface, mediaEl) {
    if (!surface || !mediaEl || !gifDecodeSupported()) return null;
    const src = String(mediaEl.currentSrc || mediaEl.src || "").trim();
    if (!src) return null;
    const existing = surface.gifState;
    if (existing && existing.src === src) return existing;

    clearGifState(surface);
    const state = {
      src,
      decoder: null,
      bitmap: null,
      frameCount: 0,
      nextFrameIndex: 0,
      nextDue: 0,
      loading: true,
      decoding: false,
      unsupported: false,
    };
    surface.gifState = state;

    (async () => {
      let blob = null;
      try {
        const res = await fetch(src, { cache: "force-cache" });
        if (!res || !res.ok) throw new Error("gif_fetch_failed");
        blob = await res.blob();
      } catch {
        if (surface.gifState === state) state.unsupported = true;
        return;
      }
      if (surface.gifState !== state) return;
      try {
        state.decoder = new ImageDecoder({ data: blob, type: "image/gif" });
      } catch {
        if (surface.gifState === state) state.unsupported = true;
        return;
      }
      try {
        if (
          state.decoder &&
          state.decoder.tracks &&
          state.decoder.tracks.ready
        ) {
          await state.decoder.tracks.ready;
        }
      } catch {}
      if (surface.gifState !== state) return;
      const fc = Number(state.decoder?.tracks?.selectedTrack?.frameCount || 0);
      state.frameCount = Number.isFinite(fc) && fc > 0 ? fc : 0;
      state.nextFrameIndex = 0;
      state.nextDue = 0;
      requestRender();
    })().finally(() => {
      if (surface.gifState === state) state.loading = false;
    });

    return state;
  }

  function scheduleGifFrameDecode(surface, time) {
    const state = surface && surface.gifState;
    if (
      !state ||
      state.unsupported ||
      state.loading ||
      state.decoding ||
      !state.decoder
    )
      return;
    if (
      Number.isFinite(state.nextDue) &&
      state.nextDue > 0 &&
      time < state.nextDue
    )
      return;
    state.decoding = true;
    const frameIndex = Number.isFinite(state.nextFrameIndex)
      ? Math.max(0, state.nextFrameIndex | 0)
      : 0;
    const decoder = state.decoder;

    (async () => {
      let decoded = null;
      try {
        decoded = await decoder.decode({ frameIndex });
      } catch {
        if (surface.gifState !== state) return;
        state.nextFrameIndex = 0;
        state.nextDue = performance.now() + GIF_FRAME_FALLBACK_MS;
        return;
      }
      if (surface.gifState !== state) {
        try {
          decoded?.image?.close?.();
        } catch {}
        return;
      }

      const frame = decoded && decoded.image ? decoded.image : null;
      const durationUs = Number(frame?.duration || 0);
      let bitmap = null;
      if (frame) {
        try {
          bitmap = await createImageBitmap(frame);
        } catch {}
        try {
          frame.close();
        } catch {}
      }
      if (surface.gifState !== state) {
        closeGifBitmap(bitmap);
        return;
      }
      if (bitmap) {
        closeGifBitmap(state.bitmap);
        state.bitmap = bitmap;
      }
      if (state.frameCount > 0)
        state.nextFrameIndex = (frameIndex + 1) % state.frameCount;
      else state.nextFrameIndex = frameIndex + 1;
      const durationMs =
        durationUs > 0 ? Math.max(8, durationUs / 1000) : GIF_FRAME_FALLBACK_MS;
      state.nextDue = performance.now() + durationMs;
      requestRender();
    })().finally(() => {
      if (surface.gifState === state) state.decoding = false;
    });
  }

  function updateEngineState() {
    const appEl = document.getElementById("app");
    if (!appEl) return;
    const anyDrawn = Array.from(surfaces.values()).some(
      (s) => s.active && s.hasDrawn,
    );
    if (anyDrawn) appEl.setAttribute("data-media-filter-engine", "on");
    else appEl.removeAttribute("data-media-filter-engine");
  }

  function ensureSurface(name) {
    if (surfaces.has(name)) return surfaces.get(name);
    const surface = {
      name,
      container: null,
      mediaEl: null,
      target: null,
      type: null,
      filterMode: "off",
      canvas: null,
      ctx: null,
      offscreen: null,
      offctx: null,
      workscreen: null,
      workctx: null,
      scratchscreen: null,
      scratchctx: null,
      halationExtractCanvas: null,
      halationExtractCtx: null,
      vhsFuzzCanvas: null,
      vhsFuzzCtx: null,
      vhsFuzzStripCanvas: null,
      vhsFuzzStripCtx: null,
      vhsFuzzLowCanvas: null,
      vhsFuzzLowCtx: null,
      aberrationscreen: null,
      aberrationctx: null,
      aberrationchannelscreen: null,
      aberrationchannelctx: null,
      active: false,
      bound: false,
      hasDrawn: false,
      awaitingFreshFrame: false,
      videoFrameActive: false,
      gifState: null,
      framescreen: null,
      framectx: null,
      ghostPrevCanvas: null,
      ghostPrevCtx: null,
      ghostWorkCanvas: null,
      ghostWorkCtx: null,
      ghostHasFrame: false,
    };
    surfaces.set(name, surface);
    return surface;
  }

  function ensureCanvas(surface) {
    if (!surface.canvas) {
      surface.canvas = document.createElement("canvas");
      surface.canvas.className = "mediaCanvas";
      surface.canvas.style.display = "none";
    }
    if (!surface.ctx) surface.ctx = surface.canvas.getContext("2d");
    if (!surface.offscreen)
      surface.offscreen = document.createElement("canvas");
    if (!surface.offctx) surface.offctx = surface.offscreen.getContext("2d");
    if (!surface.workscreen)
      surface.workscreen = document.createElement("canvas");
    if (!surface.workctx) surface.workctx = surface.workscreen.getContext("2d");
    if (!surface.scratchscreen)
      surface.scratchscreen = document.createElement("canvas");
    if (!surface.scratchctx)
      surface.scratchctx = surface.scratchscreen.getContext("2d", {
        willReadFrequently: true,
      });
    if (!surface.aberrationscreen)
      surface.aberrationscreen = document.createElement("canvas");
    if (!surface.aberrationctx)
      surface.aberrationctx = surface.aberrationscreen.getContext("2d");
    if (!surface.aberrationchannelscreen)
      surface.aberrationchannelscreen = document.createElement("canvas");
    if (!surface.aberrationchannelctx)
      surface.aberrationchannelctx =
        surface.aberrationchannelscreen.getContext("2d");
    if (!surface.framescreen)
      surface.framescreen = document.createElement("canvas");
    if (!surface.framectx)
      surface.framectx = surface.framescreen.getContext("2d");
    if (surface.container && !surface.container.contains(surface.canvas)) {
      surface.container.appendChild(surface.canvas);
    }
  }

  function bindMediaEvents(surface, el) {
    if (!el || surface.mediaEl === el) return;
    clearGifState(surface);
    if (surface.mediaEl && surface.bound) {
      surface.mediaEl.removeEventListener("load", requestRender);
      surface.mediaEl.removeEventListener("loadeddata", requestRender);
      surface.mediaEl.removeEventListener("play", requestRender);
      surface.mediaEl.removeEventListener("pause", requestRender);
      surface.mediaEl.removeEventListener("seeked", requestRender);
    }
    surface.mediaEl = el;
    surface.bound = true;
    el.addEventListener("load", requestRender);
    el.addEventListener("loadeddata", requestRender);
    el.addEventListener("play", requestRender);
    el.addEventListener("pause", requestRender);
    el.addEventListener("seeked", requestRender);
  }

  function attach(name, mediaEl, container, type, filterMode, target = null) {
    const surface = ensureSurface(name);
    surface.container = container;
    surface.target = target;
    surface.type = type;
    surface.filterMode = filterMode || "off";
    surface.active = true;
    surface.awaitingFreshFrame = true;
    surface.ghostHasFrame = false;
    bindMediaEvents(surface, mediaEl);
    ensureCanvas(surface);
    if (surface.mediaEl && surface.hasDrawn) {
      const keepRawVisible =
        type === "image" &&
        String(surface.mediaEl.getAttribute("data-is-gif") || "") === "1";
      if (!keepRawVisible) surface.mediaEl.classList.add("mediaHidden");
    }
    if (
      type === "video" &&
      mediaEl &&
      typeof mediaEl.requestVideoFrameCallback === "function"
    ) {
      surface.videoFrameActive = true;
      const onFrame = () => {
        if (!surface.active || !surface.videoFrameActive) return;
        requestRender();
        mediaEl.requestVideoFrameCallback(onFrame);
      };
      mediaEl.requestVideoFrameCallback(onFrame);
    } else {
      surface.videoFrameActive = false;
    }
    if (type !== "image") clearGifState(surface);
    updateEngineState();
    requestRender();
    let pulseCount = 0;
    const pulse = () => {
      if (!surface.active) return;
      if (surface.hasDrawn) return;
      pulseCount++;
      requestRender();
      if (pulseCount < 20) requestAnimationFrame(pulse);
    };
    requestAnimationFrame(pulse);
  }

  function detach(name, options = null) {
    const surface = surfaces.get(name);
    if (!surface) return;
    const preserveFrame = !!(options && options.preserveFrame);
    surface.active = false;
    surface.target = null;
    surface.awaitingFreshFrame = false;
    surface.videoFrameActive = false;
    surface.ghostHasFrame = false;
    clearGifState(surface);
    if (!preserveFrame) {
      surface.hasDrawn = false;
      if (surface.canvas) {
        surface.canvas.style.display = "none";
        surface.canvas.classList.remove("ready");
      }
    }
    updateEngineState();
  }

  function reset(name) {
    const surface = surfaces.get(name);
    if (!surface) return;
    surface.active = false;
    surface.target = null;
    surface.hasDrawn = false;
    surface.awaitingFreshFrame = false;
    surface.videoFrameActive = false;
    clearGifState(surface);
    if (surface.canvas && surface.canvas.parentElement) {
      surface.canvas.parentElement.removeChild(surface.canvas);
    }
    surface.canvas = null;
    surface.ctx = null;
    surface.offscreen = null;
    surface.offctx = null;
    surface.workscreen = null;
    surface.workctx = null;
    surface.scratchscreen = null;
    surface.scratchctx = null;
    surface.aberrationscreen = null;
    surface.aberrationctx = null;
    surface.aberrationchannelscreen = null;
    surface.aberrationchannelctx = null;
    surface.framescreen = null;
    surface.framectx = null;
    surface.ghostPrevCanvas = null;
    surface.ghostPrevCtx = null;
    surface.ghostWorkCanvas = null;
    surface.ghostWorkCtx = null;
    surface.ghostHasFrame = false;
    if (surface.mediaEl) surface.mediaEl.classList.remove("mediaHidden");
    updateEngineState();
  }

  function requestRender() {
    if (rafId) return;
    rafId = requestAnimationFrame(render);
  }

  function render(time) {
    rafId = null;
    let needsMore = false;
    for (const surface of surfaces.values()) {
      if (!surface.active) continue;
      if (drawSurface(surface, time)) needsMore = true;
    }
    updateEngineState();
    if (needsMore) requestRender();
  }

  function drawSurface(surface, time) {
    const overlayCfg = resolveMediaOverlayConfigForTarget(surface.target);
    if (!overlayCfg) {
      if (surface.canvas) surface.canvas.style.display = "none";
      if (surface.mediaEl) surface.mediaEl.classList.remove("mediaHidden");
      surface.hasDrawn = false;
      surface.awaitingFreshFrame = false;
      return false;
    }
    if (
      !surface.mediaEl ||
      !surface.container ||
      !surface.canvas ||
      !surface.ctx ||
      !surface.framescreen ||
      !surface.framectx
    )
      return false;

    const el = surface.mediaEl;
    const isVideo = surface.type === "video";
    const isGifImage =
      !isVideo && String(el.getAttribute("data-is-gif") || "") === "1";
    if (!isGifImage) clearGifState(surface);
    const ready = isVideo
      ? el.readyState >= 2 && el.videoWidth > 0 && el.videoHeight > 0
      : el.complete && el.naturalWidth > 0 && el.naturalHeight > 0;
    if (!ready) {
      if (!surface.hasDrawn) {
        if (surface.canvas) surface.canvas.style.display = "none";
        if (surface.mediaEl) surface.mediaEl.classList.remove("mediaHidden");
      }
      return false;
    }

    const cw = surface.container.clientWidth || 0;
    const ch = surface.container.clientHeight || 0;
    if (!cw || !ch) return false;

    const dpr = window.devicePixelRatio || 1;
    const pixelW = Math.max(1, Math.round(cw * dpr));
    const pixelH = Math.max(1, Math.round(ch * dpr));
    if (surface.canvas.width !== pixelW || surface.canvas.height !== pixelH) {
      surface.canvas.width = pixelW;
      surface.canvas.height = pixelH;
    }

    const ctx = surface.ctx;
    const frameCtx = surface.framectx;
    resizeCanvasBuffer(surface.framescreen, pixelW, pixelH);
    frameCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
    frameCtx.imageSmoothingEnabled = true;
    frameCtx.clearRect(0, 0, cw, ch);

    let drawSource = el;
    let srcW = isVideo ? el.videoWidth : el.naturalWidth;
    let srcH = isVideo ? el.videoHeight : el.naturalHeight;
    if (isGifImage) {
      const gifState = ensureGifState(surface, el);
      if (gifState && !gifState.unsupported) {
        scheduleGifFrameDecode(surface, time);
        if (
          gifState.bitmap &&
          gifState.bitmap.width > 0 &&
          gifState.bitmap.height > 0
        ) {
          drawSource = gifState.bitmap;
          srcW = gifState.bitmap.width;
          srcH = gifState.bitmap.height;
        }
      }
    }
    const sourceCrop = isVideo
      ? computeCroppedSourceRect(
          srcW,
          srcH,
          getVideoCropForTarget(surface.target),
        )
      : { sx: 0, sy: 0, sw: srcW, sh: srcH };
    const croppedSrcW = Math.max(1, Number(sourceCrop.sw || srcW || 1));
    const croppedSrcH = Math.max(1, Number(sourceCrop.sh || srcH || 1));
    const drawCropped = (targetCtx, dx2, dy2, dw2, dh2) => {
      if (sourceCrop.sw > 0 && sourceCrop.sh > 0) {
        targetCtx.drawImage(
          drawSource,
          sourceCrop.sx,
          sourceCrop.sy,
          sourceCrop.sw,
          sourceCrop.sh,
          dx2,
          dy2,
          dw2,
          dh2,
        );
        return;
      }
      targetCtx.drawImage(drawSource, dx2, dy2, dw2, dh2);
    };
    const rect = computeContainRect(croppedSrcW, croppedSrcH, cw, ch);
    const animatedForSurface = animatedMediaFiltersEnabledForType(surface.type);
    const dx = rect.x;
    const dy = rect.y;

    let currentCanvas = surface.workscreen;
    let currentCtx = surface.workctx;
    let scratchCanvas = surface.scratchscreen;
    let scratchCtx = surface.scratchctx;
    resizeCanvasBuffer(currentCanvas, rect.w, rect.h);
    resizeCanvasBuffer(scratchCanvas, rect.w, rect.h);
    currentCtx.setTransform(1, 0, 0, 1, 0, 0);
    currentCtx.clearRect(0, 0, currentCanvas.width, currentCanvas.height);
    currentCtx.imageSmoothingEnabled = true;
    currentCtx.filter = "none";
    const fitRect = computeContainRect(
      croppedSrcW,
      croppedSrcH,
      currentCanvas.width,
      currentCanvas.height,
    );
    drawCropped(currentCtx, fitRect.x, fitRect.y, fitRect.w, fitRect.h);
    const swapBuffers = () => {
      const oldCanvas = currentCanvas;
      const oldCtx = currentCtx;
      currentCanvas = scratchCanvas;
      currentCtx = scratchCtx;
      scratchCanvas = oldCanvas;
      scratchCtx = oldCtx;
    };

    try {
      const colorFilter =
        Array.isArray(overlayCfg.colorFilters) && overlayCfg.colorFilters.length
          ? overlayCfg.colorFilters.join(" ")
          : "none";
      if (colorFilter !== "none") {
        resizeCanvasBuffer(
          scratchCanvas,
          currentCanvas.width,
          currentCanvas.height,
        );
        scratchCtx.setTransform(1, 0, 0, 1, 0, 0);
        scratchCtx.clearRect(0, 0, scratchCanvas.width, scratchCanvas.height);
        scratchCtx.imageSmoothingEnabled = true;
        scratchCtx.filter = colorFilter;
        scratchCtx.drawImage(
          currentCanvas,
          0,
          0,
          scratchCanvas.width,
          scratchCanvas.height,
        );
        scratchCtx.filter = "none";
        swapBuffers();
      }
      applyPixelOpsToCanvas(currentCanvas, overlayCfg);
      if (overlayCfg.pixelate > 0) {
        const scale = Math.max(1, overlayCfg.pixelate);
        resizeCanvasBuffer(
          surface.offscreen,
          Math.max(1, Math.round(currentCanvas.width / scale)),
          Math.max(1, Math.round(currentCanvas.height / scale)),
        );
        surface.offctx.setTransform(1, 0, 0, 1, 0, 0);
        surface.offctx.clearRect(
          0,
          0,
          surface.offscreen.width,
          surface.offscreen.height,
        );
        surface.offctx.imageSmoothingEnabled = true;
        surface.offctx.filter = "none";
        surface.offctx.drawImage(
          currentCanvas,
          0,
          0,
          surface.offscreen.width,
          surface.offscreen.height,
        );
        resizeCanvasBuffer(
          scratchCanvas,
          currentCanvas.width,
          currentCanvas.height,
        );
        scratchCtx.setTransform(1, 0, 0, 1, 0, 0);
        scratchCtx.clearRect(0, 0, scratchCanvas.width, scratchCanvas.height);
        scratchCtx.imageSmoothingEnabled = false;
        scratchCtx.filter = "none";
        scratchCtx.drawImage(
          surface.offscreen,
          0,
          0,
          scratchCanvas.width,
          scratchCanvas.height,
        );
        swapBuffers();
      }
      if (overlayCfg.blur > 0) {
        resizeCanvasBuffer(
          scratchCanvas,
          currentCanvas.width,
          currentCanvas.height,
        );
        scratchCtx.setTransform(1, 0, 0, 1, 0, 0);
        scratchCtx.clearRect(0, 0, scratchCanvas.width, scratchCanvas.height);
        scratchCtx.imageSmoothingEnabled = true;
        scratchCtx.filter = `blur(${overlayCfg.blur}px)`;
        scratchCtx.drawImage(
          currentCanvas,
          0,
          0,
          scratchCanvas.width,
          scratchCanvas.height,
        );
        scratchCtx.filter = "none";
        swapBuffers();
      }
    } catch {
      if (!surface.hasDrawn) {
        if (surface.canvas) {
          surface.canvas.style.display = "none";
          surface.canvas.classList.remove("ready");
        }
        if (surface.mediaEl) surface.mediaEl.classList.remove("mediaHidden");
      }
      return false;
    }

    const outputRect = { x: dx, y: dy, w: rect.w, h: rect.h };
    frameCtx.imageSmoothingEnabled = true;
    frameCtx.filter = "none";
    if (
      !drawChromaticAberrationToContext(
        frameCtx,
        currentCanvas,
        outputRect.x,
        outputRect.y,
        outputRect.w,
        outputRect.h,
        overlayCfg.chroma,
        {
          compositeCanvas: surface.aberrationscreen,
          compositeCtx: surface.aberrationctx,
          channelCanvas: surface.aberrationchannelscreen,
          channelCtx: surface.aberrationchannelctx,
        },
      )
    ) {
      frameCtx.drawImage(
        currentCanvas,
        outputRect.x,
        outputRect.y,
        outputRect.w,
        outputRect.h,
      );
    }

    if (overlayCfg.halation) {
      drawHalationToContext(
        frameCtx,
        currentCanvas,
        outputRect,
        overlayCfg.halation,
        surface,
      );
    }

    if (overlayCfg.ghosting) {
      drawTemporalGhostingToContext(
        frameCtx,
        currentCanvas,
        outputRect,
        overlayCfg.ghosting,
        time,
        surface,
        { animated: animatedForSurface },
      );
    }

    if (overlayCfg.lineDamage) {
      drawLineDamageToContext(
        frameCtx,
        currentCanvas,
        outputRect,
        overlayCfg.lineDamage,
        time,
        surface,
        { animated: animatedForSurface },
      );
    }

    if (overlayCfg.grain) {
      frameCtx.save();
      frameCtx.beginPath();
      frameCtx.rect(outputRect.x, outputRect.y, outputRect.w, outputRect.h);
      frameCtx.clip();
      const noiseCanvas = ensureNoiseCanvas();
      if (animatedForSurface) {
        if (time - noise.lastTime > 80) {
          updateNoiseCanvas();
          noise.lastTime = time;
        }
      } else if (!noise.lastTime) {
        updateNoiseCanvas();
        noise.lastTime = time;
      }
      const pattern = frameCtx.createPattern(noiseCanvas, "repeat");
      if (pattern) {
        frameCtx.globalAlpha = overlayCfg.grain;
        frameCtx.globalCompositeOperation = "overlay";
        frameCtx.fillStyle = pattern;
        frameCtx.fillRect(
          outputRect.x,
          outputRect.y,
          outputRect.w,
          outputRect.h,
        );
      }
      frameCtx.restore();
    }

    if (overlayCfg.vignette) {
      frameCtx.save();
      frameCtx.beginPath();
      frameCtx.rect(outputRect.x, outputRect.y, outputRect.w, outputRect.h);
      frameCtx.clip();
      const cx = outputRect.x + outputRect.w * 0.5;
      const cy = outputRect.y + outputRect.h * 0.5;
      const g = frameCtx.createRadialGradient(
        cx,
        cy,
        Math.min(outputRect.w, outputRect.h) * 0.2,
        cx,
        cy,
        Math.max(outputRect.w, outputRect.h) * 0.7,
      );
      g.addColorStop(0, "rgba(0,0,0,0)");
      g.addColorStop(1, `rgba(0,0,0,${overlayCfg.vignette})`);
      frameCtx.fillStyle = g;
      frameCtx.fillRect(outputRect.x, outputRect.y, outputRect.w, outputRect.h);
      frameCtx.restore();
    }

    if (overlayCfg.cornerRadius) {
      const radius = Math.max(
        0,
        Math.min(outputRect.w, outputRect.h) * overlayCfg.cornerRadius,
      );
      applyRoundedCornerMask(frameCtx, outputRect, radius);
    }

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.imageSmoothingEnabled = true;
    ctx.filter = "none";
    ctx.clearRect(0, 0, pixelW, pixelH);
    ctx.drawImage(surface.framescreen, 0, 0, pixelW, pixelH);
    surface.canvas.style.display = "block";
    surface.canvas.classList.add("ready");
    surface.hasDrawn = true;
    surface.awaitingFreshFrame = false;
    if (surface.mediaEl) {
      if (isGifImage) surface.mediaEl.classList.remove("mediaHidden");
      else surface.mediaEl.classList.add("mediaHidden");
    }

    const needsAnim =
      animatedForSurface &&
      !!(overlayCfg.grain || overlayCfg.ghosting || overlayCfg.lineDamage);
    if (isVideo) {
      if (surface.videoFrameActive) {
        return false;
      }
      if (!el.paused) return true;
      return needsAnim;
    }
    if (isGifImage) return true;
    return needsAnim;
  }

  return {
    attach,
    detach,
    reset,
    requestRender,
    hasSurfaceDrawn: (name) => {
      const surface = surfaces.get(name);
      return !!(surface && surface.hasDrawn);
    },
  };
})();

function fileDisplayName(name) {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  const parts = splitNameExt(name || "");
  const base = applyDisplayNameRules(parts.base || "", opt, { isFile: true });
  return `${base}${opt && opt.hideFileExtensionsInFileNames ? "" : parts.ext || ""}`;
}

function relPathDisplayName(relPath) {
  const parts = String(relPath || "")
    .split("/")
    .filter(Boolean);
  if (!parts.length) return "";
  const out = parts.map((seg, idx) => {
    if (idx !== parts.length - 1) return displayName(seg || "") || "";
    return fileDisplayName(seg || "") || "";
  });
  return out.join("/") || "";
}

function normalizeTitleLayoutModeValue(value, fallback = "pane") {
  const mode = String(value || "")
    .trim()
    .toLowerCase();
  if (mode === "compact" || mode === "pane") return mode;
  return fallback === "compact" || fallback === "pane" ? fallback : "pane";
}

function directoriesPaneOpenEnabled(opt = null) {
  const src = opt || (WS.meta && WS.meta.options ? WS.meta.options : null);
  return !(src && src.directoriesPaneOpen === false);
}

function titleLayoutModeFromOptions(opt = null) {
  const src = opt || (WS.meta && WS.meta.options ? WS.meta.options : null);
  return normalizeTitleLayoutModeValue(src && src.titleLayoutMode, "pane");
}

function isCompactTitleLayout() {
  return titleLayoutModeFromOptions() === "compact";
}

// Legacy helper kept in place while old grid-mode call sites are retired.
// Unified layout always uses pane-style navigation semantics.
function isGridInteractionMode() {
  return false;
}

function sharedThumbWidthForMode(modeRaw) {
  const mode = normalizeThumbRenderModeValue(modeRaw, "medium");
  if (mode === "small") return 224;
  if (mode === "high") return 640;
  if (mode === "native") return 640;
  return 384;
}

function imageThumbWidthForOption() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return sharedThumbWidthForMode(
    opt ? String(opt.imageThumbSize || "medium") : "medium",
  );
}

function videoThumbWidthForOption() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return sharedThumbWidthForMode(
    opt ? String(opt.videoThumbSize || "medium") : "medium",
  );
}

function setOptionsStatus(text) {
  if (!optionsStatusLabel) return;
  optionsStatusLabel.textContent = text || "—";
}

function applyDefaultViewFromOptions() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  if (!opt) return;
  WS.view.filterMode = "all";
  WS.view.randomMode = false;
  WS.view.randomFolderMode = false;
  WS.view.randomCache = new Map();
  WS.view.randomFolderCache = new Map();
  WS.view.activePane = directoriesPaneOpenEnabled(opt)
    ? "directories"
    : "preview";
  WS.view.previewSelectedKey = "";
  WS.view.previewSelectionContextKey = "";
  WS.view.folderBehavior = "slide";
  WS.view.hiddenMode = false;
  WS.view.hiddenRootActive = false;
  WS.view.hiddenAnchorPath = "";
  applyColorSchemeFromOptions();
  applyTagFolderTitleColorsFromOptions();
}

function applyColorSchemeFromOptions() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  const root = document.documentElement;
  if (!root) return;
  const lightMode = !!(opt && opt.lightMode);
  root.setAttribute("data-theme", lightMode ? "retro90s" : "retro90s-dark");
}

function applyTagFolderTitleColorsFromOptions() {
  const root = document.documentElement;
  if (!root) return;
  root.style.removeProperty("--dir-tag-title-color");
  root.style.removeProperty("--dir-tag-favorite-title-color");
  root.style.removeProperty("--dir-tag-album-title-color");
}

function applyRetroModeFromOptions() {
  const root = document.documentElement;
  if (!root) return;
  root.setAttribute("data-retro", "on");
}

function retroPaletteEnabled(opt = null) {
  return true;
}

function favoriteHeartSymbol(opt = null) {
  return "♥︎";
}

function favoriteMenuButtonLabel(opt = null) {
  return `<span class="dirMenuFavoriteGlyph" aria-hidden="true">${escapeHtml(favoriteHeartSymbol(opt))}</span>`;
}

function syncThumbFilterKeyWithCurrentAppearanceContext() {
  const nextThumbKey = buildThumbFilterKey();
  if (nextThumbKey === THUMB_FILTER_KEY) return false;
  THUMB_FILTER_KEY = nextThumbKey;
  if (WS.root) invalidateAllThumbs();
  return true;
}

function applyMediaFilterFromOptions() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  const prevFilterMode = MEDIA_FILTER_STATE.mode || "off";
  MEDIA_OVERLAY_STATE = buildMediaOverlayConfigFromOptions(opt);
  const appEl = document.getElementById("app");
  if (!appEl) return;
  const filter = anyMediaFilterEnabled() ? "custom" : "off";
  if (filter && filter !== "off")
    appEl.setAttribute("data-media-filter", "custom-overlay");
  else appEl.removeAttribute("data-media-filter");
  const root = document.documentElement;
  if (root) {
    root.style.setProperty("--thumb-filter", "none");
  }
  MEDIA_FILTER_STATE.mode = filter || "off";
  MEDIA_FILTER_STATE.animatedMode = normalizeAnimatedMediaFiltersValue(
    opt ? opt.animatedMediaFilters : null,
    "on",
  );
  if (prevFilterMode !== MEDIA_FILTER_STATE.mode) {
    MediaFilterEngine.detach("preview");
    MediaFilterEngine.detach("viewer");
    const quadSlots = getQuadPlaybackSlots();
    for (let i = 0; i < quadSlots.length; i++) {
      const slot = quadSlots[i];
      if (!slot) continue;
      MediaFilterEngine.detach(slot.surfaceName);
    }
  }
  if (syncThumbFilterKeyWithCurrentAppearanceContext()) {
    if (WS.root) {
      renderPreviewPane(false, true);
      kickVideoThumbsForPreview();
      kickImageThumbsForPreview();
    }
  }
  const filtersActive = anyMediaFilterEnabled();
  if (!filtersActive) {
    MediaFilterEngine.reset("preview");
    MediaFilterEngine.reset("viewer");
    if (previewImgEl) previewImgEl.classList.remove("mediaHidden");
    if (previewVideoEl) previewVideoEl.classList.remove("mediaHidden");
    if (viewerImgEl) viewerImgEl.classList.remove("mediaHidden");
    if (viewerVideoEl) viewerVideoEl.classList.remove("mediaHidden");
    const quadSlots = getQuadPlaybackSlots();
    for (let i = 0; i < quadSlots.length; i++) {
      const slot = quadSlots[i];
      if (!slot || !slot.videoEl) continue;
      MediaFilterEngine.reset(slot.surfaceName);
      slot.videoEl.classList.remove("mediaHidden");
    }
    applyScrollImageProcessingFallback(previewImgEl, null, "none");
    applyScrollImageProcessingFallback(viewerImgEl, null, "none");
    appEl.removeAttribute("data-media-filter-engine");
  } else {
    const activeViewerItem =
      viewerItems && viewerItems.length
        ? viewerItems[viewerIndex] || null
        : null;
    const viewerRec =
      activeViewerItem && !activeViewerItem.isFolder
        ? WS.fileById.get(activeViewerItem.id) || null
        : null;
    const previewRec =
      WS.preview && WS.preview.kind === "file" && WS.preview.fileId
        ? WS.fileById.get(WS.preview.fileId) || null
        : null;
    if (VIEWER_MODE) {
      if (isQuadPlaybackMode()) {
        const quadSlots = getQuadPlaybackSlots();
        for (let i = 0; i < quadSlots.length; i++) {
          const slot = quadSlots[i];
          if (
            !slot ||
            !slot.videoEl ||
            slot.videoEl.style.display === "none" ||
            !slot.rec
          )
            continue;
          syncMediaFilterSurface(
            slot.surfaceName,
            slot.videoEl,
            slot.cellEl,
            "video",
            slot.rec,
          );
        }
      } else if (viewerVideoEl && viewerVideoEl.style.display !== "none") {
        syncMediaFilterSurface(
          "viewer",
          viewerVideoEl,
          viewport,
          "video",
          viewerRec,
        );
      } else if (viewerImgEl && viewerImgEl.style.display !== "none") {
        const mode = detectScrollImageMode(viewerRec, viewerImgEl);
        if (mode !== "none") {
          clearMediaFilterSurface("viewer", viewerImgEl);
          applyScrollImageProcessingFallback(viewerImgEl, viewerRec, mode);
        } else {
          applyScrollImageProcessingFallback(viewerImgEl, viewerRec, "none");
          syncMediaFilterSurface(
            "viewer",
            viewerImgEl,
            viewport,
            "image",
            viewerRec,
          );
        }
      }
    }
    if (ACTIVE_MEDIA_SURFACE === "preview") {
      if (previewVideoEl && previewVideoEl.style.display !== "none") {
        syncMediaFilterSurface(
          "preview",
          previewVideoEl,
          previewViewportBox,
          "video",
          previewRec,
        );
      } else if (previewImgEl && previewImgEl.style.display !== "none") {
        const mode = detectScrollImageMode(previewRec, previewImgEl);
        if (mode !== "none") {
          clearMediaFilterSurface("preview", previewImgEl);
          applyScrollImageProcessingFallback(previewImgEl, previewRec, mode);
        } else {
          applyScrollImageProcessingFallback(previewImgEl, previewRec, "none");
          syncMediaFilterSurface(
            "preview",
            previewImgEl,
            previewViewportBox,
            "image",
            previewRec,
          );
        }
      }
    }
  }
  MediaFilterEngine.requestRender();
}

function applyThumbFitFromOptions() {
  const root = document.documentElement;
  if (!root) return;
  root.style.setProperty("--thumb-fit", "contain");
  root.style.setProperty("--thumb-bg", "transparent");
  root.setAttribute("data-thumb-fit", "contain");
}

function getThumbnailStyleFromOptions(opt = null) {
  if (!ENABLE_ASPECT_RATIO_THUMBNAIL_STYLE) return "cropped";
  const src = opt || (WS.meta && WS.meta.options ? WS.meta.options : null);
  const raw = String((src && src.thumbnailStyle) || "cropped").toLowerCase();
  return raw === "aspect" ? "aspect" : "cropped";
}

function getThumbnailScaleForStyle(style, opt = null) {
  const src = opt || (WS.meta && WS.meta.options ? WS.meta.options : null);
  const s = style === "aspect" ? "aspect" : "cropped";
  const fallback = s === "aspect" ? "small" : "medium";
  const key = s === "aspect" ? "thumbnailScaleAspect" : "thumbnailScaleCropped";
  return normalizeThumbnailScaleValue(src ? src[key] : null, fallback);
}

function getActiveThumbnailScale(opt = null) {
  const style = getThumbnailStyleFromOptions(opt);
  return getThumbnailScaleForStyle(style, opt);
}

function getActiveThumbnailScaleMultiplier(opt = null) {
  const style = getThumbnailStyleFromOptions(opt);
  const scale = getThumbnailScaleForStyle(style, opt);
  if (style === "aspect") {
    // Shift aspect scales upward so previous XXL maps to Medium.
    if (scale === "small") return 1.52;
    if (scale === "medium") return 1.72;
    if (scale === "large") return 1.94;
    if (scale === "xl") return 2.18;
    if (scale === "xxl") return 2.44;
    if (scale === "xxxl") return 2.72;
    return 1.72;
  }
  if (scale === "small") return 0.86;
  if (scale === "large") return 1.18;
  if (scale === "xl") return 1.34;
  if (scale === "xxl") return 1.52;
  if (scale === "xxxl") return 1.72;
  return 1;
}

function naturalAspectThumbnailCardsEnabled() {
  return getThumbnailStyleFromOptions() === "aspect";
}

function previewSquareMediaThumbsEnabled() {
  return !naturalAspectThumbnailCardsEnabled();
}

function mediaFilterEnabled() {
  return anyMediaFilterEnabled();
}

function formatBytes(bytes) {
  const n = Number(bytes);
  if (!Number.isFinite(n) || n <= 0) return "0 B";
  const units = ["B", "KB", "MB", "GB", "TB"];
  let value = n;
  let idx = 0;
  while (value >= 1024 && idx < units.length - 1) {
    value /= 1024;
    idx++;
  }
  const shown =
    value >= 100 || idx === 0 ? Math.round(value) : value.toFixed(1);
  return `${shown} ${units[idx]}`;
}

function syncMediaFilterSurface(
  surfaceName,
  mediaEl,
  container,
  type,
  target = undefined,
) {
  if (!mediaEl || !container) return;
  let processingTarget = target;
  if (typeof processingTarget === "undefined") {
    if (mediaEl.hasAttribute("data-dir-path")) {
      processingTarget = mediaEl.getAttribute("data-dir-path") || "";
    } else {
      processingTarget = null;
    }
  }
  if (!resolveMediaOverlayConfigForTarget(processingTarget)) {
    mediaEl.classList.remove("mediaHidden");
    MediaFilterEngine.detach(surfaceName);
    return;
  }
  MediaFilterEngine.attach(
    surfaceName,
    mediaEl,
    container,
    type,
    getMediaFilterForType(processingTarget),
    processingTarget,
  );
}

function clearPendingFilmCornerMask(mediaEl) {
  if (!mediaEl) return;
  mediaEl.classList.remove("pendingFilmCorners");
  mediaEl.style.removeProperty("--pending-film-corner-radius");
}

function applyPendingFilmCornerMask(mediaEl, processingTarget = null) {
  if (!mediaEl) return;
  clearPendingFilmCornerMask(mediaEl);
  const overlayCfg = resolveMediaOverlayConfigForTarget(processingTarget);
  if (!overlayCfg) return;
  const cornerRadius = Number((overlayCfg && overlayCfg.cornerRadius) || 0);
  if (!(cornerRadius > 0)) return;
  const pct = Math.max(0, Math.min(50, cornerRadius * 100));
  mediaEl.style.setProperty("--pending-film-corner-radius", `${pct}%`);
  mediaEl.classList.add("pendingFilmCorners");
}

function clearMediaFilterSurface(surfaceName, mediaEl) {
  MediaFilterEngine.detach(surfaceName);
  clearPendingFilmCornerMask(mediaEl);
  if (mediaEl) mediaEl.classList.remove("mediaHidden");
}

function applyDisplaySizesFromOptions() {
  const root = document.documentElement;
  if (!root) return;
  const mediaSize = "medium";
  const folderSize = "small";
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  const scaleMult = getActiveThumbnailScaleMultiplier(opt);
  if (mediaSize === "medium") root.removeAttribute("data-media-size");
  else root.setAttribute("data-media-size", mediaSize);
  if (folderSize === "medium") root.removeAttribute("data-folder-size");
  else root.setAttribute("data-folder-size", folderSize);
  root.style.setProperty("--thumb-scale-media", String(scaleMult));
  root.style.setProperty("--thumb-scale-folder", String(scaleMult));
}

function applyDirectoryMiniThumbSizeFromOptions() {
  const root = document.documentElement;
  if (!root) return;
  const px = 120;
  root.style.setProperty("--dir-mini-thumb-h", `${px}px`);
}

function applyDirectoryFileThumbLayoutFromOptions() {
  const root = document.documentElement;
  if (!root) return;
  root.setAttribute("data-dir-file-thumb-layout", "full-card");
}

function applyDirectoryFolderCardLayoutFromOptions() {
  const root = document.documentElement;
  if (!root) return;
  root.setAttribute("data-dir-folder-card-layout", "square");
}

function applyNaturalAspectThumbnailModeFromOptions() {
  const root = document.documentElement;
  if (!root) return;
  if (naturalAspectThumbnailCardsEnabled())
    root.setAttribute("data-natural-thumb-cards", "on");
  else root.removeAttribute("data-natural-thumb-cards");
}

function setActivePane(nextPane, opts = null) {
  if (!WS.view) return false;
  const pane = nextPane === "preview" ? "preview" : "directories";
  const prev =
    WS.view.activePane === "preview" || WS.view.activePane === "directories"
      ? WS.view.activePane
      : "";
  if (prev === pane) return false;
  if (!(opts && opts.keepBulkSelection)) {
    finalizeBulkSelectionAction();
  }
  WS.view.activePane = pane;
  return true;
}

function syncActivePaneWithLayout() {
  const appEl = document.getElementById("app");
  if (!WS.view) return;
  if (!directoriesPaneOpenEnabled()) {
    setActivePane("preview");
  } else if (
    WS.view.activePane !== "directories" &&
    WS.view.activePane !== "preview"
  ) {
    setActivePane("directories");
  }
  if (appEl) {
    appEl.classList.toggle(
      "directories-pane-active",
      WS.view.activePane === "directories",
    );
    appEl.classList.toggle(
      "preview-pane-active",
      WS.view.activePane === "preview",
    );
  }
}

function applyInteractionModeFromOptions() {
  const appEl = document.getElementById("app");
  if (!appEl) return;
  const sidebarOpen = directoriesPaneOpenEnabled();
  const titleMode = titleLayoutModeFromOptions();
  appEl.classList.toggle("sidebar-closed", !sidebarOpen);
  appEl.classList.toggle("title-layout-compact", titleMode === "compact");
  appEl.classList.toggle("title-layout-pane", titleMode !== "compact");
  appEl.classList.toggle("menu-pane-open", !!MENU_OPEN);
  appEl.classList.toggle(
    "preview-media-pane-background",
    !!(
      WS.meta &&
      WS.meta.options &&
      WS.meta.options.previewMediaUsePaneBackground === true
    ),
  );
  syncActivePaneWithLayout();
  updateGridModeListTopInset();
}

function applyOptionsEverywhere(invalidateThumbs = false) {
  const refreshOpenMenu = () => {
    refreshMenuTabAvailability();
    if (!MENU_OPEN) return;
    applyMenuPaneWidthFromOptions();
    setMenuTab(
      isMenuTabAvailable(MENU_ACTIVE_TAB) ? MENU_ACTIVE_TAB : "general",
    );
  };
  if (!WS.root) {
    applyColorSchemeFromOptions();
    applyTagFolderTitleColorsFromOptions();
    applyRetroModeFromOptions();
    applyMediaFilterFromOptions();
    applyThumbFitFromOptions();
    applyDisplaySizesFromOptions();
    applyDirectoryMiniThumbSizeFromOptions();
    applyDirectoryFileThumbLayoutFromOptions();
    applyDirectoryFolderCardLayoutFromOptions();
    applyNaturalAspectThumbnailModeFromOptions();
    applyInteractionModeFromOptions();
    applyDescriptionVisibilityFromOptions();
    applyPaneDividerFromOptions();
    refreshOpenMenu();
    syncButtons();
    return;
  }

  if (invalidateThumbs) {
    invalidateAllThumbs();
  }

  applyColorSchemeFromOptions();
  applyTagFolderTitleColorsFromOptions();
  applyRetroModeFromOptions();
  applyMediaFilterFromOptions();
  applyThumbFitFromOptions();
  applyDisplaySizesFromOptions();
  applyDirectoryMiniThumbSizeFromOptions();
  applyDirectoryFileThumbLayoutFromOptions();
  applyDirectoryFolderCardLayoutFromOptions();
  applyNaturalAspectThumbnailModeFromOptions();
  applyInteractionModeFromOptions();
  applyDescriptionVisibilityFromOptions();
  rebuildDirectoriesEntries();
  WS.nav.selectedIndex = findNearestSelectableIndex(WS.nav.selectedIndex, 1);
  syncPreviewToSelection();
  renderDirectoriesPane(true);
  renderPreviewPane(true, true);
  applyPaneDividerFromOptions();
  applyMediaFilterFromOptions();
  refreshOpenMenu();
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  if (VIEWER_MODE) renderViewerItem(viewerIndex);
  else if (ACTIVE_MEDIA_SURFACE === "preview")
    renderPreviewViewerItem(viewerIndex);
}

function applyDescriptionVisibilityFromOptions() {}

function applyPaneDividerFromOptions() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  const pct =
    opt && typeof opt.leftPaneWidthPct === "number"
      ? opt.leftPaneWidthPct
      : opt && !Number.isNaN(parseFloat(opt.leftPaneWidthPct))
        ? parseFloat(opt.leftPaneWidthPct)
        : 0.28;
  setDividerPositionFromPct(pct);
}

function setDividerPositionFromPct(pct) {
  const appEl = document.getElementById("app");
  if (!appEl) return;
  if (!directoriesPaneOpenEnabled()) {
    appEl.style.removeProperty("grid-template-columns");
    const dividerEl = document.getElementById("divider");
    if (dividerEl) dividerEl.style.removeProperty("left");
    MediaFilterEngine.requestRender();
    return;
  }
  pct = Math.max(0.05, Math.min(0.9, Number(pct) || 0.28));
  appEl.style.gridTemplateColumns = `${(pct * 100).toFixed(2)}% 1fr`;
  const dividerEl = document.getElementById("divider");
  if (dividerEl) {
    const left = Math.round(appEl.clientWidth * pct);
    dividerEl.style.left = left + "px";
  }
  // Keep filtered preview/video canvases in sync with live pane geometry while dragging the divider.
  MediaFilterEngine.requestRender();
}

const SAFE_KEY_VALUES = (() => {
  const out = [];
  for (let i = 0; i < 26; i++) out.push(String.fromCharCode(97 + i));
  for (let i = 0; i < 10; i++) out.push(String(i));
  out.push("Space");
  out.push("Tab");
  out.push("ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown");
  return out;
})();

const SAFE_KEY_SET = new Set(SAFE_KEY_VALUES);
const KEY_MODIFIER_ORDER = ["Cmd", "Ctrl", "Alt", "Shift"];
const MODIFIER_KEY_STATE = {
  Cmd: false,
  Ctrl: false,
  Alt: false,
  Shift: false,
};
const KEY_MODIFIER_LABELS = Object.freeze({
  Cmd: "Command",
  Ctrl: "Control",
  Alt: "Option",
  Shift: "Shift",
});
const MODIFIER_ALIASES = Object.freeze({
  command: "Cmd",
  cmd: "Cmd",
  meta: "Cmd",
  control: "Ctrl",
  ctrl: "Ctrl",
  option: "Alt",
  opt: "Alt",
  alt: "Alt",
  shift: "Shift",
});

const KEY_LABELS = {
  Escape: "Escape",
  Space: "Space",
  Tab: "Tab",
  ArrowLeft: "Left Arrow",
  ArrowRight: "Right Arrow",
  ArrowUp: "Up Arrow",
  ArrowDown: "Down Arrow",
  "=": "+ / =",
  "-": "- / _",
};

const SHIFT_DIGIT_SYMBOL_TO_KEY = Object.freeze({
  "!": "1",
  "@": "2",
  "#": "3",
  $: "4",
  "%": "5",
  "^": "6",
  "&": "7",
  "*": "8",
  "(": "9",
  ")": "0",
});

function syncModifierKeyStateFromEvent(e) {
  if (!e) return;
  MODIFIER_KEY_STATE.Cmd = !!e.metaKey;
  MODIFIER_KEY_STATE.Ctrl = !!e.ctrlKey;
  MODIFIER_KEY_STATE.Alt = !!e.altKey;
  MODIFIER_KEY_STATE.Shift = !!e.shiftKey;
}

function clearModifierKeyState() {
  MODIFIER_KEY_STATE.Cmd = false;
  MODIFIER_KEY_STATE.Ctrl = false;
  MODIFIER_KEY_STATE.Alt = false;
  MODIFIER_KEY_STATE.Shift = false;
}

function eventShiftHeld(e) {
  return !!((e && e.shiftKey) || MODIFIER_KEY_STATE.Shift);
}

function eventCmdOrCtrlHeld(e) {
  return !!(
    (e && (e.metaKey || e.ctrlKey)) ||
    MODIFIER_KEY_STATE.Cmd ||
    MODIFIER_KEY_STATE.Ctrl
  );
}

function normalizeBaseKeyValue(key) {
  if (!key && key !== 0) return "";
  const raw = String(key);
  if (!raw) return "";
  if (raw === " ") return "Space";
  if (raw === "+" || raw === "=") return "=";
  if (raw === "_" || raw === "-") return "-";
  if (SHIFT_DIGIT_SYMBOL_TO_KEY[raw]) return SHIFT_DIGIT_SYMBOL_TO_KEY[raw];
  if (/^space$/i.test(raw)) return "Space";
  if (/^escape$/i.test(raw) || /^esc$/i.test(raw)) return "Escape";
  if (raw.length === 1) return raw.toLowerCase();
  return raw;
}

function normalizeKeyValue(key) {
  if (!key && key !== 0) return "";
  const raw = String(key).trim();
  if (!raw) return "";
  const parts = raw
    .split("+")
    .map((part) => String(part || "").trim())
    .filter(Boolean);
  if (!parts.length) return "";
  const mods = { Cmd: false, Ctrl: false, Alt: false, Shift: false };
  let base = "";
  for (const partRaw of parts) {
    const part = String(partRaw || "").trim();
    if (!part) continue;
    const mod = MODIFIER_ALIASES[part.toLowerCase()] || "";
    if (mod) {
      mods[mod] = true;
      continue;
    }
    base = normalizeBaseKeyValue(part);
  }
  if (!base) return "";
  if (base === "=" || base === "-" || base === "Escape") return base;
  const modParts = KEY_MODIFIER_ORDER.filter((mod) => mods[mod]);
  return modParts.length ? `${modParts.join("+")}+${base}` : base;
}

function parseKeybindValue(value) {
  const norm = normalizeKeyValue(value);
  const parsed = {
    key: "",
    mods: { Cmd: false, Ctrl: false, Alt: false, Shift: false },
  };
  if (!norm) return parsed;
  const parts = norm.split("+").filter(Boolean);
  if (!parts.length) return parsed;
  const base = parts[parts.length - 1];
  parsed.key = base;
  for (let i = 0; i < parts.length - 1; i++) {
    const mod = parts[i];
    if (parsed.mods.hasOwnProperty(mod)) parsed.mods[mod] = true;
  }
  return parsed;
}

function buildKeybindValue(baseKey, modifiers = null) {
  const base = normalizeBaseKeyValue(baseKey);
  if (!base) return "";
  if (base === "=" || base === "-" || base === "Escape") return base;
  const mods = {
    Cmd: !!(modifiers && modifiers.Cmd),
    Ctrl: !!(modifiers && modifiers.Ctrl),
    Alt: !!(modifiers && modifiers.Alt),
    Shift: !!(modifiers && modifiers.Shift),
  };
  const modParts = KEY_MODIFIER_ORDER.filter((mod) => mods[mod]);
  return modParts.length ? `${modParts.join("+")}+${base}` : base;
}

function keybindValueFromEvent(e) {
  if (!e) return "";
  const keyRaw = String(e.key || "");
  const codeRaw = String(e.code || "");
  if (!keyRaw && !codeRaw) return "";
  if (
    keyRaw === "Meta" ||
    keyRaw === "Control" ||
    keyRaw === "Alt" ||
    keyRaw === "Shift"
  )
    return "";
  const mods = {
    Cmd: !!e.metaKey,
    Ctrl: !!e.ctrlKey,
    Alt: !!e.altKey,
    Shift: !!e.shiftKey,
  };

  let base = "";
  if (/^Key[A-Z]$/.test(codeRaw)) {
    base = codeRaw.slice(3).toLowerCase();
  } else if (/^Digit[0-9]$/.test(codeRaw)) {
    base = codeRaw.slice(5);
  } else if (codeRaw === "Space") {
    base = "Space";
  } else if (codeRaw === "Escape") {
    base = "Escape";
  } else if (codeRaw === "Equal") {
    base = "=";
  } else if (codeRaw === "Minus") {
    base = "-";
  } else {
    const shiftedDigitBase = SHIFT_DIGIT_SYMBOL_TO_KEY[keyRaw];
    if (shiftedDigitBase)
      return buildKeybindValue(
        shiftedDigitBase,
        Object.assign({}, mods, { Shift: true }),
      );
    base = normalizeBaseKeyValue(keyRaw);
  }

  if (!base) return "";
  if (base === "=" || base === "-" || base === "Escape") return base;
  return buildKeybindValue(base, mods);
}

function isSafeKey(key) {
  const base = normalizeBaseKeyValue(key);
  return SAFE_KEY_SET.has(base);
}

function isSafeKeybindValue(keybind) {
  const parsed = parseKeybindValue(keybind);
  if (!parsed.key) return true;
  return isSafeKey(parsed.key);
}

function keyLabel(key) {
  if (!key) return "Unassigned";
  const norm = normalizeKeyValue(key);
  const parsed = parseKeybindValue(norm);
  if (!parsed.key) return "Unassigned";
  const modText = KEY_MODIFIER_ORDER.filter((mod) => parsed.mods[mod])
    .map((mod) => KEY_MODIFIER_LABELS[mod] || mod)
    .join("+");
  const base = KEY_LABELS[parsed.key]
    ? KEY_LABELS[parsed.key]
    : parsed.key.length === 1
      ? parsed.key.toUpperCase()
      : parsed.key;
  return modText ? `${modText}+${base}` : base;
}

