      WS.meta && WS.meta.tagThumbPresets ? WS.meta.tagThumbPresets.size : 0;
    const tagModeCount =
      WS.meta && WS.meta.tagThumbModes ? WS.meta.tagThumbModes.size : 0;
    const total = cropCount + dirCount + tagPresetCount + tagModeCount;
