function metaComputeFingerprints() {
  WS.meta.dirFingerprints.clear();
  if (!WS.root) return;

  (function walk(node) {
    for (const d of node.childrenDirs) walk(d);

    const fileIds = node.childrenFiles.slice().sort();
    const childFps = node.childrenDirs
      .slice()
      .map((d) => {
        const fp = WS.meta.dirFingerprints.get(d.path || "");
        return Number.isFinite(fp) ? fp : 0;
      })
      .sort((a, b) => a - b);

    let s = "F:";
    for (let i = 0; i < fileIds.length; i++) s += fileIds[i] + "|";
    s += "D:";
    for (let i = 0; i < childFps.length; i++) s += childFps[i] + "|";

    const fp = hash32(s);
    WS.meta.dirFingerprints.set(node.path || "", fp);
  })(WS.root);
}

function metaMakeScoresLogObject() {
  const folders = {};
  for (const [path, node] of WS.dirByPath.entries()) {
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    folders[path] = { score: metaGetScore(path), fp: fp >>> 0 };
  }
  return {
    schema: 2,
    updatedAt: Date.now(),
    sortMode: normalizeDirSortMode(WS.meta.dirSortMode),
    folders,
    scoreHistory: normalizeScoreHistoryList(
      WS.meta && Array.isArray(WS.meta.scoreHistory)
        ? WS.meta.scoreHistory
        : [],
    ),
  };
}

function metaMakeTagsLogObject() {
  const folders = {};
  const tagByFp = {};
  const hiddenTagByKey = {};
  const thumbnailByFolder = {};
  const mediaPresetByFolder = {};
  const mediaPresetByTagContext = {};
  const tagThumbnailModeByTag = {};
  const tagThumbnailByTag = {};
  const tagAlbumByTag = {};
  const fileThumbnailCropByRelPath = {};
  const videoThumbnailTimeByRelPath = {};
  for (const [path, node] of WS.dirByPath.entries()) {
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    const tags = metaGetTags(path).filter(
      (tag) => tag !== LEGACY_PROCESSING_DISABLED_TAG,
    );
    folders[path] = { fp: fp >>> 0, tags: tags };
    if (
      WS.meta &&
      WS.meta.dirThumbPresets &&
      WS.meta.dirThumbPresets.has(path)
    ) {
      const rawThumb = String(WS.meta.dirThumbPresets.get(path) || "");
      if (
        rawThumb === FOLDER_THUMB_NONE_SENTINEL ||
        rawThumb === FOLDER_THUMB_ROTATE_SENTINEL
      ) {
        thumbnailByFolder[path] = rawThumb;
      } else {
        const presetRelPath = normalizeWorkspaceRelPath(rawThumb);
        if (presetRelPath) thumbnailByFolder[path] = presetRelPath;
      }
    }
    if (
      WS.meta &&
      WS.meta.dirAppearancePresetIds &&
      WS.meta.dirAppearancePresetIds.has(path)
    ) {
      const presetId = normalizeAppearancePresetIdValue(
        WS.meta.dirAppearancePresetIds.get(path),
      );
      if (presetId) mediaPresetByFolder[path] = presetId;
    }
    if (tags && tags.length) {
      const k = String(fp >>> 0);
      if (!tagByFp[k]) tagByFp[k] = tags.slice();
    }
  }
  if (WS.meta && WS.meta.tagThumbModes) {
    for (const [tagKey, modeRaw] of WS.meta.tagThumbModes.entries()) {
      const key = String(tagKey || "");
      if (!key) continue;
      const mode = normalizeTagThumbnailMode(modeRaw);
      if (mode === "quad") continue;
      tagThumbnailModeByTag[key] = mode;
    }
  }
  if (WS.meta && WS.meta.hiddenTagKeys) {
    for (const tagKeyRaw of WS.meta.hiddenTagKeys.values()) {
      const tagKey = String(tagKeyRaw || "");
      if (!tagKey) continue;
      hiddenTagByKey[tagKey] = true;
    }
  }
  if (WS.meta && WS.meta.tagThumbPresets) {
    for (const [tagKey, relPathRaw] of WS.meta.tagThumbPresets.entries()) {
      const key = String(tagKey || "");
      if (!key) continue;
      const relPath = normalizeWorkspaceRelPath(relPathRaw);
      if (!relPath) continue;
      tagThumbnailByTag[key] = relPath;
    }
  }
  if (WS.meta && WS.meta.tagAlbumByTag) {
    for (const [tagKeyRaw, albumRaw] of WS.meta.tagAlbumByTag.entries()) {
      const parsed = parseTagAlbumMembershipKey(tagKeyRaw);
      const album = normalizeTagAlbumName(albumRaw);
      if (!parsed || !album) continue;
      tagAlbumByTag[parsed.key] = album;
    }
  }
  if (WS.meta && WS.meta.tagAppearancePresetIds) {
    for (const [
      tagKeyRaw,
      presetIdRaw,
    ] of WS.meta.tagAppearancePresetIds.entries()) {
      const tagKey = String(tagKeyRaw || "");
      const presetId = normalizeAppearancePresetIdValue(presetIdRaw);
      if (!tagKey || !presetId) continue;
      mediaPresetByTagContext[tagKey] = presetId;
    }
  }
  if (WS.meta && WS.meta.fileThumbCrop) {
    for (const [relPathRaw, cropRaw] of WS.meta.fileThumbCrop.entries()) {
      const relPath = normalizeWorkspaceRelPath(relPathRaw);
      if (!relPath) continue;
      const normalizedCrop = normalizeThumbCropValue(cropRaw);
      if (isThumbCropDefault(normalizedCrop)) continue;
      fileThumbnailCropByRelPath[relPath] = normalizedCrop;
    }
  }
  if (WS.meta && WS.meta.videoThumbTime) {
    for (const [relPathRaw, timeRaw] of WS.meta.videoThumbTime.entries()) {
      const relPath = normalizeWorkspaceRelPath(relPathRaw);
      const timeValue = normalizeVideoThumbTimeValue(timeRaw);
      if (!relPath || !Number.isFinite(timeValue)) continue;
      videoThumbnailTimeByRelPath[relPath] = timeValue;
    }
  }
  const pending =
    WS.meta && WS.meta.pendingTagsByPath ? WS.meta.pendingTagsByPath : null;
  if (pending && pending.size) {
    for (const [path, tags] of pending.entries()) {
      const p = String(path || "");
      if (!p || folders[p]) continue;
      const tg = normalizeTagList(tags);
      if (!tg.length) continue;
      folders[p] = { fp: 0, tags: tg };
    }
  }
  return {
    schema: 1,
    updatedAt: Date.now(),
    folders,
    tagByFp,
    thumbnailByFolder,
    mediaPresetByFolder,
    mediaPresetByTagContext,
    hiddenTagByKey,
    tagThumbnailModeByTag,
    tagThumbnailByTag,
    tagAlbumByTag,
    fileThumbnailCropByRelPath,
    videoThumbnailTimeByRelPath,
  };
}

function metaMakeOptionsLogObject() {
  return {
    schema: 2,
    updatedAt: Date.now(),
    options: normalizeOptions(WS.meta.options || null),
    appearancePresets: normalizeAppearancePresetList(
      WS.meta && Array.isArray(WS.meta.appearancePresets)
        ? WS.meta.appearancePresets
        : null,
    ),
  };
}

function metaMakeKeybindsLogObject() {
  const bindings = Array.isArray(WS.meta.keybinds)
    ? syncPaneKeybindBindingsWithCurrentActions(false)
    : defaultKeybinds(WS.meta && WS.meta.appearancePresets);
  const gridBindings = Array.isArray(WS.meta.gridKeybinds)
    ? WS.meta.gridKeybinds
    : defaultGridKeybinds();
  return {
    schema: 1,
    updatedAt: Date.now(),
    bindings: bindings.map((b) => ({ id: b.id, key: b.key || "" })),
    gridBindings: gridBindings.map((b) => ({ id: b.id, key: b.key || "" })),
  };
}

function metaMakeLogObject() {
  const folders = {};
  const tagByFp = {};
  for (const [path, node] of WS.dirByPath.entries()) {
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    const tags = metaGetTags(path);
    folders[path] = { score: metaGetScore(path), fp: fp >>> 0, tags: tags };
    if (tags && tags.length) {
      const k = String(fp >>> 0);
      if (!tagByFp[k]) tagByFp[k] = tags.slice();
    }
  }
  return {
    schema: 2,
    updatedAt: Date.now(),
    sortMode: normalizeDirSortMode(WS.meta.dirSortMode),
    folders,
    tagByFp,
    options: normalizeOptions(WS.meta.options || null),
  };
}

function metaApplyScoresLog(log) {
  if (!log || typeof log !== "object") return;

  const sortMode = normalizeDirSortMode(log.sortMode);
  WS.meta.dirSortMode = sortMode;
  WS.meta.scoreHistory = normalizeScoreHistoryList(log.scoreHistory || []);

  const folders =
    log.folders && typeof log.folders === "object" ? log.folders : {};
  const oldByPath = new Map();
  const oldByFp = new Map();

  for (const p of Object.keys(folders)) {
    const it = folders[p];
    const sc = it && Number.isFinite(it.score) ? it.score | 0 : 0;
    const fp = it && Number.isFinite(it.fp) ? it.fp >>> 0 : 0;
    oldByPath.set(p, { score: sc, fp });
    if (!oldByFp.has(fp)) oldByFp.set(fp, []);
    oldByFp.get(fp).push({ path: p, score: sc });
  }

  const claimed = new Set();
  WS.meta.dirScores.clear();

  for (const [path, node] of WS.dirByPath.entries()) {
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    if (oldByPath.has(path)) {
      WS.meta.dirScores.set(path, oldByPath.get(path).score | 0);
      claimed.add(path);
      continue;
    }
    const list = oldByFp.get(fp >>> 0) || null;
    if (list && list.length) {
      let picked = null;
      for (let i = 0; i < list.length; i++) {
        const cand = list[i];
        if (!claimed.has(cand.path)) {
          picked = cand;
          break;
        }
      }
      if (picked) {
        WS.meta.dirScores.set(path, picked.score | 0);
        claimed.add(picked.path);
        continue;
      }
    }
    WS.meta.dirScores.set(path, 0);
  }
}

function stashPendingTagsFromLog(oldTagsByPath) {
  if (!WS.meta) return;
  WS.meta.pendingTagsByPath = new Map();
  for (const [path, tags] of oldTagsByPath.entries()) {
    if (!tags || !tags.length) continue;
    WS.meta.pendingTagsByPath.set(String(path || ""), normalizeTagList(tags));
  }
}

function applyPendingTagsToWorkspace() {
  const pending = WS.meta && WS.meta.pendingTagsByPath;
  if (!pending || !pending.size) return false;
  let applied = false;
  for (const [path, tags] of pending.entries()) {
    if (!WS.dirByPath.has(path)) continue;
    WS.meta.dirTags.set(path, normalizeTagList(tags));
    pending.delete(path);
    applied = true;
  }
  return applied;
}

function metaApplyTagsLog(log) {
  if (!log || typeof log !== "object") return;

  const folders =
    log.folders && typeof log.folders === "object" ? log.folders : {};
  const oldTagsByPath = new Map();
  const legacyProcessingDisabledPaths = new Set();

  for (const p of Object.keys(folders)) {
    const it = folders[p];
    const rawTags = it && Array.isArray(it.tags) ? it.tags : [];
    for (let i = 0; i < rawTags.length; i++) {
      if (normalizeTag(rawTags[i]) !== LEGACY_PROCESSING_DISABLED_TAG) continue;
      legacyProcessingDisabledPaths.add(normalizeDirPathValue(p));
      break;
    }
    const tg = it && Array.isArray(it.tags) ? normalizeTagList(it.tags) : [];
    if (tg.length) oldTagsByPath.set(p, tg);
  }

  const oldTagByFp = new Map();
  if (log.tagByFp && typeof log.tagByFp === "object") {
    for (const k of Object.keys(log.tagByFp)) {
      const fp = Number(k) >>> 0 || 0;
      const tg = normalizeTagList(log.tagByFp[k]);
      if (tg.length) oldTagByFp.set(fp >>> 0, tg);
    }
  }
  if (!oldTagByFp.size) {
    for (const [p, tg] of oldTagsByPath.entries()) {
      const it = folders[p];
      const fp = it && Number.isFinite(it.fp) ? it.fp >>> 0 : 0;
      if (!fp) continue;
      if (!oldTagByFp.has(fp)) oldTagByFp.set(fp, tg.slice());
    }
  }

  stashPendingTagsFromLog(oldTagsByPath);

  WS.meta.dirTags.clear();
  for (const [path, node] of WS.dirByPath.entries()) {
    if (oldTagsByPath.has(path)) {
      WS.meta.dirTags.set(path, oldTagsByPath.get(path).slice());
      if (WS.meta.pendingTagsByPath) WS.meta.pendingTagsByPath.delete(path);
      continue;
    }
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    const tg = oldTagByFp.get(fp >>> 0) || [];
    WS.meta.dirTags.set(path, tg.slice());
  }

  WS.meta.dirThumbPresets.clear();
  const thumbnailByFolder =
    log.thumbnailByFolder && typeof log.thumbnailByFolder === "object"
      ? log.thumbnailByFolder
      : {};
  for (const dirPath of Object.keys(thumbnailByFolder)) {
    const normalizedDirPath = normalizeDirPathValue(dirPath);
    const rawValue = String(thumbnailByFolder[dirPath] || "");
    const normalizedRelPath = normalizeWorkspaceRelPath(rawValue);
    if (!normalizedDirPath && !WS.dirByPath.has("")) continue;
    if (
      !normalizedRelPath &&
      rawValue !== FOLDER_THUMB_NONE_SENTINEL &&
      rawValue !== FOLDER_THUMB_ROTATE_SENTINEL
    )
      continue;
    if (!WS.dirByPath.has(normalizedDirPath)) continue;
    if (
      rawValue === FOLDER_THUMB_NONE_SENTINEL ||
      rawValue === FOLDER_THUMB_ROTATE_SENTINEL
    ) {
      WS.meta.dirThumbPresets.set(normalizedDirPath, rawValue);
    } else {
      WS.meta.dirThumbPresets.set(normalizedDirPath, normalizedRelPath);
    }
  }

  WS.meta.dirAppearancePresetIds.clear();
  const mediaPresetByFolder =
    log.mediaPresetByFolder && typeof log.mediaPresetByFolder === "object"
      ? log.mediaPresetByFolder
      : {};
  for (const dirPath of Object.keys(mediaPresetByFolder)) {
    const normalizedDirPath = normalizeDirPathValue(dirPath);
    const presetId = normalizeAppearancePresetIdValue(
      mediaPresetByFolder[dirPath],
    );
    if (!presetId) continue;
    if (
      presetId === BUILTIN_NULL_APPEARANCE_PRESET_ID &&
      legacyProcessingDisabledPaths.has(normalizedDirPath)
    )
      continue;
    if (!normalizedDirPath && !WS.dirByPath.has("")) continue;
    if (!WS.dirByPath.has(normalizedDirPath)) continue;
    WS.meta.dirAppearancePresetIds.set(normalizedDirPath, presetId);
  }

  WS.meta.tagAppearancePresetIds.clear();
  const mediaPresetByTagContext =
    log.mediaPresetByTagContext &&
    typeof log.mediaPresetByTagContext === "object"
      ? log.mediaPresetByTagContext
      : {};
  for (const rawTagKey of Object.keys(mediaPresetByTagContext)) {
    const tagKey = String(rawTagKey || "");
    const presetId = normalizeAppearancePresetIdValue(
      mediaPresetByTagContext[rawTagKey],
    );
    if (!tagKey || !presetId) continue;
    WS.meta.tagAppearancePresetIds.set(tagKey, presetId);
  }

  WS.meta.hiddenTagKeys.clear();
  const hiddenTagByKey =
    log.hiddenTagByKey && typeof log.hiddenTagByKey === "object"
      ? log.hiddenTagByKey
      : {};
  for (const rawTagKey of Object.keys(hiddenTagByKey)) {
    const tagKey = String(rawTagKey || "");
    if (!tagKey || !hiddenTagByKey[rawTagKey]) continue;
    WS.meta.hiddenTagKeys.add(tagKey);
  }

  WS.meta.tagThumbModes.clear();
  const tagThumbnailModeByTag =
    log.tagThumbnailModeByTag && typeof log.tagThumbnailModeByTag === "object"
      ? log.tagThumbnailModeByTag
      : {};
  for (const rawKey of Object.keys(tagThumbnailModeByTag)) {
    const key = String(rawKey || "");
    if (!key) continue;
    const mode = normalizeTagThumbnailMode(tagThumbnailModeByTag[rawKey]);
    if (mode === "quad") continue;
    WS.meta.tagThumbModes.set(key, mode);
  }

  WS.meta.tagThumbPresets.clear();
  const tagThumbnailByTag =
    log.tagThumbnailByTag && typeof log.tagThumbnailByTag === "object"
      ? log.tagThumbnailByTag
      : {};
  for (const rawKey of Object.keys(tagThumbnailByTag)) {
    const key = String(rawKey || "");
    if (!key) continue;
    const relPath = normalizeWorkspaceRelPath(tagThumbnailByTag[rawKey]);
    if (!relPath) continue;
    WS.meta.tagThumbPresets.set(key, relPath);
  }
  for (const key of WS.meta.tagThumbPresets.keys()) {
    const mode = metaGetTagThumbnailModeByKey(key);
    if (mode !== "single") WS.meta.tagThumbModes.set(key, "single");
  }

  WS.meta.tagAlbumByTag.clear();
  const tagAlbumByTag =
    log.tagAlbumByTag && typeof log.tagAlbumByTag === "object"
      ? log.tagAlbumByTag
      : {};
  for (const rawKey of Object.keys(tagAlbumByTag)) {
    const parsed = parseTagAlbumMembershipKey(rawKey);
    const album = normalizeTagAlbumName(tagAlbumByTag[rawKey]);
    if (!parsed || !album) continue;
    WS.meta.tagAlbumByTag.set(parsed.key, album);
  }

  WS.meta.fileThumbCrop.clear();
  const fileThumbnailCropByRelPath =
    log.fileThumbnailCropByRelPath &&
    typeof log.fileThumbnailCropByRelPath === "object"
      ? log.fileThumbnailCropByRelPath
      : {};
  for (const rawRelPath of Object.keys(fileThumbnailCropByRelPath)) {
    const relPath = normalizeWorkspaceRelPath(rawRelPath);
    if (!relPath) continue;
    const crop = normalizeThumbCropValue(
      fileThumbnailCropByRelPath[rawRelPath],
    );
    if (isThumbCropDefault(crop)) continue;
    WS.meta.fileThumbCrop.set(relPath, crop);
  }

  WS.meta.videoThumbTime.clear();
  const videoThumbnailTimeByRelPath =
    log.videoThumbnailTimeByRelPath &&
    typeof log.videoThumbnailTimeByRelPath === "object"
      ? log.videoThumbnailTimeByRelPath
      : {};
  for (const rawRelPath of Object.keys(videoThumbnailTimeByRelPath)) {
    const relPath = normalizeWorkspaceRelPath(rawRelPath);
    if (!relPath) continue;
    const timeValue = normalizeVideoThumbTimeValue(
      videoThumbnailTimeByRelPath[rawRelPath],
    );
    if (!Number.isFinite(timeValue)) continue;
    WS.meta.videoThumbTime.set(relPath, timeValue);
  }

  if (cleanupLegacyProcessingDisabledMetadata()) {
    metaTrackDirtyDocIds([META_DOC_IDS.tags]);
  }
}

function metaApplyOptionsLog(log) {
  if (!log || typeof log !== "object") return;
  WS.meta.appearancePresets = normalizeAppearancePresetList(
    log.appearancePresets,
    !Array.isArray(log.appearancePresets),
  );
  WS.meta.options = normalizeOptions(log.options || null);
  syncActiveAppearancePresetSelection(WS.meta.options);
  WS.view.appearancePresetEditingId =
    effectiveActiveAppearancePresetId() || BUILTIN_NULL_APPEARANCE_PRESET_ID;
  WS.view.appearancePresetDraftName = "";
  WS.view.appearancePresetPromptMode = "";
  applyDefaultViewFromOptions();
  applyColorSchemeFromOptions();
  applyRetroModeFromOptions();
  applyMediaFilterFromOptions();
  applyThumbFitFromOptions();
  applyDisplaySizesFromOptions();
  applyDirectoryMiniThumbSizeFromOptions();
  applyDescriptionVisibilityFromOptions();
  applyInteractionModeFromOptions();
  applyPaneDividerFromOptions();
}

function metaApplyKeybindsLog(log) {
  if (!log || typeof log !== "object") return;
  const normalized = normalizeKeybinds(
    log,
    WS.meta && WS.meta.appearancePresets,
  );
  WS.meta.keybinds = normalized.bindings;
  const normalizedGrid = normalizeGridKeybinds(log);
  WS.meta.gridKeybinds = normalizedGrid.bindings;
  rebuildKeybindIndex();
}

function metaApplyFromLog(log) {
  if (!log || typeof log !== "object") return;

  const sortMode = normalizeDirSortMode(log.sortMode);
  WS.meta.dirSortMode = sortMode;

  WS.meta.appearancePresets = defaultAppearancePresets();
  WS.meta.options = normalizeOptions(log.options || null);
  syncActiveAppearancePresetSelection(WS.meta.options);
  WS.view.appearancePresetEditingId =
    effectiveActiveAppearancePresetId() || BUILTIN_NULL_APPEARANCE_PRESET_ID;
  WS.view.appearancePresetDraftName = "";
  WS.view.appearancePresetPromptMode = "";
  applyColorSchemeFromOptions();
  applyRetroModeFromOptions();
  applyMediaFilterFromOptions();
  applyThumbFitFromOptions();
  applyDisplaySizesFromOptions();
  applyDirectoryMiniThumbSizeFromOptions();
  applyDescriptionVisibilityFromOptions();
  applyInteractionModeFromOptions();
  applyPaneDividerFromOptions();

  const folders =
    log.folders && typeof log.folders === "object" ? log.folders : {};
  const oldByPath = new Map();
  const oldByFp = new Map();

  const oldTagsByPath = new Map();

  for (const p of Object.keys(folders)) {
    const it = folders[p];
    const sc = it && Number.isFinite(it.score) ? it.score | 0 : 0;
    const fp = it && Number.isFinite(it.fp) ? it.fp >>> 0 : 0;
    oldByPath.set(p, { score: sc, fp });
    if (!oldByFp.has(fp)) oldByFp.set(fp, []);
    oldByFp.get(fp).push({ path: p, score: sc });

    const tg = it && Array.isArray(it.tags) ? normalizeTagList(it.tags) : [];
    if (tg.length) oldTagsByPath.set(p, tg);
  }

  const oldTagByFp = new Map();
  if (log.tagByFp && typeof log.tagByFp === "object") {
    for (const k of Object.keys(log.tagByFp)) {
      const fp = Number(k) >>> 0 || 0;
      const tg = normalizeTagList(log.tagByFp[k]);
      if (tg.length) oldTagByFp.set(fp >>> 0, tg);
    }
  }
  if (!oldTagByFp.size) {
    for (const [p, tg] of oldTagsByPath.entries()) {
      const it = folders[p];
      const fp = it && Number.isFinite(it.fp) ? it.fp >>> 0 : 0;
      if (!fp) continue;
      if (!oldTagByFp.has(fp)) oldTagByFp.set(fp, tg.slice());
    }
  }

  stashPendingTagsFromLog(oldTagsByPath);

  const claimed = new Set();
  WS.meta.dirScores.clear();

  for (const [path, node] of WS.dirByPath.entries()) {
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    if (oldByPath.has(path)) {
      WS.meta.dirScores.set(path, oldByPath.get(path).score | 0);
      claimed.add(path);
      continue;
    }
    const list = oldByFp.get(fp >>> 0) || null;
    if (list && list.length) {
      let picked = null;
      for (let i = 0; i < list.length; i++) {
        const cand = list[i];
        if (!claimed.has(cand.path)) {
          picked = cand;
          break;
        }
      }
      if (picked) {
        WS.meta.dirScores.set(path, picked.score | 0);
        claimed.add(picked.path);
        continue;
      }
    }
    WS.meta.dirScores.set(path, 0);
  }

  WS.meta.dirTags.clear();
  for (const [path, node] of WS.dirByPath.entries()) {
    if (oldTagsByPath.has(path)) {
      WS.meta.dirTags.set(path, oldTagsByPath.get(path).slice());
      if (WS.meta.pendingTagsByPath) WS.meta.pendingTagsByPath.delete(path);
      continue;
    }
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    const tg = oldTagByFp.get(fp >>> 0) || [];
    WS.meta.dirTags.set(path, tg.slice());
  }

  WS.meta.dirAppearancePresetIds.clear();
  if (cleanupLegacyProcessingDisabledMetadata()) {
    metaTrackDirtyDocIds([META_DOC_IDS.tags]);
  }

  applyDefaultViewFromOptions();
  syncMetaButtons();
  renderOptionsUi();
}

function metaMakeScoresDocObject() {
  const folders = {};
  for (const [path] of WS.dirByPath.entries()) {
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    folders[path] = { score: metaGetScore(path), fp: fp >>> 0 };
  }
  return {
    schema: 1,
    updatedAt: Date.now(),
    folders,
  };
}

function metaMakeScoreHistoryDocObject() {
  return {
    schema: 1,
    updatedAt: Date.now(),
    history: normalizeScoreHistoryList(
      WS.meta && Array.isArray(WS.meta.scoreHistory)
        ? WS.meta.scoreHistory
        : [],
    ),
  };
}

function metaMakeTagsDocObject() {
  const folders = {};
  const tagByFp = {};
  const hiddenTagByKey = {};
  const tagMediaFilterByKey = {};
  for (const [path] of WS.dirByPath.entries()) {
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    const tags = metaGetTags(path).filter(
      (tag) => tag !== LEGACY_PROCESSING_DISABLED_TAG,
    );
    folders[path] = { fp: fp >>> 0, tags };
    if (tags && tags.length) {
      const key = String(fp >>> 0);
      if (!tagByFp[key]) tagByFp[key] = tags.slice();
    }
  }
  const pending =
    WS.meta && WS.meta.pendingTagsByPath ? WS.meta.pendingTagsByPath : null;
  if (pending && pending.size) {
    for (const [path, tags] of pending.entries()) {
      const normalizedPath = String(path || "");
      if (!normalizedPath || folders[normalizedPath]) continue;
      const normalizedTags = normalizeTagList(tags);
      if (!normalizedTags.length) continue;
      folders[normalizedPath] = { fp: 0, tags: normalizedTags };
    }
  }
  if (WS.meta && WS.meta.hiddenTagKeys) {
    for (const tagKeyRaw of WS.meta.hiddenTagKeys.values()) {
      const tagKey = String(tagKeyRaw || "");
      if (!tagKey) continue;
      hiddenTagByKey[tagKey] = true;
    }
  }
  if (WS.meta && WS.meta.tagMediaFilterByKey) {
    for (const [
      tagKeyRaw,
      filterValueRaw,
    ] of WS.meta.tagMediaFilterByKey.entries()) {
      const tagKey = String(tagKeyRaw || "");
      const filterValue = normalizeTagMediaFilterValue(filterValueRaw);
      if (!tagKey || !filterValue.length) continue;
      tagMediaFilterByKey[tagKey] = filterValue.slice();
    }
  }
  return {
    schema: 1,
    updatedAt: Date.now(),
    folders,
    tagByFp,
    hiddenTagByKey,
    tagMediaFilterByKey,
  };
}

function metaMakeTagAlbumsDocObject() {
  const tagAlbumByTag = {};
  if (WS.meta && WS.meta.tagAlbumByTag) {
    for (const [tagKeyRaw, albumRaw] of WS.meta.tagAlbumByTag.entries()) {
      const parsed = parseTagAlbumMembershipKey(tagKeyRaw);
      const album = normalizeTagAlbumName(albumRaw);
      if (!parsed || !album) continue;
      tagAlbumByTag[parsed.key] = album;
    }
  }
  return {
    schema: 1,
    updatedAt: Date.now(),
    tagAlbumByTag,
  };
}

function metaMakeThumbnailsDocObject() {
  const thumbnailByFolder = {};
  const tagThumbnailModeByTag = {};
  const tagThumbnailByTag = {};
  const fileThumbnailCropByRelPath = {};
  const videoThumbnailTimeByRelPath = {};
  if (WS.meta && WS.meta.dirThumbPresets) {
    for (const [path, rawThumbValue] of WS.meta.dirThumbPresets.entries()) {
      const rawThumb = String(rawThumbValue || "");
      if (
        rawThumb === FOLDER_THUMB_NONE_SENTINEL ||
        rawThumb === FOLDER_THUMB_ROTATE_SENTINEL
      ) {
        thumbnailByFolder[path] = rawThumb;
        continue;
      }
      const presetRelPath = normalizeWorkspaceRelPath(rawThumb);
      if (presetRelPath) thumbnailByFolder[path] = presetRelPath;
    }
  }
  if (WS.meta && WS.meta.tagThumbModes) {
    for (const [tagKey, modeRaw] of WS.meta.tagThumbModes.entries()) {
      const key = String(tagKey || "");
      if (!key) continue;
      const mode = normalizeTagThumbnailMode(modeRaw);
      if (mode === "quad") continue;
      tagThumbnailModeByTag[key] = mode;
    }
  }
  if (WS.meta && WS.meta.tagThumbPresets) {
    for (const [tagKey, relPathRaw] of WS.meta.tagThumbPresets.entries()) {
      const key = String(tagKey || "");
      if (!key) continue;
      const relPath = normalizeWorkspaceRelPath(relPathRaw);
      if (!relPath) continue;
      tagThumbnailByTag[key] = relPath;
    }
  }
  if (WS.meta && WS.meta.fileThumbCrop) {
    for (const [relPathRaw, cropRaw] of WS.meta.fileThumbCrop.entries()) {
      const relPath = normalizeWorkspaceRelPath(relPathRaw);
      if (!relPath) continue;
      const normalizedCrop = normalizeThumbCropValue(cropRaw);
      if (isThumbCropDefault(normalizedCrop)) continue;
      fileThumbnailCropByRelPath[relPath] = normalizedCrop;
    }
  }
  if (WS.meta && WS.meta.videoThumbTime) {
    for (const [relPathRaw, timeRaw] of WS.meta.videoThumbTime.entries()) {
      const relPath = normalizeWorkspaceRelPath(relPathRaw);
      const timeValue = normalizeVideoThumbTimeValue(timeRaw);
      if (!relPath || !Number.isFinite(timeValue)) continue;
      videoThumbnailTimeByRelPath[relPath] = timeValue;
    }
  }
  return {
    schema: 1,
    updatedAt: Date.now(),
    thumbnailByFolder,
    tagThumbnailModeByTag,
    tagThumbnailByTag,
    fileThumbnailCropByRelPath,
    videoThumbnailTimeByRelPath,
  };
}

function metaMakeAppearancePresetsDocObject() {
  return {
    schema: 1,
    updatedAt: Date.now(),
    presets: normalizeAppearancePresetList(
      WS.meta && Array.isArray(WS.meta.appearancePresets)
        ? WS.meta.appearancePresets
        : null,
    ),
  };
}

function metaMakeAppearanceAssignmentsDocObject() {
  const mediaPresetByFolder = {};
  const mediaPresetByTagContext = {};
  if (WS.meta && WS.meta.dirAppearancePresetIds) {
    for (const [
      path,
      presetIdRaw,
    ] of WS.meta.dirAppearancePresetIds.entries()) {
      const presetId = normalizeAppearancePresetIdValue(presetIdRaw);
      if (!presetId) continue;
      mediaPresetByFolder[path] = presetId;
    }
  }
  if (WS.meta && WS.meta.tagAppearancePresetIds) {
    for (const [
      tagKeyRaw,
      presetIdRaw,
    ] of WS.meta.tagAppearancePresetIds.entries()) {
      const tagKey = String(tagKeyRaw || "");
      const presetId = normalizeAppearancePresetIdValue(presetIdRaw);
      if (!tagKey || !presetId) continue;
      mediaPresetByTagContext[tagKey] = presetId;
    }
  }
  return {
    schema: 1,
    updatedAt: Date.now(),
    mediaPresetByFolder,
    mediaPresetByTagContext,
  };
}

function metaMakePreferenceSectionLogObject(docId) {
  const optionKeys =
    docId === META_DOC_IDS.prefGeneral
      ? META_GENERAL_PREFERENCE_OPTION_KEYS
      : docId === META_DOC_IDS.prefNotifications
        ? META_PREFERENCE_SECTION_OPTION_KEYS.notifications
      : docId === META_DOC_IDS.prefAppearance
        ? META_PREFERENCE_SECTION_OPTION_KEYS.appearance
        : docId === META_DOC_IDS.prefPlayback
          ? META_PREFERENCE_SECTION_OPTION_KEYS.playback
          : docId === META_DOC_IDS.prefThumbnails
            ? META_PREFERENCE_SECTION_OPTION_KEYS.thumbnails
            : docId === META_DOC_IDS.prefFilenames
              ? META_PREFERENCE_SECTION_OPTION_KEYS.filenames
              : docId === META_DOC_IDS.prefControls
                ? META_PREFERENCE_SECTION_OPTION_KEYS.controls
                : [];
  const source =
    WS.meta && WS.meta.options
      ? normalizeOptions(WS.meta.options)
      : normalizeOptions(null);
  const options = {};
  for (let i = 0; i < optionKeys.length; i++) {
    const key = String(optionKeys[i] || "");
    if (!key) continue;
    options[key] = Object.prototype.hasOwnProperty.call(source, key)
      ? source[key]
      : null;
  }
  const out = {
    schema: 1,
    updatedAt: Date.now(),
    options,
  };
  if (docId === META_DOC_IDS.prefGeneral) {
    out.dirSortMode = normalizeDirSortMode(WS.meta && WS.meta.dirSortMode);
  }
  return out;
}

function metaMakeTrashDocObject() {
  const itemsByTrashPath = {};
  for (const [trashPath, item] of WS.meta.trashItemsByPath.entries()) {
    const normalizedTrashPath = normalizeWorkspaceRelPath(trashPath);
    const normalizedOriginalPath = normalizeWorkspaceRelPath(
      item && item.originalPath,
    );
    if (!normalizedTrashPath || !isPathInsideInternalTrash(normalizedTrashPath))
      continue;
    if (!normalizedOriginalPath || isPathInsideInternalTrash(normalizedOriginalPath))
      continue;
    itemsByTrashPath[normalizedTrashPath] = {
      originalPath: normalizedOriginalPath,
      trashedAt:
        typeof item?.trashedAt === "string" && item.trashedAt.trim()
          ? item.trashedAt
          : new Date().toISOString(),
    };
  }
  return {
    schema: 1,
    updatedAt: Date.now(),
    itemsByTrashPath,
  };
}

function metaDocObjectForId(docId) {
  switch (docId) {
    case META_DOC_IDS.scores:
      return metaMakeScoresDocObject();
    case META_DOC_IDS.scoreHistory:
      return metaMakeScoreHistoryDocObject();
    case META_DOC_IDS.tags:
      return metaMakeTagsDocObject();
    case META_DOC_IDS.tagAlbums:
      return metaMakeTagAlbumsDocObject();
    case META_DOC_IDS.trash:
      return metaMakeTrashDocObject();
    case META_DOC_IDS.thumbnails:
      return metaMakeThumbnailsDocObject();
    case META_DOC_IDS.appearancePresets:
      return metaMakeAppearancePresetsDocObject();
    case META_DOC_IDS.appearanceAssignments:
      return metaMakeAppearanceAssignmentsDocObject();
    case META_DOC_IDS.prefGeneral:
    case META_DOC_IDS.prefNotifications:
    case META_DOC_IDS.prefAppearance:
    case META_DOC_IDS.prefPlayback:
    case META_DOC_IDS.prefThumbnails:
    case META_DOC_IDS.prefFilenames:
    case META_DOC_IDS.prefControls:
      return metaMakePreferenceSectionLogObject(docId);
    case META_DOC_IDS.keybinds:
      return metaMakeKeybindsLogObject();
    default:
      return null;
  }
}

function metaApplyScoresDocLog(log) {
  if (!log || typeof log !== "object") return;
  const folders =
    log.folders && typeof log.folders === "object" ? log.folders : {};
  const oldByPath = new Map();
  const oldByFp = new Map();

  for (const p of Object.keys(folders)) {
    const it = folders[p];
    const sc = it && Number.isFinite(it.score) ? it.score | 0 : 0;
    const fp = it && Number.isFinite(it.fp) ? it.fp >>> 0 : 0;
    oldByPath.set(p, { score: sc, fp });
    if (!oldByFp.has(fp)) oldByFp.set(fp, []);
    oldByFp.get(fp).push({ path: p, score: sc });
  }

  const claimed = new Set();
  WS.meta.dirScores.clear();
  for (const [path] of WS.dirByPath.entries()) {
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    if (oldByPath.has(path)) {
      WS.meta.dirScores.set(path, oldByPath.get(path).score | 0);
      claimed.add(path);
      continue;
    }
    const list = oldByFp.get(fp >>> 0) || null;
    if (list && list.length) {
      let picked = null;
      for (let i = 0; i < list.length; i++) {
        const cand = list[i];
        if (!claimed.has(cand.path)) {
          picked = cand;
          break;
        }
      }
      if (picked) {
        WS.meta.dirScores.set(path, picked.score | 0);
        claimed.add(picked.path);
        continue;
      }
    }
    WS.meta.dirScores.set(path, 0);
  }
}

function metaApplyScoreHistoryDocLog(log) {
  if (!log || typeof log !== "object") return;
  WS.meta.scoreHistory = normalizeScoreHistoryList(
    log.history || log.scoreHistory || [],
  );
}

function metaApplyTagsDocLog(log) {
  if (!log || typeof log !== "object") return;
  const folders =
    log.folders && typeof log.folders === "object" ? log.folders : {};
  const oldTagsByPath = new Map();

  for (const p of Object.keys(folders)) {
    const it = folders[p];
    const tg = it && Array.isArray(it.tags) ? normalizeTagList(it.tags) : [];
    if (tg.length) oldTagsByPath.set(p, tg);
  }

  const oldTagByFp = new Map();
  if (log.tagByFp && typeof log.tagByFp === "object") {
    for (const k of Object.keys(log.tagByFp)) {
      const fp = Number(k) >>> 0 || 0;
      const tg = normalizeTagList(log.tagByFp[k]);
      if (tg.length) oldTagByFp.set(fp >>> 0, tg);
    }
  }
  if (!oldTagByFp.size) {
    for (const [p, tg] of oldTagsByPath.entries()) {
      const it = folders[p];
      const fp = it && Number.isFinite(it.fp) ? it.fp >>> 0 : 0;
      if (!fp) continue;
      if (!oldTagByFp.has(fp)) oldTagByFp.set(fp, tg.slice());
    }
  }

  stashPendingTagsFromLog(oldTagsByPath);

  WS.meta.dirTags.clear();
  for (const [path] of WS.dirByPath.entries()) {
    if (oldTagsByPath.has(path)) {
      WS.meta.dirTags.set(path, oldTagsByPath.get(path).slice());
      if (WS.meta.pendingTagsByPath) WS.meta.pendingTagsByPath.delete(path);
      continue;
    }
    const fp = WS.meta.dirFingerprints.get(path) || 0;
    const tg = oldTagByFp.get(fp >>> 0) || [];
    WS.meta.dirTags.set(path, tg.slice());
  }

  WS.meta.hiddenTagKeys.clear();
  const hiddenTagByKey =
    log.hiddenTagByKey && typeof log.hiddenTagByKey === "object"
      ? log.hiddenTagByKey
      : {};
  for (const rawKey of Object.keys(hiddenTagByKey)) {
    const key = String(rawKey || "");
    if (!key || !hiddenTagByKey[rawKey]) continue;
    WS.meta.hiddenTagKeys.add(key);
  }

  WS.meta.tagMediaFilterByKey.clear();
  const tagMediaFilterByKey =
    log.tagMediaFilterByKey && typeof log.tagMediaFilterByKey === "object"
      ? log.tagMediaFilterByKey
      : {};
  for (const rawKey of Object.keys(tagMediaFilterByKey)) {
    const key = String(rawKey || "");
    const filterValue = normalizeTagMediaFilterValue(
      tagMediaFilterByKey[rawKey],
    );
    if (!key || !filterValue.length) continue;
    WS.meta.tagMediaFilterByKey.set(key, filterValue);
  }
}

function metaApplyTagAlbumsDocLog(log) {
  if (!log || typeof log !== "object") return;
  WS.meta.tagAlbumByTag.clear();
  const tagAlbumByTag =
    log.tagAlbumByTag && typeof log.tagAlbumByTag === "object"
      ? log.tagAlbumByTag
      : {};
  for (const rawKey of Object.keys(tagAlbumByTag)) {
    const parsed = parseTagAlbumMembershipKey(rawKey);
    const album = normalizeTagAlbumName(tagAlbumByTag[rawKey]);
    if (!parsed || !album) continue;
    WS.meta.tagAlbumByTag.set(parsed.key, album);
  }
}

function metaApplyTrashDocLog(log) {
  WS.meta.trashItemsByPath.clear();
  if (!log || typeof log !== "object") return;
  const itemsByTrashPath =
    log.itemsByTrashPath && typeof log.itemsByTrashPath === "object"
      ? log.itemsByTrashPath
      : {};
  for (const rawTrashPath of Object.keys(itemsByTrashPath)) {
    const trashPath = normalizeWorkspaceRelPath(rawTrashPath);
    const item =
      itemsByTrashPath[rawTrashPath] &&
      typeof itemsByTrashPath[rawTrashPath] === "object"
        ? itemsByTrashPath[rawTrashPath]
        : null;
    const originalPath = normalizeWorkspaceRelPath(item && item.originalPath);
    const trashedAt =
      typeof item?.trashedAt === "string" && item.trashedAt.trim()
        ? item.trashedAt
        : new Date().toISOString();
    if (!trashPath || !isPathInsideInternalTrash(trashPath)) continue;
    if (!originalPath || isPathInsideInternalTrash(originalPath)) continue;
    WS.meta.trashItemsByPath.set(trashPath, {
      originalPath,
      trashedAt,
    });
  }
}

function metaApplyThumbnailsDocLog(log) {
  if (!log || typeof log !== "object") return;

  WS.meta.dirThumbPresets.clear();
  const thumbnailByFolder =
    log.thumbnailByFolder && typeof log.thumbnailByFolder === "object"
      ? log.thumbnailByFolder
      : {};
  for (const dirPath of Object.keys(thumbnailByFolder)) {
    const normalizedDirPath = normalizeDirPathValue(dirPath);
    const rawValue = String(thumbnailByFolder[dirPath] || "");
    const normalizedRelPath = normalizeWorkspaceRelPath(rawValue);
    if (!normalizedDirPath && !WS.dirByPath.has("")) continue;
    if (
      !normalizedRelPath &&
      rawValue !== FOLDER_THUMB_NONE_SENTINEL &&
      rawValue !== FOLDER_THUMB_ROTATE_SENTINEL
    )
      continue;
    if (!WS.dirByPath.has(normalizedDirPath)) continue;
    if (
      rawValue === FOLDER_THUMB_NONE_SENTINEL ||
      rawValue === FOLDER_THUMB_ROTATE_SENTINEL
    ) {
      WS.meta.dirThumbPresets.set(normalizedDirPath, rawValue);
    } else {
      WS.meta.dirThumbPresets.set(normalizedDirPath, normalizedRelPath);
    }
  }

  WS.meta.tagThumbModes.clear();
  const tagThumbnailModeByTag =
    log.tagThumbnailModeByTag && typeof log.tagThumbnailModeByTag === "object"
      ? log.tagThumbnailModeByTag
      : {};
  for (const rawKey of Object.keys(tagThumbnailModeByTag)) {
    const key = String(rawKey || "");
    if (!key) continue;
    const mode = normalizeTagThumbnailMode(tagThumbnailModeByTag[rawKey]);
    if (mode === "quad") continue;
    WS.meta.tagThumbModes.set(key, mode);
  }

  WS.meta.tagThumbPresets.clear();
  const tagThumbnailByTag =
    log.tagThumbnailByTag && typeof log.tagThumbnailByTag === "object"
      ? log.tagThumbnailByTag
      : {};
  for (const rawKey of Object.keys(tagThumbnailByTag)) {
    const key = String(rawKey || "");
    if (!key) continue;
    const relPath = normalizeWorkspaceRelPath(tagThumbnailByTag[rawKey]);
    if (!relPath) continue;
    WS.meta.tagThumbPresets.set(key, relPath);
  }
  for (const key of WS.meta.tagThumbPresets.keys()) {
    const mode = metaGetTagThumbnailModeByKey(key);
    if (mode !== "single") WS.meta.tagThumbModes.set(key, "single");
  }

  WS.meta.fileThumbCrop.clear();
  const fileThumbnailCropByRelPath =
    log.fileThumbnailCropByRelPath &&
    typeof log.fileThumbnailCropByRelPath === "object"
      ? log.fileThumbnailCropByRelPath
      : {};
  for (const rawRelPath of Object.keys(fileThumbnailCropByRelPath)) {
    const relPath = normalizeWorkspaceRelPath(rawRelPath);
    if (!relPath) continue;
    const crop = normalizeThumbCropValue(
      fileThumbnailCropByRelPath[rawRelPath],
    );
    if (isThumbCropDefault(crop)) continue;
    WS.meta.fileThumbCrop.set(relPath, crop);
  }

  WS.meta.videoThumbTime.clear();
  const videoThumbnailTimeByRelPath =
    log.videoThumbnailTimeByRelPath &&
    typeof log.videoThumbnailTimeByRelPath === "object"
      ? log.videoThumbnailTimeByRelPath
      : {};
  for (const rawRelPath of Object.keys(videoThumbnailTimeByRelPath)) {
    const relPath = normalizeWorkspaceRelPath(rawRelPath);
    if (!relPath) continue;
    const timeValue = normalizeVideoThumbTimeValue(
      videoThumbnailTimeByRelPath[rawRelPath],
    );
    if (!Number.isFinite(timeValue)) continue;
    WS.meta.videoThumbTime.set(relPath, timeValue);
  }
}

function metaApplyAppearancePresetsDocLog(log) {
  if (!log || typeof log !== "object") return;
  WS.meta.appearancePresets = normalizeAppearancePresetList(
    log.presets || log.appearancePresets,
    !Array.isArray(log.presets || log.appearancePresets),
  );
}

function metaMergeOptionsPartial(partialOptions) {
  const source =
    partialOptions && typeof partialOptions === "object" ? partialOptions : {};
  WS.meta.options = normalizeOptions(
    Object.assign({}, WS.meta.options || normalizeOptions(null), source),
  );
}

function metaApplyPreferenceSectionDocLog(docId, log) {
  if (!log || typeof log !== "object") return;
  if (docId === META_DOC_IDS.prefGeneral) {
    WS.meta.dirSortMode = normalizeDirSortMode(
      log.dirSortMode || WS.meta.dirSortMode,
    );
  }
  metaMergeOptionsPartial(log.options || null);
}

function metaApplyAppearanceAssignmentsDocLog(log) {
  if (!log || typeof log !== "object") return;

  WS.meta.dirAppearancePresetIds.clear();
  const mediaPresetByFolder =
    log.mediaPresetByFolder && typeof log.mediaPresetByFolder === "object"
      ? log.mediaPresetByFolder
      : {};
  for (const dirPath of Object.keys(mediaPresetByFolder)) {
    const normalizedDirPath = normalizeDirPathValue(dirPath);
    const presetId = normalizeAppearancePresetIdValue(
      mediaPresetByFolder[dirPath],
    );
    if (!presetId) continue;
    if (!normalizedDirPath && !WS.dirByPath.has("")) continue;
    if (!WS.dirByPath.has(normalizedDirPath)) continue;
    WS.meta.dirAppearancePresetIds.set(normalizedDirPath, presetId);
  }

  WS.meta.tagAppearancePresetIds.clear();
  const mediaPresetByTagContext =
    log.mediaPresetByTagContext &&
    typeof log.mediaPresetByTagContext === "object"
      ? log.mediaPresetByTagContext
      : {};
  for (const rawTagKey of Object.keys(mediaPresetByTagContext)) {
    const tagKey = String(rawTagKey || "");
    const presetId = normalizeAppearancePresetIdValue(
      mediaPresetByTagContext[rawTagKey],
    );
    if (!tagKey || !presetId) continue;
    WS.meta.tagAppearancePresetIds.set(tagKey, presetId);
  }
}

function metaApplyDocLogById(docId, log) {
  switch (docId) {
    case META_DOC_IDS.scores:
      metaApplyScoresDocLog(log);
      return;
    case META_DOC_IDS.scoreHistory:
      metaApplyScoreHistoryDocLog(log);
      return;
    case META_DOC_IDS.tags:
      metaApplyTagsDocLog(log);
      return;
    case META_DOC_IDS.tagAlbums:
      metaApplyTagAlbumsDocLog(log);
      return;
    case META_DOC_IDS.trash:
      metaApplyTrashDocLog(log);
      return;
    case META_DOC_IDS.thumbnails:
      metaApplyThumbnailsDocLog(log);
      return;
    case META_DOC_IDS.appearancePresets:
      metaApplyAppearancePresetsDocLog(log);
      return;
    case META_DOC_IDS.appearanceAssignments:
      metaApplyAppearanceAssignmentsDocLog(log);
      return;
    case META_DOC_IDS.prefGeneral:
    case META_DOC_IDS.prefNotifications:
    case META_DOC_IDS.prefAppearance:
    case META_DOC_IDS.prefPlayback:
    case META_DOC_IDS.prefThumbnails:
    case META_DOC_IDS.prefFilenames:
    case META_DOC_IDS.prefControls:
      metaApplyPreferenceSectionDocLog(docId, log);
      return;
    case META_DOC_IDS.keybinds:
      metaApplyKeybindsLog(log);
      return;
  }
}

function metaGetTrashRestoreInfo(trashPath) {
  const normalized = normalizeWorkspaceRelPath(trashPath);
  return normalized ? WS.meta.trashItemsByPath.get(normalized) || null : null;
}

function metaSetTrashRestoreInfo(trashPath, originalPath, trashedAt = null) {
  const normalizedTrashPath = normalizeWorkspaceRelPath(trashPath);
  const normalizedOriginalPath = normalizeWorkspaceRelPath(originalPath);
  if (
    !normalizedTrashPath ||
    !normalizedOriginalPath ||
    !isPathInsideInternalTrash(normalizedTrashPath) ||
    isPathInsideInternalTrash(normalizedOriginalPath)
  ) {
    return false;
  }
  const next = {
    originalPath: normalizedOriginalPath,
    trashedAt:
      typeof trashedAt === "string" && trashedAt.trim()
        ? trashedAt
        : new Date().toISOString(),
  };
  const prev = WS.meta.trashItemsByPath.get(normalizedTrashPath) || null;
  if (
    prev &&
    prev.originalPath === next.originalPath &&
    prev.trashedAt === next.trashedAt
  ) {
    return false;
  }
  WS.meta.trashItemsByPath.set(normalizedTrashPath, next);
  metaMarkDirty(META_DOC_IDS.trash);
  return true;
}

function metaDeleteTrashRestoreInfo(trashPath) {
  const normalized = normalizeWorkspaceRelPath(trashPath);
  if (!normalized || !WS.meta.trashItemsByPath.has(normalized)) return false;
  WS.meta.trashItemsByPath.delete(normalized);
  metaMarkDirty(META_DOC_IDS.trash);
  return true;
}

function metaPruneMissingTrashRestoreInfo() {
  let changed = false;
  for (const trashPath of Array.from(WS.meta.trashItemsByPath.keys())) {
    if (WS.dirByPath.has(trashPath)) continue;
    WS.meta.trashItemsByPath.delete(trashPath);
    changed = true;
  }
  if (changed) metaMarkDirty(META_DOC_IDS.trash);
  return changed;
}

function metaFinalizeLoadedState() {
  syncActiveAppearancePresetSelection(WS.meta.options);
  WS.view.appearancePresetEditingId =
    effectiveActiveAppearancePresetId() || BUILTIN_NULL_APPEARANCE_PRESET_ID;
  WS.view.appearancePresetDraftName = "";
  WS.view.appearancePresetPromptMode = "";
  applyDefaultViewFromOptions();
  applyColorSchemeFromOptions();
  applyRetroModeFromOptions();
  applyMediaFilterFromOptions();
  applyThumbFitFromOptions();
  applyDisplaySizesFromOptions();
  applyDirectoryMiniThumbSizeFromOptions();
  applyDescriptionVisibilityFromOptions();
  applyInteractionModeFromOptions();
  applyPaneDividerFromOptions();
}

function metaNormalizeDocIdsToSave(docIds = null) {
  const requested = Array.isArray(docIds)
    ? docIds.slice()
    : Array.from(docIds || []);
  const unique = [];
  const seen = new Set();
  const push = (docId) => {
    const id = String(docId || "");
    if (!id || seen.has(id) || !META_ALL_DOC_IDS.includes(id)) return;
    seen.add(id);
    unique.push(id);
  };
  for (let i = 0; i < requested.length; i++) push(requested[i]);
  if (unique.length) return unique;
  if (WS.meta && WS.meta.dirtyDocIds && WS.meta.dirtyDocIds.size) {
    for (const docId of WS.meta.dirtyDocIds) push(docId);
  }
  if (!unique.length && WS.meta && WS.meta.dirty) {
    for (let i = 0; i < META_ALL_DOC_IDS.length; i++) push(META_ALL_DOC_IDS[i]);
  }
  return unique;
}

function metaTrackDirtyDocIds(docIds = null) {
  if (!WS.meta) return;
  const list = Array.isArray(docIds)
    ? docIds.slice()
    : Array.from(docIds || []);
  const targetIds = list.length ? list : META_ALL_DOC_IDS.slice();
  if (!(WS.meta.dirtyDocIds instanceof Set)) WS.meta.dirtyDocIds = new Set();
  for (let i = 0; i < targetIds.length; i++) {
    const docId = String(targetIds[i] || "");
    if (!META_ALL_DOC_IDS.includes(docId)) continue;
    WS.meta.dirtyDocIds.add(docId);
  }
  WS.meta.dirty = !!WS.meta.dirtyDocIds.size;
}

function metaMarkDirty(...docIds) {
  metaTrackDirtyDocIds(docIds);
  metaScheduleSave();
}

function metaClearSavedDocIds(docIds = null) {
  if (!WS.meta) return;
  const list = metaNormalizeDocIdsToSave(docIds);
  if (!(WS.meta.dirtyDocIds instanceof Set)) WS.meta.dirtyDocIds = new Set();
  for (let i = 0; i < list.length; i++) WS.meta.dirtyDocIds.delete(list[i]);
  WS.meta.dirty = !!WS.meta.dirtyDocIds.size;
}

function metaParseText(text) {
  const t = String(text || "").trim();
  if (!t) return null;
  try {
    return JSON.parse(t);
  } catch {
    return null;
  }
}

function metaLocalKeys() {
  const k = String(WS.meta.storageKey || "");
  if (!k) return null;
  const docs = {};
  for (let i = 0; i < META_ALL_DOC_IDS.length; i++) {
    const docId = META_ALL_DOC_IDS[i];
    const prefix = META_LOCAL_KEY_PREFIXES[docId];
    if (!prefix) continue;
    docs[docId] = `${prefix}::${k}`;
  }
  return {
    docs,
    legacy: {
      scores: `LocalGalleryScores::${k}`,
      tags: `LocalGalleryTags::${k}`,
      options: `LocalGalleryPreferences::${k}`,
      keybinds: `LocalGalleryKeyboard::${k}`,
      combined: `LocalGalleryVotes::${k}`,
    },
  };
}

function metaLoadLocalDoc(key) {
  if (!key) return null;
  try {
    const txt = localStorage.getItem(key);
    return metaParseText(txt);
  } catch {
    return null;
  }
}

function metaSaveLocalDoc(key, obj) {
  if (!key) return;
  try {
    localStorage.setItem(key, JSON.stringify(obj));
  } catch {}
}

function metaClearLegacyLocalDocs(keys) {
  const legacy = keys && keys.legacy;
  if (!legacy) return;
  const doomed = [legacy.combined, legacy.scores, legacy.tags, legacy.options];
  for (let i = 0; i < doomed.length; i++) {
    const key = doomed[i];
    if (!key) continue;
    try {
      localStorage.removeItem(key);
    } catch {}
  }
}

function metaSaveLocalNow(docIds = null) {
  const keys = metaLocalKeys();
  if (!keys) return;
  const ids = metaNormalizeDocIdsToSave(docIds);
  for (let i = 0; i < ids.length; i++) {
    const docId = ids[i];
    const key = keys.docs && keys.docs[docId];
    const obj = metaDocObjectForId(docId);
    if (!key || !obj) continue;
    metaSaveLocalDoc(key, obj);
  }
  metaClearSavedDocIds(ids);
}

function normalizeWorkspaceRelPath(path) {
  const raw = String(path || "")
    .replace(/\\/g, "/")
    .replace(/^\/+|\/+$/g, "");
  if (!raw) return "";
  const parts = raw.split("/").filter(Boolean);
  if (!parts.length) return "";
  if (parts.includes(".local-gallery")) return "";
  return parts.join("/");
}

async function metaEnsureFsHandles(rootHandle) {
  if (!rootHandle) return false;
  try {
    const sys = await rootHandle.getDirectoryHandle(".local-gallery", {
      create: true,
    });
    const docHandles = Object.create(null);
    for (let i = 0; i < META_ALL_DOC_IDS.length; i++) {
      const docId = META_ALL_DOC_IDS[i];
      const fileName = META_DOC_FILE_NAMES[docId];
      if (!fileName) continue;
      docHandles[docId] = await sys.getFileHandle(fileName, { create: true });
    }
    const legacyHandles = {
      scores: await sys.getFileHandle("folder-scores.log.json", {
        create: true,
      }),
      tags: await sys.getFileHandle("folder-tags.log.json", { create: true }),
      options: await sys.getFileHandle("preferences.log.json", {
        create: true,
      }),
      keybinds:
        docHandles[META_DOC_IDS.keybinds] ||
        (await sys.getFileHandle("keyboard-configuration.log.json", {
          create: true,
        })),
      combined: await sys.getFileHandle("folder-votes.log.json", {
        create: true,
      }),
    };
    WS.meta.fsRootHandle = rootHandle;
    WS.meta.fsSysDirHandle = sys;
    WS.meta.fsDocHandles = docHandles;
    WS.meta.fsLegacyDocHandles = legacyHandles;
    WS.meta.storageMode = "fs";
    return true;
  } catch {
    return false;
  }
}

async function metaLoadFsDoc(fh) {
  if (!fh) return null;
  try {
    const f = await fh.getFile();
    const txt = await f.text();
    return metaParseText(txt);
  } catch {
    return null;
  }
}

async function metaSaveFsDoc(fh, obj) {
  if (!fh) return;
  const txt = JSON.stringify(obj);
  try {
    const writable = await fh.createWritable();
    await writable.write(txt);
    await writable.close();
  } catch {}
}

async function metaClearFsDoc(fh) {
  if (!fh) return;
  try {
    const writable = await fh.createWritable();
    await writable.write("");
    await writable.close();
  } catch {}
}

async function metaClearLegacyFsDocs(handles) {
  if (!handles || typeof handles !== "object") return;
  const doomed = [
    handles.combined,
    handles.scores,
    handles.tags,
    handles.options,
  ];
  for (let i = 0; i < doomed.length; i++) {
    await metaClearFsDoc(doomed[i]);
  }
}

function metaFsHandleForDocId(docId) {
  const handles = WS.meta && WS.meta.fsDocHandles;
  if (!handles || typeof handles !== "object") return null;
  return handles[String(docId || "")] || null;
}

async function metaSaveFsNow(docIds = null) {
  const ids = metaNormalizeDocIdsToSave(docIds);
  for (let i = 0; i < ids.length; i++) {
    const docId = ids[i];
    const fh = metaFsHandleForDocId(docId);
    const obj = metaDocObjectForId(docId);
    if (!fh || !obj) continue;
    await metaSaveFsDoc(fh, obj);
  }
  metaClearSavedDocIds(ids);
}

function metaScheduleSave(...docIds) {
  if (docIds.length) metaTrackDirtyDocIds(docIds);
  if (WS.meta.saveTimer) return;
  WS.meta.saveTimer = setTimeout(async () => {
    WS.meta.saveTimer = null;
    const ids = metaNormalizeDocIdsToSave();
    if (!ids.length) return;
    if (WS.meta.storageMode === "fs") await metaSaveFsNow(ids);
    else metaSaveLocalNow(ids);
  }, 500);
}

function showBusyOverlay(text, detail = "") {
  if (busyLabel) busyLabel.textContent = text || "Working...";
  if (busyDetail) busyDetail.textContent = detail || "";
  if (busyOverlay) busyOverlay.classList.add("active");
}

function hideBusyOverlay() {
  if (busyDetail) busyDetail.textContent = "";
  if (busyOverlay) busyOverlay.classList.remove("active");
}

function busyOverlayActive() {
  return !!(busyOverlay && busyOverlay.classList.contains("active"));
}

function metaInitForCurrentWorkspace() {
  metaComputeFingerprints();
  const dirtyDocs = new Set();

  if (WS.meta.storageMode === "local") {
    const keys = metaLocalKeys();
    if (keys) {
      const loadOrder = [
        META_DOC_IDS.appearancePresets,
        META_DOC_IDS.prefGeneral,
        META_DOC_IDS.prefNotifications,
        META_DOC_IDS.prefAppearance,
        META_DOC_IDS.prefPlayback,
        META_DOC_IDS.prefThumbnails,
        META_DOC_IDS.prefFilenames,
        META_DOC_IDS.prefControls,
        META_DOC_IDS.scores,
        META_DOC_IDS.scoreHistory,
        META_DOC_IDS.tags,
        META_DOC_IDS.tagAlbums,
        META_DOC_IDS.trash,
        META_DOC_IDS.thumbnails,
        META_DOC_IDS.appearanceAssignments,
        META_DOC_IDS.keybinds,
      ];
      const splitDocs = [];
      for (let i = 0; i < loadOrder.length; i++) {
        const docId = loadOrder[i];
        const log = metaLoadLocalDoc(keys.docs && keys.docs[docId]);
        if (!log) continue;
        splitDocs.push([docId, log]);
      }

      if (splitDocs.length) {
        for (let i = 0; i < splitDocs.length; i++) {
          metaApplyDocLogById(splitDocs[i][0], splitDocs[i][1]);
        }
        const legacyDisabledPaths = new Set();
        const legacyCombinedLog = metaLoadLocalDoc(keys.legacy.combined);
        const legacyTagsLog = metaLoadLocalDoc(keys.legacy.tags);
        for (const path of collectLegacyProcessingDisabledPathsFromLog(
          legacyCombinedLog,
        ))
          legacyDisabledPaths.add(path);
        for (const path of collectLegacyProcessingDisabledPathsFromLog(
          legacyTagsLog,
        ))
          legacyDisabledPaths.add(path);
        if (cleanupLegacyProcessingDisabledMetadata(legacyDisabledPaths)) {
          dirtyDocs.add(META_DOC_IDS.tags);
          dirtyDocs.add(META_DOC_IDS.appearanceAssignments);
        }
        metaClearLegacyLocalDocs(keys);
      } else {
        const legacyCombinedLog = metaLoadLocalDoc(keys.legacy.combined);
        const legacyScoresLog = metaLoadLocalDoc(keys.legacy.scores);
        const legacyTagsLog = metaLoadLocalDoc(keys.legacy.tags);
        const legacyOptionsLog = metaLoadLocalDoc(keys.legacy.options);

        if (legacyCombinedLog) {
          metaApplyFromLog(legacyCombinedLog);
          for (let i = 0; i < META_ALL_DOC_IDS.length; i++)
            dirtyDocs.add(META_ALL_DOC_IDS[i]);
        }
        if (legacyScoresLog) {
          metaApplyScoresLog(legacyScoresLog);
          for (let i = 0; i < META_ALL_DOC_IDS.length; i++)
            dirtyDocs.add(META_ALL_DOC_IDS[i]);
        }
        if (legacyTagsLog) {
          metaApplyTagsLog(legacyTagsLog);
          for (let i = 0; i < META_ALL_DOC_IDS.length; i++)
            dirtyDocs.add(META_ALL_DOC_IDS[i]);
        }
        if (legacyOptionsLog) {
          metaApplyOptionsLog(legacyOptionsLog);
          for (let i = 0; i < META_ALL_DOC_IDS.length; i++)
            dirtyDocs.add(META_ALL_DOC_IDS[i]);
        }
      }
    }
  }

  if (cleanupLegacyProcessingDisabledMetadata()) {
    dirtyDocs.add(META_DOC_IDS.tags);
    dirtyDocs.add(META_DOC_IDS.appearanceAssignments);
  }
  if (metaPruneMissingTrashRestoreInfo()) {
    dirtyDocs.add(META_DOC_IDS.trash);
  }

  metaFinalizeLoadedState();
  if (dirtyDocs.size) {
    const list = Array.from(dirtyDocs);
    metaMarkDirty(...list);
  }
  syncMetaButtons();
  renderOptionsUi();
  applyDescriptionVisibilityFromOptions();
  applyPaneDividerFromOptions();
}

async function metaInitForCurrentWorkspaceFs() {
  metaComputeFingerprints();
  const dirtyDocs = new Set();
  const legacyHandles =
    WS.meta && WS.meta.fsLegacyDocHandles ? WS.meta.fsLegacyDocHandles : {};

  const loadOrder = [
    META_DOC_IDS.appearancePresets,
    META_DOC_IDS.prefGeneral,
    META_DOC_IDS.prefNotifications,
    META_DOC_IDS.prefAppearance,
    META_DOC_IDS.prefPlayback,
    META_DOC_IDS.prefThumbnails,
    META_DOC_IDS.prefFilenames,
    META_DOC_IDS.prefControls,
    META_DOC_IDS.scores,
    META_DOC_IDS.scoreHistory,
    META_DOC_IDS.tags,
    META_DOC_IDS.tagAlbums,
    META_DOC_IDS.trash,
    META_DOC_IDS.thumbnails,
    META_DOC_IDS.appearanceAssignments,
    META_DOC_IDS.keybinds,
  ];
  const splitDocs = [];
  for (let i = 0; i < loadOrder.length; i++) {
    const docId = loadOrder[i];
    const log = await metaLoadFsDoc(metaFsHandleForDocId(docId));
    if (!log) continue;
    splitDocs.push([docId, log]);
  }

  if (splitDocs.length) {
    for (let i = 0; i < splitDocs.length; i++) {
      metaApplyDocLogById(splitDocs[i][0], splitDocs[i][1]);
    }
    const legacyDisabledPaths = new Set();
    const legacyCombinedLog = await metaLoadFsDoc(legacyHandles.combined);
    const legacyTagsLog = await metaLoadFsDoc(legacyHandles.tags);
    for (const path of collectLegacyProcessingDisabledPathsFromLog(
      legacyCombinedLog,
    ))
      legacyDisabledPaths.add(path);
    for (const path of collectLegacyProcessingDisabledPathsFromLog(
      legacyTagsLog,
    ))
      legacyDisabledPaths.add(path);
    if (cleanupLegacyProcessingDisabledMetadata(legacyDisabledPaths)) {
      dirtyDocs.add(META_DOC_IDS.tags);
      dirtyDocs.add(META_DOC_IDS.appearanceAssignments);
    }
    await metaClearLegacyFsDocs(legacyHandles);
  } else {
    const legacyCombinedLog = await metaLoadFsDoc(legacyHandles.combined);
    const legacyScoresLog = await metaLoadFsDoc(legacyHandles.scores);
    const legacyTagsLog = await metaLoadFsDoc(legacyHandles.tags);
    const legacyOptionsLog = await metaLoadFsDoc(legacyHandles.options);

    if (legacyCombinedLog) {
      metaApplyFromLog(legacyCombinedLog);
      for (let i = 0; i < META_ALL_DOC_IDS.length; i++)
        dirtyDocs.add(META_ALL_DOC_IDS[i]);
    }
    if (legacyScoresLog) {
      metaApplyScoresLog(legacyScoresLog);
      for (let i = 0; i < META_ALL_DOC_IDS.length; i++)
        dirtyDocs.add(META_ALL_DOC_IDS[i]);
    }
    if (legacyTagsLog) {
      metaApplyTagsLog(legacyTagsLog);
      for (let i = 0; i < META_ALL_DOC_IDS.length; i++)
        dirtyDocs.add(META_ALL_DOC_IDS[i]);
    }
    if (legacyOptionsLog) {
      metaApplyOptionsLog(legacyOptionsLog);
      for (let i = 0; i < META_ALL_DOC_IDS.length; i++)
        dirtyDocs.add(META_ALL_DOC_IDS[i]);
    }
  }

  if (metaPruneMissingTrashRestoreInfo()) {
    dirtyDocs.add(META_DOC_IDS.trash);
  }

  if (cleanupLegacyProcessingDisabledMetadata()) {
    dirtyDocs.add(META_DOC_IDS.tags);
    dirtyDocs.add(META_DOC_IDS.appearanceAssignments);
  }

  metaFinalizeLoadedState();
  if (dirtyDocs.size) metaMarkDirty(...Array.from(dirtyDocs));
  syncMetaButtons();
  renderOptionsUi();
  applyDescriptionVisibilityFromOptions();
  applyPaneDividerFromOptions();
}

async function metaReapplyFsScoresAndTags() {
  metaComputeFingerprints();
  const scoresLog = await metaLoadFsDoc(
    metaFsHandleForDocId(META_DOC_IDS.scores),
  );
  const tagsLog = await metaLoadFsDoc(metaFsHandleForDocId(META_DOC_IDS.tags));
  if (scoresLog) metaApplyScoresDocLog(scoresLog);
  if (tagsLog) metaApplyTagsDocLog(tagsLog);
}

async function buildWorkspaceFromFiles(fileList) {
  resetWorkspace();
  clearWorkspaceEmptyState();

  WS.root = makeDirNode(inferRootNameFromFileList(fileList), null);
  WS.root.path = "";
  WS.dirByPath.set("", WS.root);
  applyMediaFilterFromOptions();

  const files = Array.from(fileList || []);

  for (const f of files) {
    if (!f || !f.name) continue;
    if (f.name[0] === ".") continue;

    const relPath = f.webkitRelativePath || f.name;
    if (relPath.split("/").includes(".local-gallery")) continue;

    const parts = relPath.split("/").filter(Boolean);
    if (!parts.length) continue;

    const filename = parts[parts.length - 1];
    const dirPath = parts.slice(0, -1).join("/");
    const isImg = isImageName(filename);
    const isVid = isVideoName(filename);
    if (!isImg && !isVid) continue;

    const id = fileKey(f, relPath);
    if (WS.fileById.has(id)) continue;

    const extDot = filename.lastIndexOf(".");
    const ext = extDot >= 0 ? filename.slice(extDot).toLowerCase() : "";

    const rec = {
      id,
      file: f,
      name: filename,
      relPath,
      dirPath,
      ext,
      type: isVid ? "video" : "image",
      size: f.size,
      lastModified: f.lastModified,
      url: null,
      thumbUrl: null,
      videoThumbUrl: null,
      indices: null,
      thumbMode: null,
      videoThumbMode: null,
      nativePath: "",
    };

    rec.nativePath = getNativePathForFile(f);
    WS.fileById.set(id, rec);
    const dirNode = ensureDirPath(dirPath);
    dirNode.childrenFiles.push(id);
  }

  normalizeRootIfSingleDir();

  WS.view.randomSeed = computeWorkspaceSeed();
  WS.view.randomCache = new Map();
  WS.view.randomFolderCache = new Map();

  WS.meta.storageMode = "local";
  WS.meta.storageKey = String(WS.view.randomSeed >>> 0);

  metaInitForCurrentWorkspace();
  hydrateEditedThumbnailAspects()
    .then((changed) => {
      if (!changed || !WS.root) return;
      renderDirectoriesPane(true);
      renderPreviewPane(false, true);
      syncButtons();
      kickVideoThumbsForPreview();
      kickImageThumbsForPreview();
    })
    .catch(() => {});

  // Initialize List Pane at root listing
  WS.nav.dirNode = WS.root;
  WS.view.aboveRootView = false;
  syncActivePaneWithLayout();
  syncBulkSelectionForCurrentDir();
  syncFavoritesUi();
  syncTagUiForCurrentDir();
  rebuildDirectoriesEntries();
  WS.nav.selectedIndex = 0;
  WS.nav.selectedIndex = findNearestSelectableIndex(WS.nav.selectedIndex, 1);
  syncPreviewToSelection({ force: true });
  primeDirectoryNavManifests(WS.root);
  syncPinnedHotNavigationDirectories(WS.root);
  applyDefaultRootLandingSidebars();

  await prepareNavigationSnapshot(
    currentNavigationSnapshot(),
    "Preparing directory thumbnails...",
  );

  renderDirectoriesPane();
  renderPreviewPane(true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  scheduleWorkspaceNavigationWarm(WS.root, 1000);
  syncMetaButtons();
  initDirHistory();
}

async function collectFilesFromDirHandle(dirHandle, basePath, out) {
  for await (const [name, handle] of dirHandle.entries()) {
    if (name === ".local-gallery") continue;
    if (handle.kind === "file") {
      const f = await handle.getFile();
      if (!f || !f.name) continue;
      if (f.name[0] === ".") continue;
      const relPath = basePath ? basePath + "/" + name : name;
      out.push({ file: f, relPath });
    } else if (handle.kind === "directory") {
      const nextBase = basePath ? basePath + "/" + name : name;
      await collectFilesFromDirHandle(handle, nextBase, out);
    }
  }
}

async function ensureInternalTrashDirectoryForRootHandle(rootHandle) {
  if (!rootHandle) return false;
  try {
    await rootHandle.getDirectoryHandle(INTERNAL_TRASH_DIR_NAME, {
      create: true,
    });
    return true;
  } catch {
    try {
      await rootHandle.getDirectoryHandle(INTERNAL_TRASH_DIR_NAME);
      return true;
    } catch {
      return false;
    }
  }
}

async function buildWorkspaceFromDirectoryHandle(rootHandle) {
  resetWorkspace();
  clearWorkspaceEmptyState();

  WS.root = makeDirNode(String(rootHandle?.name || "root"), null);
  WS.root.path = "";
  WS.dirByPath.set("", WS.root);
  applyMediaFilterFromOptions();

  const trashDirAvailable = await ensureInternalTrashDirectoryForRootHandle(
    rootHandle,
  );
  const all = [];
  await collectFilesFromDirHandle(rootHandle, "", all);

  for (const it of all) {
    const f = it.file;
    const relPath = it.relPath || f.name;
    if (relPath.split("/").includes(".local-gallery")) continue;

    const parts = relPath.split("/").filter(Boolean);
    if (!parts.length) continue;

    const filename = parts[parts.length - 1];
    const dirPath = parts.slice(0, -1).join("/");
    const isImg = isImageName(filename);
    const isVid = isVideoName(filename);
    if (!isImg && !isVid) continue;

    const id = fileKey(f, relPath);
    if (WS.fileById.has(id)) continue;

    const extDot = filename.lastIndexOf(".");
    const ext = extDot >= 0 ? filename.slice(extDot).toLowerCase() : "";

    const rec = {
      id,
      file: f,
      name: filename,
      relPath,
      dirPath,
      ext,
      type: isVid ? "video" : "image",
      size: f.size,
      lastModified: f.lastModified,
      url: null,
      thumbUrl: null,
      videoThumbUrl: null,
      indices: null,
      thumbMode: null,
      videoThumbMode: null,
      nativePath: "",
    };

    rec.nativePath = getNativePathForFile(f);
    WS.fileById.set(id, rec);
    const dirNode = ensureDirPath(dirPath);
    dirNode.childrenFiles.push(id);
  }

  if (trashDirAvailable) ensureDirPath(INTERNAL_TRASH_DIR_NAME);

  normalizeRootIfSingleDir();

  WS.view.randomSeed = computeWorkspaceSeed();
  WS.view.randomCache = new Map();
  WS.view.randomFolderCache = new Map();

  const ok = await metaEnsureFsHandles(rootHandle);
  if (!ok) {
    WS.meta.storageMode = "local";
    WS.meta.storageKey = String(WS.view.randomSeed >>> 0);
    metaInitForCurrentWorkspace();
  } else {
    WS.meta.storageKey = String(WS.view.randomSeed >>> 0);
    await metaInitForCurrentWorkspaceFs();
    if (WS.meta.saveTimer) {
      clearTimeout(WS.meta.saveTimer);
      WS.meta.saveTimer = null;
    }
    if (WS.meta.dirtyDocIds && WS.meta.dirtyDocIds.size) metaScheduleSave();
  }

  try {
    await hydrateEditedThumbnailAspects();
  } catch {}

  WS.nav.dirNode = WS.root;
  WS.view.aboveRootView = false;
  syncActivePaneWithLayout();
  syncBulkSelectionForCurrentDir();
  syncFavoritesUi();
  syncTagUiForCurrentDir();
  rebuildDirectoriesEntries();
  WS.nav.selectedIndex = 0;
  WS.nav.selectedIndex = findNearestSelectableIndex(WS.nav.selectedIndex, 1);
  syncPreviewToSelection({ force: true });
  primeDirectoryNavManifests(WS.root);
  syncPinnedHotNavigationDirectories(WS.root);
  applyDefaultRootLandingSidebars();

  await prepareNavigationSnapshot(
    currentNavigationSnapshot(),
    "Preparing directory thumbnails...",
  );

  renderDirectoriesPane();
  renderPreviewPane(true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  scheduleWorkspaceNavigationWarm(WS.root, 1000);
  syncMetaButtons();
  initDirHistory();
}

async function buildWorkspaceFromFileList(fileList) {
  const files = Array.from(fileList || []).filter(Boolean);
  if (!files.length) return false;

  resetWorkspace();
  clearWorkspaceEmptyState();

  let rootName = "root";
  for (let i = 0; i < files.length; i++) {
    const rel = String(files[i]?.webkitRelativePath || "");
    const parts = rel.split("/").filter(Boolean);
    if (parts.length > 1) {
      rootName = parts[0];
      break;
    }
  }

  WS.root = makeDirNode(rootName, null);
  WS.root.path = "";
  WS.dirByPath.set("", WS.root);
  applyMediaFilterFromOptions();

  for (let i = 0; i < files.length; i++) {
    const f = files[i];
    if (!f) continue;
    const rawRelPath = String(f.webkitRelativePath || f.name || "");
    const relParts = rawRelPath.split("/").filter(Boolean);
    if (!relParts.length) continue;
    const relPath =
      relParts.length > 1 ? relParts.slice(1).join("/") : relParts[0];
    if (!relPath || relPath.split("/").includes(".local-gallery")) continue;

    const parts = relPath.split("/").filter(Boolean);
    if (!parts.length) continue;

    const filename = parts[parts.length - 1];
    const dirPath = parts.slice(0, -1).join("/");
    const isImg = isImageName(filename);
    const isVid = isVideoName(filename);
    if (!isImg && !isVid) continue;

    const id = fileKey(f, relPath);
    if (WS.fileById.has(id)) continue;

    const extDot = filename.lastIndexOf(".");
    const ext = extDot >= 0 ? filename.slice(extDot).toLowerCase() : "";

    const rec = {
      id,
      file: f,
      name: filename,
      relPath,
      dirPath,
      ext,
      type: isVid ? "video" : "image",
      size: f.size,
      lastModified: f.lastModified,
      url: null,
      thumbUrl: null,
      videoThumbUrl: null,
      indices: null,
      thumbMode: null,
      videoThumbMode: null,
      nativePath: "",
    };

    rec.nativePath = getNativePathForFile(f);
    WS.fileById.set(id, rec);
    const dirNode = ensureDirPath(dirPath);
    dirNode.childrenFiles.push(id);
  }

  normalizeRootIfSingleDir();

  WS.view.randomSeed = computeWorkspaceSeed();
  WS.view.randomCache = new Map();
  WS.view.randomFolderCache = new Map();

  WS.meta.storageMode = "local";
  WS.meta.storageKey = String(WS.view.randomSeed >>> 0);
  WS.meta.fsRootHandle = null;
  WS.meta.fsSysDirHandle = null;
  WS.meta.fsDocHandles = Object.create(null);
  WS.meta.fsLegacyDocHandles = Object.create(null);
  metaInitForCurrentWorkspace();

  try {
    await hydrateEditedThumbnailAspects();
  } catch {}

  WS.nav.dirNode = WS.root;
  WS.view.aboveRootView = false;
  syncActivePaneWithLayout();
  syncBulkSelectionForCurrentDir();
  syncFavoritesUi();
  syncTagUiForCurrentDir();
  rebuildDirectoriesEntries();
  WS.nav.selectedIndex = 0;
  WS.nav.selectedIndex = findNearestSelectableIndex(WS.nav.selectedIndex, 1);
  syncPreviewToSelection();
  primeDirectoryNavManifests(WS.root);
  syncPinnedHotNavigationDirectories(WS.root);
  applyDefaultRootLandingSidebars();

  await prepareNavigationSnapshot(
    currentNavigationSnapshot(),
    "Preparing directory thumbnails...",
  );

  renderDirectoriesPane();
  renderPreviewPane(true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  scheduleWorkspaceNavigationWarm(WS.root, 1000);
  syncMetaButtons();
  initDirHistory();
  showStatusMessage("Loaded folder in read-only mode.");
  return true;
}

function snapshotRefreshState() {
  const entry = WS.nav.entries[WS.nav.selectedIndex] || null;
  let entryKey = null;
  if (entry && entry.kind === "dir") {
    entryKey = { kind: "dir", path: String(entry.node?.path || "") };
  } else if (entry && entry.kind === "file") {
    const rec = WS.fileById.get(entry.id);
    entryKey = { kind: "file", relPath: String(rec?.relPath || "") };
  }

  return {
    dirPath: String(WS.nav.dirNode?.path || ""),
    entryKey,
    view: {
      filterMode: WS.view.filterMode,
      randomMode: !!WS.view.randomMode,
      randomFolderMode: !!WS.view.randomFolderMode,
      loopWithinDir: WS.view.loopWithinDir,
      aboveRootView: !!WS.view.aboveRootView,
      tagFolderActiveMode: WS.view.tagFolderActiveMode,
      tagFolderActiveTag: WS.view.tagFolderActiveTag,
      tagFolderActiveAlbum: WS.view.tagFolderActiveAlbum,
      tagFolderOriginPath: WS.view.tagFolderOriginPath,
      favoritesMode: WS.view.favoritesMode,
      favoritesRootActive: !!WS.view.favoritesRootActive,
      favoritesAnchorPath: WS.view.favoritesAnchorPath,
      hiddenMode: WS.view.hiddenMode,
      hiddenRootActive: !!WS.view.hiddenRootActive,
      hiddenAnchorPath: WS.view.hiddenAnchorPath,
      dirSearchPinned: WS.view.dirSearchPinned,
      previewSearchActive: !!WS.view.previewSearchActive,
      dirSearchQuery: WS.view.dirSearchQuery,
      searchRootActive: WS.view.searchRootActive,
      searchRootPath: WS.view.searchRootPath,
      searchAnchorPath: WS.view.searchAnchorPath,
      searchEntryRootPath: WS.view.searchEntryRootPath,
      searchRootIsFavorites: WS.view.searchRootIsFavorites,
      searchRootIsHidden: WS.view.searchRootIsHidden,
    },
  };
}

function restoreRefreshViewState(viewState) {
  if (!viewState) return;
  WS.view.filterMode = viewState.filterMode;
  WS.view.randomMode = !!viewState.randomMode;
  WS.view.randomFolderMode = !!viewState.randomFolderMode;
  WS.view.loopWithinDir = viewState.loopWithinDir;
  WS.view.folderBehavior = "slide";
  WS.view.aboveRootView = !!viewState.aboveRootView && showRootViewEnabled();
  WS.view.tagFolderActiveMode = String(viewState.tagFolderActiveMode || "");
  WS.view.tagFolderActiveTag = String(viewState.tagFolderActiveTag || "");
  WS.view.tagFolderActiveAlbum = String(viewState.tagFolderActiveAlbum || "");
  WS.view.tagFolderOriginPath = String(viewState.tagFolderOriginPath || "");
  WS.view.favoritesMode = !!viewState.favoritesMode;
  WS.view.favoritesRootActive = !!viewState.favoritesRootActive;
  WS.view.favoritesAnchorPath = String(viewState.favoritesAnchorPath || "");
  WS.view.hiddenMode = !!viewState.hiddenMode;
  WS.view.hiddenRootActive = !!viewState.hiddenRootActive;
  WS.view.hiddenAnchorPath = String(viewState.hiddenAnchorPath || "");
  WS.view.dirSearchPinned = !!viewState.dirSearchPinned;
  WS.view.previewSearchActive = !!viewState.previewSearchActive;
  WS.view.dirSearchQuery = String(viewState.dirSearchQuery || "");
  WS.view.searchRootActive = !!viewState.searchRootActive;
  WS.view.searchRootPath = String(viewState.searchRootPath || "");
  WS.view.searchAnchorPath = String(viewState.searchAnchorPath || "");
  WS.view.searchEntryRootPath = String(viewState.searchEntryRootPath || "");
  WS.view.searchRootIsFavorites = !!viewState.searchRootIsFavorites;
  WS.view.searchRootIsHidden = !!viewState.searchRootIsHidden;
  WS.view.searchRootFavorites = WS.view.searchRootIsFavorites
    ? getAllFavoriteDirs()
    : [];
  WS.view.searchRootHidden = WS.view.searchRootIsHidden
    ? getAllHiddenDirs()
    : [];
}

function restoreRefreshSelection(entryKey) {
  if (!entryKey) return 0;
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (!entry) continue;
    if (entryKey.kind === "dir" && entry.kind === "dir") {
      if (String(entry.node?.path || "") === String(entryKey.path || ""))
        return i;
    } else if (entryKey.kind === "file" && entry.kind === "file") {
      const rec = WS.fileById.get(entry.id);
      if (String(rec?.relPath || "") === String(entryKey.relPath || ""))
        return i;
    }
  }
  return 0;
}

function captureViewerCloseRestoreState(opts = null) {
  const options = opts && typeof opts === "object" ? opts : {};
  const snap = snapshotRefreshState();
  const previewContextKey = currentPreviewSelectionContextKeyFromState();
  const tagNavStack = Array.isArray(WS.view && WS.view.tagNavStack)
    ? WS.view.tagNavStack.map((frame) =>
        frame && typeof frame === "object" ? Object.assign({}, frame) : frame,
      )
    : [];
  return {
    dirPath: String(snap.dirPath || ""),
    entryKey: entryKeyForSelection(
      WS.nav.entries[WS.nav.selectedIndex] || null,
    ),
    view: snap.view ? Object.assign({}, snap.view) : null,
    tagNavStack,
    activePane: String(
      options.activePane || WS.view.activePane || "directories",
    ),
    directoriesScrollTop: getDirectoriesScrollTop(),
    previewState: capturePreviewRestoreState(),
    pendingPreviewSelectionKey: String(
      options.pendingPreviewSelectionKey || "",
    ),
    previewContextKey,
    previewSelectedKey: String((WS.view && WS.view.previewSelectedKey) || ""),
    previewFolderBridgeReturnState: cloneViewerCloseRestoreState(
      WS.view?.previewFolderBridgeReturnState,
    ),
  };
}

function capturePreviewRestoreState(previewState = null) {
  const src =
    previewState && typeof previewState === "object" ? previewState : WS.preview;
  if (!src || !src.kind) return null;
  if (src.kind === "dir" && src.dirNode) {
    if (src.dirNode._skipTagFilters) {
      return {
        kind: "tag-dir",
        mode: String(src.dirNode._tagPreviewMode || ""),
        tag: String(src.dirNode._tagPreviewTag || ""),
        album: String(src.dirNode._tagPreviewAlbum || ""),
        originPath: String(
          src.dirNode._tagPreviewOriginPath || src.dirNode.parent?.path || "",
        ),
      };
    }
    return {
      kind: "dir",
      path: String(src.dirNode.path || ""),
    };
  }
  if (src.kind === "file" && src.fileId) {
    return {
      kind: "file",
      fileId: String(src.fileId || ""),
      dirPath: String(src.dirNode?.path || ""),
    };
  }
  return null;
}

function clonePreviewRestoreState(state) {
  if (!state || typeof state !== "object") return null;
  const kind = String(state.kind || "");
  if (kind === "tag-dir") {
    return {
      kind,
      mode: String(state.mode || ""),
      tag: String(state.tag || ""),
      album: String(state.album || ""),
      originPath: String(state.originPath || ""),
    };
  }
  if (kind === "dir") {
    return {
      kind,
      path: String(state.path || ""),
    };
  }
  if (kind === "file") {
    return {
      kind,
      fileId: String(state.fileId || ""),
      dirPath: String(state.dirPath || ""),
    };
  }
  return null;
}

function cloneViewerCloseRestoreState(state) {
  if (!state || typeof state !== "object") return null;
  return {
    dirPath: String(state.dirPath || ""),
    entryKey: String(state.entryKey || ""),
    view:
      state.view && typeof state.view === "object"
        ? Object.assign({}, state.view)
        : null,
    tagNavStack: Array.isArray(state.tagNavStack)
      ? state.tagNavStack
          .map((frame) =>
            frame && typeof frame === "object" ? Object.assign({}, frame) : frame,
          )
          .filter(Boolean)
      : [],
    activePane:
      state.activePane === "directories" ? "directories" : "preview",
    directoriesScrollTop: Number(state.directoriesScrollTop) || 0,
    previewState: clonePreviewRestoreState(state.previewState),
    pendingPreviewSelectionKey: String(state.pendingPreviewSelectionKey || ""),
    previewContextKey: String(state.previewContextKey || ""),
    previewSelectedKey: String(state.previewSelectedKey || ""),
    previewFolderBridgeReturnState: state.previewFolderBridgeReturnState
      ? cloneViewerCloseRestoreState(state.previewFolderBridgeReturnState)
      : null,
  };
}

function retargetViewerCloseRestoreStateToDir(state, dirNode) {
  if (!state || !dirNode) return state;
  const targetPath = String(dirNode.path || "");
  if (!targetPath) return state;
  const targetEntryKey = `dir:${targetPath}`;
  const view = state.view && typeof state.view === "object" ? state.view : null;
  const hasPortalHistory = !!(
    Array.isArray(state.tagNavStack) && state.tagNavStack.length
  );
  const plainDirectoryContext = !!(
    dirNode.parent &&
    view &&
    !view.searchRootActive &&
    !view.tagFolderActiveMode &&
    !view.favoritesMode &&
    !view.hiddenMode &&
    !hasPortalHistory
  );

  state.entryKey = targetEntryKey;
  state.previewState = capturePreviewRestoreState({
    kind: "dir",
    dirNode,
    fileId: null,
  });
  state.previewContextKey = targetEntryKey;
  if (plainDirectoryContext) {
    state.dirPath = String(dirNode.parent?.path || "");
  }

  const nested = cloneViewerCloseRestoreState(state.previewFolderBridgeReturnState);
  if (nested) {
    nested.pendingPreviewSelectionKey = targetEntryKey;
    state.previewFolderBridgeReturnState = nested;
  }

  return state;
}

function resolvePreviewFileBridgeReturnState(pendingPreviewSelectionKey = "") {
  const base = cloneViewerCloseRestoreState(WS.view?.previewFileBridgeReturnState);
  if (!base) return null;
  base.activePane = "preview";
  base.pendingPreviewSelectionKey = String(pendingPreviewSelectionKey || "");

  const currentPreviewDir =
    WS.preview && WS.preview.kind === "file" ? WS.preview.dirNode || null : null;
  if (currentPreviewDir && !currentPreviewDir._skipTagFilters) {
    retargetViewerCloseRestoreStateToDir(base, currentPreviewDir);
  }

  return base;
}

function restorePreviewFolderBridgeState() {
  const state = cloneViewerCloseRestoreState(WS.view?.previewFolderBridgeReturnState);
  WS.view.previewFolderBridgeReturnState = null;
  if (!state) return false;
  state.activePane = "preview";
  return restoreViewerCloseState(state);
}

function restoreViewerCloseState(state) {
  if (!state || !WS.root) return false;
  cancelPendingNavigationRender();
  restoreRefreshViewState(state.view || null);
  WS.view.tagNavStack = Array.isArray(state.tagNavStack)
    ? state.tagNavStack
        .map((frame) =>
          frame && typeof frame === "object" ? Object.assign({}, frame) : frame,
        )
        .filter(Boolean)
    : [];
  WS.view.previewFolderBridgeReturnState = cloneViewerCloseRestoreState(
    state.previewFolderBridgeReturnState,
  );
  WS.nav.dirNode = WS.dirByPath.get(String(state.dirPath || "")) || WS.root;
  pruneStaleVirtualPortalFramesForPath(WS.nav.dirNode?.path || "");
  TAG_EDIT_PATH = null;
  clearBulkTagPlaceholder();
  syncBulkSelectionForCurrentDir();
  syncFavoritesUi();
  syncHiddenUi();
  syncTagUiForCurrentDir();
  rebuildDirectoriesEntries();
  const idx = findEntryIndexByKey(String(state.entryKey || ""));
  WS.nav.selectedIndex = findNearestSelectableIndex(idx >= 0 ? idx : 0, 1);
  setActivePane(
    state.activePane === "preview" || state.activePane === "directories"
      ? state.activePane
      : "directories",
  );
  const previewState = clonePreviewRestoreState(state.previewState);
  const previewContextKey = String(state.previewContextKey || "");
  let restoredPreview = false;
  if (WS.view.activePane === "preview") {
    if (previewState && previewState.kind === "tag-dir") {
      const previewNode = makeTagPreviewNodeForContext(
        previewState.mode || "",
        previewState.tag || "",
        previewState.originPath || "",
        previewState.album || "",
      );
      if (previewNode) {
        applyPreviewState({ kind: "dir", dirNode: previewNode, fileId: null });
        restoredPreview = true;
      }
    } else if (previewState && previewState.kind === "dir") {
      const previewNode =
        WS.dirByPath.get(String(previewState.path || "")) || null;
      if (previewNode) {
        applyPreviewState({ kind: "dir", dirNode: previewNode, fileId: null });
        restoredPreview = true;
      }
    } else if (previewState && previewState.kind === "file") {
      const previewFileId = String(previewState.fileId || "");
      if (previewFileId && WS.fileById.has(previewFileId)) {
        applyPreviewState({
          kind: "file",
          dirNode: WS.dirByPath.get(String(previewState.dirPath || "")) || null,
          fileId: previewFileId,
        });
        restoredPreview = true;
      }
    } else if (previewContextKey.startsWith("dir:")) {
      const previewPath = previewContextKey.slice(4);
      const previewNode = WS.dirByPath.get(previewPath) || null;
      if (previewNode) {
        applyPreviewState({ kind: "dir", dirNode: previewNode, fileId: null });
        restoredPreview = true;
      }
    } else if (previewContextKey.startsWith("file:")) {
      const previewFileId = previewContextKey.slice(5);
      if (previewFileId && WS.fileById.has(previewFileId)) {
        applyPreviewState({
          kind: "file",
          dirNode: null,
          fileId: previewFileId,
        });
        restoredPreview = true;
      }
    }
  }
  if (!restoredPreview) syncPreviewToSelection();
  WS.view.pendingPreviewSelectionKey = String(
    state.pendingPreviewSelectionKey ||
      (WS.view.activePane === "preview" ? state.previewSelectedKey || "" : ""),
  );
  renderDirectoriesPane(true);
  if (
    directoriesListEl &&
    Number.isFinite(Number(state.directoriesScrollTop))
  ) {
    directoriesListEl.scrollTop = Math.max(
      0,
      Number(state.directoriesScrollTop) || 0,
    );
  }
  renderPreviewPane(false, true);
  if (WS.view.activePane === "preview") activatePreviewPaneSelection();
  else updatePreviewSelectionClasses();
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  return true;
}

async function refreshWorkspaceFromRootHandle() {
  const rootHandle = WS.meta.fsRootHandle;
  if (!rootHandle) return;
  const state = snapshotRefreshState();

  await buildWorkspaceFromDirectoryHandle(rootHandle);

  restoreRefreshViewState(state?.view);
  const targetDir = WS.dirByPath.get(state?.dirPath || "") || WS.root;
  if (targetDir) WS.nav.dirNode = targetDir;

  if (WS.view.dirSearchPinned || String(WS.view.dirSearchQuery || "").trim()) {
    computeDirectorySearchResults();
  }

  rebuildDirectoriesEntries();
  const idx = restoreRefreshSelection(state?.entryKey);
  WS.nav.selectedIndex = findNearestSelectableIndex(idx, 1);
  syncPreviewToSelection();
  scheduleNearbyDirectoryRamWarm(currentNavigationSnapshot());
  renderDirectoriesPane(true);
  renderPreviewPane(true, true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
}

async function getDirectoryHandleForPath(rootHandle, path) {
  const norm = String(path || "").replace(/^\/+|\/+$/g, "");
  if (!norm) {
    DIR_HANDLE_CACHE.set("", rootHandle);
    return rootHandle;
  }
  if (DIR_HANDLE_CACHE.has(norm)) return DIR_HANDLE_CACHE.get(norm);
  let cur = rootHandle;
  let acc = "";
  const parts = norm.split("/").filter(Boolean);
  for (const part of parts) {
    acc = acc ? acc + "/" + part : part;
    if (DIR_HANDLE_CACHE.has(acc)) {
      cur = DIR_HANDLE_CACHE.get(acc);
      continue;
    }
    cur = await cur.getDirectoryHandle(part);
    DIR_HANDLE_CACHE.set(acc, cur);
  }
  return cur;
}

async function ensureDirectoryHandleForPath(rootHandle, path) {
  const norm = String(path || "").replace(/^\/+|\/+$/g, "");
  if (!norm) {
    DIR_HANDLE_CACHE.set("", rootHandle);
    return rootHandle;
  }
  if (DIR_HANDLE_CACHE.has(norm)) return DIR_HANDLE_CACHE.get(norm);
  let cur = rootHandle;
  let acc = "";
  const parts = norm.split("/").filter(Boolean);
  for (const part of parts) {
    acc = acc ? acc + "/" + part : part;
    if (DIR_HANDLE_CACHE.has(acc)) {
      cur = DIR_HANDLE_CACHE.get(acc);
      continue;
    }
    cur = await cur.getDirectoryHandle(part, { create: true });
    DIR_HANDLE_CACHE.set(acc, cur);
  }
  return cur;
}

function invalidateDirHandleCache(prefix) {
  const p = String(prefix || "");
  if (!p) {
    DIR_HANDLE_CACHE = new Map();
    return;
  }
  for (const key of Array.from(DIR_HANDLE_CACHE.keys())) {
    if (key === p || key.startsWith(p + "/")) DIR_HANDLE_CACHE.delete(key);
  }
}

async function copyDirectoryHandle(srcHandle, dstHandle) {
  for await (const [name, handle] of srcHandle.entries()) {
    if (name === ".local-gallery") continue;
    if (handle.kind === "file") {
      const file = await handle.getFile();
      const dstFile = await dstHandle.getFileHandle(name, { create: true });
      const writable = await dstFile.createWritable();
      await writable.write(file);
      await writable.close();
    } else if (handle.kind === "directory") {
      const childDst = await dstHandle.getDirectoryHandle(name, {
        create: true,
      });
      await copyDirectoryHandle(handle, childDst);
    }
  }
}

async function renameDirectoryOnDisk(oldPath, newName) {
  const rootHandle = WS.meta.fsRootHandle;
  if (!rootHandle) throw new Error("No writable folder loaded.");

  const parts = String(oldPath || "")
    .split("/")
    .filter(Boolean);
  const oldName = parts.pop() || "";
  const parentPath = parts.join("/");

  const parentHandle = await getDirectoryHandleForPath(rootHandle, parentPath);

  let existing = null;
  try {
    existing = await parentHandle.getDirectoryHandle(newName);
  } catch {}
  if (existing) throw new Error("Target folder exists.");

  const srcHandle = await parentHandle.getDirectoryHandle(oldName);

  if (typeof srcHandle.move === "function") {
    try {
      await srcHandle.move(parentHandle, newName);
      return;
    } catch {}
  }

  const dstHandle = await parentHandle.getDirectoryHandle(newName, {
    create: true,
  });
  await copyDirectoryHandle(srcHandle, dstHandle);
  await parentHandle.removeEntry(oldName, { recursive: true });
}

async function renameFileOnDisk(dirHandle, fileHandle, oldName, newName) {
  if (!dirHandle || !fileHandle) return false;
  if (typeof fileHandle.move === "function") {
    try {
      await fileHandle.move(dirHandle, newName);
      return true;
    } catch {}
  }
  try {
    const file = await fileHandle.getFile();
    const dstFile = await dirHandle.getFileHandle(newName, { create: true });
    const writable = await dstFile.createWritable();
    await writable.write(file);
    await writable.close();
    await dirHandle.removeEntry(oldName);
    return true;
  } catch {}
  return false;
}

async function renameDirectoryHandleInParent(
  parentHandle,
  dirHandle,
  oldName,
  newName,
) {
  if (!parentHandle || !dirHandle) return false;
  if (typeof dirHandle.move === "function") {
    try {
      await dirHandle.move(parentHandle, newName);
      return true;
    } catch {}
  }
  try {
    const dstHandle = await parentHandle.getDirectoryHandle(newName, {
      create: true,
    });
    await copyDirectoryHandle(dirHandle, dstHandle);
    await parentHandle.removeEntry(oldName, { recursive: true });
    return true;
  } catch {}
  return false;
}

function sanitizeFsNamePart(value) {
  return String(value || "")
    .replace(/[^A-Za-z0-9 _-]+/g, "")
    .trim()
    .replace(/ {2,}/g, " ");
}

function sanitizeFsEntryName(name) {
  const raw = String(name || "");
  if (!raw || raw === "." || raw === "..") return raw;

  if (raw.startsWith(".")) {
    const rest = raw.slice(1);
    if (!rest || !rest.includes(".")) {
      const sanitizedHidden = sanitizeFsNamePart(rest);
      return sanitizedHidden ? `.${sanitizedHidden}` : "";
    }
  }

  if (raw.includes(".")) {
    const dotIndex = raw.lastIndexOf(".");
    const stem = raw.slice(0, dotIndex);
    const ext = raw.slice(dotIndex + 1);
    const sanitizedStem = sanitizeFsNamePart(stem);
    const sanitizedExt = sanitizeFsNamePart(ext);
    if (sanitizedStem && sanitizedExt) return `${sanitizedStem}.${sanitizedExt}`;
    if (sanitizedStem) return sanitizedStem;
    if (sanitizedExt) return sanitizedExt;
    return "";
  }

  return sanitizeFsNamePart(raw);
}

function remapTagThumbnailPresetPathsForRename(oldPrefix, newPrefix) {
  if (!WS.meta || !WS.meta.tagThumbPresets) return;
  const next = new Map();
  for (const [tagKey, relPath] of WS.meta.tagThumbPresets.entries()) {
    const remapped = normalizeWorkspaceRelPath(
      remapPathPrefix(oldPrefix, newPrefix, relPath),
    );
    if (!remapped) continue;
    next.set(String(tagKey || ""), remapped);
  }
  WS.meta.tagThumbPresets = next;
}

function remapRestoreStateForPathRename(state, oldPrefix, newPrefix) {
  if (!state || typeof state !== "object") return;
  state.dirPath = remapPathPrefix(oldPrefix, newPrefix, state.dirPath);
  if (state.entryKey && state.entryKey.kind === "dir") {
    state.entryKey.path = remapPathPrefix(
      oldPrefix,
      newPrefix,
      state.entryKey.path,
    );
  } else if (state.entryKey && state.entryKey.kind === "file") {
    state.entryKey.relPath = remapPathPrefix(
      oldPrefix,
      newPrefix,
      state.entryKey.relPath,
    );
  }
  const view = state.view && typeof state.view === "object" ? state.view : null;
  if (!view) return;
  view.tagFolderOriginPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    view.tagFolderOriginPath,
  );
  view.favoritesAnchorPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    view.favoritesAnchorPath,
  );
  view.hiddenAnchorPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    view.hiddenAnchorPath,
  );
  view.searchRootPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    view.searchRootPath,
  );
  view.searchAnchorPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    view.searchAnchorPath,
  );
  view.searchEntryRootPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    view.searchEntryRootPath,
  );
}

function remapRestoreStateForFileRename(state, oldRelPath, newRelPath) {
  if (!state || typeof state !== "object") return;
  if (
    state.entryKey &&
    state.entryKey.kind === "file" &&
    String(state.entryKey.relPath || "") === String(oldRelPath || "")
  ) {
    state.entryKey.relPath = String(newRelPath || "");
  }
}

async function collectSanitizeNameCandidatesRecursive(
  dirHandle,
  basePath = "",
  progressCb = null,
) {
  const out = [];
  let scanned = 0;

  const walk = async (parentHandle, parentPath) => {
    for await (const [name, handle] of parentHandle.entries()) {
      if (name === ".local-gallery") continue;
      if (!parentPath && name === INTERNAL_TRASH_DIR_NAME) continue;
      if (handle.kind !== "file" && handle.kind !== "directory") continue;
      const relPath = parentPath ? `${parentPath}/${name}` : name;
      if (handle.kind === "directory") {
        await walk(handle, relPath);
      }
      scanned += 1;
      const sanitizedName = sanitizeFsEntryName(name);
      if (sanitizedName !== name) {
        out.push({
          kind: handle.kind,
          path: relPath,
          parentPath,
          oldName: name,
          newName: sanitizedName,
          parentHandle,
          handle,
        });
      }
      if (progressCb) {
        await progressCb(scanned, out.length);
      }
    }
  };

  await walk(dirHandle, basePath);
  return out;
}

async function sanitizeWorkspaceNames() {
  if (RENAME_BUSY) return false;
  if (!WS.meta.fsRootHandle) {
    showStatusMessage("Sanitize names requires a writable folder.");
    return false;
  }

  const rootHandle = WS.meta.fsRootHandle;
  const restoreState = snapshotRefreshState();
  const dirtyDocIds = new Set();
  let renamed = 0;
  let failed = 0;
  let skipped = 0;
  let scanned = 0;

  RENAME_BUSY = true;
  try {
    showBusyOverlay("Scanning names... 0 checked");
    const candidates = await collectSanitizeNameCandidatesRecursive(
      rootHandle,
      "",
      async (nextScanned, foundCount) => {
        scanned = nextScanned;
        if (nextScanned <= 5 || nextScanned % 25 === 0) {
          showBusyOverlay(
            `Scanning names... ${nextScanned} checked • ${foundCount} pending`,
            "",
          );
          await new Promise((resolve) => requestAnimationFrame(() => resolve()));
        }
      },
    );

    if (!candidates.length) {
      showStatusMessage(
        scanned
          ? "No file or folder names need sanitizing."
          : "Nothing found to sanitize.",
      );
      return false;
    }

    for (let i = 0; i < candidates.length; i++) {
      const item = candidates[i];
      const label = displayPath(item.path || "") || item.oldName || "item";
      showBusyOverlay(
        `Sanitizing names... ${i + 1}/${candidates.length} • Renamed ${renamed} • Failed ${failed} • Skipped ${skipped}`,
        label,
      );

      if (!item.newName) {
        skipped += 1;
        continue;
      }
      if (await entryExistsInDir(item.parentHandle, item.newName)) {
        skipped += 1;
        continue;
      }

      let ok = false;
      if (item.kind === "directory") {
        ok = await renameDirectoryHandleInParent(
          item.parentHandle,
          item.handle,
          item.oldName,
          item.newName,
        );
      } else if (item.kind === "file") {
        ok = await renameFileOnDisk(
          item.parentHandle,
          item.handle,
          item.oldName,
          item.newName,
        );
      }

      if (!ok) {
        failed += 1;
        continue;
      }

      renamed += 1;
      const oldPath = String(item.path || "");
      const newPath = item.parentPath ? `${item.parentPath}/${item.newName}` : item.newName;

      if (item.kind === "directory") {
        const dirNode = WS.dirByPath.get(oldPath) || null;
        if (dirNode) {
          const renamedPaths = applyRenameInMemory(dirNode, item.newName);
          updateFileRecordsForRename(renamedPaths.oldPath, renamedPaths.newPath);
          remapTagThumbnailPresetPathsForRename(
            renamedPaths.oldPath,
            renamedPaths.newPath,
          );
          remapRestoreStateForPathRename(
            restoreState,
            renamedPaths.oldPath,
            renamedPaths.newPath,
          );
        } else {
          remapRestoreStateForPathRename(restoreState, oldPath, newPath);
        }
        dirtyDocIds.add(META_DOC_IDS.scores);
        dirtyDocIds.add(META_DOC_IDS.scoreHistory);
        dirtyDocIds.add(META_DOC_IDS.tags);
        dirtyDocIds.add(META_DOC_IDS.thumbnails);
        dirtyDocIds.add(META_DOC_IDS.appearanceAssignments);
        dirtyDocIds.add(META_DOC_IDS.trash);
      } else {
        const rec = findFileRecordByRelPath(oldPath);
        if (rec) {
          const dirNode =
            WS.dirByPath.get(String(rec.dirPath || "")) ||
            WS.dirByPath.get(String(item.parentPath || "")) ||
            null;
          if (dirNode) {
            await updateFileRecordsForFileRenames(
              dirNode,
              new Map([[item.oldName, item.newName]]),
              item.parentHandle,
            );
          } else {
            remapFolderThumbnailPresetValues(new Map([[oldPath, newPath]]));
          }
        } else {
          remapFolderThumbnailPresetValues(new Map([[oldPath, newPath]]));
        }
        remapRestoreStateForFileRename(restoreState, oldPath, newPath);
        dirtyDocIds.add(META_DOC_IDS.thumbnails);
      }
    }

    if (!renamed) {
      showStatusMessage(
        failed || skipped
          ? `Sanitize finished: ${skipped} skipped, ${failed} failed.`
          : "No names sanitized.",
      );
      return false;
    }

    metaComputeFingerprints();

    if (dirtyDocIds.size) {
      metaTrackDirtyDocIds(Array.from(dirtyDocIds));
      if (WS.meta.storageMode === "fs") await metaSaveFsNow();
      else metaSaveLocalNow();
    }

    showBusyOverlay("Reloading workspace...");
    await buildWorkspaceFromDirectoryHandle(rootHandle);
    restoreRefreshViewState(restoreState.view);
    const targetDir = WS.dirByPath.get(restoreState.dirPath || "") || WS.root;
    if (targetDir) WS.nav.dirNode = targetDir;
    if (WS.view.dirSearchPinned || String(WS.view.dirSearchQuery || "").trim()) {
      computeDirectorySearchResults();
    }
    rebuildDirectoriesEntries();
    const idx = restoreRefreshSelection(restoreState.entryKey);
    WS.nav.selectedIndex = findNearestSelectableIndex(idx, 1);
    syncPreviewToSelection();
    scheduleNearbyDirectoryRamWarm(currentNavigationSnapshot());
    renderDirectoriesPane(true);
    renderPreviewPane(true, true);
    syncButtons();
    kickVideoThumbsForPreview();
    kickImageThumbsForPreview();

    showStatusMessage(
      `Sanitize complete: ${renamed} renamed, ${skipped} skipped, ${failed} failed.`,
    );
    return true;
  } catch (err) {
    console.error("Sanitize names failed.", err);
    showStatusMessage("Sanitize names failed.");
    return false;
  } finally {
    RENAME_BUSY = false;
    hideBusyOverlay();
  }
}

function updateViewStatePathsForRename(oldPrefix, newPrefix) {
  WS.view.dirActionMenuPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    WS.view.dirActionMenuPath,
  );
  WS.view.searchRootPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    WS.view.searchRootPath,
  );
  WS.view.searchAnchorPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    WS.view.searchAnchorPath,
  );
  WS.view.searchEntryRootPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    WS.view.searchEntryRootPath,
  );
  WS.view.favoritesAnchorPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    WS.view.favoritesAnchorPath,
  );
  WS.view.hiddenAnchorPath = remapPathPrefix(
    oldPrefix,
    newPrefix,
    WS.view.hiddenAnchorPath,
  );

  if (WS.view.favoritesReturnState) {
    WS.view.favoritesReturnState.dirPath = remapPathPrefix(
      oldPrefix,
      newPrefix,
      WS.view.favoritesReturnState.dirPath,
    );
    if (
      WS.view.favoritesReturnState.sel &&
      WS.view.favoritesReturnState.sel.kind === "dir"
    ) {
      WS.view.favoritesReturnState.sel.path = remapPathPrefix(
        oldPrefix,
        newPrefix,
        WS.view.favoritesReturnState.sel.path,
      );
    }
  }

  if (WS.view.hiddenReturnState) {
    WS.view.hiddenReturnState.dirPath = remapPathPrefix(
      oldPrefix,
      newPrefix,
      WS.view.hiddenReturnState.dirPath,
    );
    if (
      WS.view.hiddenReturnState.sel &&
      WS.view.hiddenReturnState.sel.kind === "dir"
    ) {
      WS.view.hiddenReturnState.sel.path = remapPathPrefix(
        oldPrefix,
        newPrefix,
        WS.view.hiddenReturnState.sel.path,
      );
    }
  }

  WS.view.bulkTagSelectionsByDir = remapPathMapKeys(
    WS.view.bulkTagSelectionsByDir,
    oldPrefix,
    newPrefix,
  );
  WS.view.bulkTagFolderSelectionsByDir = remapPathMapKeys(
    WS.view.bulkTagFolderSelectionsByDir,
    oldPrefix,
    newPrefix,
  );
  WS.view.bulkFileSelectionsByDir = remapPathMapKeys(
    WS.view.bulkFileSelectionsByDir,
    oldPrefix,
    newPrefix,
  );
  WS.view.bulkTagSelectedPaths = remapPathSet(
    WS.view.bulkTagSelectedPaths,
    oldPrefix,
    newPrefix,
  );
}

function updateMetaPathsForRename(oldPrefix, newPrefix) {
  WS.meta.dirScores = remapPathMapKeys(WS.meta.dirScores, oldPrefix, newPrefix);
  WS.meta.dirTags = remapPathMapKeys(WS.meta.dirTags, oldPrefix, newPrefix);
  WS.meta.pendingTagsByPath = remapPathMapKeys(
    WS.meta.pendingTagsByPath,
    oldPrefix,
    newPrefix,
  );
  WS.meta.dirFingerprints = remapPathMapKeys(
    WS.meta.dirFingerprints,
    oldPrefix,
    newPrefix,
  );
  WS.meta.dirThumbPresets = remapPathMapKeys(
    WS.meta.dirThumbPresets,
    oldPrefix,
    newPrefix,
  );
  WS.meta.dirAppearancePresetIds = remapPathMapKeys(
    WS.meta.dirAppearancePresetIds,
    oldPrefix,
    newPrefix,
  );
  WS.meta.dirThumbPresets = remapPathMapValues(
    WS.meta.dirThumbPresets,
    oldPrefix,
    newPrefix,
  );
  WS.meta.fileThumbCrop = remapPathMapKeys(
    WS.meta.fileThumbCrop,
    oldPrefix,
    newPrefix,
  );
  WS.meta.videoThumbTime = remapPathMapKeys(
    WS.meta.videoThumbTime,
    oldPrefix,
    newPrefix,
  );
  if (WS.meta.trashItemsByPath && WS.meta.trashItemsByPath.size) {
    const nextTrashItemsByPath = new Map();
    let trashChanged = false;
    for (const [trashPath, item] of WS.meta.trashItemsByPath.entries()) {
      const nextOriginalPath = remapPathPrefix(
        oldPrefix,
        newPrefix,
        item && item.originalPath,
      );
      if (nextOriginalPath !== String(item?.originalPath || ""))
        trashChanged = true;
      nextTrashItemsByPath.set(trashPath, Object.assign({}, item, {
        originalPath: nextOriginalPath,
      }));
    }
    WS.meta.trashItemsByPath = nextTrashItemsByPath;
    if (trashChanged) metaMarkDirty(META_DOC_IDS.trash);
  }
  if (Array.isArray(WS.meta.scoreHistory) && WS.meta.scoreHistory.length) {
    WS.meta.scoreHistory = normalizeScoreHistoryList(
      WS.meta.scoreHistory.map((entry) => {
        if (!entry || typeof entry !== "object") return entry;
        const selectedRaw = Array.isArray(entry.selectedPaths)
          ? entry.selectedPaths
          : [];
        const changedRaw = Array.isArray(entry.changed) ? entry.changed : [];
        const selectedPaths = selectedRaw.map((p) =>
          remapPathPrefix(oldPrefix, newPrefix, p),
        );
        const changed = changedRaw.map((it) => {
          if (!it || typeof it !== "object") return it;
          return Object.assign({}, it, {
            path: remapPathPrefix(oldPrefix, newPrefix, it.path),
          });
        });
        return Object.assign({}, entry, { selectedPaths, changed });
      }),
    );
  }
}

function applyRenameInMemory(dirNode, newName) {
  const oldPath = String(dirNode?.path || "");
  const parentPath = String(dirNode?.parent?.path || "");
  const newPath = parentPath ? parentPath + "/" + newName : newName;

  dirNode.name = newName;

  (function walk(node) {
    node.path = remapPathPrefix(oldPath, newPath, node.path || "");
    for (const d of node.childrenDirs) walk(d);
  })(dirNode);

  WS.dirByPath = remapPathMapKeys(WS.dirByPath, oldPath, newPath);
  updateMetaPathsForRename(oldPath, newPath);
  updateViewStatePathsForRename(oldPath, newPath);
  invalidateDirHandleCache(oldPath);
  invalidateDirMetricsCaches();
  return { oldPath, newPath };
}

function applyDirectoryMoveInMemory(dirNode, newParentNode, newName) {
  if (!dirNode) return { oldPath: "", newPath: "" };
  const oldPath = String(dirNode.path || "");
  const oldParent = dirNode.parent || null;
  const parentNode = newParentNode || null;
  const parentPath = String(parentNode?.path || "");
  const nextName = String(newName || dirNode.name || "");
  const newPath = parentPath ? `${parentPath}/${nextName}` : nextName;

  if (oldParent && Array.isArray(oldParent.childrenDirs)) {
    oldParent.childrenDirs = oldParent.childrenDirs.filter((child) => child !== dirNode);
  }
  dirNode.parent = parentNode;
  dirNode.name = nextName;
  if (parentNode && Array.isArray(parentNode.childrenDirs)) {
    if (!parentNode.childrenDirs.includes(dirNode)) parentNode.childrenDirs.push(dirNode);
  }

  (function walk(node) {
    node.path = remapPathPrefix(oldPath, newPath, node.path || "");
    for (const d of node.childrenDirs) walk(d);
  })(dirNode);

  WS.dirByPath = remapPathMapKeys(WS.dirByPath, oldPath, newPath);
  updateMetaPathsForRename(oldPath, newPath);
  updateViewStatePathsForRename(oldPath, newPath);
  updateFileRecordsForRename(oldPath, newPath);
  invalidateDirHandleCache(oldPath);
  invalidateDirHandleCache(newPath);
  invalidateDirMetricsCaches();
  return { oldPath, newPath };
}

function remapFileSelectionIds(idMap) {
  const next = new Set();
  for (const id of WS.view.bulkFileSelectedIds || []) {
    next.add(idMap.get(id) || id);
  }
  WS.view.bulkFileSelectedIds = next;
}

function remapIdValue(idMap, value) {
  const key = String(value || "");
  if (!key) return "";
  return idMap.get(key) || key;
}

function remapFileIdsInDirTree(idMap) {
  for (const node of WS.dirByPath.values()) {
    if (!node || !node.childrenFiles) continue;
    for (let i = 0; i < node.childrenFiles.length; i++) {
      const oldId = String(node.childrenFiles[i] || "");
      if (idMap.has(oldId)) node.childrenFiles[i] = idMap.get(oldId);
    }
  }
}

function remapRuntimeFileStateIds(idMap) {
  if (!idMap || !idMap.size) return;
  WS.view.fileActionMenuId = remapIdValue(idMap, WS.view.fileActionMenuId);
  DIR_FILE_DRAG.id = remapIdValue(idMap, DIR_FILE_DRAG.id);
  PREVIEW_DRAG_STATE.draggedId = remapIdValue(
    idMap,
    PREVIEW_DRAG_STATE.draggedId,
  );
  if (Array.isArray(PREVIEW_DRAG_STATE.visibleIds)) {
    PREVIEW_DRAG_STATE.visibleIds = PREVIEW_DRAG_STATE.visibleIds
      .map((id) => remapIdValue(idMap, id))
      .filter(Boolean);
  }
  PREVIEW_VIDEO_PAUSE.fileId = remapIdValue(idMap, PREVIEW_VIDEO_PAUSE.fileId);
  VIDEO_CARRY.fileId = remapIdValue(idMap, VIDEO_CARRY.fileId);
}

function remapFileIdsAcrossViewState(idMap) {
  if (!idMap || !idMap.size) return;
  remapFileIdsInDirTree(idMap);
  remapFileSelectionIds(idMap);
  remapRuntimeFileStateIds(idMap);
  if (WS.preview.kind === "file" && WS.preview.fileId) {
    WS.preview.fileId = remapIdValue(idMap, WS.preview.fileId);
  }
  for (const entry of WS.nav.entries || []) {
    if (entry && entry.kind === "file" && idMap.has(String(entry.id || ""))) {
      entry.id = idMap.get(String(entry.id || ""));
    }
  }
  for (const it of viewerItems || []) {
    if (it && !it.isFolder && idMap.has(String(it.id || "")))
      it.id = idMap.get(String(it.id || ""));
  }
}

async function refreshRenamedRecordFileFromDisk(rec, dirHandleOverride = null) {
  if (!rec || !WS.meta.fsRootHandle) return false;
  const fileName = String(rec.name || "");
  if (!fileName) return false;

  let dirHandle = dirHandleOverride || null;
  if (!dirHandle) {
    try {
      dirHandle = await getDirectoryHandleForPath(
        WS.meta.fsRootHandle,
        String(rec.dirPath || ""),
      );
    } catch {}
  }
  if (!dirHandle) return false;

  let fileHandle = null;
  try {
    fileHandle = await dirHandle.getFileHandle(fileName);
  } catch {}
  if (!fileHandle) return false;

  let freshFile = null;
  try {
    freshFile = await fileHandle.getFile();
  } catch {}
  if (!freshFile) return false;

  try {
    if (rec.url) URL.revokeObjectURL(rec.url);
  } catch {}
  try {
    if (rec.thumbUrl) URL.revokeObjectURL(rec.thumbUrl);
  } catch {}
  try {
    if (rec.videoThumbUrl) URL.revokeObjectURL(rec.videoThumbUrl);
  } catch {}
  rec.url = null;
  rec.thumbUrl = null;
  rec.videoThumbUrl = null;
  rec.thumbMode = null;
  rec.videoThumbMode = null;

  rec.file = freshFile;
  rec.size = Number.isFinite(freshFile.size) ? freshFile.size : rec.size;
  rec.lastModified = Number.isFinite(freshFile.lastModified)
    ? freshFile.lastModified
    : rec.lastModified;
  return true;
}

function updateFileRecordsForRename(oldPrefix, newPrefix) {
  const idMap = new Map();
  const nextFileById = new Map();
  for (const [id, rec] of WS.fileById.entries()) {
    const oldDirPath = String(rec.dirPath || "");
    const oldRelPath = String(rec.relPath || "");
    const nextDirPath = remapPathPrefix(oldPrefix, newPrefix, oldDirPath);
    const nextRelPath = remapPathPrefix(oldPrefix, newPrefix, oldRelPath);
    const nextId =
      nextRelPath !== oldRelPath ? fileKeyForRecord(rec, nextRelPath) : id;
    rec.dirPath = nextDirPath;
    rec.relPath = nextRelPath;
    rec.id = nextId;
    if (nextId !== id) idMap.set(id, nextId);
    nextFileById.set(nextId, rec);
  }
  WS.fileById = nextFileById;
  remapFileIdsAcrossViewState(idMap);
  WS.view.randomCache = remapPathMapKeys(
    WS.view.randomCache,
    oldPrefix,
    newPrefix,
  );
  WS.view.randomFolderCache = remapPathMapKeys(
    WS.view.randomFolderCache,
    oldPrefix,
    newPrefix,
  );
}

async function updateFileRecordsForFileRenames(
  dirNode,
  renameMap,
  dirHandleForRefresh = null,
) {
  if (!dirNode || !renameMap || !renameMap.size) return;
  const dirPath = String(dirNode.path || "");
  const idMap = new Map();
  const relPathMap = new Map();
  const nextFileById = new Map();

  for (const [id, rec] of WS.fileById.entries()) {
    if (String(rec.dirPath || "") !== dirPath) {
      nextFileById.set(id, rec);
      continue;
    }
    const oldName = String(rec.name || "");
    if (!renameMap.has(oldName)) {
      nextFileById.set(id, rec);
      continue;
    }
    const newName = renameMap.get(oldName);
    const extDot = newName.lastIndexOf(".");
    const ext = extDot >= 0 ? newName.slice(extDot).toLowerCase() : "";
    const relPath = dirPath ? dirPath + "/" + newName : newName;
    const oldRelPath = String(rec.relPath || "");
    rec.name = newName;
    rec.ext = ext;
    rec.relPath = relPath;
    rec.type = isVideoName(newName) ? "video" : "image";
    await refreshRenamedRecordFileFromDisk(rec, dirHandleForRefresh);
    const nextId = fileKeyForRecord(rec, relPath);
    if (oldRelPath && relPath && oldRelPath !== relPath)
      relPathMap.set(oldRelPath, relPath);
    rec.id = nextId;
    if (nextId !== id) idMap.set(id, nextId);
    nextFileById.set(nextId, rec);
  }

  WS.fileById = nextFileById;
  remapFileIdsAcrossViewState(idMap);
  remapFolderThumbnailPresetValues(relPathMap);
  WS.view.randomCache.delete(dirPath);
}

async function performBatchIndexForDir(dirNode, opts = {}) {
  if (!dirNode || !WS.meta.fsRootHandle) return { renamed: false, files: 0 };

  const dirPath = String(dirNode.path || "");
  const base = String(dirNode.name || "folder");
  const dirHandle = await getDirectoryHandleForPath(
    WS.meta.fsRootHandle,
    dirPath,
  );

  const files = [];
  const handleByName = new Map();
  for await (const [name, handle] of dirHandle.entries()) {
    if (handle.kind !== "file") continue;
    files.push({ name, handle });
    handleByName.set(name, handle);
  }

  const orderedNames = [];
  if (dirNode.preserveOrder) {
    const seen = new Set();
    for (const id of dirNode.childrenFiles || []) {
      const rec = WS.fileById.get(id);
      const name = rec?.name;
      if (!name || !handleByName.has(name) || seen.has(name)) continue;
      orderedNames.push(name);
      seen.add(name);
    }
    const remaining = files
      .map((f) => f.name)
      .sort((a, b) => compareIndexedNames(a, b));
    for (const name of remaining) {
      if (!seen.has(name)) orderedNames.push(name);
    }
  } else {
    orderedNames.push(
      ...files.map((f) => f.name).sort((a, b) => compareIndexedNames(a, b)),
    );
  }

  const count = orderedNames.length;
  if (!count) return { renamed: false, files: 0 };
  const width = String(count).length + 1;

  const renamePlan = [];
  const existingNames = new Set(files.map((f) => f.name));
  for (let i = 0; i < count; i++) {
    const idx = String(i + 1).padStart(width, "0");
    const oldName = orderedNames[i];
    const handle = handleByName.get(oldName);
    if (!handle) continue;
    const dot = oldName.lastIndexOf(".");
    const ext = dot >= 0 ? oldName.slice(dot + 1) : "";
    const newName = `${base}_${idx}${ext ? "." + ext : ""}`;
    if (newName === oldName) continue;
    renamePlan.push({ oldName, newName, handle, ext: ext ? "." + ext : "" });
  }

  if (!renamePlan.length) return { renamed: false, files: 0 };

  const renameMap = new Map();
  const labelBase = opts.label || "Batch Index";
  const hasConflicts = renamePlan.some((entry) =>
    existingNames.has(entry.newName),
  );

  if (!hasConflicts) {
    for (let i = 0; i < renamePlan.length; i++) {
      const entry = renamePlan[i];
      if (opts.progress)
        showBusyOverlay(
          `${labelBase}... ${opts.progress} (${i + 1}/${renamePlan.length})`,
        );
      else showBusyOverlay(`${labelBase}... ${i + 1}/${renamePlan.length}`);
      const ok = await renameFileOnDisk(
        dirHandle,
        entry.handle,
        entry.oldName,
        entry.newName,
      );
      if (ok) renameMap.set(entry.oldName, entry.newName);
    }
  } else {
    const usedNames = new Set(existingNames);
    const tempPrefix = "__pg_tmp";
    const tempWidth = String(renamePlan.length).length + 1;
    const tempPlan = renamePlan.map((entry, idx) => {
      let tempName = "";
      do {
        const tempIdx = String(idx + 1).padStart(tempWidth, "0");
        const rand = Math.random().toString(36).slice(2, 10);
        tempName = `${tempPrefix}_${tempIdx}_${rand}${entry.ext}`;
      } while (usedNames.has(tempName));
      usedNames.add(tempName);
      return { ...entry, tempName };
    });

    const tempRenamed = [];
    for (let i = 0; i < tempPlan.length; i++) {
      const entry = tempPlan[i];
      if (opts.progress)
        showBusyOverlay(
          `${labelBase}... ${opts.progress} (1/2 ${i + 1}/${tempPlan.length})`,
        );
      else showBusyOverlay(`${labelBase}... (1/2 ${i + 1}/${tempPlan.length})`);
      const ok = await renameFileOnDisk(
        dirHandle,
        entry.handle,
        entry.oldName,
        entry.tempName,
      );
      if (ok) tempRenamed.push(entry);
    }

    for (let i = 0; i < tempRenamed.length; i++) {
      const entry = tempRenamed[i];
      if (opts.progress)
        showBusyOverlay(
          `${labelBase}... ${opts.progress} (2/2 ${i + 1}/${tempRenamed.length})`,
        );
      else
        showBusyOverlay(`${labelBase}... (2/2 ${i + 1}/${tempRenamed.length})`);
      let tempHandle = null;
      try {
        tempHandle = await dirHandle.getFileHandle(entry.tempName);
      } catch {}
      if (!tempHandle) continue;
      const ok = await renameFileOnDisk(
        dirHandle,
        tempHandle,
        entry.tempName,
        entry.newName,
      );
      if (ok) renameMap.set(entry.oldName, entry.newName);
    }
  }

  if (renameMap.size) {
    await updateFileRecordsForFileRenames(dirNode, renameMap, dirHandle);
    return { renamed: true, files: renameMap.size };
  }
  return { renamed: false, files: 0 };
}

function getBatchIndexDirNodesRecursive(dirNode) {
  const out = [];
  const walk = (node) => {
    if (!node) return;
    out.push(node);
    const children = (node.childrenDirs || []).slice();
    children.sort((a, b) =>
      String(a?.name || "").localeCompare(String(b?.name || "")),
    );
    for (let i = 0; i < children.length; i++) walk(children[i]);
  };
  walk(dirNode);
  return out;
}

async function batchIndexFolderFiles(dirNode) {
  if (RENAME_BUSY) return false;
  if (!dirNode) return false;
  if (!WS.meta.fsRootHandle) {
    showStatusMessage("Renaming files requires a writable folder.");
    return false;
  }

  const targets = getBatchIndexDirNodesRecursive(dirNode);
  RENAME_BUSY = true;
  showBusyOverlay("Indexing files...");
  let renamedAny = false;
  try {
    for (let i = 0; i < targets.length; i++) {
      const target = targets[i];
      if (!target) continue;
      const progress = targets.length > 1 ? `${i + 1}/${targets.length}` : "";
      const res = await performBatchIndexForDir(target, {
        label: "Index",
        progress,
      });
      if (!res.renamed) continue;
      resetDirFileOrder(target, { silent: true });
      renamedAny = true;
    }
    if (renamedAny) {
      rebuildDirectoriesEntries();
      WS.nav.selectedIndex = findNearestSelectableIndex(
        WS.nav.selectedIndex,
        1,
      );
      syncPreviewToSelection({ force: true });
      renderDirectoriesPane(true);
      renderPreviewPane(true, true);
      syncButtons();
      kickVideoThumbsForPreview();
      kickImageThumbsForPreview();
      showStatusMessage("Index complete.");
      return true;
    }
    showStatusMessage("No files renamed.");
    return false;
  } finally {
    RENAME_BUSY = false;
    hideBusyOverlay();
  }
}

async function renameFolderDirNode(dirNode, nextName) {
  if (!dirNode) return false;
  if (!dirNode.parent) {
    showStatusMessage("Root folder cannot be renamed.");
    return false;
  }
  if (!WS.meta.fsRootHandle) {
    showStatusMessage("Rename requires a writable folder.");
    return false;
  }

  const clean = normalizeFolderNameInput(nextName);
  if (!isValidFolderName(clean)) {
    showStatusMessage("Invalid folder name.");
    return false;
  }
  if (clean === String(dirNode.name || "")) return true;

  const lower = clean.toLowerCase();
  for (const d of dirNode.parent.childrenDirs || []) {
    if (d !== dirNode && String(d.name || "").toLowerCase() === lower) {
      showStatusMessage("A folder with that name already exists.");
      return false;
    }
  }

  const oldPath = String(dirNode.path || "");
  const state = snapshotRefreshState();
  showBusyOverlay("Renaming folder...");
  try {
    await renameDirectoryOnDisk(oldPath, clean);
    const { oldPath: prevPath, newPath } = applyRenameInMemory(dirNode, clean);
    updateFileRecordsForRename(prevPath, newPath);
    metaComputeFingerprints();
    metaTrackDirtyDocIds([
      META_DOC_IDS.scores,
      META_DOC_IDS.tags,
      META_DOC_IDS.thumbnails,
      META_DOC_IDS.appearanceAssignments,
    ]);

    try {
      if (WS.meta.storageMode === "fs") await metaSaveFsNow();
      else metaSaveLocalNow();
    } catch {}

    const entryKey = state?.entryKey || null;
    if (entryKey && entryKey.kind === "dir") {
      entryKey.path = remapPathPrefix(prevPath, newPath, entryKey.path);
    } else if (entryKey && entryKey.kind === "file") {
      entryKey.relPath = remapPathPrefix(prevPath, newPath, entryKey.relPath);
    }

    rebuildDirectoriesEntries();
    const idx = restoreRefreshSelection(entryKey);
    WS.nav.selectedIndex = findNearestSelectableIndex(idx, 1);
    syncPreviewToSelection({ force: true });
    renderDirectoriesPane(true);
    renderPreviewPane(true, true);
    syncButtons();
    kickVideoThumbsForPreview();
    kickImageThumbsForPreview();

    showStatusMessage("Rename complete.");
    return true;
  } catch {
    showStatusMessage("Rename failed.");
    return false;
  } finally {
    hideBusyOverlay();
  }
}

if (refreshBtn)
  refreshBtn.addEventListener("click", async () => {
    try {
      await refreshWorkspaceFromRootHandle();
    } catch {}
  });

openWritableBtn.addEventListener("click", async () => {
  try {
    if (window.showDirectoryPicker) {
      const rootHandle = await window.showDirectoryPicker({
        mode: "readwrite",
      });
      if (!rootHandle) return;
      await buildWorkspaceFromDirectoryHandle(rootHandle);
      return;
    }
    if (openWritableInput) {
      openWritableInput.value = "";
      openWritableInput.click();
      return;
    }
    showStatusMessage("Folder picker unavailable.");
  } catch (err) {
    console.error("Load folder failed.", err);
    showStatusMessage("Load folder failed.");
  }
});

if (openWritableInput) {
  openWritableInput.addEventListener("change", async () => {
    const files = openWritableInput.files;
    if (!files || !files.length) return;
    try {
      await buildWorkspaceFromFileList(files);
    } catch (err) {
      console.error("Load folder from file list failed.", err);
      showStatusMessage("Load folder failed.");
    } finally {
      openWritableInput.value = "";
    }
  });
}

/* =========================================================
       Sorting helpers
       ========================================================= */

let DIR_SORT_METRICS_CACHE = null;
let DIR_ITEM_COUNT_CACHE = new Map();
let DIR_ITEM_COUNT_CACHE_FILTER_MODE = "";
let TAG_ENTRY_DIRS_CACHE = new Map();
let TAG_ENTRY_METRICS_CACHE = new Map();
let TAG_ENTRY_PREVIEW_POOL_CACHE = new Map();
let TAG_GROUPS_BY_DIR_CACHE = new Map();
let TAG_ALBUM_STATS_BY_SCOPE_CACHE = new Map();

function clearTagEntryDerivedCaches() {
  TAG_ENTRY_DIRS_CACHE = new Map();
  TAG_ENTRY_METRICS_CACHE = new Map();
  TAG_ENTRY_PREVIEW_POOL_CACHE = new Map();
  TAG_GROUPS_BY_DIR_CACHE = new Map();
  TAG_ALBUM_STATS_BY_SCOPE_CACHE = new Map();
}

function invalidateDirSortMetricsCache() {
  DIR_SORT_METRICS_CACHE = null;
}

function invalidateDirItemCountCache() {
  DIR_ITEM_COUNT_CACHE = new Map();
  DIR_ITEM_COUNT_CACHE_FILTER_MODE = "";
}

function invalidateDirMetricsCaches() {
  invalidateDirSortMetricsCache();
  invalidateDirItemCountCache();
  clearTagEntryDerivedCaches();
  DIR_NAV_MANIFESTS.clear();
  HOT_NAV_DIR_PATHS.clear();
  PINNED_HOT_NAV_DIR_PATHS.clear();
  PINNED_HOT_NAV_DECODE_CACHE.clear();
}

function byName(a, b) {
  return compareIndexedNames(a?.name || "", b?.name || "");
}

function dirSortModeOptions(includeScoreUi = true) {
  const options = [
    { value: "name", label: "Name" },
    { value: "score", label: "Score" },
    { value: "efficiency", label: "Efficiency" },
    { value: "size-desc", label: "Size" },
    { value: "count-recursive", label: "Item count" },
  ];
  if (includeScoreUi) return options;
  return options.filter(
    (opt) => opt.value !== "score" && opt.value !== "efficiency",
  );
}

function normalizeDirSortMode(mode) {
  const raw = String(mode || "");
  const allowed = dirSortModeOptions().map((opt) => opt.value);
  if (allowed.includes(raw)) return raw;
  return "name";
}

function dirSortModeLabel(mode) {
  const normalized = normalizeDirSortMode(mode);
  const found = dirSortModeOptions().find((opt) => opt.value === normalized);
  return found ? found.label : "Name";
}

function cycleDirSortMode(mode, includeScoreUi = true) {
  const values = dirSortModeOptions(includeScoreUi).map((opt) => opt.value);
  const current = normalizeDirSortMode(mode);
  const idx = values.indexOf(current);
  return values[(idx >= 0 ? idx + 1 : 0) % values.length];
}

function buildDirSortMetrics() {
  if (DIR_SORT_METRICS_CACHE) return DIR_SORT_METRICS_CACHE;
  const sizeByPath = new Map();
  const recursiveCountByPath = new Map();
  const recursiveScoreByPath = new Map();
  const efficiencyByPath = new Map();

  if (!WS.root) {
    return {
      sizeByPath,
      recursiveCountByPath,
      recursiveScoreByPath,
      efficiencyByPath,
    };
  }

  (function walk(node) {
    if (!node) return;
    const files = Array.isArray(node.childrenFiles) ? node.childrenFiles : [];
    const dirs = Array.isArray(node.childrenDirs) ? node.childrenDirs : [];
    const ownCount = files.length + dirs.length;

    let size = 0;
    for (let i = 0; i < files.length; i++) {
      const rec = WS.fileById.get(files[i]);
      const fileSize = Number(rec && rec.size);
      if (Number.isFinite(fileSize) && fileSize > 0) size += fileSize;
    }

    let recursiveCount = ownCount;
    for (let i = 0; i < dirs.length; i++) {
      const child = dirs[i];
      walk(child);
      const childPath = String(child?.path || "");
      size += sizeByPath.get(childPath) || 0;
      recursiveCount += recursiveCountByPath.get(childPath) || 0;
    }

    const path = String(node.path || "");
    const recursiveScore = Number(metaGetScore(path)) || 0;
    const sizeMb = size / (1024 * 1024);
    sizeByPath.set(path, size);
    recursiveCountByPath.set(path, recursiveCount);
    recursiveScoreByPath.set(path, recursiveScore);
    efficiencyByPath.set(path, recursiveScore / Math.max(0.01, sizeMb));
  })(WS.root);

  DIR_SORT_METRICS_CACHE = {
    sizeByPath,
    recursiveCountByPath,
    recursiveScoreByPath,
    efficiencyByPath,
  };
  return DIR_SORT_METRICS_CACHE;
}

function randomSortAffectsFiles() {
  return !!WS.view.randomMode;
}

function randomSortAffectsFolders() {
  return !!WS.view.randomFolderMode;
}

function recordMediaFilterType(rec) {
  if (!rec) return "";
  if (rec.type === "video") return "videos";
  if (isGifRecord(rec)) return "gifs";
  if (rec.type === "image") return "images";
  return "";
}

function recordPassesTagMediaFilter(rec, filterValue) {
  if (!rec) return false;
  const hiddenTypes = normalizeTagMediaFilterValue(filterValue);
  if (!hiddenTypes.length) return true;
  const recordType = recordMediaFilterType(rec);
  if (!recordType) return true;
  return !hiddenTypes.includes(recordType);
}

function effectiveFilterCacheKey() {
  const contextual = currentContextualTagMediaFilterValue();
  if (contextual.length) {
    return `tag:${String(WS.nav && WS.nav.dirNode ? WS.nav.dirNode.path || "" : "")}:${contextual.join(",")}`;
  }
  return `global:${String(WS?.view?.filterMode || "all")}`;
}

function reseedRandomSortMode() {
  const workspaceSeed = computeWorkspaceSeed();
  const timeSeed = Date.now() >>> 0;
  const randSeed = Math.floor(Math.random() * 0xffffffff) >>> 0;
  WS.view.randomSeed = (workspaceSeed ^ timeSeed ^ randSeed) >>> 0;
  if (!WS.view.randomSeed) WS.view.randomSeed = (workspaceSeed || 1) >>> 0;
  WS.view.randomCache = new Map();
  WS.view.randomFolderCache = new Map();
}

function getRandomOrderForDirs(dirs) {
  const list = Array.isArray(dirs) ? dirs.slice() : [];
  if (!list.length) return list;
  const parentPath = String(list[0]?.parent?.path || "");
  if (!parentPath) return list;
  const key = parentPath;
  if (WS.view.randomFolderCache && WS.view.randomFolderCache.has(key)) {
    const cachedPaths = WS.view.randomFolderCache.get(key) || [];
    const byPath = new Map(
      list.map((node) => [String(node?.path || ""), node]),
    );
    const ordered = [];
    cachedPaths.forEach((p) => {
      const node = byPath.get(String(p || ""));
      if (node) ordered.push(node);
    });
    list.forEach((node) => {
      const p = String(node?.path || "");
      if (!cachedPaths.includes(p)) ordered.push(node);
    });
    if (ordered.length === list.length) return ordered;
  }
  const seed = (WS.view.randomSeed ^ hash32(`dir:${parentPath}`)) >>> 0;
  const shuffled = shuffleWithSeed(list.slice(), seed);
  if (WS.view.randomFolderCache) {
    WS.view.randomFolderCache.set(
      key,
      shuffled.map((node) => String(node?.path || "")),
    );
  }
  return shuffled;
}

function sortDirsForDisplay(dirs) {
  const out = Array.isArray(dirs) ? dirs.slice() : [];
  if (randomSortAffectsFolders() && out.length) {
    const parentPath = String(out[0]?.parent?.path || "");
    if (parentPath) return getRandomOrderForDirs(out);
  }
  const sortMode = normalizeDirSortMode(WS.meta.dirSortMode);
  if (sortMode === "score") {
    out.sort((a, b) => {
      const sa = metaGetScore(a?.path || "");
      const sb = metaGetScore(b?.path || "");
      if (sa !== sb) return sb - sa;
      return byName(a, b);
    });
    return out;
  }

  if (
    sortMode === "efficiency" ||
    sortMode === "size-desc" ||
    sortMode === "count-recursive"
  ) {
    const metrics = buildDirSortMetrics();
    out.sort((a, b) => {
      const pathA = String(a?.path || "");
      const pathB = String(b?.path || "");

      let va = 0;
      let vb = 0;
      if (sortMode === "efficiency") {
        va = metrics.efficiencyByPath.get(pathA) || 0;
        vb = metrics.efficiencyByPath.get(pathB) || 0;
      } else if (sortMode === "size-desc") {
        va = metrics.sizeByPath.get(pathA) || 0;
        vb = metrics.sizeByPath.get(pathB) || 0;
      } else {
        va = metrics.recursiveCountByPath.get(pathA) || 0;
        vb = metrics.recursiveCountByPath.get(pathB) || 0;
      }

      if (va !== vb) return vb - va;
      return byName(a, b);
    });
    return out;
  }

  out.sort(byName);
  return out;
}

function passesFilter(rec) {
  if (!rec) return false;
  const contextualFilter = contextualTagMediaFilterForDirPath(
    String(rec.dirPath || ""),
  );
  if (contextualFilter.length)
    return recordPassesTagMediaFilter(rec, contextualFilter);
  const m = WS.view.filterMode;
  if (m === "images") return rec.type === "image";
  if (m === "videos") return rec.type === "video";
  if (m === "gifs") return rec.ext === ".gif";
  return true;
}

function dirItemCount(node) {
  if (!node) return 0;
  const filterKey = effectiveFilterCacheKey();
  if (DIR_ITEM_COUNT_CACHE_FILTER_MODE !== filterKey) {
    DIR_ITEM_COUNT_CACHE_FILTER_MODE = filterKey;
    DIR_ITEM_COUNT_CACHE.clear();
  }
  const pathKey = String(node.path || "");
  if (DIR_ITEM_COUNT_CACHE.has(pathKey))
    return DIR_ITEM_COUNT_CACHE.get(pathKey) || 0;
  let c = 0;
  for (const id of node.childrenFiles) {
    const rec = WS.fileById.get(id);
    if (passesFilter(rec)) c++;
  }
  for (const d of node.childrenDirs) c += dirItemCount(d);
  DIR_ITEM_COUNT_CACHE.set(pathKey, c);
  return c;
}

function escapeHtml(s) {
  return String(s).replace(
    /[&<>"']/g,
    (c) =>
      ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#039;",
      })[c],
  );
}

function getRandomOrderForDir(dirNode) {
  if (!dirNode) return [];
  const p = dirNode.path || "";
  if (WS.view.randomCache.has(p)) return WS.view.randomCache.get(p).slice();
  const ids = dirNode.childrenFiles.slice();
  ids.sort((a, b) =>
    compareIndexedNames(
      WS.fileById.get(a)?.name || "",
      WS.fileById.get(b)?.name || "",
    ),
  );
  const seed = (WS.view.randomSeed ^ hash32(p)) >>> 0;
  const out = shuffleWithSeed(ids.slice(), seed);
  WS.view.randomCache.set(p, out.slice());
  return out.slice();
}

function getOrderedFileIdsForDir(dirNode, includeChildren = false) {
  if (!dirNode) return [];
  let ids = [];

  if (randomSortAffectsFiles()) {
    ids = getRandomOrderForDir(dirNode);
  } else if (dirNode.preserveOrder) {
    ids = dirNode.childrenFiles.slice();
  } else {
    ids = dirNode.childrenFiles.slice();
    ids.sort((a, b) =>
      compareIndexedNames(
        WS.fileById.get(a)?.name || "",
        WS.fileById.get(b)?.name || "",
      ),
    );
  }

  ids = ids.filter((id) => passesFilter(WS.fileById.get(id)));

  if (!includeChildren) return ids;

  for (const child of getChildDirsForNode(dirNode)) {
    const childIds = getOrderedFileIdsForDir(child, false);
    for (const id of childIds) ids.push(id);
  }

  return ids;
}

const DIR_FILE_DRAG = { id: null, dirPath: null };
const DIRECTORIES_GRID_DRAG_STATE = {
  placeholder: null,
  container: null,
  draggedId: null,
  draggedRow: null,
  dirNode: null,
  visibleIds: null,
  raf: 0,
  lastX: 0,
  lastY: 0,
  pendingHide: false,
};

function ensureDirectoriesGridDragPlaceholder(row) {
  if (!DIRECTORIES_GRID_DRAG_STATE.placeholder) {
    const ph = document.createElement("div");
    ph.className = "dirRow fileRow drag-placeholder";
    ph.setAttribute("aria-hidden", "true");
    DIRECTORIES_GRID_DRAG_STATE.placeholder = ph;
  }
  const rect = row.getBoundingClientRect();
  const ph = DIRECTORIES_GRID_DRAG_STATE.placeholder;
  ph.style.width = `${Math.max(1, Math.round(rect.width))}px`;
  ph.style.height = `${Math.max(1, Math.round(rect.height))}px`;
  return ph;
}

function placeDirectoriesGridDragPlaceholder(row) {
  const container = row?.parentElement || directoriesListEl;
  if (!container || !row) return;
  const ph = ensureDirectoriesGridDragPlaceholder(row);
  if (ph.parentElement && ph.parentElement !== container) {
    ph.parentElement.removeChild(ph);
  }
  DIRECTORIES_GRID_DRAG_STATE.container = container;
  if (row !== ph) container.insertBefore(ph, row);
}

function clearDirectoriesGridDragPlaceholder() {
  const ph = DIRECTORIES_GRID_DRAG_STATE.placeholder;
  if (ph && ph.parentElement) ph.parentElement.removeChild(ph);
  DIRECTORIES_GRID_DRAG_STATE.container = null;
}

function getDirectoriesGridDragRows(container) {
  if (!container) return [];
  return Array.from(
    container.querySelectorAll(".dirRow.fileRow[data-file-id]"),
  ).filter(
    (row) =>
      !row.classList.contains("drag-placeholder") &&
      !row.classList.contains("drag-hidden"),
  );
}

function updateDirectoriesGridPlaceholderFromPoint(container, x, y) {
  const rows = getDirectoriesGridDragRows(container);
  if (!rows.length) {
    const ph = DIRECTORIES_GRID_DRAG_STATE.placeholder;
    if (ph) container.appendChild(ph);
    return;
  }
  for (const row of rows) {
    const rect = row.getBoundingClientRect();
    const rowMid = rect.top + rect.height / 2;
    if (y < rowMid) {
      placeDirectoriesGridDragPlaceholder(row);
      return;
    }
    if (y >= rect.top && y <= rect.bottom) {
      const colMid = rect.left + rect.width / 2;
      if (x < colMid) {
        placeDirectoriesGridDragPlaceholder(row);
        return;
      }
    }
  }
  const ph = DIRECTORIES_GRID_DRAG_STATE.placeholder;
  if (ph) container.appendChild(ph);
}

function scheduleDirectoriesGridDragUpdate(container, x, y) {
  DIRECTORIES_GRID_DRAG_STATE.lastX = x;
  DIRECTORIES_GRID_DRAG_STATE.lastY = y;
  if (DIRECTORIES_GRID_DRAG_STATE.raf) return;
  DIRECTORIES_GRID_DRAG_STATE.raf = requestAnimationFrame(() => {
    DIRECTORIES_GRID_DRAG_STATE.raf = 0;
    updateDirectoriesGridPlaceholderFromPoint(
      container,
      DIRECTORIES_GRID_DRAG_STATE.lastX,
      DIRECTORIES_GRID_DRAG_STATE.lastY,
    );
  });
}

function beginDirectoriesGridFileDrag(row, dragDir, visibleIds) {
  DIRECTORIES_GRID_DRAG_STATE.draggedRow = row;
  DIRECTORIES_GRID_DRAG_STATE.draggedId = String(row?.dataset?.fileId || "");
  DIRECTORIES_GRID_DRAG_STATE.dirNode = dragDir;
  DIRECTORIES_GRID_DRAG_STATE.visibleIds = Array.isArray(visibleIds)
    ? visibleIds.map((id) => String(id || ""))
    : null;
  DIRECTORIES_GRID_DRAG_STATE.container = row?.parentElement || null;
  DIRECTORIES_GRID_DRAG_STATE.pendingHide = true;
}

function finishDirectoriesGridFileDrag() {
  if (DIRECTORIES_GRID_DRAG_STATE.raf) {
    cancelAnimationFrame(DIRECTORIES_GRID_DRAG_STATE.raf);
    DIRECTORIES_GRID_DRAG_STATE.raf = 0;
  }
  const row = DIRECTORIES_GRID_DRAG_STATE.draggedRow;
  if (row) {
    row.classList.remove("drag-hidden");
    row.classList.remove("dragging");
  }
  DIRECTORIES_GRID_DRAG_STATE.draggedRow = null;
  DIRECTORIES_GRID_DRAG_STATE.draggedId = null;
  DIRECTORIES_GRID_DRAG_STATE.dirNode = null;
  DIRECTORIES_GRID_DRAG_STATE.visibleIds = null;
  DIRECTORIES_GRID_DRAG_STATE.pendingHide = false;
  clearDirectoriesGridDragPlaceholder();
}

function ensureDirectoriesGridDragHidden() {
  if (!DIRECTORIES_GRID_DRAG_STATE.pendingHide) return;
  const row = DIRECTORIES_GRID_DRAG_STATE.draggedRow;
  const container =
    DIRECTORIES_GRID_DRAG_STATE.container || row?.parentElement || null;
  if (!row || !container) return;
  DIRECTORIES_GRID_DRAG_STATE.pendingHide = false;
  placeDirectoriesGridDragPlaceholder(row);
  row.classList.add("drag-hidden");
}

function setupDirectoriesGridFileDropZone(container) {
  if (!container || container.dataset.gridFileDropBound === "1") return;
  container.dataset.gridFileDropBound = "1";

  container.addEventListener("dragover", (e) => {
    if (!DIRECTORIES_GRID_DRAG_STATE.draggedId) return;
    if (
      DIRECTORIES_GRID_DRAG_STATE.container &&
      DIRECTORIES_GRID_DRAG_STATE.container !== container
    )
      return;
    if (!container.classList.contains("gridModeList")) return;
    e.preventDefault();
    ensureDirectoriesGridDragHidden();
    scheduleDirectoriesGridDragUpdate(container, e.clientX, e.clientY);
  });

  container.addEventListener("drop", (e) => {
    if (!DIRECTORIES_GRID_DRAG_STATE.draggedId) return;
    if (
      DIRECTORIES_GRID_DRAG_STATE.container &&
      DIRECTORIES_GRID_DRAG_STATE.container !== container
    )
      return;
    if (!container.classList.contains("gridModeList")) return;
    e.preventDefault();
    e.stopPropagation();
    updateDirectoriesGridPlaceholderFromPoint(container, e.clientX, e.clientY);
    const dirNode = DIRECTORIES_GRID_DRAG_STATE.dirNode;
    const dragId = DIRECTORIES_GRID_DRAG_STATE.draggedId;
    const ids =
      DIRECTORIES_GRID_DRAG_STATE.visibleIds &&
      DIRECTORIES_GRID_DRAG_STATE.visibleIds.length
        ? DIRECTORIES_GRID_DRAG_STATE.visibleIds
        : dirNode
          ? getOrderedFileIdsForDir(dirNode)
          : [];
    const list = ids.filter((id) => String(id || "") !== String(dragId));
    const children = Array.from(container.children);
    let insertIdx = 0;
    for (const child of children) {
      if (child === DIRECTORIES_GRID_DRAG_STATE.placeholder) break;
      if (
        child.classList &&
        child.classList.contains("dirRow") &&
        child.classList.contains("fileRow") &&
        !child.classList.contains("drag-hidden") &&
        !child.classList.contains("drag-placeholder")
      ) {
        insertIdx++;
      }
    }
    insertIdx = Math.max(0, Math.min(list.length, insertIdx));
    let targetId = null;
    let placeAfter = false;
    if (list.length) {
      if (insertIdx >= list.length) {
        targetId = list[list.length - 1];
        placeAfter = true;
      } else {
        targetId = list[insertIdx];
        placeAfter = false;
      }
    }
    if (dirNode && targetId) {
      const moved = reorderFilesInDir(dirNode, dragId, targetId, placeAfter, {
        visibleIds: ids,
      });
      if (moved) syncAfterDirOrderChange(null, { preserveSelection: true });
    }
    DIR_FILE_DRAG.id = null;
    DIR_FILE_DRAG.dirPath = null;
    finishDirectoriesGridFileDrag();
  });
}

function setupDirectoriesGridFileDragSource(row, dragDir, visibleIds) {
  if (!row || row.dataset.gridFileDragBound === "1") return;
  row.dataset.gridFileDragBound = "1";
  const fileId = String(row.dataset.fileId || "");
  if (!fileId || !dragDir) return;

  const handleDragStart = (e) => {
    if (
      !isGridInteractionMode() ||
      !directoriesListEl ||
      !directoriesListEl.classList.contains("gridModeList")
    ) {
      e.preventDefault();
      return;
    }
    if (!canReorderFilesInDir(dragDir) || WS.view.bulkSelectMode) {
      e.preventDefault();
      return;
    }
    DIR_FILE_DRAG.id = fileId;
    DIR_FILE_DRAG.dirPath = String(dragDir.path || "");
    row.classList.add("dragging");
    beginDirectoriesGridFileDrag(row, dragDir, visibleIds);
    if (e.dataTransfer) {
      e.dataTransfer.effectAllowed = "move";
      try {
        e.dataTransfer.setData("text/plain", fileId);
      } catch {}
      try {
        const rect = row.getBoundingClientRect();
        e.dataTransfer.setDragImage(row, rect.width / 2, rect.height / 2);
      } catch {}
    }
  };

  const handleDragEnd = () => {
    DIR_FILE_DRAG.id = null;
    DIR_FILE_DRAG.dirPath = null;
    row.classList.remove("dragging");
    finishDirectoriesGridFileDrag();
  };

  const setupDragSource = (el) => {
    if (!el) return;
    el.draggable = true;
    el.addEventListener("dragstart", handleDragStart);
    el.addEventListener("dragend", handleDragEnd);
  };

  setupDragSource(row);
  setupDragSource(row.querySelector(".dirFileThumbCard"));
  setupDragSource(row.querySelector(".dirInlinePreview"));
  setupDragSource(row.querySelector(".dirFileOverlay"));
}

function canReorderFilesInDir(dirNode) {
  if (!WS.root || !dirNode) return false;
  if (searchResultsVisibleInDirectoriesPane()) return false;
  if (WS.view.favoritesMode && WS.view.favoritesRootActive) return false;
  if (WS.view.hiddenMode && WS.view.hiddenRootActive) return false;
  return true;
}

function canReorderFilesInCurrentDir() {
  return canReorderFilesInDir(WS.nav.dirNode);
}

function findFileEntryIndexById(fileId) {
  const id = String(fileId || "");
  if (!id) return -1;
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (entry && entry.kind === "file" && String(entry.id || "") === id)
      return i;
  }
  return -1;
}

function syncAfterDirOrderChange(selectId, opts = {}) {
  const preserveSelection = !!opts.preserveSelection;
  const prevEntry = preserveSelection
    ? WS.nav.entries[WS.nav.selectedIndex] || null
    : null;
  rebuildDirectoriesEntries();
  if (selectId) {
    const idx = findFileEntryIndexById(selectId);
    if (idx >= 0) WS.nav.selectedIndex = idx;
    else
      WS.nav.selectedIndex = findNearestSelectableIndex(
        WS.nav.selectedIndex,
        1,
      );
  } else if (preserveSelection && prevEntry) {
    let idx = -1;
    if (prevEntry.kind === "file") {
      idx = findFileEntryIndexById(prevEntry.id);
    } else if (prevEntry.kind === "dir") {
      idx = findDirEntryIndexByPath(prevEntry.node?.path || "");
    } else if (prevEntry.kind === "tag") {
      const tag = String(prevEntry.tag || "");
      const label = String(prevEntry.label || prevEntry.tag || "");
      for (let i = 0; i < WS.nav.entries.length; i++) {
        const entry = WS.nav.entries[i];
        if (
          entry &&
          entry.kind === "tag" &&
          String(entry.tag || "") === tag &&
          String(entry.label || entry.tag || "") === label
        ) {
          idx = i;
          break;
        }
      }
    }
    if (idx >= 0) WS.nav.selectedIndex = idx;
    else
      WS.nav.selectedIndex = findNearestSelectableIndex(
        WS.nav.selectedIndex,
        1,
      );
  } else {
    WS.nav.selectedIndex = findNearestSelectableIndex(WS.nav.selectedIndex, 1);
  }
  syncPreviewToSelection({ force: true });
  renderDirectoriesPane(true);
  renderPreviewPane(true, true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
}

function isDirWithin(rootNode, childNode) {
  if (!rootNode || !childNode) return false;
  const rootPath = String(rootNode.path || "");
  let cur = childNode;
  while (cur) {
    if (cur === rootNode) return true;
    if (rootPath && String(cur.path || "") === rootPath) return true;
    cur = cur.parent;
  }
  return false;
}

function resetDirFileOrder(dirNode, opts = {}) {
  if (!dirNode || !Array.isArray(dirNode.childrenFiles)) return false;
  dirNode.preserveOrder = false;
  dirNode.childrenFiles.sort((a, b) =>
    compareIndexedNames(
      WS.fileById.get(a)?.name || "",
      WS.fileById.get(b)?.name || "",
    ),
  );
  WS.view.randomCache.delete(dirNode.path || "");
  if (!opts.silent) {
    syncAfterDirOrderChange(opts.selectId || null);
  } else {
    const previewTarget = getPreviewTargetDir();
    const refreshPreview = !!(
      previewTarget &&
      (isDirWithin(previewTarget, dirNode) ||
        isDirWithin(dirNode, previewTarget))
    );
    if (refreshPreview) {
      renderPreviewPane(true, true);
      kickVideoThumbsForPreview();
      kickImageThumbsForPreview();
    }
  }
  return true;
}

function reorderFilesInDir(
  dirNode,
  draggedId,
  targetId,
  placeAfter,
  opts = {},
) {
  if (!dirNode || !draggedId || !targetId) return false;
  const list = dirNode.childrenFiles;
  if (!Array.isArray(list) || list.length < 2) return false;
  const dragId = String(draggedId);
  const target = String(targetId);
  if (dragId === target) return false;

  const visible = Array.isArray(opts.visibleIds)
    ? opts.visibleIds.map((id) => String(id || ""))
    : null;
  if (visible && visible.length) {
    const visibleSet = new Set(visible);
    if (!visibleSet.has(dragId) || !visibleSet.has(target)) return false;
    const reorderedVisible = visible.filter((id) => id !== dragId);
    const targetIdx = reorderedVisible.indexOf(target);
    if (targetIdx < 0) return false;
    const insertIdx = Math.max(
      0,
      Math.min(reorderedVisible.length, placeAfter ? targetIdx + 1 : targetIdx),
    );
    reorderedVisible.splice(insertIdx, 0, dragId);

    const result = new Array(list.length);
    const slots = [];
    for (let i = 0; i < list.length; i++) {
      const id = String(list[i] || "");
      if (visibleSet.has(id)) slots.push(i);
      else result[i] = id;
    }
    if (slots.length !== reorderedVisible.length) return false;
    for (let i = 0; i < slots.length; i++) {
      result[slots[i]] = reorderedVisible[i];
    }
    list.length = 0;
    list.push(...result);
    dirNode.preserveOrder = true;
    WS.view.randomCache.delete(dirNode.path || "");
    return true;
  }

  const fromIdx = list.indexOf(dragId);
  if (fromIdx < 0) return false;
  list.splice(fromIdx, 1);
  let toIdx = list.indexOf(target);
  if (toIdx < 0) return false;
  if (placeAfter) toIdx += 1;
  toIdx = Math.max(0, Math.min(list.length, toIdx));
  list.splice(toIdx, 0, dragId);
  dirNode.preserveOrder = true;
  WS.view.randomCache.delete(dirNode.path || "");
  return true;
}

function reverseFilesInDir(dirNode, opts = {}) {
  if (!dirNode || !Array.isArray(dirNode.childrenFiles)) return false;
  const list = dirNode.childrenFiles;
  if (list.length < 2) return false;

  const visible = Array.isArray(opts.visibleIds)
    ? opts.visibleIds.map((id) => String(id || ""))
    : null;
  if (visible && visible.length) {
    const visibleSet = new Set(visible);
    const reversedVisible = visible.slice().reverse();
    const result = new Array(list.length);
    const slots = [];
    for (let i = 0; i < list.length; i++) {
      const id = String(list[i] || "");
      if (visibleSet.has(id)) slots.push(i);
      else result[i] = id;
    }
    if (slots.length !== reversedVisible.length) return false;
    for (let i = 0; i < slots.length; i++) {
      result[slots[i]] = reversedVisible[i];
    }
    list.length = 0;
    list.push(...result);
  } else {
    list.reverse();
  }

  dirNode.preserveOrder = true;
  WS.view.randomCache.delete(dirNode.path || "");
  return true;
}

function invalidateAllThumbs() {
  for (const it of WS.fileById.values()) {
    if (!it) continue;
    if (it.thumbUrl) {
      try {
        URL.revokeObjectURL(it.thumbUrl);
      } catch {}
      it.thumbUrl = null;
    }
    it.thumbMode = null;

    if (it.videoThumbUrl) {
      try {
        URL.revokeObjectURL(it.videoThumbUrl);
      } catch {}
      it.videoThumbUrl = null;
    }
    it.videoThumbMode = null;
  }
  WS.videoThumbPriorityQueue = [];
  WS.videoThumbQueue = [];
  if (WS.videoThumbQueuedIds instanceof Set) WS.videoThumbQueuedIds.clear();
  else WS.videoThumbQueuedIds = new Set();
  if (WS.videoThumbInFlightIds instanceof Set) WS.videoThumbInFlightIds.clear();
  else WS.videoThumbInFlightIds = new Set();
  if (WS.videoThumbInFlightBackgroundIds instanceof Set)
    WS.videoThumbInFlightBackgroundIds.clear();
  else WS.videoThumbInFlightBackgroundIds = new Set();
  WS.videoThumbActive = 0;
  WS.imageThumbQueue = [];
  WS.imageThumbPriorityQueue = [];
  if (WS.imageThumbQueuedIds instanceof Set) WS.imageThumbQueuedIds.clear();
  else WS.imageThumbQueuedIds = new Set();
  if (WS.imageThumbInFlightIds instanceof Set) WS.imageThumbInFlightIds.clear();
  else WS.imageThumbInFlightIds = new Set();
  WS.imageThumbActive = 0;
  WS.thumbnailDemandToken = ((Number(WS.thumbnailDemandToken) || 0) + 1) >>> 0;
  WS.thumbnailDesiredIds = new Set();
  WS.thumbnailPreviewDemandIds = new Set();
  WS.thumbnailDirectoriesDemandIds = new Set();
  WS.thumbnailUiDirtyPreview = false;
  WS.thumbnailUiDirtyDirectories = false;
  THUMBNAIL_DEMAND_RAF = 0;
  if (THUMBNAIL_DEMAND_DEFER_TIMER) {
    try {
      clearTimeout(THUMBNAIL_DEMAND_DEFER_TIMER);
    } catch {}
  }
  THUMBNAIL_DEMAND_DEFER_TIMER = 0;
  THUMBNAIL_INVALIDATION_RAF = 0;
}

/* =========================================================
       List Pane
       - lists folders + files for WS.nav.dirNode
       - selection drives Preview Pane
       ========================================================= */

function isDirHidden(dirNode) {
  if (!dirNode) return false;
  return metaHasHidden(dirNode.path || "");
}

function isDirOrAncestorHidden(dirNode) {
  let cur = dirNode;
  while (cur) {
    if (metaHasHidden(cur.path || "")) return true;
    cur = cur.parent;
  }
  return false;
}

async function renameSingleFile(rec, nextName) {
  if (!rec) return false;
  if (!WS.meta.fsRootHandle) {
    showStatusMessage("Renaming files requires a writable folder.");
    return false;
  }

  const clean = String(nextName || "").trim();
  if (!isValidFileName(clean)) {
    showStatusMessage("Invalid file name.");
    return false;
  }
  if (clean === String(rec.name || "")) return true;

  const dirPath = String(rec.dirPath || "");
  const dirHandle = await getDirectoryHandleForPath(
    WS.meta.fsRootHandle,
    dirPath,
  );
  let existing = false;
  try {
    await dirHandle.getFileHandle(clean);
    existing = true;
  } catch {}
  if (existing) {
    showStatusMessage("A file with that name already exists.");
    return false;
  }

  const fileHandle = await dirHandle.getFileHandle(String(rec.name || ""));
  const ok = await renameFileOnDisk(
    dirHandle,
    fileHandle,
    String(rec.name || ""),
    clean,
  );
  if (!ok) {
    showStatusMessage("Rename failed.");
    return false;
  }

  const dirNode = WS.dirByPath.get(dirPath) || null;
  if (dirNode) {
    const renameMap = new Map([[String(rec.name || ""), clean]]);
    await updateFileRecordsForFileRenames(dirNode, renameMap, dirHandle);
  }

  metaComputeFingerprints();
  metaTrackDirtyDocIds([
    META_DOC_IDS.scores,
    META_DOC_IDS.tags,
    META_DOC_IDS.thumbnails,
    META_DOC_IDS.appearanceAssignments,
  ]);
  try {
    if (WS.meta.storageMode === "fs") await metaSaveFsNow();
    else metaSaveLocalNow();
  } catch {}

  showStatusMessage("Rename complete.");
  return true;
}

function getChildDirsForNodeBase(dirNode) {
  if (!dirNode) return [];
  const base = sortDirsForDisplay(dirNode.childrenDirs)
    .filter((d) => !isInternalTrashDirNode(d))
    .filter(
    (d) => dirItemCount(d) > 0,
  );
  if (isPathInsideInternalTrash(dirNode.path || "")) return base;
  const showHidden =
    WS.view.hiddenMode ||
    showHiddenFolderEnabled() ||
    (isViewingTagFolder() && WS.view.tagFolderActiveMode === "hidden");
  const visibleBase = showHidden
    ? base
    : base.filter((d) => !isDirOrAncestorHidden(d));
  return visibleBase;
}

function showRootViewEnabled() {
  return true;
}

function includeHiddenItemsInStatsEnabled() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return scoreInterfaceEnabled(opt) && !!(opt && opt.includeHiddenItemsInStats);
}

function showHiddenFolderEnabled() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return !!(opt && opt.showHiddenFolder);
}

function showTrashFolderEnabled() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return !!(opt && opt.showTrashFolder);
}

function quickNavigationEnabled() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return !!(opt && opt.quickNavigation);
}

function showUntaggedFolderEnabled() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return !!(opt && opt.showUntaggedFolder);
}

function showTagFolderSpacerRowEnabled() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return !!(opt && opt.showTagFolderSpacerRow);
}

function getInternalTrashRootNode() {
  return WS.dirByPath.get(INTERNAL_TRASH_DIR_NAME) || null;
}

function shouldShowRootTrashEntry(dirNode) {
  return !!(
    dirNode &&
    dirNode === WS.root &&
    showTrashFolderEnabled() &&
    getInternalTrashRootNode()
  );
}

function buildRootTrashDirEntry() {
  const trashNode = getInternalTrashRootNode();
  if (!trashNode) return null;
  return {
    kind: "dir",
    node: trashNode,
    specialRootTrash: true,
  };
}

function isTrashRootPortalEntry(entry) {
  return !!(
    entry &&
    entry.kind === "dir" &&
    entry.specialRootTrash &&
    isInternalTrashDirNode(entry.node)
  );
}

function isTrashRootPortalNode(node) {
  return !!node && node.parent === WS.root && isInternalTrashDirNode(node);
}

function isPutBackEligibleTrashPath(path) {
  const normalized = normalizeWorkspaceRelPath(path);
  return !!(
    normalized &&
    isDirectChildOfInternalTrash(normalized) &&
    metaGetTrashRestoreInfo(normalized)
  );
}

function navigateOutOfTrashIfHidden() {
  if (showTrashFolderEnabled()) return false;
  const navPath = String(WS.nav.dirNode?.path || "");
  const previewDirPath = String(getPreviewTargetDir()?.path || "");
  if (!isPathInsideInternalTrash(navPath) && !isPathInsideInternalTrash(previewDirPath)) {
    return false;
  }
  exitTagFolderView(false);
  WS.view.favoritesRootActive = false;
  WS.view.hiddenRootActive = false;
  WS.view.searchRootActive = false;
  WS.view.previewSearchActive = false;
  WS.nav.dirNode = WS.root;
  WS.view.aboveRootView = false;
  TAG_EDIT_PATH = null;
  RENAME_EDIT_PATH = null;
  RENAME_EDIT_FILE_ID = null;
  clearBulkTagPlaceholder();
  syncBulkSelectionForCurrentDir();
  syncFavoritesUi();
  syncHiddenUi();
  syncTagUiForCurrentDir();
  rebuildDirectoriesEntries();
  WS.nav.selectedIndex = findNearestSelectableIndex(0, 1);
  syncPreviewToSelection({ force: true });
  return true;
}

function getUntaggedDirsForNode(dirNode) {
  if (!dirNode) return [];
  const children = getChildDirsForNodeBase(dirNode);
  if (!children.length) return [];
  return children.filter((d) => metaGetUserTags(d.path || "").length === 0);
}

function isViewingTagFolder() {
  return !!WS.view.tagFolderActiveMode;
}

function gatherTagGroupsForDir(dirNode) {
  const cacheKey = String(dirNode?.path || "__root__");
  if (TAG_GROUPS_BY_DIR_CACHE.has(cacheKey)) {
    return TAG_GROUPS_BY_DIR_CACHE.get(cacheKey) || new Map();
  }
  const groups = new Map();
  if (!dirNode) return groups;
  const children = getChildDirsForNodeBase(dirNode);
  for (const child of children) {
    const tags = metaGetUserTags(child.path || "");
    const seen = new Set();
    for (const tag of tags) {
      const key = String(tag || "");
      if (!key || seen.has(key)) continue;
      seen.add(key);
      const list = groups.get(key) || [];
      list.push(child);
      groups.set(key, list);
    }
  }
  TAG_GROUPS_BY_DIR_CACHE.set(cacheKey, groups);
  return groups;
}

function collectTagAlbumStatsForGroups(tagGroups, scopePath = null) {
  const cacheKey = String(scopePath || "__root__");
  if (TAG_ALBUM_STATS_BY_SCOPE_CACHE.has(cacheKey)) {
    return TAG_ALBUM_STATS_BY_SCOPE_CACHE.get(cacheKey) || new Map();
  }
  const byAlbum = new Map();
  for (const [tag, nodes] of (tagGroups || []).entries()) {
    const album = metaGetTagAlbumForTag(tag, scopePath);
    if (!album) continue;
    let bucket = byAlbum.get(album);
    if (!bucket) {
      bucket = {
        tags: new Set(),
        folderPaths: new Set(),
      };
      byAlbum.set(album, bucket);
    }
    bucket.tags.add(String(tag || ""));
    for (let i = 0; i < (nodes || []).length; i++) {
      const path = String(nodes[i]?.path || "");
      if (path) bucket.folderPaths.add(path);
    }
  }
  TAG_ALBUM_STATS_BY_SCOPE_CACHE.set(cacheKey, byAlbum);
  return byAlbum;
}

function buildBulkTagPlaceholderEntry() {
  if (!BULK_TAG_PLACEHOLDER) return null;
  const type =
    String(BULK_TAG_PLACEHOLDER.type || "tag") === "album" ? "album" : "tag";
  return {
    kind: "tag",
    label:
      BULK_TAG_PLACEHOLDER.label ||
      (type === "album" ? "New tag album" : "New tag folder"),
    tag: "",
    count: BULK_TAG_PLACEHOLDER.count || 0,
    placeholder: true,
    placeholderType: type,
  };
}

function getTagFolderEntriesForDir(dirNode, opts = null) {
  if (!WS.root || !dirNode) return [];
  if (dirNode._skipTagFilters) return [];
  if (isPathInsideInternalTrash(dirNode.path || "")) return [];

  const options = opts && typeof opts === "object" ? opts : null;
  const includePlaceholder = !(options && options.includePlaceholder === false);
  const entries = [];
  const placeholderEntry = includePlaceholder
    ? buildBulkTagPlaceholderEntry()
    : null;
  if (placeholderEntry) entries.push(placeholderEntry);

  const originPath = String(dirNode.path || "");
  const visibleChildren = getChildDirsForNodeBase(dirNode);

  const favs = visibleChildren.filter((d) => metaHasFavorite(d.path || ""));
  if (favs.length) {
    entries.push({
      kind: "tag",
      label: "Favorites",
      special: "favorites",
      count: favs.length,
      originPath,
    });
  }
  if (showUntaggedFolderEnabled()) {
    const untagged = getUntaggedDirsForNode(dirNode);
    if (untagged.length) {
      entries.push({
        kind: "tag",
        label: "Untagged",
        special: "untagged",
        count: untagged.length,
        originPath,
      });
    }
  }
  const tagGroups = gatherTagGroupsForDir(dirNode);
  if (tagGroups.size) {
    const albumStats = collectTagAlbumStatsForGroups(tagGroups, originPath);
    if (albumStats.size) {
      const sortedAlbums = Array.from(albumStats.keys()).sort((a, b) =>
        String(a).localeCompare(String(b)),
      );
      for (let i = 0; i < sortedAlbums.length; i++) {
        const album = sortedAlbums[i];
        const stats = albumStats.get(album);
        if (!stats || !stats.tags.size) continue;
        entries.push({
          kind: "tag",
          album,
          label: album,
          count: stats.folderPaths.size,
          tagCount: stats.tags.size,
          originPath,
        });
      }
    }
    const sorted = Array.from(tagGroups.keys()).sort((a, b) =>
      String(a).localeCompare(String(b)),
    );
    for (const tag of sorted) {
      if (metaGetTagAlbumForTag(tag, originPath)) continue;
      const nodes = tagGroups.get(tag) || [];
      if (!nodes.length) continue;
      entries.push({
        kind: "tag",
        tag,
        label: tag,
        count: nodes.length,
        originPath,
      });
    }
  }

  return entries;
}

function getTagFolderEntries() {
  if (!WS.root || !WS.nav.dirNode) return [];
  if (
    searchResultsVisibleInDirectoriesPane() ||
    WS.view.favoritesMode ||
    WS.view.hiddenMode
  )
    return [];
  return getTagFolderEntriesForDir(WS.nav.dirNode, {
    includePlaceholder: true,
  });
}

function getTagFolderBaseNode() {
  const basePath = String(WS.view.tagFolderOriginPath || "");
  if (basePath) {
    const node = WS.dirByPath.get(basePath);
    if (node) return node;
  }
  return WS.nav.dirNode || WS.root;
}

function getTagEntriesForTagFolderView() {
  if (!isViewingTagFolder()) return [];
  if (WS.view.tagFolderActiveMode !== "album") return [];
  const album = normalizeTagAlbumName(WS.view.tagFolderActiveAlbum || "");
  if (!album) return [];
  const baseNode = getTagFolderBaseNode();
  return getTagEntriesForAlbumForBaseNode(baseNode, album);
}

function getTagEntriesForAlbumForBaseNode(baseNode, albumName) {
  const album = normalizeTagAlbumName(albumName || "");
  if (!baseNode) return [];
  if (!album) return [];
  const tagGroups = gatherTagGroupsForDir(baseNode);
  if (!tagGroups.size) return [];
  const sorted = Array.from(tagGroups.keys()).sort((a, b) =>
    String(a).localeCompare(String(b)),
  );
  const out = [];
  for (let i = 0; i < sorted.length; i++) {
    const tag = String(sorted[i] || "");
    if (!tag) continue;
    if (metaGetTagAlbumForTag(tag, String(baseNode.path || "")) !== album)
      continue;
    const nodes = tagGroups.get(tag) || [];
    if (!nodes.length) continue;
    out.push({
      kind: "tag",
      tag,
      album,
      label: tag,
      count: nodes.length,
      originPath: String(baseNode.path || ""),
      albumTag: true,
    });
  }
  return out;
}

function getDirsForTagFolderView() {
  if (!isViewingTagFolder()) return [];
  const baseNode = getTagFolderBaseNode();
  if (!baseNode) return [];
  const children = getChildDirsForNodeBase(baseNode);
  if (WS.view.tagFolderActiveMode === "favorites") {
    return children.filter((d) => metaHasFavorite(d.path || ""));
  }
  if (WS.view.tagFolderActiveMode === "untagged") {
    return children.filter((d) => metaGetUserTags(d.path || "").length === 0);
  }
  if (WS.view.tagFolderActiveMode === "hidden") {
    return children.filter((d) => metaHasHidden(d.path || ""));
  }
  if (WS.view.tagFolderActiveMode === "album") {
    return [];
  }
  const tag = String(WS.view.tagFolderActiveTag || "");
  if (!tag) return [];
  return children.filter((d) => {
    const tags = metaGetUserTags(d.path || "");
    return tags.includes(tag);
  });
}

function getDirsForTagViewFrame(frame) {
  if (!frame) return [];
  const baseNode = WS.dirByPath.get(String(frame.originPath || "")) || WS.root;
  if (!baseNode) return [];
  const children = getChildDirsForNodeBase(baseNode);
  if (frame.mode === "favorites")
    return children.filter((d) => metaHasFavorite(d.path || ""));
  if (frame.mode === "untagged")
    return children.filter((d) => metaGetUserTags(d.path || "").length === 0);
  if (frame.mode === "hidden")
    return children.filter((d) => metaHasHidden(d.path || ""));
  if (frame.mode === "album") return [];
  const tag = String(frame.tag || "");
  if (!tag) return [];
  return children.filter((d) => {
    const tags = metaGetUserTags(d.path || "");
    return tags.includes(tag);
  });
}

function getDirsForTagEntry(entry) {
  if (!entry || entry.kind !== "tag") return [];
  const cacheKey = `${String(tagEntrySelectionKey(entry) || "")}@@${String(entry.originPath || "")}`;
  if (cacheKey && TAG_ENTRY_DIRS_CACHE.has(cacheKey)) {
    return TAG_ENTRY_DIRS_CACHE.get(cacheKey) || [];
  }
  const originPath = String(entry.originPath || "");
  const dirNode = WS.dirByPath.get(originPath) || WS.nav.dirNode;
  if (!dirNode) return [];
  const children = getChildDirsForNodeBase(dirNode);
  if (!children.length) return [];
  if (entry.album && !entry.tag) {
    const album = normalizeTagAlbumName(entry.album);
    if (!album) return [];
    const tagGroups = gatherTagGroupsForDir(dirNode);
    if (!tagGroups.size) return [];
    const out = [];
    const seen = new Set();
    for (const [tag, nodes] of tagGroups.entries()) {
      if (metaGetTagAlbumForTag(tag, originPath) !== album) continue;
      for (let i = 0; i < (nodes || []).length; i++) {
        const node = nodes[i];
        const path = String(node?.path || "");
        if (!path || seen.has(path)) continue;
        seen.add(path);
        out.push(node);
      }
    }
    if (cacheKey) TAG_ENTRY_DIRS_CACHE.set(cacheKey, out);
    return out;
  }
  if (entry.special) {
    if (entry.special === "favorites") {
      const out = children.filter((d) => metaHasFavorite(d.path || ""));
      if (cacheKey) TAG_ENTRY_DIRS_CACHE.set(cacheKey, out);
      return out;
    }
    if (entry.special === "untagged") {
      const out = children.filter(
        (d) => metaGetUserTags(d.path || "").length === 0,
      );
      if (cacheKey) TAG_ENTRY_DIRS_CACHE.set(cacheKey, out);
      return out;
    }
    if (entry.special === "hidden") {
      const out = children.filter((d) => metaHasHidden(d.path || ""));
      if (cacheKey) TAG_ENTRY_DIRS_CACHE.set(cacheKey, out);
      return out;
    }
    return [];
  }
  const tag = String(entry.tag || "");
  if (!tag) return [];
  const out = children.filter((d) => {
    const tags = metaGetUserTags(d.path || "");
    return tags.includes(tag);
  });
  if (cacheKey) TAG_ENTRY_DIRS_CACHE.set(cacheKey, out);
  return out;
}

function getTagEntryDisplayIcon(entry) {
  if (!entry || entry.kind !== "tag") return "🏷";
  if (entry.album && !entry.tag) return "🗂";
  if (entry.special === "favorites") return favoriteHeartSymbol();
  if (entry.special === "hidden") return "🙈";
  if (entry.special === "untagged") return "📂";
  return "🏷";
}

function getTagEntryCountText(entry) {
  const folderCount = Math.max(0, Number(entry && entry.count) || 0);
  const type = String((entry && entry.placeholderType) || "");
  if (entry && entry.album && !entry.tag) {
    const tagCount = Math.max(0, Number(entry.tagCount) || 0);
    if (tagCount && folderCount)
      return `${tagCount} tags • ${folderCount} folders`;
    if (tagCount) return `${tagCount} tags`;
    if (folderCount) return `${folderCount} folders`;
    return "Tag album";
  }
  if (type === "album") {
    return folderCount ? `${folderCount} tags` : "Tag album";
  }
  return folderCount ? `${folderCount} folders` : "Tag folder";
}

function getTagEntryAggregateMetrics(entry, sizeMemo = null) {
  const cacheKey =
    !sizeMemo && entry && entry.kind === "tag"
      ? `${String(tagEntrySelectionKey(entry) || "")}@@${String(entry.originPath || "")}`
      : "";
  if (cacheKey && TAG_ENTRY_METRICS_CACHE.has(cacheKey)) {
    return TAG_ENTRY_METRICS_CACHE.get(cacheKey) || {
      dirs: [],
      score: 0,
      sizeBytes: 0,
    };
  }
  const dirs = getDirsForTagEntry(entry);
  let score = 0;
  let sizeBytes = 0;
  const seen = new Set();
  for (let i = 0; i < dirs.length; i++) {
    const dirNode = dirs[i];
    const path = String(dirNode?.path || "");
    if (!path || seen.has(path)) continue;
    seen.add(path);
    score += Number(metaGetScore(path)) || 0;
    sizeBytes += getDirRecursiveSizeBytesForNode(dirNode, sizeMemo);
  }
  const result = {
    dirs,
    score,
    sizeBytes,
  };
  if (cacheKey) TAG_ENTRY_METRICS_CACHE.set(cacheKey, result);
  return result;
}

function effectiveTagMediaFilterForEntry(entry) {
  const key = tagThumbnailKeyForEntry(entry);
  if (!key) return [];
  const direct = metaGetTagMediaFilterByKey(key);
  if (direct.length) return direct;
  if (entry && entry.kind === "tag" && entry.tag && entry.album) {
    return contextualTagMediaFilterForTagContext(
      "tag",
      entry.tag,
      entry.album,
      entry.originPath,
    );
  }
  if (entry && entry.kind === "tag" && entry.album && !entry.tag) {
    return contextualTagMediaFilterForTagContext(
      "album",
      "",
      entry.album,
      entry.originPath,
    );
  }
  return [];
}

function recordPassesTagEntryFilter(rec, entry) {
  const tagFilter = effectiveTagMediaFilterForEntry(entry);
  if (tagFilter.length) return recordPassesTagMediaFilter(rec, tagFilter);
  return passesFilter(rec);
}

const ROTATING_PREVIEW_POOLS = new Map();
const ROTATING_PREVIEW_ORDER = new Map();
const ROTATING_PREVIEW_INDEX = new Map();
const ROTATING_PREVIEW_NEXT_AT = new Map();
let ROTATING_PREVIEW_TIMER = 0;
const ROTATING_PREVIEW_INTERVAL_MS = 24000;
const ROTATING_PREVIEW_JITTER_RATIO = 0.5;
const ROTATING_PREVIEW_JITTER_MS = Math.round(
  ROTATING_PREVIEW_INTERVAL_MS * ROTATING_PREVIEW_JITTER_RATIO,
);
const ROTATING_PREVIEW_POLL_MS = 1000;
const ROTATING_PREVIEW_FADE_MS = 900;

function shuffleArrayInPlace(arr) {
  if (!Array.isArray(arr) || arr.length < 2) return arr;
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const t = arr[i];
    arr[i] = arr[j];
    arr[j] = t;
  }
  return arr;
}

function topRootBucketKeyForDirPath(dirPath) {
  const parts = String(dirPath || "")
    .split("/")
    .filter(Boolean);
  return parts.length ? String(parts[0] || "") : "";
}

function buildRootBucketRecursiveMediaCounts() {
  const counts = new Map();
  for (const rec of WS.fileById.values()) {
    if (!rec) continue;
    const bucketKey = topRootBucketKeyForDirPath(rec.dirPath || "");
    counts.set(bucketKey, (counts.get(bucketKey) || 0) + 1);
  }
  return counts;
}

function pickWeightedRotationId(ids, weights, totalWeight) {
  const list = Array.isArray(ids) ? ids : [];
  const w = Array.isArray(weights) ? weights : [];
  if (!list.length) return "";
  if (list.length === 1) return String(list[0] || "");
  const total = Number(totalWeight);
  if (!Number.isFinite(total) || total <= 0) {
    return String(list[Math.floor(Math.random() * list.length)] || "");
  }
  let needle = Math.random() * total;
  for (let i = 0; i < list.length; i++) {
    needle -= Number(w[i] || 0);
    if (needle <= 0) return String(list[i] || "");
  }
  return String(list[list.length - 1] || "");
}

function buildWeightedRotationOrder(ids) {
  const uniq = [];
  const seen = new Set();
  for (let i = 0; i < (ids || []).length; i++) {
    const id = String(ids[i] || "");
    if (!id || seen.has(id)) continue;
    if (!WS.fileById.has(id)) continue;
    seen.add(id);
    uniq.push(id);
  }
  if (uniq.length < 2) return uniq.slice();

  const rootBucketCounts = buildRootBucketRecursiveMediaCounts();
  const weights = [];
  let totalWeight = 0;
  for (let i = 0; i < uniq.length; i++) {
    const rec = WS.fileById.get(uniq[i]);
    const bucketKey = topRootBucketKeyForDirPath(rec?.dirPath || "");
    const bucketCount = Math.max(
      1,
      Number(rootBucketCounts.get(bucketKey) || 0),
    );
    const weight = 1 / bucketCount;
    weights.push(weight);
    totalWeight += weight;
  }
  if (!Number.isFinite(totalWeight) || totalWeight <= 0) {
    return shuffleArrayInPlace(uniq.slice());
  }

  const out = [];
  let lastId = "";
  for (let i = 0; i < uniq.length; i++) {
    let picked = pickWeightedRotationId(uniq, weights, totalWeight);
    if (picked && picked === lastId && uniq.length > 1) {
      for (let tries = 0; tries < 3 && picked === lastId; tries++) {
        picked = pickWeightedRotationId(uniq, weights, totalWeight);
      }
    }
    if (!picked) picked = uniq[Math.floor(Math.random() * uniq.length)] || "";
    out.push(picked);
    lastId = picked;
  }
  return out;
}

function sampleRecursivePreviewRecords(
  dirNodes,
  limit = 72,
  includeRootFiles = true,
) {
  const roots = Array.isArray(dirNodes) ? dirNodes.filter(Boolean) : [];
  if (!roots.length) return [];
  const capRaw = Number(limit);
  const cap = Number.isFinite(capRaw) ? Math.max(0, Math.floor(capRaw)) : 0;
  const out = [];
  const seenIds = new Set();
  for (let r = 0; r < roots.length; r++) {
    const root = roots[r];
    if (!root) continue;
    const queue = [root];
    for (let q = 0; q < queue.length; q++) {
      const cur = queue[q];
      if (!cur) continue;
      const includeHere = includeRootFiles || cur !== root;
      if (includeHere) {
        const ids = getOrderedFileIdsForDir(cur, false);
        for (let i = 0; i < ids.length; i++) {
          const id = String(ids[i] || "");
          if (!id || seenIds.has(id)) continue;
          const rec = WS.fileById.get(id);
          if (!rec) continue;
          seenIds.add(id);
          out.push(rec);
        }
      }
      const kids = getChildDirsForNode(cur);
      for (let i = 0; i < kids.length; i++) queue.push(kids[i]);
    }
  }
  if (!cap || out.length <= cap) return out;
  const seedSource = roots.map((n) => String((n && n.path) || "")).join("|");
  const seed = hash32(
    `rotate-sample|${seedSource}|${includeRootFiles ? "1" : "0"}|${out.length}`,
  );
  const shuffled = shuffleWithSeed(out.slice(), seed);
  return shuffled.slice(0, cap);
}

function getFirstDirectPreviewRecordForDir(dirNode) {
  const ids = getOrderedFileIdsForDir(dirNode, false);
  if (!ids.length) return null;
  return WS.fileById.get(ids[0]) || null;
}

function directoryNavManifestKey(dirNode) {
  if (!dirNode) return "";
  return String(dirNode.path || "__root__");
}

function getDirectoryNavManifest(dirNode) {
  if (!dirNode) return null;
  const key = directoryNavManifestKey(dirNode);
  if (DIR_NAV_MANIFESTS.has(key)) return DIR_NAV_MANIFESTS.get(key) || null;

  const fileIds = getOrderedFileIdsForDir(dirNode, false)
    .map((id) => String(id || ""))
    .filter(Boolean);
  const childDirs = getChildDirsForNode(dirNode);
  const childDirPaths = [];
  const childLeadRecordIds = [];
  for (let i = 0; i < childDirs.length; i++) {
    const child = childDirs[i];
    if (!child) continue;
    childDirPaths.push(String(child.path || ""));
    const childManifest = getDirectoryNavManifest(child);
    const childLeadId = String(
      (childManifest && childManifest.leadRecordId) || "",
    );
    if (childLeadId) childLeadRecordIds.push(childLeadId);
  }

  const presetRec = getPresetPreviewRecordForDir(dirNode);
  const directRec = getFirstDirectPreviewRecordForDir(dirNode);
  const leadRecordId = String(
    (presetRec && presetRec.id) ||
      (directRec && directRec.id) ||
      childLeadRecordIds[0] ||
      "",
  );
  const navRecordIds = [];
  const seen = new Set();
  const pushId = (id) => {
    const normalized = String(id || "");
    if (!normalized || seen.has(normalized)) return;
    seen.add(normalized);
    navRecordIds.push(normalized);
  };
  for (let i = 0; i < fileIds.length; i++) pushId(fileIds[i]);
  for (let i = 0; i < childLeadRecordIds.length; i++)
    pushId(childLeadRecordIds[i]);

  const manifest = {
    key,
    path: String(dirNode.path || ""),
    fileIds,
    childDirPaths,
    childLeadRecordIds,
    leadRecordId,
    navRecordIds,
  };
  DIR_NAV_MANIFESTS.set(key, manifest);
  return manifest;
}

function primeDirectoryNavManifests(rootNode = null) {
  const startNode = rootNode || WS.root;
  if (!startNode) return;
  getDirectoryNavManifest(startNode);
}

function manifestPathKey(pathValue) {
  const path = String(pathValue || "");
  return path || "__root__";
}

function collectManifestNavigationRecordsForPaths(paths, includeFiles = true) {
  const out = [];
  const seen = new Set();
  const list = Array.isArray(paths) ? paths : [];
  for (let i = 0; i < list.length; i++) {
    const key = manifestPathKey(list[i]);
    const manifest = DIR_NAV_MANIFESTS.get(key);
    const ids = includeFiles
      ? Array.isArray(manifest && manifest.navRecordIds)
        ? manifest.navRecordIds
        : []
      : Array.isArray(manifest && manifest.childLeadRecordIds)
        ? manifest.childLeadRecordIds
        : [];
    for (let j = 0; j < ids.length; j++) {
      const id = String(ids[j] || "");
      if (!id || seen.has(id)) continue;
      const rec = WS.fileById.get(id);
      if (!rec) continue;
      seen.add(id);
      out.push(rec);
    }
  }
  return out;
}

function collectWorkspaceNavigationRecords(rootNode = null) {
  const startNode = rootNode || WS.root;
  if (!startNode) return [];
  primeDirectoryNavManifests(startNode);
  const rootPath = String(startNode.path || "");
  const paths = [];
  for (const manifest of DIR_NAV_MANIFESTS.values()) {
    const path = String((manifest && manifest.path) || "");
    if (!rootPath || path === rootPath || path.startsWith(rootPath + "/"))
      paths.push(path);
  }
  return collectManifestNavigationRecordsForPaths(
    paths,
    shouldAutoLoadFileThumbnails(),
  );
}

function findFileRecordByRelPath(relPath) {
  const needle = normalizeWorkspaceRelPath(relPath);
  if (!needle) return null;
  for (const rec of WS.fileById.values()) {
    if (!rec) continue;
    if (normalizeWorkspaceRelPath(rec.relPath || "") === needle) return rec;
  }
  return null;
}

function isRecordInDirSubtree(rec, dirNode) {
  if (!rec || !dirNode) return false;
  const dirPath = String(dirNode.path || "");
  const recDirPath = String(rec.dirPath || "");
  if (!dirPath) return true;
  return recDirPath === dirPath || recDirPath.startsWith(dirPath + "/");
}

function getPresetPreviewRecordForDir(dirNode) {
  if (!dirNode) return null;
  const dirPath = String(dirNode.path || "");
  if (!dirPath && dirNode !== WS.root) return null;
  const relPath = metaGetFolderThumbnailPresetRelPath(dirPath);
  if (!relPath) return null;
  const rec = findFileRecordByRelPath(relPath);
  if (!rec) return null;
  if (!passesFilter(rec)) return null;
  if (!isRecordInDirSubtree(rec, dirNode)) return null;
  return rec;
}

function getRecursivePreviewRecordsForDir(
  dirNode,
  limit = 72,
  includeSelfFiles = true,
) {
  if (!dirNode) return [];
  return sampleRecursivePreviewRecords([dirNode], limit, includeSelfFiles);
}

function folderEligibleForParentThumbnailPreset(dirNode) {
  if (!dirNode) return false;
  const dirPath = String(dirNode.path || "");
  if (!dirPath && dirNode !== WS.root) return false;
  if (metaGetFolderThumbnailMode(dirPath) !== "rotate") return true;
  if (getFirstDirectPreviewRecordForDir(dirNode)) return false;
  return getRecursivePreviewRecordsForDir(dirNode, 1, false).length > 0;
}

function getDisplayLeadPreviewForDir(dirNode, rotateKeyPrefix = "dir") {
  if (!dirNode) return { record: null, rotateKey: "" };
  const dirPath = String(dirNode.path || "");
  if (metaGetFolderThumbnailMode(dirPath) === "none")
    return { record: null, rotateKey: "" };
  const presetRec = getPresetPreviewRecordForDir(dirNode);
  if (presetRec) return { record: presetRec, rotateKey: "" };
  const directRec = getFirstDirectPreviewRecordForDir(dirNode);
  if (directRec) return { record: directRec, rotateKey: "" };
  if (naturalAspectThumbnailCardsEnabled())
    return { record: null, rotateKey: "" };
  if (!dirPath && dirNode !== WS.root) return { record: null, rotateKey: "" };
  const recursivePool = getRecursivePreviewRecordsForDir(dirNode, 0, false);
  if (!recursivePool.length) return { record: null, rotateKey: "" };
  const record = recursivePool[0] || null;
  return { record, rotateKey: "" };
}

function findNearestPresettableParentForRecord(rec) {
  if (!rec) return null;
  const startNode = WS.dirByPath.get(String(rec.dirPath || ""));
  let cur = startNode && startNode.parent ? startNode.parent : null;
  while (cur) {
    if (folderEligibleForParentThumbnailPreset(cur)) return cur;
    cur = cur.parent;
  }
  return null;
}

function setFolderThumbnailTargetFromRecord(rec, targetPath) {
  const normalizedPath = normalizeDirPathValue(targetPath);
  if (!normalizedPath) {
    return setRootThumbnailFromRecord(rec);
  }
  const folderNode = WS.dirByPath.get(normalizedPath);
  if (!folderNode) {
    showStatusMessage("Target folder is unavailable.");
    return false;
  }
  const relPath = normalizeWorkspaceRelPath(rec?.relPath);
  if (!relPath) {
    showStatusMessage("Selected file is unavailable.");
    return false;
  }
  const changed = metaSetFolderThumbnailPreset(normalizedPath, relPath);
  if (!changed) {
    showStatusMessage(
      `Thumbnail already set for ${dirDisplayName(folderNode)}.`,
    );
    return false;
  }
  renderDirectoriesPane(true);
  renderPreviewPane(false, true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  showStatusMessage(`Set thumbnail for ${dirDisplayName(folderNode)}.`);
  return true;
}

function setParentThumbnailFromRecord(rec) {
  const targetNode = findNearestPresettableParentForRecord(rec);
  if (!targetNode || !targetNode.path) {
    showStatusMessage("No eligible parent folder found.");
    return false;
  }
  return setFolderThumbnailTargetFromRecord(rec, String(targetNode.path || ""));
}

function setFolderThumbnailFromRecord(rec) {
  const folderPath = String(rec?.dirPath || "");
  if (!folderPath || !WS.dirByPath.has(folderPath)) {
    showStatusMessage("Selected file has no target folder.");
    return false;
  }
  return setFolderThumbnailTargetFromRecord(rec, folderPath);
}

function setRootThumbnailFromRecord(rec) {
  if (!WS.root) {
    showStatusMessage("No root folder is available.");
    return false;
  }
  const relPath = normalizeWorkspaceRelPath(rec?.relPath || "");
  if (!relPath) {
    showStatusMessage("Selected file is unavailable.");
    return false;
  }
  const changed = metaSetTagThumbnailPresetByKey(rootThumbnailKey(), relPath);
  if (!changed) {
    showStatusMessage("Root thumbnail is already set to this file.");
    return false;
  }
  renderDirectoriesPane(true);
  renderPreviewPane(false, true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  showStatusMessage("Set thumbnail for root.");
  return true;
}

function getRootThumbnailMode() {
  return metaGetTagThumbnailModeByKey(rootThumbnailKey());
}

function isRootThumbnailModeDefault(mode) {
  return String(mode || "") === defaultRotatingThumbnailMode();
}

function rootThumbnailHasPreset() {
  return metaHasTagThumbnailPresetByKey(rootThumbnailKey());
}

function setRootThumbnailMode(mode) {
  return metaSetTagThumbnailModeByKey(rootThumbnailKey(), mode);
}

function clearRootThumbnailPreset() {
  return metaClearTagThumbnailPresetByKey(rootThumbnailKey());
}

function resetRootThumbnailToDefault() {
  const cleared = clearRootThumbnailPreset();
  const modeChanged = setRootThumbnailMode(defaultRotatingThumbnailMode());
  return cleared || modeChanged;
}

function clearEditedThumbnailCrops() {
  if (!WS.meta) return 0;
  const cropCount = WS.meta.fileThumbCrop ? WS.meta.fileThumbCrop.size : 0;
  const frameCount = WS.meta.videoThumbTime ? WS.meta.videoThumbTime.size : 0;
  const count = cropCount + frameCount;
  if (!count) return 0;
  if (WS.meta.fileThumbCrop) WS.meta.fileThumbCrop.clear();
  if (WS.meta.videoThumbTime) WS.meta.videoThumbTime.clear();
  metaMarkDirty(META_DOC_IDS.thumbnails);
  return count;
}

function clearThumbnailAssignmentsToDefaults() {
  if (!WS.meta) return 0;
  let count = 0;
  if (WS.meta.dirThumbPresets && WS.meta.dirThumbPresets.size) {
    count += WS.meta.dirThumbPresets.size;
    WS.meta.dirThumbPresets.clear();
  }
  if (WS.meta.tagThumbPresets && WS.meta.tagThumbPresets.size) {
    count += WS.meta.tagThumbPresets.size;
    WS.meta.tagThumbPresets.clear();
  }
  if (WS.meta.tagThumbModes && WS.meta.tagThumbModes.size) {
    count += WS.meta.tagThumbModes.size;
    WS.meta.tagThumbModes.clear();
  }
  if (!count) return 0;
  metaMarkDirty(META_DOC_IDS.thumbnails);
  return count;
}

function clearAllThumbnailCustomizations() {
  if (!WS.meta) return { cropCount: 0, assignmentCount: 0, total: 0 };
  const cropCount =
    (WS.meta.fileThumbCrop ? WS.meta.fileThumbCrop.size : 0) +
    (WS.meta.videoThumbTime ? WS.meta.videoThumbTime.size : 0);
  const dirCount = WS.meta.dirThumbPresets ? WS.meta.dirThumbPresets.size : 0;
  const tagPresetCount = WS.meta.tagThumbPresets
    ? WS.meta.tagThumbPresets.size
    : 0;
  const tagModeCount = WS.meta.tagThumbModes ? WS.meta.tagThumbModes.size : 0;
  const assignmentCount = dirCount + tagPresetCount + tagModeCount;
  if (WS.meta.fileThumbCrop) WS.meta.fileThumbCrop.clear();
  if (WS.meta.videoThumbTime) WS.meta.videoThumbTime.clear();
  if (WS.meta.dirThumbPresets) WS.meta.dirThumbPresets.clear();
  if (WS.meta.tagThumbPresets) WS.meta.tagThumbPresets.clear();
  if (WS.meta.tagThumbModes) WS.meta.tagThumbModes.clear();
  const total = cropCount + assignmentCount;
  if (total > 0) {
    metaMarkDirty(META_DOC_IDS.thumbnails);
  }
  return { cropCount, assignmentCount, total };
}

function hasKnownPreviewAspect(rec) {
  const ar = Number(rec && rec.previewAspect);
  return Number.isFinite(ar) && ar > 0;
}

async function detectRecordPreviewAspect(rec) {
  if (!rec) return null;
  if (hasKnownPreviewAspect(rec)) {
    return normalizePreviewAspect(rec.previewAspect, 4 / 3);
  }

  if (rec.type === "image") {
    let w = 0;
    let h = 0;
    if (rec.file) {
      try {
        const bmp = await createImageBitmap(rec.file);
        w = Number(bmp && bmp.width) || 0;
        h = Number(bmp && bmp.height) || 0;
        try {
          bmp.close();
        } catch {}
      } catch {}
    }
    if (!(w > 0 && h > 0)) {
      const src = ensureMediaUrl(rec);
      if (src) {
        try {
          const dims = await new Promise((resolve) => {
            const img = new Image();
            const done = (out) => resolve(out || { w: 0, h: 0 });
            img.onload = () =>
              done({
                w: Number(img.naturalWidth) || 0,
                h: Number(img.naturalHeight) || 0,
              });
            img.onerror = () => done({ w: 0, h: 0 });
            img.src = src;
          });
          w = Number(dims && dims.w) || 0;
          h = Number(dims && dims.h) || 0;
        } catch {}
      }
    }
    if (w > 0 && h > 0) return normalizePreviewAspect(w / h, 4 / 3);
    return null;
  }

  if (rec.type === "video") {
    const knownVideoAspect = Number(rec.videoAspect);
    if (Number.isFinite(knownVideoAspect) && knownVideoAspect > 0) {
      return normalizePreviewAspect(knownVideoAspect, 4 / 3);
    }
    const src = ensureMediaUrl(rec);
    if (!src) return null;
    try {
      const dims = await new Promise((resolve) => {
        const v = document.createElement("video");
        let settled = false;
        const done = (out) => {
          if (settled) return;
          settled = true;
          try {
            v.pause();
            v.removeAttribute("src");
            v.load();
          } catch {}
          resolve(out || { w: 0, h: 0 });
        };
        const timer = setTimeout(() => done({ w: 0, h: 0 }), 2000);
        v.preload = "metadata";
        v.muted = true;
        v.playsInline = true;
        v.onloadedmetadata = () => {
          clearTimeout(timer);
          done({ w: Number(v.videoWidth) || 0, h: Number(v.videoHeight) || 0 });
        };
        v.onerror = () => {
          clearTimeout(timer);
          done({ w: 0, h: 0 });
        };
        v.src = src;
      });
      const w = Number(dims && dims.w) || 0;
      const h = Number(dims && dims.h) || 0;
      if (w > 0 && h > 0) return normalizePreviewAspect(w / h, 4 / 3);
    } catch {}
  }

  return null;
}

async function hydrateEditedThumbnailAspects() {
  if (!WS.meta || !WS.meta.fileThumbCrop || !WS.meta.fileThumbCrop.size)
    return false;
  const records = [];
  const seen = new Set();
  for (const relPath of WS.meta.fileThumbCrop.keys()) {
    const rec = findFileRecordByRelPath(relPath);
    if (!rec) continue;
    const id = String(rec.id || "");
    if (!id || seen.has(id)) continue;
    if (hasKnownPreviewAspect(rec)) continue;
    seen.add(id);
    records.push(rec);
  }
  if (!records.length) return false;

  let changed = false;
  for (let i = 0; i < records.length; i++) {
    const rec = records[i];
    const detected = await detectRecordPreviewAspect(rec);
    if (!detected) continue;
    const prev = Number(rec.previewAspect);
    if (!Number.isFinite(prev) || Math.abs(prev - detected) > 0.0001) {
      rec.previewAspect = detected;
      changed = true;
    }
  }
  return changed;
}

function getRootPresetPreviewRecord(rootNode, rootPool = null) {
  if (!rootNode) return null;
  const key = rootThumbnailKey();
  const relPath = metaGetTagThumbnailPresetRelPathByKey(key);
  if (!relPath) return null;
  const rec = findFileRecordByRelPath(relPath);
  if (!rec || !passesFilter(rec) || !isRecordInDirSubtree(rec, rootNode))
    return null;
  if (Array.isArray(rootPool) && rootPool.length) {
    const idSet = new Set(
      rootPool.map((r) => String((r && r.id) || "")).filter(Boolean),
    );
    if (!idSet.has(String(rec.id || ""))) return null;
  }
  return rec;
}

function tagThumbnailLabelForKey(tagKey) {
  const key = String(tagKey || "");
  if (!key) return "tag";
  const parsed = parseTagThumbnailStructuredKey(key);
  if (parsed) {
    const value = String(parsed.value || "");
    const scopeLabel = parsed.scoped
      ? tagThumbnailScopeLabelForPath(parsed.scopePath)
      : "";
    if (parsed.kind === "tag") {
      if (!value) return "tag";
      return parsed.scoped ? `${value} in ${scopeLabel}` : value;
    }
    if (parsed.kind === "album") {
      if (!value) return "Album";
      return parsed.scoped
        ? `Album ${value} in ${scopeLabel}`
        : `Album ${value}`;
    }
  }
  if (key === rootThumbnailKey()) return "Root";
  if (key.startsWith("special:favorites:")) {
    const scope = key.slice("special:favorites:".length);
    const scopePath = tagThumbnailScopePathFromKey(scope);
    const scopeLabel = tagThumbnailScopeLabelForPath(scopePath);
    return `Favorites in ${scopeLabel}`;
  }
  if (key === "special:favorites") return "Favorites";
  if (key === "special:hidden") return "Hidden";
  if (key === "special:untagged") return "Untagged";
  if (key.startsWith("special:")) return toTitleCaps(key.slice(8) || "tag");
  return key;
}

function thumbnailMenuScopeLabel(node) {
  const scopePath = String(node?.path || "");
  if (!scopePath) return "root";
  return dirDisplayName(node) || "folder";
}

function thumbnailMenuFolderLabel(node) {
  const folderPath = String(node?.path || "");
  if (!folderPath) return "Root";
  return dirDisplayName(node) || "folder";
}

function getThumbnailMenuTargetsForRecord(rec) {
  const out = [];
  if (!rec) return out;
  const seenFolders = new Set();
  const seenTags = new Set();
  let cur = WS.dirByPath.get(String(rec.dirPath || "")) || WS.root || null;
  while (cur) {
    const folderPath = String(cur.path || "");
    if (!seenFolders.has(folderPath)) {
      seenFolders.add(folderPath);
      const folderLabel = thumbnailMenuFolderLabel(cur);
      out.push({
        action: folderThumbnailActionForPath(folderPath),
        label: folderPath
          ? `Set '${folderLabel}' thumbnail`
          : "Set root thumbnail",
      });
    }

    const scopeNode = cur.parent || WS.root || null;
    const scopePath = String(scopeNode?.path || "");
    const scopeLabel = thumbnailMenuScopeLabel(scopeNode);
    const tags = metaGetUserTags(cur.path || "");
    for (let i = 0; i < tags.length; i++) {
      const tag = normalizeTag(tags[i] || "");
      if (!tag) continue;
      const key = tagThumbnailKeyForTag(tag, scopePath);
      if (!key || seenTags.has(key)) continue;
      seenTags.add(key);
      out.push({
        action: tagThumbnailActionForKey(key),
        label: `Set '${tag}' thumbnail in ${scopeLabel}`,
      });

      const album = metaGetTagAlbumForTag(tag, scopePath);
      const albumKey = tagThumbnailKeyForAlbum(album, scopePath);
      if (album && albumKey && !seenTags.has(albumKey)) {
        seenTags.add(albumKey);
        out.push({
          action: tagThumbnailActionForKey(albumKey),
          label: `Set album '${album}' thumbnail in ${scopeLabel}`,
        });
      }
    }

    if (metaHasFavorite(cur.path || "")) {
      const scopeKey = tagThumbnailScopeKeyFromPath(scopePath);
      const key = `special:favorites:${scopeKey}`;
      if (!seenTags.has(key)) {
        seenTags.add(key);
        out.push({
          action: tagThumbnailActionForKey(key),
          label: `Set favorites thumbnail in ${scopeLabel}`,
        });
      }
    }

    cur = cur.parent || null;
  }
  return out;
}

function isRecordInAnyDirSubtree(rec, dirs) {
  if (!rec || !Array.isArray(dirs) || !dirs.length) return false;
  for (let i = 0; i < dirs.length; i++) {
    if (isRecordInDirSubtree(rec, dirs[i])) return true;
  }
  return false;
}

function tagThumbnailActionForKey(tagKey) {
  return `set-tag-thumbnail:${encodeURIComponent(String(tagKey || ""))}`;
}

function folderThumbnailActionForPath(path) {
  const normalized = normalizeDirPathValue(path);
  const key = normalized ? normalized : "__root__";
  return `set-folder-thumbnail-target:${encodeURIComponent(key)}`;
}

function parseFolderThumbnailAction(action) {
  const raw = String(action || "");
  const prefix = "set-folder-thumbnail-target:";
  if (!raw.startsWith(prefix)) return null;
  const encoded = raw.slice(prefix.length);
  if (!encoded) return null;
  try {
    const decoded = decodeURIComponent(encoded);
    if (decoded === "__root__") return "";
    return normalizeDirPathValue(decoded);
  } catch {
    return null;
  }
}

function parseTagThumbnailAction(action) {
  const raw = String(action || "");
  const prefix = "set-tag-thumbnail:";
  if (!raw.startsWith(prefix)) return "";
  const encoded = raw.slice(prefix.length);
  if (!encoded) return "";
  try {
    return decodeURIComponent(encoded);
  } catch {
    return "";
  }
}

function closeThumbnailCropEditor() {
  if (!THUMB_CROP_EDITOR) return;
  const editorVideo = THUMB_CROP_EDITOR.querySelector
    ? THUMB_CROP_EDITOR.querySelector("video.thumbCropEditorPreviewFull")
    : null;
  if (editorVideo) {
    try {
      editorVideo.pause();
    } catch {}
    try {
      editorVideo.removeAttribute("src");
    } catch {}
    try {
      editorVideo.load();
    } catch {}
  }
  try {
    THUMB_CROP_EDITOR.remove();
  } catch {}
  THUMB_CROP_EDITOR = null;
}

function formatThumbnailEditorTimeLabel(secondsRaw) {
  const seconds = Math.max(0, Number(secondsRaw) || 0);
  const whole = Math.floor(seconds);
  const mins = Math.floor(whole / 60);
  const secs = whole % 60;
  const frac = Math.floor((seconds - whole) * 100);
  return `${mins}:${String(secs).padStart(2, "0")}.${String(frac).padStart(2, "0")}`;
}

function openThumbnailCropEditor(rec) {
  const targetLabel = "this file";
  if (!rec) return false;
  const isVideoEditor = rec.type === "video";
  const previewSrc = isVideoEditor
    ? ensureMediaUrl(rec) || ""
    : ensureThumbUrl(rec) || "";
  if (!previewSrc) {
    showStatusMessage("Thumbnail preview is unavailable.");
    return false;
  }

  closeThumbnailCropEditor();

  const crop = normalizeThumbCropValue(
    metaGetFileThumbnailCropForRecord(rec) || { x: 50, y: 50, zoom: 1 },
  );
  const savedVideoFrameTime = isVideoEditor
    ? metaGetVideoThumbnailTimeForRecord(rec)
    : null;
  const mediaHtml = isVideoEditor
    ? `<video class="thumbCropEditorPreviewFull thumbCropEditorPreviewVideo" src="${escapeHtml(previewSrc)}" preload="metadata" playsinline muted></video>`
    : `<img class="thumbCropEditorPreviewFull" src="${escapeHtml(previewSrc)}" alt="" />`;
  const frameControlHtml = isVideoEditor
    ? `
          <div class="thumbCropEditorControl">
            <label>Frame</label>
            <input type="range" min="0" max="0" step="0.01" value="0" data-crop-field="frame" disabled />
            <span data-crop-value="frame">0:00.00</span>
          </div>
        `
    : "";
  const overlay = document.createElement("div");
  overlay.className = "thumbCropEditorOverlay";
  overlay.tabIndex = -1;
  overlay.innerHTML = `
        <div class="thumbCropEditorPanel" role="dialog" aria-modal="true" aria-label="Edit thumbnail">
          <div class="thumbCropEditorTitle">Edit thumbnail</div>
          <div class="thumbCropEditorSubtitle">${escapeHtml(targetLabel)}</div>
          <div class="thumbCropEditorPreviewWrap">
            ${mediaHtml}
            <div class="thumbCropEditorShade" data-crop-shade="top"></div>
            <div class="thumbCropEditorShade" data-crop-shade="left"></div>
            <div class="thumbCropEditorShade" data-crop-shade="right"></div>
            <div class="thumbCropEditorShade" data-crop-shade="bottom"></div>
            <div class="thumbCropEditorCropBox" data-crop-box="1"></div>
            <button type="button" class="thumbCropEditorResizeHandle" data-crop-handle="resize" aria-label="Resize crop viewport" tabindex="-1"></button>
          </div>
          ${frameControlHtml}
          <div class="thumbCropEditorHint">Drag to pan. Drag corner or pinch to zoom.</div>
          <div class="thumbCropEditorControl">
            <label>Horizontal focus</label>
            <input type="range" min="0" max="100" step="1" value="${escapeHtml(String(crop.x))}" data-crop-field="x" />
            <span data-crop-value="x">${escapeHtml(String(Math.round(crop.x)))}</span>
          </div>
          <div class="thumbCropEditorControl">
            <label>Vertical focus</label>
            <input type="range" min="0" max="100" step="1" value="${escapeHtml(String(crop.y))}" data-crop-field="y" />
            <span data-crop-value="y">${escapeHtml(String(Math.round(crop.y)))}</span>
          </div>
          <div class="thumbCropEditorControl">
            <label>Zoom</label>
            <input type="range" min="1" max="4" step="0.01" value="${escapeHtml(String(crop.zoom))}" data-crop-field="zoom" />
            <span data-crop-value="zoom">${escapeHtml(crop.zoom.toFixed(2))}</span>
          </div>
          <div class="thumbCropEditorActions">
            <button type="button" data-crop-action="reset">Reset</button>
            <button type="button" data-crop-action="cancel">Cancel</button>
            <button type="button" data-crop-action="save">Save</button>
          </div>
        </div>
      `;
  document.body.appendChild(overlay);
  THUMB_CROP_EDITOR = overlay;

  const panel = overlay.querySelector(".thumbCropEditorPanel");
  const previewWrap = overlay.querySelector(".thumbCropEditorPreviewWrap");
  const previewMedia = overlay.querySelector(".thumbCropEditorPreviewFull");
  const previewImage = isVideoEditor ? null : previewMedia;
  const previewVideo = isVideoEditor ? previewMedia : null;
  const cropBox = overlay.querySelector('[data-crop-box="1"]');
  const shadeTop = overlay.querySelector('[data-crop-shade="top"]');
  const shadeLeft = overlay.querySelector('[data-crop-shade="left"]');
  const shadeRight = overlay.querySelector('[data-crop-shade="right"]');
  const shadeBottom = overlay.querySelector('[data-crop-shade="bottom"]');
  const resizeHandle = overlay.querySelector('[data-crop-handle="resize"]');
  const rangeX = overlay.querySelector('input[data-crop-field="x"]');
  const rangeY = overlay.querySelector('input[data-crop-field="y"]');
  const rangeZoom = overlay.querySelector('input[data-crop-field="zoom"]');
  const rangeFrame = overlay.querySelector('input[data-crop-field="frame"]');
  const valX = overlay.querySelector('[data-crop-value="x"]');
  const valY = overlay.querySelector('[data-crop-value="y"]');
  const valZoom = overlay.querySelector('[data-crop-value="zoom"]');
  const valFrame = overlay.querySelector('[data-crop-value="frame"]');
  let editorAspect = normalizePreviewAspect(
    getPreviewAspectForRecord(rec),
    4 / 3,
  );
  let editorVideoDuration = 0;
  const getEditorAspect = () => normalizePreviewAspect(editorAspect, 4 / 3);
  const applyEditorAspect = (nextAspect) => {
    editorAspect = normalizePreviewAspect(nextAspect, getEditorAspect());
    if (previewWrap)
      previewWrap.style.setProperty("--editor-ar", String(editorAspect));
  };
  const getCurrent = () =>
    normalizeThumbCropValue({
      x: Number(rangeX?.value || 50),
      y: Number(rangeY?.value || 50),
      zoom: Number(rangeZoom?.value || 1),
    });
  const applyPreview = () => {
    const cur = getCurrent();
    const overlayWin = computeEditorCropWindow(getEditorAspect(), cur);
    const left = Number(overlayWin.leftPct) || 0;
    const top = Number(overlayWin.topPct) || 0;
    const width = Number(overlayWin.widthPct) || 0;
    const height = Number(overlayWin.heightPct) || 0;
    const right = Math.max(0, 100 - (left + width));
    const bottom = Math.max(0, 100 - (top + height));
    if (valX) valX.textContent = String(Math.round(cur.x));
    if (valY) valY.textContent = String(Math.round(cur.y));
    if (valZoom) valZoom.textContent = cur.zoom.toFixed(2);
    if (cropBox) {
      cropBox.style.left = `${left}%`;
      cropBox.style.top = `${top}%`;
      cropBox.style.width = `${width}%`;
      cropBox.style.height = `${height}%`;
    }
    if (shadeTop) {
      shadeTop.style.left = "0%";
      shadeTop.style.top = "0%";
      shadeTop.style.width = "100%";
      shadeTop.style.height = `${top}%`;
    }
    if (shadeBottom) {
      shadeBottom.style.left = "0%";
      shadeBottom.style.top = `${top + height}%`;
      shadeBottom.style.width = "100%";
      shadeBottom.style.height = `${bottom}%`;
    }
    if (shadeLeft) {
      shadeLeft.style.left = "0%";
      shadeLeft.style.top = `${top}%`;
      shadeLeft.style.width = `${left}%`;
      shadeLeft.style.height = `${height}%`;
    }
    if (shadeRight) {
      shadeRight.style.left = `${left + width}%`;
      shadeRight.style.top = `${top}%`;
      shadeRight.style.width = `${right}%`;
      shadeRight.style.height = `${height}%`;
    }
    if (resizeHandle) {
      resizeHandle.style.left = `${left + width}%`;
      resizeHandle.style.top = `${top + height}%`;
    }
  };
  const setCurrent = (nextCrop) => {
    const next = normalizeThumbCropValue(nextCrop);
    if (rangeX) rangeX.value = String(next.x);
    if (rangeY) rangeY.value = String(next.y);
    if (rangeZoom) rangeZoom.value = String(next.zoom);
    applyPreview();
  };
  const clampEditorVideoTime = (timeValue) =>
    normalizeVideoThumbTimeValue(timeValue, editorVideoDuration);
  const getDefaultEditorVideoTime = () => {
    if (!isVideoEditor) return 0;
    const seekTimes = computeVideoThumbSeekTimes(editorVideoDuration || 0);
    return clampEditorVideoTime(seekTimes[0] || 0) || 0;
  };
  const getCurrentEditorVideoTime = () => {
    if (!isVideoEditor || !rangeFrame) return null;
    return clampEditorVideoTime(rangeFrame.value);
  };
  const updateEditorVideoFrameLabel = (timeValue) => {
    if (!valFrame) return;
    valFrame.textContent = formatThumbnailEditorTimeLabel(timeValue);
  };
  const syncEditorVideoTimeToSlider = (timeValue) => {
    if (!rangeFrame) return;
    const clamped = clampEditorVideoTime(timeValue);
    const safeValue = Number.isFinite(clamped) ? clamped : 0;
    rangeFrame.value = String(safeValue);
    updateEditorVideoFrameLabel(safeValue);
  };
  const seekEditorVideoToTime = (timeValue) => {
    if (!previewVideo) return;
    const clamped = clampEditorVideoTime(timeValue);
    if (!Number.isFinite(clamped)) return;
    syncEditorVideoTimeToSlider(clamped);
    try {
      previewVideo.currentTime = clamped;
    } catch {}
  };
  const updateEditorVideoFrameRange = () => {
    if (!rangeFrame) return;
    if (!(editorVideoDuration > 0)) {
      rangeFrame.min = "0";
      rangeFrame.max = "0";
      rangeFrame.step = "0.01";
      rangeFrame.value = "0";
      rangeFrame.disabled = true;
      updateEditorVideoFrameLabel(0);
      return;
    }
    const step = Math.max(0.01, Math.min(0.25, editorVideoDuration / 1000));
    rangeFrame.min = "0";
    rangeFrame.max = String(Math.max(0, editorVideoDuration - 0.05));
    rangeFrame.step = String(Math.round(step * 1000) / 1000);
    rangeFrame.disabled = false;
  };
  const getWrapSize = () => {
    const rect =
      previewWrap && previewWrap.getBoundingClientRect
        ? previewWrap.getBoundingClientRect()
        : null;
    return {
      width: Math.max(1, Number(rect && rect.width) || 1),
      height: Math.max(1, Number(rect && rect.height) || 1),
    };
  };
  const cropWithZoomAroundAnchor = (
    startCrop,
    nextZoom,
    anchorU = null,
    anchorV = null,
  ) => {
    const base = normalizeThumbCropValue(startCrop || getCurrent());
    const zoom = Math.min(4, Math.max(1, Number(nextZoom) || base.zoom || 1));
    const baseWin = computeEditorCropWindow(getEditorAspect(), base);
    const baseLeft = (Number(baseWin.leftPct) || 0) / 100;
    const baseTop = (Number(baseWin.topPct) || 0) / 100;
    const baseW = (Number(baseWin.widthPct) || 0) / 100;
    const baseH = (Number(baseWin.heightPct) || 0) / 100;
    const focusU = Number.isFinite(Number(anchorU))
      ? Math.max(0, Math.min(1, Number(anchorU)))
      : Math.max(0, Math.min(1, baseLeft + baseW * 0.5));
    const focusV = Number.isFinite(Number(anchorV))
      ? Math.max(0, Math.min(1, Number(anchorV)))
      : Math.max(0, Math.min(1, baseTop + baseH * 0.5));
    const probe = computeEditorCropWindow(getEditorAspect(), {
      x: 50,
      y: 50,
      zoom,
    });
    const nextW = (Number(probe.widthPct) || 0) / 100;
    const nextH = (Number(probe.heightPct) || 0) / 100;
    const nextRangeX = (Number(probe.rangeXPct) || 0) / 100;
    const nextRangeY = (Number(probe.rangeYPct) || 0) / 100;
    const nextLeft = Math.min(nextRangeX, Math.max(0, focusU - nextW * 0.5));
    const nextTop = Math.min(nextRangeY, Math.max(0, focusV - nextH * 0.5));
    const nextX = nextRangeX > 0.000001 ? (nextLeft / nextRangeX) * 100 : 50;
    const nextY = nextRangeY > 0.000001 ? (nextTop / nextRangeY) * 100 : 50;
    return normalizeThumbCropValue({ x: nextX, y: nextY, zoom });
  };
  const cropFromPanPixels = (startCrop, dx, dy, zoomOverride = null) => {
    const hasZoomOverride =
      zoomOverride !== null &&
      zoomOverride !== undefined &&
      zoomOverride !== "";
    const overrideZoom = hasZoomOverride ? Number(zoomOverride) : NaN;
    const liveZoom = Number(rangeZoom?.value);
    const currentZoom = Number(getCurrent().zoom);
    const startZoom = Number(startCrop && startCrop.zoom);
    const zoom = Number.isFinite(overrideZoom)
      ? overrideZoom
      : Number.isFinite(liveZoom)
        ? liveZoom
        : Number.isFinite(currentZoom)
          ? currentZoom
          : Number.isFinite(startZoom)
            ? startZoom
            : 1;
    const base = normalizeThumbCropValue({
      x: Number(startCrop && startCrop.x),
      y: Number(startCrop && startCrop.y),
      zoom,
    });
    const wrapSize = getWrapSize();
    const overlayWin = computeEditorCropWindow(getEditorAspect(), base);
    const rangeX = Math.max(0, Number(overlayWin.rangeXPct) / 100);
    const rangeY = Math.max(0, Number(overlayWin.rangeYPct) / 100);
    const nextX =
      rangeX > 0.000001
        ? base.x + ((Number(dx) || 0) / wrapSize.width) * (100 / rangeX)
        : base.x;
    const nextY =
      rangeY > 0.000001
        ? base.y + ((Number(dy) || 0) / wrapSize.height) * (100 / rangeY)
        : base.y;
    return normalizeThumbCropValue({
      x: nextX,
      y: nextY,
      zoom: base.zoom,
    });
  };

  [rangeX, rangeY, rangeZoom, rangeFrame].forEach((el) => {
    if (!el) return;
    if (el === rangeFrame) {
      el.addEventListener("input", () => {
        const nextTime = getCurrentEditorVideoTime();
        if (!Number.isFinite(nextTime)) return;
        seekEditorVideoToTime(nextTime);
      });
      return;
    }
    el.addEventListener("input", applyPreview);
  });
  applyEditorAspect(getEditorAspect());
  if (previewImage) {
    previewImage.addEventListener("load", () => {
      const w = Number(previewImage.naturalWidth) || 0;
      const h = Number(previewImage.naturalHeight) || 0;
      if (w > 0 && h > 0) {
        const naturalAspect = normalizePreviewAspect(
          w / h,
          getPreviewAspectForRecord(rec),
        );
        applyEditorAspect(naturalAspect);
        // Keep render-time crop math in sync with editor math, even before thumb jobs finish.
        if (rec && (rec.type === "image" || previewSrc !== BLACK_POSTER_URL)) {
          rec.previewAspect = naturalAspect;
        }
      }
      applyPreview();
    });
  }
  if (previewVideo) {
    previewVideo.controls = false;
    previewVideo.autoplay = false;
    previewVideo.loop = false;
    previewVideo.muted = true;
    previewVideo.addEventListener("play", () => {
      try {
        previewVideo.pause();
      } catch {}
    });
    previewVideo.addEventListener("loadedmetadata", () => {
      editorVideoDuration = Math.max(0, Number(previewVideo.duration || 0));
      updateEditorVideoFrameRange();
      const w = Number(previewVideo.videoWidth) || 0;
      const h = Number(previewVideo.videoHeight) || 0;
      if (w > 0 && h > 0) {
        const naturalAspect = normalizePreviewAspect(
          w / h,
          getPreviewAspectForRecord(rec),
        );
        applyEditorAspect(naturalAspect);
        rec.previewAspect = naturalAspect;
      }
      const initial = Number.isFinite(savedVideoFrameTime)
        ? clampEditorVideoTime(savedVideoFrameTime)
        : getDefaultEditorVideoTime();
      seekEditorVideoToTime(initial);
      applyPreview();
    });
    previewVideo.addEventListener("seeked", () => {
      syncEditorVideoTimeToSlider(previewVideo.currentTime || 0);
    });
    previewVideo.addEventListener("loadeddata", () => {
      const w = Number(previewVideo.videoWidth) || 0;
      const h = Number(previewVideo.videoHeight) || 0;
      if (w > 0 && h > 0) {
        const naturalAspect = normalizePreviewAspect(
          w / h,
          getPreviewAspectForRecord(rec),
        );
        applyEditorAspect(naturalAspect);
        rec.previewAspect = naturalAspect;
      }
      applyPreview();
    });
  }
  applyPreview();

  if (previewWrap) {
    let resizeGesture = null;
    const activePointers = new Map();
    let gesture = null;
    const pointerPosInWrap = (e) => {
      const rect =
        previewWrap && previewWrap.getBoundingClientRect
          ? previewWrap.getBoundingClientRect()
          : null;
      const left = Number(rect && rect.left) || 0;
      const top = Number(rect && rect.top) || 0;
      return {
        x: (Number(e && e.clientX) || 0) - left,
        y: (Number(e && e.clientY) || 0) - top,
      };
    };
    const getFirstTwoPointers = () => {
      const vals = Array.from(activePointers.values());
      if (vals.length < 2) return null;
      return [vals[0], vals[1]];
    };
    const pointerDistance = (a, b) =>
      Math.hypot(
        Number(a && a.x) - Number(b && b.x),
        Number(a && a.y) - Number(b && b.y),
      );
    const pointerCenter = (a, b) => ({
      x: (Number(a && a.x) + Number(b && b.x)) * 0.5,
      y: (Number(a && a.y) + Number(b && b.y)) * 0.5,
    });
    const refreshGesture = () => {
      if (activePointers.size >= 2) {
        const pair = getFirstTwoPointers();
        if (!pair) return;
        const center = pointerCenter(pair[0], pair[1]);
        gesture = {
          type: "pinch",
          startCrop: getCurrent(),
          startDist: Math.max(0.0001, pointerDistance(pair[0], pair[1])),
          startCenterX: center.x,
          startCenterY: center.y,
        };
        previewWrap.classList.add("dragging");
        return;
      }
      if (activePointers.size === 1) {
        const point = Array.from(activePointers.values())[0];
        gesture = {
          type: "pan",
          startCrop: getCurrent(),
          startX: Number(point && point.x) || 0,
          startY: Number(point && point.y) || 0,
        };
        previewWrap.classList.add("dragging");
        return;
      }
      gesture = null;
      previewWrap.classList.remove("dragging");
    };
    const onPointerEnd = (e) => {
      if (!activePointers.has(e.pointerId)) return;
      activePointers.delete(e.pointerId);
      try {
        previewWrap.releasePointerCapture(e.pointerId);
      } catch {}
      refreshGesture();
    };

    previewWrap.addEventListener("pointerdown", (e) => {
      if (resizeGesture) return;
      if (
        e.target &&
        e.target.closest &&
        e.target.closest('[data-crop-handle="resize"]')
      )
        return;
      if (e.pointerType === "mouse" && e.button !== 0) return;
      activePointers.set(e.pointerId, {
        x: Number(e.clientX) || 0,
        y: Number(e.clientY) || 0,
      });
      try {
        previewWrap.setPointerCapture(e.pointerId);
      } catch {}
      refreshGesture();
      e.preventDefault();
    });
    previewWrap.addEventListener("pointermove", (e) => {
      if (!activePointers.has(e.pointerId)) return;
      activePointers.set(e.pointerId, {
        x: Number(e.clientX) || 0,
        y: Number(e.clientY) || 0,
      });
      if (!gesture) {
        refreshGesture();
        return;
      }
      if (gesture.type === "pinch" && activePointers.size >= 2) {
        const pair = getFirstTwoPointers();
        if (!pair) return;
        const dist = pointerDistance(pair[0], pair[1]);
        const center = pointerCenter(pair[0], pair[1]);
        const scale = Math.max(
          0.25,
          Math.min(4, dist / Math.max(0.0001, Number(gesture.startDist) || 1)),
        );
        const nextZoom = Math.min(
          4,
          Math.max(1, Number(gesture.startCrop.zoom || 1) * scale),
        );
        const dx = center.x - Number(gesture.startCenterX || 0);
        const dy = center.y - Number(gesture.startCenterY || 0);
        const next = cropFromPanPixels(gesture.startCrop, dx, dy, nextZoom);
        setCurrent(next);
        e.preventDefault();
        return;
      }
      if (gesture.type === "pan" && activePointers.size === 1) {
        const point = Array.from(activePointers.values())[0];
        const dx =
          (Number(point && point.x) || 0) - Number(gesture.startX || 0);
        const dy =
          (Number(point && point.y) || 0) - Number(gesture.startY || 0);
        const next = cropFromPanPixels(gesture.startCrop, dx, dy);
        setCurrent(next);
        e.preventDefault();
        return;
      }
      refreshGesture();
    });
    previewWrap.addEventListener("pointerup", onPointerEnd);
    previewWrap.addEventListener("pointercancel", onPointerEnd);
    previewWrap.addEventListener("lostpointercapture", onPointerEnd);
    previewWrap.addEventListener(
      "wheel",
      (e) => {
        if (!e.ctrlKey && !e.metaKey) return;
        const cur = getCurrent();
        const delta = Number(e.deltaY) || 0;
        if (!delta) return;
        const factor = Math.exp(-delta * 0.0025);
        const nextZoom = Math.min(4, Math.max(1, cur.zoom * factor));
        if (Math.abs(nextZoom - cur.zoom) < 0.0001) return;
        setCurrent({ x: cur.x, y: cur.y, zoom: nextZoom });
        e.preventDefault();
      },
      { passive: false },
    );

    if (resizeHandle) {
      const onResizeEnd = (e) => {
        if (!resizeGesture || e.pointerId !== resizeGesture.pointerId) return;
        try {
          resizeHandle.releasePointerCapture(e.pointerId);
        } catch {}
        resizeGesture = null;
        previewWrap.classList.remove("resizing");
      };
      resizeHandle.addEventListener("pointerdown", (e) => {
        if (e.pointerType === "mouse" && e.button !== 0) return;
        const startCrop = getCurrent();
        const startWin = computeEditorCropWindow(getEditorAspect(), startCrop);
        const anchorU =
          ((Number(startWin.leftPct) || 0) +
            (Number(startWin.widthPct) || 0) * 0.5) /
          100;
        const anchorV =
          ((Number(startWin.topPct) || 0) +
            (Number(startWin.heightPct) || 0) * 0.5) /
          100;
        const wrapSize = getWrapSize();
        const centerPx = {
          x: anchorU * wrapSize.width,
          y: anchorV * wrapSize.height,
        };
        const pos = pointerPosInWrap(e);
        const startDist = Math.max(
          8,
          Math.hypot(pos.x - centerPx.x, pos.y - centerPx.y),
        );
        resizeGesture = {
          pointerId: e.pointerId,
          startCrop,
          startDist,
          centerPx,
          anchorU,
          anchorV,
        };
        try {
          resizeHandle.setPointerCapture(e.pointerId);
        } catch {}
        previewWrap.classList.add("resizing");
        e.preventDefault();
        e.stopPropagation();
      });
      resizeHandle.addEventListener("pointermove", (e) => {
        if (!resizeGesture || e.pointerId !== resizeGesture.pointerId) return;
        const pos = pointerPosInWrap(e);
        const dist = Math.max(
          1,
          Math.hypot(
            pos.x - resizeGesture.centerPx.x,
            pos.y - resizeGesture.centerPx.y,
          ),
        );
        const scale = dist / Math.max(1, resizeGesture.startDist);
        const nextZoom = Math.min(
          4,
          Math.max(
            1,
            Number(resizeGesture.startCrop.zoom || 1) / Math.max(0.2, scale),
          ),
        );
        const next = cropWithZoomAroundAnchor(
          resizeGesture.startCrop,
          nextZoom,
          resizeGesture.anchorU,
          resizeGesture.anchorV,
        );
        setCurrent(next);
        e.preventDefault();
        e.stopPropagation();
      });
      resizeHandle.addEventListener("pointerup", onResizeEnd);
      resizeHandle.addEventListener("pointercancel", onResizeEnd);
      resizeHandle.addEventListener("lostpointercapture", onResizeEnd);
    }
  }

  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) closeThumbnailCropEditor();
  });
  overlay.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      e.preventDefault();
      closeThumbnailCropEditor();
    }
  });
  if (panel) panel.addEventListener("click", (e) => e.stopPropagation());

  const actionBtns = Array.from(overlay.querySelectorAll("[data-crop-action]"));
  actionBtns.forEach((btn) => {
    btn.addEventListener("click", () => {
      const action = String(btn.getAttribute("data-crop-action") || "");
      if (action === "cancel") {
        closeThumbnailCropEditor();
        return;
      }
      if (action === "reset") {
        if (rangeX) rangeX.value = "50";
        if (rangeY) rangeY.value = "50";
        if (rangeZoom) rangeZoom.value = "1";
        if (isVideoEditor) {
          seekEditorVideoToTime(getDefaultEditorVideoTime());
        }
        applyPreview();
        return;
      }
      if (action === "save") {
        const nextCrop = getCurrent();
        metaSetFileThumbnailCropForRecord(rec, nextCrop);
        if (isVideoEditor) {
          const selectedFrameTime = getCurrentEditorVideoTime();
          metaSetVideoThumbnailTimeForRecord(
            rec,
            selectedFrameTime,
            editorVideoDuration,
          );
          if (rec.videoThumbUrl) {
            try {
              URL.revokeObjectURL(rec.videoThumbUrl);
            } catch {}
            rec.videoThumbUrl = null;
          }
          rec.videoThumbMode = null;
          enqueueVideoThumb(rec);
        }
        closeThumbnailCropEditor();
        renderDirectoriesPane(true);
        renderPreviewPane(false, true);
        syncButtons();
        kickVideoThumbsForPreview();
        kickImageThumbsForPreview();
        showStatusMessage(`Saved thumbnail settings for ${targetLabel}.`);
      }
    });
  });

  requestAnimationFrame(() => {
    try {
      overlay.focus();
    } catch {}
    if (isVideoEditor) {
      try {
        rangeFrame?.focus();
      } catch {}
    } else {
      try {
        rangeZoom?.focus();
      } catch {}
    }
  });
  return true;
}

function setTagThumbnailFromRecordByKey(rec, tagKey) {
  const key = String(tagKey || "");
  if (!rec || !key) {
    showStatusMessage("Selected file is unavailable.");
    return false;
  }
  const relPath = normalizeWorkspaceRelPath(rec.relPath || "");
  if (!relPath) {
    showStatusMessage("Selected file is unavailable.");
    return false;
  }
  const changed = metaSetTagThumbnailPresetByKey(key, relPath);
  const tagLabel = tagThumbnailLabelForKey(key);
  if (!changed) {
    showStatusMessage(`Thumbnail already set for '${tagLabel}'.`);
    return false;
  }
  renderDirectoriesPane(true);
  renderPreviewPane(false, true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  showStatusMessage(`Set thumbnail for '${tagLabel}'.`);
  return true;
}

function refreshThumbnailUiAfterMetadataChange() {
  renderDirectoriesPane(true);
  renderPreviewPane(false, true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
}

function pickRandomPreviewRecord(records) {
  const pool = Array.isArray(records) ? records.filter(Boolean) : [];
  if (!pool.length) return null;
  const idx = Math.floor(Math.random() * pool.length);
  return pool[idx] || null;
}

function randomThumbnailCandidateForDirNode(dirNode) {
  if (!dirNode) return null;
  const pool = getRecursivePreviewRecordsForDir(dirNode, 0, true).filter(
    (rec) => rec && passesFilter(rec),
  );
  if (!pool.length) return null;
  return pickRandomPreviewRecord(pool);
}

function randomThumbnailCandidateForTagEntry(entry) {
  if (!entry || entry.kind !== "tag") return null;
  const pool = getRecursivePreviewRecordsForTagEntry(entry, 0);
  if (!pool.length) return null;
  return pickRandomPreviewRecord(pool);
}

function setRandomFolderThumbnailForNode(dirNode) {
  const node = dirNode || null;
  if (!node) return false;
  const rec = randomThumbnailCandidateForDirNode(node);
  if (!rec) return false;
  const relPath = normalizeWorkspaceRelPath(rec.relPath || "");
  if (!relPath) return false;
  if (node === WS.root) {
    return metaSetTagThumbnailPresetByKey(rootThumbnailKey(), relPath);
  }
  const path = String(node.path || "");
  if (!path) return false;
  return metaSetFolderThumbnailPreset(path, relPath);
}

function setRandomTagThumbnailForEntry(entry) {
  if (!entry || entry.kind !== "tag") return false;
  const key = tagThumbnailKeyForEntry(entry);
  if (!key) return false;
  const rec = randomThumbnailCandidateForTagEntry(entry);
  if (!rec) return false;
  const relPath = normalizeWorkspaceRelPath(rec.relPath || "");
  if (!relPath) return false;
  return metaSetTagThumbnailPresetByKey(key, relPath);
}

function getTagPresetPreviewRecordForEntry(entry, tagPool = null) {
  const key = tagThumbnailKeyForEntry(entry);
  if (!key) return null;
  const relPath = metaGetTagThumbnailPresetRelPathByKey(key);
  if (!relPath) return null;
  const rec = findFileRecordByRelPath(relPath);
  if (!rec || !recordPassesTagEntryFilter(rec, entry)) return null;
  const dirs = getDirsForTagEntry(entry);
  if (!dirs.length || !isRecordInAnyDirSubtree(rec, dirs)) return null;
  return rec;
}

function getRecursivePreviewRecordsForTagEntry(entry, limit = 96) {
  const normalizedLimit = Math.max(0, Math.floor(Number(limit) || 0));
  const cacheKey =
    entry && entry.kind === "tag"
      ? `${String(tagEntrySelectionKey(entry) || "")}@@${String(
          entry.originPath || "",
        )}@@${effectiveFilterCacheKey()}@@${String(
          effectiveTagMediaFilterForEntry(entry).join(","),
        )}@@${String(normalizedLimit)}`
      : "";
  if (cacheKey && TAG_ENTRY_PREVIEW_POOL_CACHE.has(cacheKey)) {
    return TAG_ENTRY_PREVIEW_POOL_CACHE.get(cacheKey) || [];
  }
  const dirs = getDirsForTagEntry(entry);
  if (!dirs.length) return [];
  const result = sampleRecursivePreviewRecords(
    dirs,
    normalizedLimit,
    true,
  ).filter((rec) =>
    recordPassesTagEntryFilter(rec, entry),
  );
  if (cacheKey) TAG_ENTRY_PREVIEW_POOL_CACHE.set(cacheKey, result);
  return result;
}

function tagThumbnailPreviewSampleLimit(modeRaw) {
  const mode = String(modeRaw || "").trim().toLowerCase();
  if (mode === "quad") return 4;
  return 1;
}

function pickRotatingPreviewSlotsForKey(baseKey, records, count = 4) {
  const out = [];
  const k = String(baseKey || "");
  const pool = Array.isArray(records) ? records : [];
  const laneCount = Math.max(1, Number(count) || 1);
  if (!k || !pool.length) return out;
  for (let i = 0; i < laneCount; i++) {
    const laneKey = `${k}:slot:${i + 1}`;
    const rec = pool[i % pool.length] || null;
    out.push({ key: laneKey, rec: rec || null });
  }
  return out;
}

function registerRotatingPreviewPool(key, records) {
  return;
}

function pickRotatingPreviewRecordForKey(key, records) {
  const pool = Array.isArray(records) ? records : [];
  if (!pool.length) return null;
  return pool[0] || null;
}

function getRootThumbnailReferenceRecord(rootNode) {
  if (!rootNode) return null;
  const rootPool = getRecursivePreviewRecordsForDir(rootNode, 0, true);
  if (!rootPool.length) return null;
  const rootMode = getRootThumbnailMode();
  if (rootMode === "none") return null;
  const presetRec = getRootPresetPreviewRecord(rootNode, rootPool);
  if (presetRec) return presetRec;
  return rootPool[0] || null;
}

function getTagThumbnailReferenceRecord(entry) {
  if (!entry || entry.kind !== "tag" || entry.placeholder) return null;
  const key = tagThumbnailKeyForEntry(entry);
  if (!key) return null;
  const mode = metaGetTagThumbnailModeByKey(key);
  if (mode === "none") return null;
  const presetRec = getTagPresetPreviewRecordForEntry(entry);
  if (presetRec) return presetRec;
  const tagPool = getRecursivePreviewRecordsForTagEntry(
    entry,
    tagThumbnailPreviewSampleLimit(mode),
  );
  if (!tagPool.length) return null;
  return tagPool[0] || null;
}

function getSelectedThumbnailSourceRecordFromUi() {
  const resolveFromContainer = (container) => {
    if (!container || !container.querySelector) return null;
    const selected = container.querySelector(
      ".previewSelected, .dirRow.selected",
    );
    if (!selected || !selected.querySelector) return null;
    const img = selected.querySelector("[data-dir-preview-id]");
    if (!img || !img.dataset) return null;
    const recId = String(img.dataset.dirPreviewId || "");
    if (!recId) return null;
    return WS.fileById.get(recId) || null;
  };
  const previewRec = resolveFromContainer(previewBodyEl);
  if (previewRec) return previewRec;
  return resolveFromContainer(directoriesListEl);
}

function getSelectedThumbnailSourceRecord() {
  if (
    !WS.root ||
    !WS.nav ||
    !Array.isArray(WS.nav.entries) ||
    !WS.nav.entries.length
  )
    return null;
  const uiRec = getSelectedThumbnailSourceRecordFromUi();
  if (uiRec) return uiRec;
  const entry = WS.nav.entries[WS.nav.selectedIndex] || null;
  if (!entry) return null;

  if (entry.kind === "file") {
    return WS.fileById.get(String(entry.id || "")) || null;
  }

  if (entry.kind === "tag") {
    return getTagThumbnailReferenceRecord(entry);
  }

  if (entry.kind === "dir") {
    const node = entry.node || null;
    if (!node) return null;
    if (node === WS.root && WS.view && WS.view.aboveRootView) {
      return getRootThumbnailReferenceRecord(node);
    }
    const leadInfo = getDisplayLeadPreviewForDir(node, "dir");
    return leadInfo && leadInfo.record ? leadInfo.record : null;
  }

  return null;
}

const THUMB_VIEWPORT_NUDGE_STEP = 8;

function nudgeSelectedThumbnailViewport(dx, dy, opts = null) {
  const options = opts && typeof opts === "object" ? opts : {};
  const quietNoTarget = !!options.quietNoTarget;
  const quietAtEdge = !!options.quietAtEdge;
  const quietSuccess = !!options.quietSuccess;
  const skipAspectResolve = !!options.skipAspectResolve;
  const rec = getSelectedThumbnailSourceRecord();
  if (!rec) {
    if (!quietNoTarget)
      showStatusMessage("Selected item has no editable thumbnail source.");
    return false;
  }
  const stepX = Number(dx) || 0;
  const stepY = Number(dy) || 0;
  if (!stepX && !stepY) return false;
  if (!skipAspectResolve && !hasKnownPreviewAspect(rec)) {
    const pendingKey = String(rec.id || rec.relPath || "");
    const canQueue =
      pendingKey && !THUMB_ASPECT_RESOLVE_PENDING.has(pendingKey);
    if (canQueue) {
      THUMB_ASPECT_RESOLVE_PENDING.add(pendingKey);
      detectRecordPreviewAspect(rec)
        .then((detected) => {
          if (!detected) return;
          rec.previewAspect = normalizePreviewAspect(detected, 4 / 3);
          nudgeSelectedThumbnailViewport(
            stepX,
            stepY,
            Object.assign({}, options, {
              skipAspectResolve: true,
              quietNoTarget: true,
            }),
          );
        })
        .finally(() => {
          THUMB_ASPECT_RESOLVE_PENDING.delete(pendingKey);
        });
    }
    if (!quietSuccess) showStatusMessage("Preparing thumbnail framing...");
    return true;
  }
  const current = normalizeThumbCropValue(
    metaGetFileThumbnailCropForRecord(rec) || { x: 50, y: 50, zoom: 1 },
  );
  const aspect = getPreviewAspectForRecord(rec);
  const movementWindow = computeEditorCropWindow(aspect, current);
  const rangeX = Math.max(
    0,
    Number(movementWindow && movementWindow.rangeXPct) || 0,
  );
  const rangeY = Math.max(
    0,
    Number(movementWindow && movementWindow.rangeYPct) || 0,
  );
  const wantsX = !!stepX;
  const wantsY = !!stepY;
  const canMoveX = rangeX > 0.0001;
  const canMoveY = rangeY > 0.0001;
  if (wantsX && !canMoveX) {
    if (!quietAtEdge)
      showStatusMessage("No horizontal movement available at current zoom.");
    return false;
  }
  if (wantsY && !canMoveY) {
    if (!quietAtEdge)
      showStatusMessage("No vertical movement available at current zoom.");
    return false;
  }
  const next = normalizeThumbCropValue({
    x: current.x + stepX,
    y: current.y + stepY,
    zoom: current.zoom,
  });
  if (next.x === current.x && next.y === current.y) {
    if (!quietAtEdge) showStatusMessage("Thumbnail viewport already at edge.");
    return false;
  }
  metaSetFileThumbnailCropForRecord(rec, next);
  renderDirectoriesPane(true);
  renderPreviewPane(false, true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();

  const direction =
    stepX < 0 ? "left" : stepX > 0 ? "right" : stepY < 0 ? "up" : "down";
  if (!quietSuccess)
    showStatusMessage(`Thumbnail viewport moved ${direction}.`);
  return true;
}

function applyPreviewRecordToImageElement(imgEl, rec) {
  if (!imgEl || !rec) return false;
  const previewId = String(rec.id || "");
  const previewSrc = getPassivePreviewSrcForRecord(rec, {
    allowImageMediaFallback: true,
  });
  if (!previewSrc) return false;
  if (imgEl.src !== previewSrc) imgEl.src = previewSrc;
  imgEl.setAttribute("data-dir-preview-id", previewId);
  const previewAspect = getPreviewAspectForRecord(rec);
  applyDirectoryInlineAspect(imgEl, previewAspect);
  if (
    rec.type === "image" &&
    !syncDirectoryInlineAspectFromNaturalSize(imgEl, rec)
  ) {
    if (imgEl.dataset.dirAspectPending !== "1") {
      imgEl.dataset.dirAspectPending = "1";
      imgEl.addEventListener(
        "load",
        () => {
          delete imgEl.dataset.dirAspectPending;
          syncDirectoryInlineAspectFromNaturalSize(imgEl, rec);
        },
        { once: true },
      );
    }
  }
  const fitCard = imgEl.closest(".fitInsideCard");
  if (fitCard) {
    fitCard.dataset.aspect = String(previewAspect);
  }
  return true;
}

function crossfadePreviewRecordOnImageElement(imgEl, rec) {
  if (!imgEl || !rec) return;
  const busyUntil = Number(imgEl.dataset.rotateBusyUntil || "0");
  const now = Date.now();
  if (Number.isFinite(busyUntil) && busyUntil > now) return;
  const until = now + ROTATING_PREVIEW_FADE_MS + 80;
  imgEl.dataset.rotateBusyUntil = String(until);
  imgEl.classList.add("rotatingThumbFade");
  setTimeout(
    () => {
      applyPreviewRecordToImageElement(imgEl, rec);
      requestAnimationFrame(() => {
        imgEl.classList.remove("rotatingThumbFade");
      });
    },
    Math.round(ROTATING_PREVIEW_FADE_MS * 0.55),
  );
}

function rotatePreviewThumbnailsTick() {
  return;
}

function ensureRotatingPreviewTicker() {
  if (ROTATING_PREVIEW_TIMER) {
    clearInterval(ROTATING_PREVIEW_TIMER);
    ROTATING_PREVIEW_TIMER = 0;
  }
}

function makeTagPreviewNode(entry) {
  const baseNode = WS.nav.dirNode;
  if (!entry || !baseNode) return null;
  const dirs = getDirsForTagEntry(entry);
  const isAlbumEntry = !!entry.album && !entry.tag;
  const mode = entry.special
    ? String(entry.special || "")
    : isAlbumEntry
      ? "album"
      : "tag";
  const label = String(entry.label || entry.tag || entry.special || "Tag");
  const pathSuffix = entry.special
    ? entry.special
    : isAlbumEntry
      ? `album-${String(entry.album || "")}`
      : entry.tag || "tag";
  const safeSuffix = String(pathSuffix || "tag").replace(/[\/\\]/g, "_");
  const virtualPath = `${String(baseNode.path || "")}/@tag-${safeSuffix}`;
  return {
    type: "dir",
    name: label,
    parent: baseNode,
    childrenDirs: isAlbumEntry ? [] : dirs,
    childrenFiles: [],
    path: virtualPath,
    _skipTagFilters: true,
    _tagPreviewMode: mode,
    _tagPreviewTag: String(entry.tag || ""),
    _tagPreviewSpecial: String(entry.special || ""),
    _tagPreviewAlbum: String(entry.album || ""),
    _tagPreviewOriginPath: String(baseNode.path || ""),
  };
}

function findTagEntryIndexInEntries(entries, mode, tag, album = "") {
  const albumKey = normalizeTagAlbumName(album);
  const list = Array.isArray(entries) ? entries : [];
  for (let i = 0; i < list.length; i++) {
    const entry = list[i];
    if (!entry || entry.kind !== "tag") continue;
    if (mode && entry.special && entry.special === mode) return i;
    if (
      mode === "album" &&
      entry.album &&
      !entry.tag &&
      normalizeTagAlbumName(entry.album) === albumKey
    )
      return i;
    if (mode === "tag" && entry.tag && entry.tag === tag) {
      const entryAlbum = normalizeTagAlbumName(entry.album || "");
      if (albumKey && entryAlbum !== albumKey) continue;
      return i;
    }
  }
  return -1;
}

function findTagEntryIndex(mode, tag, album = "") {
  return findTagEntryIndexInEntries(WS.nav.entries, mode, tag, album);
}

function restoreTagFolderEntrySelection(ctx) {
  if (!ctx) return false;
  const baseNode = WS.dirByPath.get(String(ctx.originPath || "")) || WS.root;
  if (!baseNode) return false;
  WS.nav.dirNode = baseNode;
  WS.view.tagFolderActiveMode = "";
  WS.view.tagFolderActiveTag = "";
  WS.view.tagFolderActiveAlbum = "";
  WS.view.tagFolderOriginPath = "";
  closeActionMenus();
  rebuildDirectoriesEntries();
  const idx = findTagEntryIndex(ctx.mode, ctx.tag, ctx.album);
  WS.nav.selectedIndex = findNearestSelectableIndex(idx >= 0 ? idx : 0, 1);
  syncPreviewToSelection({ force: true });
  finalizeDirectoryNavigationRender({
    animatePreview: true,
    keepDirectoriesScroll: true,
  }).catch(() => {});
  return true;
}

function applyTagFolderViewState(mode, tag, originPath, album = "") {
  WS.view.tagFolderActiveMode = mode;
  WS.view.tagFolderActiveTag = tag;
  WS.view.tagFolderActiveAlbum = String(album || "");
  WS.view.tagFolderOriginPath = String(originPath || "");
  closeActionMenus();
  rebuildDirectoriesEntries();
}

function setTagFolderViewState(mode, tag, originPath, album = "") {
  applyTagFolderViewState(mode, tag, originPath, album);
  WS.nav.selectedIndex = selectionIndexForDirectoryEnter();
  syncPreviewToSelection({ force: true });
  finalizeDirectoryNavigationRender({
    animatePreview: true,
    keepDirectoriesScroll: true,
  }).catch(() => {});
}

function makeTagPreviewNodeForContext(mode, tag, originPath, album = "") {
  const entry = {
    kind: "tag",
    originPath: String(originPath || ""),
  };
  if (mode === "favorites" || mode === "hidden" || mode === "untagged") {
    entry.special = mode;
    entry.label =
      mode === "favorites"
        ? "Favorites"
        : mode === "hidden"
          ? "Hidden"
          : "Untagged";
  } else if (mode === "album") {
    entry.album = String(album || "");
    entry.label = String(album || "") || "Album";
  } else if (mode === "tag") {
    entry.tag = String(tag || "");
    entry.album = String(album || "");
    entry.label = String(tag || "") || "Tag";
  }
  return makeTagPreviewNode(entry);
}

function getDirectoriesScrollTop() {
  if (!directoriesListEl) return 0;
  return directoriesListEl.scrollTop || 0;
}

function setDirectoriesScrollTop(value) {
  if (!directoriesListEl || typeof value !== "number") return;
  directoriesListEl.scrollTop = value;
}

function restoreDirectoriesScrollWithSelectionReveal(value) {
  setDirectoriesScrollTop(Number(value) || 0);
  if (!directoriesListEl) return;
  if (isGridInteractionMode()) {
    revealSelectedDirectoryRowInGridMode(false);
    return;
  }
  const vis = getSelectedDirectoryRowVisibility();
  if (vis.state === "offscreen") {
    centerSelectedDirectoryRow(0);
  } else if (vis.state === "partial") {
    snapSelectedDirectoryRowFullyIntoView();
  }
}

function ensureTagNavStack() {
  if (!Array.isArray(WS.view.tagNavStack)) WS.view.tagNavStack = [];
  return WS.view.tagNavStack;
}

function isSameOrDescendantPath(path, ancestorPath) {
  const pathNorm = String(path || "");
  const ancestorNorm = String(ancestorPath || "");
  if (!pathNorm || !ancestorNorm) return pathNorm === ancestorNorm;
  return pathNorm === ancestorNorm || pathNorm.startsWith(`${ancestorNorm}/`);
}

function clearTagNavigationStack() {
  WS.view.tagNavStack = [];
}

// Portal navigation is intentionally centralized here.
// This area has had long-running regressions where "leave directory" from a folder entered via
// a virtual folder (especially Favorites/Tags) incorrectly dropped users into the real tree root.
// Keep all virtual-folder matching/restore decisions in this guard so future virtual folder types
// can reuse the exact same behavior without duplicating fragile path logic.
function findMatchingVirtualPortalRootPath(frame, path) {
  const currentPath = String(path || "");
  if (!frame || !currentPath) return "";
  const frameType = String(frame.type || "");
  if (frameType !== "tag-view") return "";
  const selectedRoot = String(frame.selectedDirPath || "");
  if (selectedRoot && isSameOrDescendantPath(currentPath, selectedRoot))
    return selectedRoot;
  const ordered = Array.isArray(frame.orderedPaths) ? frame.orderedPaths : [];
  for (let i = 0; i < ordered.length; i++) {
    const candidate = String(ordered[i] || "");
    if (!candidate) continue;
    if (isSameOrDescendantPath(currentPath, candidate)) return candidate;
  }
  return "";
}

function isVirtualPortalViewFrame(frame) {
  const frameType = String((frame && frame.type) || "");
  return frameType.endsWith("-view");
}

function pruneStaleTagEntryFramesForPath(path) {
  const stack = ensureTagNavStack();
  const currentPath = String(path || "");
  let changed = false;
  while (stack.length) {
    const top = stack[stack.length - 1];
    if (!top || top.type !== "tag-entry") break;
    const entryDir = String(top.dirPath || "");
    if (entryDir === currentPath) break;
    stack.pop();
    changed = true;
  }
  return changed;
}

function pruneStaleVirtualPortalFramesForPath(path) {
  const stack = ensureTagNavStack();
  const currentPath = String(path || "");
  let changed = false;
  while (stack.length) {
    const top = stack[stack.length - 1];
    if (!top || !isVirtualPortalViewFrame(top)) break;
    if (!currentPath) break;
    if (findMatchingVirtualPortalRootPath(top, currentPath)) break;
    stack.pop();
    changed = true;
  }
  return changed;
}

function pushTagNavFrame(frame) {
  if (!frame) return;
  ensureTagNavStack().push(frame);
}

function pushTagEntryContext(mode, tag, album = "", opts = null) {
  const options = opts && typeof opts === "object" ? opts : null;
  pushTagNavFrame({
    type: "tag-entry",
    dirPath: String(
      options && options.baseDirPath !== undefined
        ? options.baseDirPath
        : WS.nav.dirNode?.path || "",
    ),
    entryMode: mode || "",
    entryTag: tag || "",
    entryAlbum: String(album || ""),
    prevMode: String(
      options && options.prevMode !== undefined
        ? options.prevMode
        : WS.view.tagFolderActiveMode || "",
    ),
    prevTag: String(
      options && options.prevTag !== undefined
        ? options.prevTag
        : WS.view.tagFolderActiveTag || "",
    ),
    prevAlbum: String(
      options && options.prevAlbum !== undefined
        ? options.prevAlbum
        : WS.view.tagFolderActiveAlbum || "",
    ),
    prevOriginPath: String(
      options && options.prevOriginPath !== undefined
        ? options.prevOriginPath
        : WS.view.tagFolderOriginPath || "",
    ),
    selectedIndex: Number.isFinite(options && options.selectedIndex)
      ? Number(options.selectedIndex)
      : WS.nav.selectedIndex,
    scrollTop: Number.isFinite(options && options.scrollTop)
      ? Number(options.scrollTop)
      : getDirectoriesScrollTop(),
  });
}

function pushTagViewContext(selectedDirPath) {
  const orderedPaths = getDirsForTagFolderView()
    .map((d) => String(d?.path || ""))
    .filter(Boolean);
  pushTagNavFrame({
    type: "tag-view",
    mode: WS.view.tagFolderActiveMode,
    tag: WS.view.tagFolderActiveTag,
    album: WS.view.tagFolderActiveAlbum,
    originPath: String(WS.view.tagFolderOriginPath || ""),
    selectedDirPath: String(selectedDirPath || ""),
    scrollTop: getDirectoriesScrollTop(),
    orderedPaths,
  });
}

function restoreTagViewFromFrame(frame, opts = null) {
  if (!frame) return false;
  const options = opts && typeof opts === "object" ? opts : null;
  const animatePreview = !(options && options.previewPortalRestore);
  const baseNode = WS.dirByPath.get(String(frame.originPath || "")) || WS.root;
  if (!baseNode) return false;
  cancelPendingNavigationRender();
  WS.nav.dirNode = baseNode;
  applyTagFolderViewState(
    frame.mode || "",
    frame.tag || "",
    frame.originPath,
    frame.album || "",
  );
  const idx = frame.selectedDirPath
    ? findDirEntryIndexByPath(frame.selectedDirPath)
    : -1;
  WS.nav.selectedIndex = findNearestSelectableIndex(idx >= 0 ? idx : 0, 1);
  if (options && options.previewPortalRestore) {
    const portalNode = makeTagPreviewNodeForContext(
      frame.mode || "",
      frame.tag || "",
      frame.originPath || "",
      frame.album || "",
    );
    const selectedDirPath = String(frame.selectedDirPath || "");
    WS.view.pendingPreviewSelectionKey = selectedDirPath
      ? `dir:${selectedDirPath}`
      : "";
    if (portalNode) {
      applyPreviewState({ kind: "dir", dirNode: portalNode, fileId: null });
    } else {
      syncPreviewToSelection({ force: true });
    }
  } else {
    syncPreviewToSelection({ force: true });
  }
  renderDirectoriesPane(true);
  renderPreviewPane(animatePreview);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  restoreDirectoriesScrollWithSelectionReveal(frame.scrollTop);
  return true;
}

function restoreDirectoriesFromTagEntryFrame(frame) {
  if (!frame) return false;
  const baseNode = WS.dirByPath.get(String(frame.dirPath || "")) || WS.root;
  if (!baseNode) return false;
  cancelPendingNavigationRender();
  WS.nav.dirNode = baseNode;
  WS.view.tagFolderActiveMode = String(frame.prevMode || "");
  WS.view.tagFolderActiveTag = String(frame.prevTag || "");
  WS.view.tagFolderActiveAlbum = String(frame.prevAlbum || "");
  WS.view.tagFolderOriginPath = String(frame.prevOriginPath || "");
  closeActionMenus();
  rebuildDirectoriesEntries();
  const idx = findTagEntryIndex(
    frame.entryMode,
    frame.entryTag,
    frame.entryAlbum,
  );
  const targetIndex =
    idx >= 0
      ? idx
      : typeof frame.selectedIndex === "number"
        ? frame.selectedIndex
        : 0;
  WS.nav.selectedIndex = findNearestSelectableIndex(targetIndex, 1);
  syncPreviewToSelection({ force: true });
  renderDirectoriesPane(true);
  renderPreviewPane(true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  restoreDirectoriesScrollWithSelectionReveal(frame.scrollTop);
  return true;
}

function tryRestoreTagDirectoryContext(pathOverride = null, opts = null) {
  // Critical behavior:
  // If a user enters from a tag/favorites virtual folder, then traverses inside matching folders,
  // "leave directory" must return to the same virtual folder view (portal) instead of dropping to
  // the real parent/root. This was a long-standing edge-case bug in favorites-root navigation.
  const options = opts && typeof opts === "object" ? opts : null;
  const currentPath =
    pathOverride !== null && pathOverride !== undefined
      ? String(pathOverride || "")
      : String(WS.nav.dirNode?.path || "");
  pruneStaleVirtualPortalFramesForPath(currentPath);
  const stack = WS.view.tagNavStack;
  if (!Array.isArray(stack) || !stack.length) return false;
  const frame = stack[stack.length - 1];
  if (frame.type !== "tag-view") return false;
  const curPath = currentPath;
  const portalRootPath = findMatchingVirtualPortalRootPath(frame, curPath);
  if (!portalRootPath) return false;
  if (curPath !== portalRootPath) return false;
  stack.pop();
  return restoreTagViewFromFrame(
    Object.assign({}, frame, {
      selectedDirPath: portalRootPath,
    }),
    {
      previewPortalRestore: !!(options && options.previewPortalRestore),
    },
  );
}

function tryRestoreTagEntryContext() {
  const stack = WS.view.tagNavStack;
  if (!Array.isArray(stack) || !stack.length) return false;
  const frame = stack[stack.length - 1];
  if (frame.type !== "tag-entry") return false;
  stack.pop();
  return restoreDirectoriesFromTagEntryFrame(frame);
}

function exitTagFolderView() {
  if (!isViewingTagFolder()) return;
  if (tryRestoreTagEntryContext()) return;
  const ctx = {
    mode: WS.view.tagFolderActiveMode,
    tag: WS.view.tagFolderActiveTag,
    album: WS.view.tagFolderActiveAlbum,
    originPath: WS.view.tagFolderOriginPath,
  };
  if (!restoreTagFolderEntrySelection(ctx)) {
    setTagFolderViewState("", "", "", "");
  }
}

function resolveTagEntryBaseNode(entry) {
  if (!entry) return null;
  const originPath = String(entry.originPath || "");
  if (originPath) {
    const originNode = WS.dirByPath.get(originPath);
    if (originNode) return originNode;
  }
  const previewDir = getPreviewTargetDir();
  if (previewDir && !previewDir._skipTagFilters) return previewDir;
  return WS.nav.dirNode || WS.root || null;
}

function openTagFolderEntry(entry) {
  if (!entry) return;
  if (entry.placeholder) return;
  const baseNode = resolveTagEntryBaseNode(entry);
  if (!baseNode) return;
  const basePath = String(baseNode.path || "");
  const currentDirPath = String(WS.nav.dirNode?.path || "");
  const rebaseToDifferentDir = currentDirPath !== basePath;
  // Keep nested tag/favorites portal history. We only drop frames that are no longer relevant to
  // the current real directory path; this avoids the old bug where entering a child tag folder
  // replaced outer portal context and caused bad exits back to the real tree.
  pruneStaleVirtualPortalFramesForPath(basePath);
  pruneStaleTagEntryFramesForPath(basePath);
  const album = String(entry.album || "");
  const isAlbumEntry = !!album && !entry.tag && !entry.special;
  const mode = entry.special ? entry.special : isAlbumEntry ? "album" : "tag";
  const tag = mode === "tag" ? entry.tag || "" : "";
  const selectedIndex = findTagEntryIndexInEntries(
    getTagFolderEntriesForDir(baseNode, { includePlaceholder: true }),
    mode,
    tag,
    album,
  );
  WS.nav.dirNode = baseNode;
  WS.view.aboveRootView = false;
  syncBulkSelectionForCurrentDir();
  syncFavoritesUi();
  syncHiddenUi();
  syncTagUiForCurrentDir();
  pushTagEntryContext(mode, tag, album, {
    baseDirPath: basePath,
    selectedIndex: selectedIndex >= 0 ? selectedIndex : 0,
    scrollTop: rebaseToDifferentDir ? 0 : getDirectoriesScrollTop(),
  });
  setTagFolderViewState(mode, tag, basePath, album);
}

function getChildDirsForNode(dirNode) {
  return getChildDirsForNodeBase(dirNode);
}

function getVisibleSiblingDirsForSlide(dirNode) {
  const dp = String(dirNode?.path || "");
  pruneStaleVirtualPortalFramesForPath(dp);
  const stack = WS.view.tagNavStack;
  if (Array.isArray(stack) && stack.length) {
    const frame = stack[stack.length - 1];
    if (frame && frame.type === "tag-view") {
      if (Array.isArray(frame.orderedPaths) && frame.orderedPaths.length) {
        const nodes = frame.orderedPaths
          .map((p) => WS.dirByPath.get(String(p || "")))
          .filter(Boolean);
        if (nodes.length) {
          const match = nodes.some((d) => String(d?.path || "") === dp);
          if (match) return nodes;
        }
      }
      const tagDirs = getDirsForTagViewFrame(frame);
      if (tagDirs.length) {
        const match = tagDirs.some((d) => String(d?.path || "") === dp);
        if (match) return tagDirs;
      }
    }
  }

  if (searchBrowsingResultFolder() && dp) {
    const dirs = (WS.view.searchResults || []).slice();
    if (dirs.some((node) => String(node?.path || "") === dp)) return dirs;
  }

  if (
    WS.view.favoritesMode &&
    !WS.view.favoritesRootActive &&
    dp &&
    dp === String(WS.view.favoritesAnchorPath || "")
  ) {
    return getAllFavoriteDirs();
  }

  if (
    WS.view.hiddenMode &&
    !WS.view.hiddenRootActive &&
    dp &&
    dp === String(WS.view.hiddenAnchorPath || "")
  ) {
    return getAllHiddenDirs();
  }

  const p = dirNode?.parent;
  if (!p) return [];
  return getChildDirsForNodeBase(p);
}

function searchSessionActive() {
  return !!(
    WS.view &&
    WS.view.dirSearchPinned &&
    String(WS.view.dirSearchQuery || "").trim()
  );
}

function searchResultsVisibleInPreviewPane() {
  return !!(
    searchSessionActive() &&
    WS.view.searchRootActive &&
    WS.view.previewSearchActive &&
    isCompactTitleLayout()
  );
}

function searchResultsVisibleInDirectoriesPane() {
  return !!(
    searchSessionActive() &&
    WS.view.searchRootActive &&
    (!WS.view.previewSearchActive || !isCompactTitleLayout())
  );
}

function searchBrowsingResultFolder() {
  return !!(searchSessionActive() && !WS.view.searchRootActive);
}

function findSearchResultNodeByPath(path) {
  const targetPath = String(path || "");
  if (!targetPath || !Array.isArray(WS.view.searchResults)) return null;
  for (let i = 0; i < WS.view.searchResults.length; i++) {
    const node = WS.view.searchResults[i];
    if (String(node?.path || "") === targetPath) return node;
  }
  return null;
}

function currentSearchResultPath() {
  const currentPath = String(WS.nav.dirNode?.path || "");
  if (findSearchResultNodeByPath(currentPath)) return currentPath;
  const rememberedPath = String(
    WS.view.searchEntryRootPath || WS.view.searchAnchorPath || "",
  );
  if (findSearchResultNodeByPath(rememberedPath)) return rememberedPath;
  const firstResult = Array.isArray(WS.view.searchResults)
    ? WS.view.searchResults[0]
    : null;
  return String(firstResult?.path || "");
}

function enterSearchResultContext(pathLike) {
  const path = String(pathLike || "");
  WS.view.searchRootActive = false;
  WS.view.searchAnchorPath = path;
  WS.view.searchEntryRootPath = path;
}

function captureSearchResultsRestoreState(dirNode, opts = null) {
  const node = dirNode || findSearchResultNodeByPath(currentSearchResultPath());
  const restorePath = String(node?.path || "");
  const activePane =
    opts && opts.activePane === "preview" ? "preview" : "directories";
  const state = captureViewerCloseRestoreState({
    activePane,
    pendingPreviewSelectionKey:
      WS.view.previewSearchActive && restorePath ? `dir:${restorePath}` : "",
  });
  if (!state) return state;
  if (state.view && typeof state.view === "object") {
    state.view.previewSearchActive = !!WS.view.previewSearchActive;
    state.view.searchRootActive = true;
    state.view.searchAnchorPath = restorePath;
    state.view.searchEntryRootPath = restorePath;
  }
  state.entryKey = restorePath ? `dir:${restorePath}` : "";
  return state;
}

function getNextSiblingDirWithFiles(dirNode) {
  if (!dirNode) return null;
  const sibs = getVisibleSiblingDirsForSlide(dirNode);
  const idx = sibs.indexOf(dirNode);
  if (idx < 0) return null;
  for (let i = idx + 1; i < sibs.length; i++) {
    const d = sibs[i];
    if (getOrderedFileIdsForDir(d).length) return d;
  }
  return null;
}

function getPrevSiblingDirWithFiles(dirNode) {
  if (!dirNode) return null;
  const sibs = getVisibleSiblingDirsForSlide(dirNode);
  const idx = sibs.indexOf(dirNode);
  if (idx < 0) return null;
  for (let i = idx - 1; i >= 0; i--) {
    const d = sibs[i];
    if (getOrderedFileIdsForDir(d).length) return d;
  }
  return null;
}

function getAllFavoriteDirs() {
  const out = [];
  if (!WS.root) return out;
  for (const [path, node] of WS.dirByPath.entries()) {
    const p = String(path || "");
    if (!p) continue;
    if (!node || node.type !== "dir") continue;
    if (isPathInsideInternalTrash(p)) continue;
    if (metaHasFavorite(p) && !metaHasHidden(p)) out.push(node);
  }
  out.sort((a, b) => {
    const ap = displayPath(a.path || "");
    const bp = displayPath(b.path || "");
    const c = ap.localeCompare(bp);
    if (c) return c;
    return compareIndexedNames(a?.name || "", b?.name || "");
  });
  return out;
}

function getAllHiddenDirs() {
  const out = [];
  if (!WS.root) return out;
  for (const [path, node] of WS.dirByPath.entries()) {
    const p = String(path || "");
    if (!p) continue;
    if (!node || node.type !== "dir") continue;
    if (isPathInsideInternalTrash(p)) continue;
    if (metaHasHidden(p)) out.push(node);
  }
  out.sort((a, b) => {
    const ap = displayPath(a.path || "");
    const bp = displayPath(b.path || "");
    const c = ap.localeCompare(bp);
    if (c) return c;
    return compareIndexedNames(a?.name || "", b?.name || "");
  });
  return out;
}

function cancelDirectorySearch() {
  WS.view.dirSearchPinned = false;
  WS.view.previewSearchActive = false;
  WS.view.dirSearchQuery = "";
  WS.view.searchRootActive = false;
  WS.view.searchRootPath = "";
  WS.view.searchAnchorPath = "";
  WS.view.searchEntryRootPath = "";
  WS.view.searchRootIsFavorites = false;
  WS.view.searchRootFavorites = [];
  WS.view.searchRootIsHidden = false;
  WS.view.searchRootHidden = [];
  WS.view.searchResults = [];
  WS.view.searchResultsDirectCount = 0;
  WS.view.pendingPreviewSelectionKey = "";
}

function compactPreviewSearchActive() {
  return searchResultsVisibleInPreviewPane();
}

function clearDirectorySearchUi() {
  cancelDirectorySearch();
  if (directoriesSearchInput) directoriesSearchInput.value = "";

  TAG_EDIT_PATH = null;
  clearBulkTagPlaceholder();
  syncBulkSelectionForCurrentDir();

  rebuildDirectoriesEntries();
  WS.nav.selectedIndex = findNearestSelectableIndex(WS.nav.selectedIndex, 1);
  syncPreviewToSelection();
  renderDirectoriesPane(true);
  renderPreviewPane(false, true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
}

function computeDirectorySearchResults() {
  const q = String(WS.view.dirSearchQuery || "")
    .trim()
    .toLowerCase();
  WS.view.searchResults = [];
  WS.view.searchResultsDirectCount = 0;
  if (!WS.root || !q) return;

  const countMemo = new Map();
  const getCount = (node) => {
    if (!node) return 0;
    const p = String(node.path || "");
    if (countMemo.has(p)) return countMemo.get(p);
    const c = dirItemCount(node) | 0;
    countMemo.set(p, c);
    return c;
  };

  const addSet = new Set();
  const directResults = [];
  const recursiveResults = [];
  const skipHidden = !(WS.view.hiddenMode || showHiddenFolderEnabled());
  const canIncludeNode = (node) => {
    if (!node) return false;
    if (skipHidden && isDirOrAncestorHidden(node)) return false;
    if (getCount(node) <= 0) return false;
    return true;
  };
  const maybeAddMatch = (node, out) => {
    if (!canIncludeNode(node)) return;
    const p = String(node.path || "");
    if (!p || addSet.has(p)) return;
    const name = dirDisplayName(node || null).toLowerCase();
    if (!name.includes(q)) return;
    addSet.add(p);
    out.push(node);
  };
  const collectRecursiveMatches = (node) => {
    const children = getChildDirsForNodeBase(node);
    for (let i = 0; i < children.length; i++) {
      const child = children[i];
      maybeAddMatch(child, recursiveResults);
      collectRecursiveMatches(child);
    }
  };

  if (WS.view.searchRootIsFavorites) {
    const roots = Array.isArray(WS.view.searchRootFavorites)
      ? WS.view.searchRootFavorites
      : [];
    for (let i = 0; i < roots.length; i++) {
      const root = roots[i];
      maybeAddMatch(root, directResults);
      collectRecursiveMatches(root);
    }
  } else if (WS.view.searchRootIsHidden) {
    const roots = Array.isArray(WS.view.searchRootHidden)
      ? WS.view.searchRootHidden
      : [];
    for (let i = 0; i < roots.length; i++) {
      const root = roots[i];
      maybeAddMatch(root, directResults);
      collectRecursiveMatches(root);
    }
  } else {
    const rp = String(WS.view.searchRootPath || "");
    const rootNode = WS.dirByPath.get(rp) || WS.root;
    const directChildren = getChildDirsForNodeBase(rootNode);
    for (let i = 0; i < directChildren.length; i++) {
      const child = directChildren[i];
      maybeAddMatch(child, directResults);
      collectRecursiveMatches(child);
    }
  }
  WS.view.searchResultsDirectCount = directResults.length;
  WS.view.searchResults = directResults.concat(recursiveResults);
  if (!WS.view.searchResults.length) {
    WS.view.pendingPreviewSelectionKey = "";
  }
}

function syncFavoritesUi() {
  if (favoritesBtn) {
    const n = WS.root ? getAllFavoriteDirs().length : 0;
    favoritesBtn.textContent = `Favorites${n ? ` (${n})` : ""}`;
    favoritesBtn.classList.toggle("active", !!WS.view.favoritesMode);
    favoritesBtn.disabled = !WS.root;
  }
}

function syncHiddenUi() {
  if (hiddenBtn) {
    const n = WS.root ? getAllHiddenDirs().length : 0;
    hiddenBtn.textContent = `Hidden${n ? ` (${n})` : ""}`;
    hiddenBtn.classList.toggle("active", !!WS.view.hiddenMode);
    hiddenBtn.disabled = !WS.root;
  }
}

function syncTagUiForCurrentDir() {
  if (!WS.root || !WS.nav.dirNode) return;
}

function shouldIncludeGridUpDirectoryEntry() {
  return false;
}

function buildGridUpDirectoryEntry() {
  let parentLabel = "parent folder";
  if (isViewingTagFolder()) {
    const originPath = String(WS.view.tagFolderOriginPath || "");
    const originNode = WS.dirByPath.get(originPath) || WS.root;
    if (originNode) parentLabel = dirDisplayName(originNode);
  } else if (WS.nav.dirNode && WS.nav.dirNode.parent) {
    parentLabel = dirDisplayName(WS.nav.dirNode.parent);
  }
  return {
    kind: "up",
    label: "Up Directory",
    icon: "↩",
    parentLabel,
  };
}

function selectionIndexForDirectoryEnter() {
  if (isGridInteractionMode()) return findNearestSelectableIndex(0, 1);
  return restoreGridSelectionForCurrentContext(0);
}

function rebuildDirectoriesEntries() {
  clearTagEntryDerivedCaches();
  WS.nav.entries = [];

  if (!WS.root) return;
  if (WS.view.aboveRootView && !showRootViewEnabled()) {
    WS.view.aboveRootView = false;
  }
  const includeGridUpEntry = shouldIncludeGridUpDirectoryEntry();
  if (WS.view.aboveRootView && WS.nav.dirNode === WS.root) {
    WS.nav.entries.push({ kind: "dir", node: WS.root });
    return;
  }

  if (isViewingTagFolder()) {
    if (includeGridUpEntry) WS.nav.entries.push(buildGridUpDirectoryEntry());
    const placeholderEntry = buildBulkTagPlaceholderEntry();
    if (placeholderEntry) WS.nav.entries.push(placeholderEntry);
    const virtualTagEntries = getTagEntriesForTagFolderView();
    for (let i = 0; i < virtualTagEntries.length; i++)
      WS.nav.entries.push(virtualTagEntries[i]);
    if (virtualTagEntries.length) return;
    const nodes = getDirsForTagFolderView();
    for (const d of nodes) WS.nav.entries.push({ kind: "dir", node: d });
    return;
  }

  if (searchResultsVisibleInDirectoriesPane()) {
    if (includeGridUpEntry) WS.nav.entries.push(buildGridUpDirectoryEntry());
    const placeholderEntry = buildBulkTagPlaceholderEntry();
    if (placeholderEntry) WS.nav.entries.push(placeholderEntry);
    const dirs = (WS.view.searchResults || []).slice();
    for (let i = 0; i < dirs.length; i++)
      WS.nav.entries.push({ kind: "dir", node: dirs[i] });
    return;
  }

  if (WS.view.favoritesMode && WS.view.favoritesRootActive) {
    if (includeGridUpEntry) WS.nav.entries.push(buildGridUpDirectoryEntry());
    const placeholderEntry = buildBulkTagPlaceholderEntry();
    if (placeholderEntry) WS.nav.entries.push(placeholderEntry);
    const dirs = getAllFavoriteDirs();
    for (const d of dirs) WS.nav.entries.push({ kind: "dir", node: d });
    return;
  }

  if (WS.view.hiddenMode && WS.view.hiddenRootActive) {
    if (includeGridUpEntry) WS.nav.entries.push(buildGridUpDirectoryEntry());
    const placeholderEntry = buildBulkTagPlaceholderEntry();
    if (placeholderEntry) WS.nav.entries.push(placeholderEntry);
    const dirs = getAllHiddenDirs();
    for (const d of dirs) WS.nav.entries.push({ kind: "dir", node: d });
    return;
  }

  const dirNode = WS.nav.dirNode;
  if (!dirNode) return;

  if (includeGridUpEntry) WS.nav.entries.push(buildGridUpDirectoryEntry());

  const rootTrashEntry = shouldShowRootTrashEntry(dirNode)
    ? buildRootTrashDirEntry()
    : null;
  if (rootTrashEntry) WS.nav.entries.push(rootTrashEntry);

  const tagEntries = getTagFolderEntries();
  if (tagEntries.length) {
    for (const entry of tagEntries) WS.nav.entries.push(entry);
  }

  const dirs = getChildDirsForNode(dirNode);
  for (const d of dirs) WS.nav.entries.push({ kind: "dir", node: d });

  const baseFiles = getOrderedFileIdsForDir(dirNode);
  for (const id of baseFiles) WS.nav.entries.push({ kind: "file", id });
}

function isSelectableEntry(entry) {
  return (
    entry &&
    (entry.kind === "dir" ||
      entry.kind === "file" ||
      entry.kind === "tag" ||
      entry.kind === "up")
  );
}

function findNearestSelectableIndex(idx, direction) {
  if (!WS.nav.entries.length) return 0;
  let i = Math.max(0, Math.min(WS.nav.entries.length - 1, idx));
  if (isSelectableEntry(WS.nav.entries[i])) return i;
  const step = direction >= 0 ? 1 : -1;
  let j = i;
  while (j >= 0 && j < WS.nav.entries.length) {
    if (isSelectableEntry(WS.nav.entries[j])) return j;
    j += step;
  }
  j = i - step;
  while (j >= 0 && j < WS.nav.entries.length) {
    if (isSelectableEntry(WS.nav.entries[j])) return j;
    j -= step;
  }
  return i;
}

function findDirEntryIndexByPath(path) {
  const p = String(path || "");
  if (!p) return -1;
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (entry && entry.kind === "dir" && String(entry.node?.path || "") === p)
      return i;
  }
  return -1;
}

// USER NOTE (DO NOT CASUALLY CHANGE):
// This shared centering routine is the stable path for both folder and file selection scroll behavior.
// Regressions here have repeatedly caused major frustration ("super pissed off"). If modified, manually
// test keyboard selection in folder lists and file-only folders before shipping.
function updateGridModeListTopInset() {
  const appEl = $("app");
  const titlePaneEl = $("titlePane");
  if (!appEl) return;
  if (titlePaneEl && titlePaneEl.getBoundingClientRect) {
    const titleH = Math.max(
      0,
      Math.ceil(titlePaneEl.getBoundingClientRect().height || 0),
    );
    if (titleH > 0) appEl.style.setProperty("--title-pane-h", `${titleH}px`);
    else appEl.style.removeProperty("--title-pane-h");
  } else {
    appEl.style.removeProperty("--title-pane-h");
  }
}

function getDirectoryViewportRange(container) {
  const view = container || directoriesListEl;
  if (!view) {
    return {
      topInset: 0,
      viewTop: 0,
      viewBottom: 0,
      viewHeight: 0,
    };
  }

  const topInset = 0;

  const viewTop = (view.scrollTop || 0) + topInset;
  const viewHeight = Math.max(1, (view.clientHeight || 1) - topInset);
  return {
    topInset,
    viewTop,
    viewBottom: viewTop + viewHeight,
    viewHeight,
  };
}

function isGridTopRowSelection(container, selectedRow) {
  if (
    !container ||
    !selectedRow ||
    !container.classList ||
    !container.classList.contains("gridModeList")
  )
    return false;
  const rows = container.querySelectorAll(".dirRow");
  if (!rows || !rows.length) return false;
  let minTop = Number.POSITIVE_INFINITY;
  for (let i = 0; i < rows.length; i++) {
    const t = Number(rows[i].offsetTop) || 0;
    if (t < minTop) minTop = t;
  }
  if (!Number.isFinite(minTop)) return false;
  const selectedTop = Number(selectedRow.offsetTop) || 0;
  return selectedTop <= minTop + 2;
}

function centerSelectedDirectoryRow(
  deferFrames = 0,
  lockRowCenterOffset = null,
) {
  const schedule = (frames) => {
    if (frames <= 0) {
      const container = directoriesListEl;
      const selectedRow = container
        ? container.querySelector(".dirRow.selected")
        : null;
      if (!container || !selectedRow) return;
      const rowMid = selectedRow.offsetTop + selectedRow.offsetHeight * 0.5;
      const viewport = getDirectoryViewportRange(container);
      const desiredMid = Number.isFinite(lockRowCenterOffset)
        ? Number(lockRowCenterOffset)
        : viewport.topInset + viewport.viewHeight * 0.5;
      const target = rowMid - desiredMid;
      const maxScroll = Math.max(
        0,
        container.scrollHeight - container.clientHeight,
      );
      WS.view.scrollBusyDirs = true;
      container.scrollTop = Math.max(0, Math.min(maxScroll, target));
      requestAnimationFrame(() => {
        WS.view.scrollBusyDirs = false;
      });
      return;
    }
    requestAnimationFrame(() => schedule(frames - 1));
  };
  schedule(Math.max(0, deferFrames | 0));
}

function getSelectedDirectoryRowVisibility() {
  const container = directoriesListEl;
  const selectedRow = container
    ? container.querySelector(".dirRow.selected")
    : null;
  if (!container || !selectedRow)
    return { state: "missing", container: null, row: null };
  const viewport = getDirectoryViewportRange(container);
  const viewTop = viewport.viewTop;
  const viewBottom = viewport.viewBottom;
  const rowTop = selectedRow.offsetTop;
  const rowBottom = rowTop + selectedRow.offsetHeight;
  if (rowBottom <= viewTop || rowTop >= viewBottom) {
    return {
      state: "offscreen",
      container,
      row: selectedRow,
      rowTop,
      rowBottom,
      viewTop,
      viewBottom,
    };
  }
  if (rowTop < viewTop || rowBottom > viewBottom) {
    return {
      state: "partial",
      container,
      row: selectedRow,
      rowTop,
      rowBottom,
      viewTop,
      viewBottom,
    };
  }
  return {
    state: "visible",
    container,
    row: selectedRow,
    rowTop,
    rowBottom,
    viewTop,
    viewBottom,
  };
}

function snapSelectedDirectoryRowFullyIntoView() {
  const vis = getSelectedDirectoryRowVisibility();
  if (
    (vis.state !== "partial" && vis.state !== "offscreen") ||
    !vis.container
  )
    return;
  const { container, row, rowTop, rowBottom, viewTop, viewBottom } = vis;
  const viewport = getDirectoryViewportRange(container);
  const rowHeight = Math.max(0, rowBottom - rowTop);
  let target = container.scrollTop;
  if (isGridTopRowSelection(container, row)) {
    target = 0;
  } else if (rowHeight >= viewport.viewHeight) {
    target = rowTop - viewport.topInset;
  } else if (rowTop < viewTop) {
    target = rowTop - viewport.topInset;
  } else if (rowBottom > viewBottom) {
    target = rowBottom - container.clientHeight;
  }
  const maxScroll = Math.max(
    0,
    container.scrollHeight - container.clientHeight,
  );
  const nextScroll = Math.max(0, Math.min(maxScroll, target));
  WS.view.scrollBusyDirs = true;
  container.scrollTop = nextScroll;
  requestAnimationFrame(() => {
    WS.view.scrollBusyDirs = false;
  });
}

function revealSelectedDirectoryRowInGridMode(center = false) {
  if (!directoriesListEl) return;
  const selectedRow = directoriesListEl.querySelector(".dirRow.selected");
  if (!selectedRow) return;
  WS.view.scrollBusyDirs = true;
  const container = directoriesListEl;
  const viewport = getDirectoryViewportRange(container);
  const rowTop = selectedRow.offsetTop;
  const rowBottom = rowTop + selectedRow.offsetHeight;
  const rowLeft = selectedRow.offsetLeft;
  const rowRight = rowLeft + selectedRow.offsetWidth;

  const viewTop = viewport.viewTop;
  const viewBottom = viewport.viewBottom;
  const viewLeft = container.scrollLeft;
  const viewRight = viewLeft + container.clientWidth;

  let nextTop = viewTop;
  let nextLeft = viewLeft;

  if (center) {
    const rowMid = rowTop + selectedRow.offsetHeight * 0.5;
    nextTop = rowMid - (viewport.topInset + viewport.viewHeight * 0.5);
  } else {
    if (isGridTopRowSelection(container, selectedRow)) {
      nextTop = 0;
    } else if (rowTop < viewTop) nextTop = rowTop - viewport.topInset;
    else if (rowBottom > viewBottom)
      nextTop = rowBottom - container.clientHeight;
  }

  if (rowLeft < viewLeft) nextLeft = rowLeft;
  else if (rowRight > viewRight) nextLeft = rowRight - container.clientWidth;

  const maxTop = Math.max(0, container.scrollHeight - container.clientHeight);
  const maxLeft = Math.max(0, container.scrollWidth - container.clientWidth);
  container.scrollTop = Math.max(0, Math.min(maxTop, nextTop));
  container.scrollLeft = Math.max(0, Math.min(maxLeft, nextLeft));
  requestAnimationFrame(() => {
    WS.view.scrollBusyDirs = false;
  });
}

function canUseFastGridSelectionUpdate() {
  if (!isGridInteractionMode()) return false;
  if (
    !directoriesListEl ||
    !directoriesListEl.classList.contains("gridModeList")
  )
    return false;
  if (
    WS.view.bulkActionMenuOpen ||
    WS.view.dirActionMenuPath ||
    WS.view.fileActionMenuId
  )
    return false;
  if (
    TAG_EDIT_PATH ||
    RENAME_EDIT_PATH ||
    RENAME_EDIT_FILE_ID ||
    TAG_ENTRY_RENAME_STATE
  )
    return false;
  if (WS.view.bulkSelectMode) return false;
  if (
    directoriesActionMenuEl &&
    directoriesActionMenuEl.classList.contains("open")
  )
    return false;
  if (directoriesListEl.querySelector(".dropdownMenu.open")) return false;
  if (directoriesListEl.querySelector(".dirRow.bulkSelected")) return false;
  return true;
}

function fastUpdateGridSelectedRow(prevIdx, nextIdx) {
  if (!directoriesListEl) return false;
  const nextRow = directoriesListEl.querySelector(
    `.dirRow[data-entry-index="${String(nextIdx)}"]`,
  );
  if (!nextRow) return false;
  const selectedRows = directoriesListEl.querySelectorAll(".dirRow.selected");
  if (selectedRows && selectedRows.length) {
    selectedRows.forEach((row) => {
      if (row && row !== nextRow) row.classList.remove("selected");
    });
  }
  nextRow.classList.add("selected");
  return true;
}

function canUseFastPaneSelectionUpdate(hadTransientUi) {
  if (isGridInteractionMode()) return false;
  if (
    !directoriesListEl ||
    directoriesListEl.classList.contains("gridModeList")
  )
    return false;
  if (busyOverlay && busyOverlay.classList.contains("active")) return false;
  if (hadTransientUi) return false;
  if (WS.view.bulkSelectMode) return false;
  return true;
}

function fastUpdatePaneSelectedRow(prevIdx, nextIdx) {
  if (!directoriesListEl) return false;
  const nextRow = directoriesListEl.querySelector(
    `.dirRow[data-entry-index="${String(nextIdx)}"]`,
  );
  if (!nextRow) return false;
  const selectedRows = directoriesListEl.querySelectorAll(".dirRow.selected");
  if (selectedRows && selectedRows.length) {
    selectedRows.forEach((row) => {
      if (row && row !== nextRow) row.classList.remove("selected");
    });
  }
  nextRow.classList.add("selected");
  return true;
}

let PREVIEW_SELECTION_RENDER_RAF = 0;
function schedulePreviewRenderForSelection() {
  if (PREVIEW_SELECTION_RENDER_RAF) {
    try {
      cancelAnimationFrame(PREVIEW_SELECTION_RENDER_RAF);
    } catch {}
    PREVIEW_SELECTION_RENDER_RAF = 0;
  }
  PREVIEW_SELECTION_RENDER_RAF = requestAnimationFrame(() => {
    PREVIEW_SELECTION_RENDER_RAF = 0;
    renderPreviewPane(false);
    kickVideoThumbsForPreview();
    kickImageThumbsForPreview();
  });
}

function reconcileSelectedDirectoryRowVisibility(
  preferCenter = false,
  forceCenter = false,
) {
  if (forceCenter) {
    centerSelectedDirectoryRow(0);
    return;
  }
  const vis = getSelectedDirectoryRowVisibility();
  if (vis.state === "offscreen" || vis.state === "partial") {
    if (preferCenter) centerSelectedDirectoryRow(0);
    else snapSelectedDirectoryRowFullyIntoView();
  }
}

let DIR_SELECTION_RECONCILE_RAF = 0;
let DIR_SELECTION_RECONCILE_TIMER = 0;
function scheduleSelectedDirectoryRowReconcile(
  delayedMs = 0,
  preferCenter = false,
  forceCenter = false,
) {
  if (DIR_SELECTION_RECONCILE_RAF) {
    try {
      cancelAnimationFrame(DIR_SELECTION_RECONCILE_RAF);
    } catch {}
    DIR_SELECTION_RECONCILE_RAF = 0;
  }
  if (DIR_SELECTION_RECONCILE_TIMER) {
    try {
      clearTimeout(DIR_SELECTION_RECONCILE_TIMER);
    } catch {}
    DIR_SELECTION_RECONCILE_TIMER = 0;
  }
  DIR_SELECTION_RECONCILE_RAF = requestAnimationFrame(() => {
    DIR_SELECTION_RECONCILE_RAF = 0;
    reconcileSelectedDirectoryRowVisibility(preferCenter, forceCenter);
  });
  if (delayedMs > 0) {
    DIR_SELECTION_RECONCILE_TIMER = setTimeout(() => {
      DIR_SELECTION_RECONCILE_TIMER = 0;
      reconcileSelectedDirectoryRowVisibility(preferCenter, forceCenter);
    }, delayedMs);
  }
}

function syncDirectoriesSelectionToFileRecord(rec, opts = null) {
  if (!rec || !WS.root) return null;
  const options = opts && typeof opts === "object" ? opts : {};
  const p = String(rec.dirPath || "");
  const dn = WS.dirByPath.get(p) || WS.nav.dirNode || WS.root;
  if (!dn) return null;

  TAG_EDIT_PATH = null;
  clearBulkTagPlaceholder();

  if (isViewingTagFolder()) {
    pushTagViewContext(dn.path || "");
    WS.view.tagFolderActiveMode = "";
    WS.view.tagFolderActiveTag = "";
    WS.view.tagFolderActiveAlbum = "";
    WS.view.tagFolderOriginPath = "";
  }

  if (searchResultsVisibleInDirectoriesPane()) {
    enterSearchResultContext(dn.path || "");
  }
  if (WS.view.favoritesMode && WS.view.favoritesRootActive) {
    WS.view.favoritesRootActive = false;
    WS.view.favoritesAnchorPath = dn.path || "";
  }
  if (WS.view.hiddenMode && WS.view.hiddenRootActive) {
    WS.view.hiddenRootActive = false;
    WS.view.hiddenAnchorPath = dn.path || "";
  }

  WS.nav.dirNode = dn;
  WS.view.aboveRootView = false;
  syncBulkSelectionForCurrentDir();
  syncFavoritesUi();
  syncHiddenUi();
  syncTagUiForCurrentDir();
  rebuildDirectoriesEntries();

  let idx = -1;
  const targetId = String(rec.id || "");
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const e = WS.nav.entries[i];
    if (e && e.kind === "file" && String(e.id || "") === targetId) {
      idx = i;
      break;
    }
  }
  WS.nav.selectedIndex = findNearestSelectableIndex(idx >= 0 ? idx : 0, 1);
  saveGridSelectionForCurrentContext();
  if (options.syncPreview !== false) syncPreviewToSelection({ force: true });
  if (options.pendingDirScroll !== false) {
    WS.view.pendingDirScroll =
      String(options.pendingDirScrollMode || "center-selected") ||
      "center-selected";
  }
  renderDirectoriesPane(!!options.keepDirectoriesScroll);
  if (options.renderPreview !== false) {
    renderPreviewPane(
      options.animatePreview !== false,
      options.keepPreviewScroll !== false,
    );
  }
  syncButtons();
  if (options.renderPreview !== false) {
    kickVideoThumbsForPreview();
    kickImageThumbsForPreview();
  }
  if (options.recordHistory !== false) recordDirHistory();
  return {
    dirNode: dn,
    selectedIndex: WS.nav.selectedIndex,
  };
}

function setDirectoriesSelection(idx, opts = null) {
  const keepScroll = !!(opts && opts.keepScroll);
  WS.view.previewFolderBridgeReturnState = null;
  clearPreviewQuickNavigationState();
  if (!WS.nav.entries.length) {
    WS.nav.selectedIndex = 0;
    setActivePane(directoriesPaneOpenEnabled() ? "directories" : "preview");
    applyPreviewState(null);
    renderDirectoriesPane();
    renderPreviewPane(true);
    syncButtons();
    return;
  }
  const hadTransientUi = !!(
    WS.view.bulkActionMenuOpen ||
    WS.view.dirActionMenuPath ||
    WS.view.fileActionMenuId ||
    TAG_EDIT_PATH ||
    RENAME_EDIT_PATH ||
    RENAME_EDIT_FILE_ID ||
    TAG_ENTRY_RENAME_STATE
  );
  closeActionMenus();
  const prevIdx = WS.nav.selectedIndex;
  const i = findNearestSelectableIndex(
    idx,
    idx >= WS.nav.selectedIndex ? 1 : -1,
  );
  WS.nav.selectedIndex = i;
  if (directoriesPaneOpenEnabled()) setActivePane("directories");
  saveGridSelectionForCurrentContext();
  syncPreviewToSelection({ force: true });
  const snapshot = currentNavigationSnapshot();
  scheduleNearbyDirectoryRamWarm(snapshot);

  if (
    canUseFastGridSelectionUpdate() &&
    fastUpdateGridSelectedRow(prevIdx, i)
  ) {
    const shouldCenter = WS.view.pendingDirScroll === "center-selected";
    const shouldGridReveal = WS.view.pendingDirScroll === "grid-nearest";
    if (shouldCenter || shouldGridReveal) WS.view.pendingDirScroll = "";
    if (shouldCenter) revealSelectedDirectoryRowInGridMode(true);
    else if (shouldGridReveal) revealSelectedDirectoryRowInGridMode(false);
    else scheduleSelectedDirectoryRowReconcile(0, false, false);
    syncButtons();
    return;
  }

  if (
    canUseFastPaneSelectionUpdate(hadTransientUi) &&
    fastUpdatePaneSelectedRow(prevIdx, i)
  ) {
    const shouldCenter = WS.view.pendingDirScroll === "center-selected";
    if (shouldCenter) WS.view.pendingDirScroll = "";
    if (shouldCenter) centerSelectedDirectoryRow(0);
    else scheduleSelectedDirectoryRowReconcile(0, false, false);
    schedulePreviewRenderForSelection();
    syncButtons();
    return;
  }

  renderDirectoriesPane(keepScroll);
  renderPreviewPane(false);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
}

async function returnToSearchResults() {
  const currentPath = String(WS.nav.dirNode?.path || "");
  const currentIsSearchResult =
    !!currentPath &&
    Array.isArray(WS.view.searchResults) &&
    WS.view.searchResults.some(
      (node) => String(node?.path || "") === currentPath,
    );
  const target = String(
    currentIsSearchResult ? currentPath : currentSearchResultPath(),
  );
  WS.view.searchRootActive = true;
  WS.view.searchAnchorPath = target;
  WS.view.searchEntryRootPath = target;
  if (searchResultsVisibleInPreviewPane()) {
    const searchRootNode =
      WS.dirByPath.get(String(WS.view.searchRootPath || "")) || null;
    const parentNode = searchRootNode
      ? searchRootNode.parent || searchRootNode || WS.root
      : WS.nav.dirNode || WS.root;
    if (parentNode) {
      WS.nav.dirNode = parentNode;
      WS.view.aboveRootView = false;
      syncBulkSelectionForCurrentDir();
      syncFavoritesUi();
      syncHiddenUi();
      syncTagUiForCurrentDir();
      rebuildDirectoriesEntries();
      const rootPath = String(searchRootNode?.path || "");
      const rootIdx = rootPath ? findDirEntryIndexByPath(rootPath) : -1;
      WS.nav.selectedIndex = findNearestSelectableIndex(
        rootIdx >= 0 ? rootIdx : 0,
        1,
      );
      syncPreviewToSelection({ force: true });
    }
    WS.view.pendingPreviewSelectionKey = target ? `dir:${target}` : "";
    setActivePane("preview");
    await finalizeDirectoryNavigationRender({
      animatePreview: true,
      keepDirectoriesScroll: true,
      recordHistory: true,
    });
    return;
  }
  rebuildDirectoriesEntries();
  const idx = target ? findDirEntryIndexByPath(target) : -1;
  WS.nav.selectedIndex = findNearestSelectableIndex(idx >= 0 ? idx : 0, 1);
  syncPreviewToSelection({ force: true });
  await finalizeDirectoryNavigationRender({
    animatePreview: true,
    recordHistory: true,
  });
}

function previewTargetStillResolvable() {
  if (!WS.preview || !WS.preview.kind) return false;
  if (WS.preview.kind === "file" && WS.preview.fileId) {
    return !!WS.fileById.get(String(WS.preview.fileId || ""));
  }
  if (WS.preview.kind === "dir" && WS.preview.dirNode) {
    if (WS.preview.dirNode === WS.root) return true;
    const previewPath = String(WS.preview.dirNode.path || "");
    if (!previewPath) return !!WS.preview.dirNode;
    return !!(
      WS.dirByPath.get(previewPath) || WS.preview.dirNode._skipTagFilters
    );
  }
  return false;
}

function preserveActivePreviewTargetDuringDirectoriesRefresh() {
  if (
    directoriesPaneOpenEnabled() &&
    WS.view?.activePane === "preview" &&
    previewTargetStillResolvable()
  ) {
    return false;
  }
  syncPreviewToSelection();
  return true;
}

function syncPreviewToSelection(opts = null) {
  const force = !!(opts && opts.force);
  if (
    !force &&
    directoriesPaneOpenEnabled() &&
    WS.view &&
    WS.view.activePane === "preview" &&
    previewTargetStillResolvable()
  ) {
    return false;
  }
  const entry = WS.nav.entries[WS.nav.selectedIndex] || null;
  applyPreviewState(previewStateForEntry(entry));
  return true;
}

function currentPreviewSelectionContextKeyFromState(state = null) {
  const src = state && typeof state === "object" ? state : WS.preview;
  if (!src || !src.kind) return "none";
  if (src.kind === "dir" && src.dirNode)
    return `dir:${String(src.dirNode.path || "")}`;
  if (src.kind === "file" && src.fileId)
    return `file:${String(src.fileId || "")}`;
  return "none";
}

function clearPreviewSelectionState(contextKey = null) {
  if (!WS.view) return;
  WS.view.previewSelectAnchorKey = "";
  WS.view.previewSelectedKey = "";
  WS.view.previewSelectionContextKey = String(
    contextKey || currentPreviewSelectionContextKeyFromState() || "none",
  );
}

function applyPendingPreviewSelectionForCurrentTarget() {
  if (!WS.view) return false;
  const nextKey = String(WS.view.pendingPreviewSelectionKey || "");
  if (!nextKey) return false;
  if (nextKey.startsWith("file:")) {
    revealPendingPreviewSelectionInVirtualGrid(nextKey);
  }
  const card = findPreviewSelectableCardByKey(nextKey);
  if (!card) return false;
  WS.view.pendingPreviewSelectionKey = "";
  WS.view.previewSelectionContextKey =
    currentPreviewSelectionContextKeyFromState();
  WS.view.previewSelectedKey = nextKey;
  return true;
}

function notePreviewTargetChanged(nextState = null) {
  bumpThumbnailDemandToken();
  clearPreviewSelectionState(
    currentPreviewSelectionContextKeyFromState(nextState),
  );
  if (!directoriesPaneOpenEnabled()) {
    setActivePane("preview");
  } else if (
    WS.view.activePane !== "directories" &&
    WS.view.activePane !== "preview"
  ) {
    setActivePane("directories");
  }
  updateTitleLabel();
}

function getPreviewSelectableCards() {
  if (!previewBodyEl) return [];
  return Array.from(previewBodyEl.querySelectorAll("[data-preview-item-key]"));
}

function getPreviewCardRelativeRect(card) {
  if (!card || !previewBodyEl || !card.getBoundingClientRect) return null;
  const containerRect = previewBodyEl.getBoundingClientRect();
  const rect = card.getBoundingClientRect();
  const width = Number(rect.width || 0);
  const height = Number(rect.height || 0);
  if (width <= 0 || height <= 0) return null;
  const left = rect.left - containerRect.left + (previewBodyEl.scrollLeft || 0);
  const top = rect.top - containerRect.top + (previewBodyEl.scrollTop || 0);
  return {
    left,
    top,
    right: left + width,
    bottom: top + height,
    width,
    height,
  };
}

function getPreviewSelectableCardMetrics() {
  if (!previewBodyEl) return [];
  const cards = getPreviewSelectableCards();
  const out = [];
  for (let i = 0; i < cards.length; i++) {
    const card = cards[i];
    const key = String(card?.dataset?.previewItemKey || "");
    const rect = getPreviewCardRelativeRect(card);
    if (!key || !rect) continue;
    out.push({
      key,
      card,
      cx: rect.left + rect.width * 0.5,
      cy: rect.top + rect.height * 0.5,
    });
  }
  return out;
}

function cssEscapeValue(value) {
  const raw = String(value || "");
  if (typeof CSS !== "undefined" && CSS && typeof CSS.escape === "function") {
    return CSS.escape(raw);
  }
  return raw.replace(/["\\]/g, "\\$&");
}

function findPreviewSelectableCardByKey(key) {
  const targetKey = String(key || "");
  if (!targetKey || !previewBodyEl) return null;
  return previewBodyEl.querySelector(
    `[data-preview-item-key="${cssEscapeValue(targetKey)}"]`,
  );
}

function findSelectedPreviewCard() {
  return findPreviewSelectableCardByKey(WS.view && WS.view.previewSelectedKey);
}

function findFirstVisiblePreviewCard() {
  if (!previewBodyEl) return null;
  const cards = getPreviewSelectableCards();
  if (!cards.length) return null;
  const viewTop = Math.max(0, Number(previewBodyEl.scrollTop) || 0);
  const viewLeft = Math.max(0, Number(previewBodyEl.scrollLeft) || 0);
  const viewBottom =
    viewTop + Math.max(1, Number(previewBodyEl.clientHeight) || 1);
  const viewRight =
    viewLeft + Math.max(1, Number(previewBodyEl.clientWidth) || 1);
  let bestFully = null;
  let bestPartial = null;
  for (let i = 0; i < cards.length; i++) {
    const card = cards[i];
    const rect = getPreviewCardRelativeRect(card);
    if (!rect) continue;
    const intersects =
      rect.bottom > viewTop + 1 &&
      rect.top < viewBottom - 1 &&
      rect.right > viewLeft + 1 &&
      rect.left < viewRight - 1;
    if (!intersects) continue;
    const fullyVisible =
      rect.top >= viewTop + 1 &&
      rect.bottom <= viewBottom - 1 &&
      rect.left >= viewLeft + 1 &&
      rect.right <= viewRight - 1;
    const score = rect.top * 100000 + rect.left;
    if (fullyVisible) {
      if (!bestFully || score < bestFully.score) bestFully = { card, score };
    } else if (!bestPartial || score < bestPartial.score) {
      bestPartial = { card, score };
    }
  }
  return (
    (bestFully && bestFully.card) ||
    (bestPartial && bestPartial.card) ||
    cards[0] ||
    null
  );
}

function isPreviewTopRowCard(card) {
  if (!card || !previewBodyEl) return false;
  const cards = getPreviewSelectableCards();
  if (!cards.length) return false;
  let minTop = Number.POSITIVE_INFINITY;
  for (let i = 0; i < cards.length; i++) {
    const rect = getPreviewCardRelativeRect(cards[i]);
    if (!rect) continue;
    if (rect.top < minTop) minTop = rect.top;
  }
  if (!Number.isFinite(minTop)) return false;
  const rect = getPreviewCardRelativeRect(card);
  if (!rect) return false;
  return rect.top <= minTop + 2;
}

function revealPreviewCard(card = null) {
  const target = card || findSelectedPreviewCard();
  const rect = getPreviewCardRelativeRect(target);
  if (!target || !previewBodyEl || !rect) return;
  const maxTop = Math.max(
    0,
    previewBodyEl.scrollHeight - previewBodyEl.clientHeight,
  );
  const maxLeft = Math.max(
    0,
    previewBodyEl.scrollWidth - previewBodyEl.clientWidth,
  );
  const viewTop = Math.max(0, Number(previewBodyEl.scrollTop) || 0);
  const viewLeft = Math.max(0, Number(previewBodyEl.scrollLeft) || 0);
  const viewBottom =
    viewTop + Math.max(1, Number(previewBodyEl.clientHeight) || 1);
  const viewRight =
    viewLeft + Math.max(1, Number(previewBodyEl.clientWidth) || 1);
  let nextTop = viewTop;
  let nextLeft = viewLeft;
  if (isPreviewTopRowCard(target)) nextTop = 0;
  else if (rect.top < viewTop) nextTop = rect.top;
  else if (rect.bottom > viewBottom)
    nextTop = rect.bottom - previewBodyEl.clientHeight;
  if (rect.left < viewLeft) nextLeft = rect.left;
  else if (rect.right > viewRight)
    nextLeft = rect.right - previewBodyEl.clientWidth;
  previewBodyEl.scrollTop = Math.max(0, Math.min(maxTop, nextTop));
  previewBodyEl.scrollLeft = Math.max(0, Math.min(maxLeft, nextLeft));
}

function updatePreviewSelectionClasses() {
  const activeKey = String((WS.view && WS.view.previewSelectedKey) || "");
  const previewActive = !!(WS.view && WS.view.activePane === "preview");
  syncActivePaneWithLayout();
  const cards = getPreviewSelectableCards();
  for (let i = 0; i < cards.length; i++) {
    const card = cards[i];
    const kind = String(card?.dataset?.previewItemKind || "");
    const key = String(card?.dataset?.previewItemKey || "");
    const selected = String(card?.dataset?.previewItemKey || "") === activeKey;
    let bulkSelected = false;
    if (kind === "dir" && key.startsWith("dir:")) {
      bulkSelected = WS.view.bulkTagSelectedPaths.has(key.slice(4));
    } else if (kind === "file" && key.startsWith("file:")) {
      bulkSelected = WS.view.bulkFileSelectedIds.has(key.slice(5));
    } else if (kind === "tag" && key.startsWith("tag:")) {
      bulkSelected = WS.view.bulkTagFolderSelectedKeys.has(key.slice(4));
    }
    card.classList.toggle("bulkSelected", bulkSelected);
    card.classList.toggle("previewSelected", selected && previewActive);
  }
}

function ensurePreviewSelectionForCurrentTarget(reset = false) {
  const contextKey = currentPreviewSelectionContextKeyFromState();
  const cards = getPreviewSelectableCards();
  if (!cards.length) {
    clearPreviewSelectionState(contextKey);
    updatePreviewSelectionClasses();
    return false;
  }
  if (
    reset ||
    String((WS.view && WS.view.previewSelectionContextKey) || "") !== contextKey
  ) {
    clearPreviewSelectionState(contextKey);
  }
  let key = String((WS.view && WS.view.previewSelectedKey) || "");
  let selectedCard = key
    ? cards.find((card) => String(card?.dataset?.previewItemKey || "") === key)
    : null;
  if (!selectedCard) {
    const shouldRespectScroll =
      !!previewBodyEl &&
      ((previewBodyEl.scrollTop || 0) > 0 ||
        (previewBodyEl.scrollLeft || 0) > 0);
    selectedCard = shouldRespectScroll
      ? findFirstVisiblePreviewCard() || cards[0]
      : cards[0];
    key = String(selectedCard?.dataset?.previewItemKey || "");
  }
  WS.view.previewSelectionContextKey = contextKey;
  WS.view.previewSelectedKey = key;
  updatePreviewSelectionClasses();
  return !!selectedCard;
}

function setPreviewSelectionKey(key, opts = null) {
  const nextKey = String(key || "");
  if (!nextKey) return false;
  const card = findPreviewSelectableCardByKey(nextKey);
  if (!card) return false;
  if (WS.view) {
    WS.view.previewSelectionContextKey =
      currentPreviewSelectionContextKeyFromState();
    WS.view.previewSelectedKey = nextKey;
    if (!(opts && opts.activate === false)) setActivePane("preview");
  }
  updatePreviewSelectionClasses();
  if (!(opts && opts.skipReveal)) revealPreviewCard(card);
  return true;
}

function activatePreviewPaneSelection() {
  setActivePane("preview");
  syncActivePaneWithLayout();
  const hasSelection = ensurePreviewSelectionForCurrentTarget(false);
  updatePreviewSelectionClasses();
  if (hasSelection) revealPreviewCard();
  return true;
}

function resetPreviewPaneForEnteredTarget() {
  if (!WS.view) return;
  WS.view.pendingPreviewSelectionKey = "";
  const dirNode = getPreviewTargetDir();
  const dirKey = previewScrollKeyForDir(dirNode);
  if (dirKey && WS.view.previewScrollByDir instanceof Map) {
    WS.view.previewScrollByDir.delete(dirKey);
  }
  if (previewBodyEl) {
    previewBodyEl.scrollTop = 0;
    previewBodyEl.scrollLeft = 0;
  }
  clearPreviewSelectionState(currentPreviewSelectionContextKeyFromState());
}

function activateDirectoriesPaneSelection() {
  if (!directoriesPaneOpenEnabled()) return false;
  setActivePane("directories");
  updatePreviewSelectionClasses();
  return true;
}

function movePreviewSelectionByDirection(direction) {
  if (!ensurePreviewSelectionForCurrentTarget(false)) return false;
  const metrics = getPreviewSelectableCardMetrics();
  if (!metrics.length) return false;
  const activeKey = String((WS.view && WS.view.previewSelectedKey) || "");
  const selected = metrics.find((m) => m.key === activeKey) || metrics[0];
  if (!selected) return false;

  let best = null;
  let bestScore = Number.POSITIVE_INFINITY;
  for (let i = 0; i < metrics.length; i++) {
    const m = metrics[i];
    if (!m || m.key === selected.key) continue;
    const dx = m.cx - selected.cx;
    const dy = m.cy - selected.cy;
    const ax = Math.abs(dx);
    const ay = Math.abs(dy);
    let primary = 0;
    let secondary = 0;
    let valid = false;
    if (direction === "up" && dy < -2) {
      valid = true;
      primary = -dy;
      secondary = ax;
    } else if (direction === "down" && dy > 2) {
      valid = true;
      primary = dy;
      secondary = ax;
    } else if (direction === "left" && dx < -2) {
      valid = true;
      primary = -dx;
      secondary = ay;
    } else if (direction === "right" && dx > 2) {
      valid = true;
      primary = dx;
      secondary = ay;
    }
    if (!valid) continue;
    const score = primary * 1000 + secondary;
    if (score < bestScore) {
      bestScore = score;
      best = m;
    }
  }
  if (!best) return false;
  return setPreviewSelectionKey(best.key, { activate: true });
}

function movePreviewSelectionAcrossFolderEdge(step) {
  if (!WS.root) return false;
  const selectedKey = String((WS.view && WS.view.previewSelectedKey) || "");
  if (!selectedKey.startsWith("file:")) return false;
  const selectedFileId = String(selectedKey.slice(5) || "");
  if (!selectedFileId) return false;
  const targetDir = getPreviewTargetDir();
  if (!targetDir || targetDir._skipTagFilters) return false;
  const navPath = String(WS.nav.dirNode?.path || "");
  const targetPath = String(targetDir.path || "");
  if (navPath !== targetPath) return false;
  const selectedIdx = findFileEntryIndexById(selectedFileId);
  if (selectedIdx < 0) return false;
  WS.nav.selectedIndex = findNearestSelectableIndex(selectedIdx, 1);
  const slide = slideStepFileInternal(step < 0 ? -1 : 1);
  if (!slide.moved) return false;
  renderDirectoriesPane(true);
  renderPreviewPane(!!slide.dirChanged, true);
  if (WS.view.activePane === "preview") activatePreviewPaneSelection();
  else updatePreviewSelectionClasses();
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  return true;
}

function openSelectedPreviewItem() {
  const card = findSelectedPreviewCard();
  const openAction =
    card && typeof card.__previewOpenAction === "function"
      ? card.__previewOpenAction
      : null;
  if (!openAction) return false;
  openAction();
  return true;
}

function handlePreviewCardSelection(card, openAction, e = null) {
  if (!card) return;
  const key = String(card.dataset.previewItemKey || "");
  if (!key) return;
  const priorSelectedKey = String(WS.view.previewSelectedKey || "");
  const isCmdOrCtrl = eventCmdOrCtrlHeld(e);
  const isShift = eventShiftHeld(e);

  if (isShift && isCmdOrCtrl) {
    const anchorKey = String(
      WS.view.previewSelectAnchorKey || priorSelectedKey || key,
    );
    if (!WS.view.bulkSelectMode) {
      const selectedCard = findSelectedPreviewCard();
      if (
        selectedCard &&
        String(selectedCard.dataset.previewItemKey || "") !== key
      ) {
        addPreviewCardBulkSelection(selectedCard);
      }
    }
    addPreviewSelectionRange(anchorKey, key, false);
    WS.view.previewSelectAnchorKey = key;
    setPreviewSelectionKey(key, { activate: true });
    refreshBulkSelectionUiFromPreview();
    return;
  }

  if (isShift) {
    const anchorKey = String(
      WS.view.previewSelectAnchorKey || priorSelectedKey || key,
    );
    addPreviewSelectionRange(anchorKey, key, true);
    WS.view.previewSelectAnchorKey = key;
    setPreviewSelectionKey(key, { activate: true });
    refreshBulkSelectionUiFromPreview();
    return;
  }

  if (isCmdOrCtrl) {
    if (!WS.view.bulkSelectMode) {
      const selectedCard = findSelectedPreviewCard();
      if (
        selectedCard &&
        String(selectedCard.dataset.previewItemKey || "") !== key
      ) {
        addPreviewCardBulkSelection(selectedCard);
      }
    }
    WS.view.bulkSelectMode = true;
    togglePreviewCardBulkSelection(card);
    if (
      !WS.view.bulkTagSelectedPaths.size &&
      !WS.view.bulkTagFolderSelectedKeys.size &&
      !WS.view.bulkFileSelectedIds.size
    ) {
      WS.view.bulkSelectMode = false;
    }
    WS.view.previewSelectAnchorKey = key;
    setPreviewSelectionKey(key, { activate: true });
    refreshBulkSelectionUiFromPreview();
    return;
  }

  const hadBulkSelection =
    WS.view.bulkSelectMode &&
    (WS.view.bulkTagSelectedPaths.size ||
      WS.view.bulkTagFolderSelectedKeys.size ||
      WS.view.bulkFileSelectedIds.size);
  const shouldOpen = !!key && priorSelectedKey === key && !hadBulkSelection;
  if (hadBulkSelection) {
    clearBulkTagSelection();
    WS.view.bulkSelectMode = false;
  }
  WS.view.previewSelectAnchorKey = key;
  setPreviewSelectionKey(key, { activate: true });
  if (hadBulkSelection) refreshBulkSelectionUiFromPreview();
  if (shouldOpen && typeof openAction === "function") openAction();
}

function entryUsesRotatingThumbnail(entry) {
  return false;
}

function focusDirectoriesOnFileRecord(rec) {
  return !!syncDirectoriesSelectionToFileRecord(rec, {
    syncPreview: true,
    pendingDirScrollMode: "center-selected",
    animatePreview: true,
    keepPreviewScroll: true,
    recordHistory: true,
  });
}

function teleportFromRotatingThumbnail(entry, rowEl = null) {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  if (!opt || !opt.clickSelectedRotatingThumbTeleports) return false;
  if (!entryUsesRotatingThumbnail(entry)) return false;
  const row =
    rowEl ||
    (directoriesListEl
      ? directoriesListEl.querySelector(".dirRow.selected")
      : null);
  const img =
    row && row.querySelector
      ? row.querySelector("img.dirInlinePreview[data-dir-preview-id]")
      : null;
  const id = String(img?.getAttribute("data-dir-preview-id") || "");
  if (!id) return false;
  const rec = WS.fileById.get(id);
  if (!rec) return false;
  return focusDirectoriesOnFileRecord(rec);
}

function openPreviewFileFromPreviewCard(rec) {
  if (!rec || !WS.root) return false;
  const fileId = String(rec.id || "");
  if (!fileId) return false;
  if (WS.preview.kind === "file" && String(WS.preview.fileId || "") === fileId) {
    if (WS.view.previewFileSelectionBridgeActive) setActivePane("directories");
    return true;
  }
  const bridgeReturnState = captureViewerCloseRestoreState({
    activePane: "preview",
  });
  const previewContextDir = currentFilePreviewContextDir();
  const synced = syncDirectoriesSelectionToFileRecord(rec, {
    syncPreview: false,
    renderPreview: false,
    pendingDirScrollMode: "center-selected",
    recordHistory: true,
  });
  if (!synced) return false;
  WS.view.returnToPreviewPaneAfterFileClose = true;
  WS.view.previewFileSelectionBridgeActive = true;
  WS.view.previewFileBridgeReturnState = bridgeReturnState;
  applyPreviewState({
    kind: "file",
    dirNode: previewContextDir || synced.dirNode || null,
    fileId,
  });
  renderPreviewPane(true, true);
  setActivePane("directories");
  syncActivePaneWithLayout();
  updatePreviewSelectionClasses();
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  return true;
}

function enterSelectedDirectory() {
  TAG_EDIT_PATH = null;
  clearBulkTagPlaceholder();
  WS.view.previewFolderBridgeReturnState = null;
  clearPreviewQuickNavigationState();

  const entry = WS.nav.entries[WS.nav.selectedIndex] || null;
  if (!entry) return;
  if (WS.view.aboveRootView) {
    if (entry.kind === "dir" && entry.node === WS.root) {
      WS.view.aboveRootView = false;
      WS.nav.dirNode = WS.root;
      syncBulkSelectionForCurrentDir();
      syncFavoritesUi();
      syncHiddenUi();
      syncTagUiForCurrentDir();
      rebuildDirectoriesEntries();
      WS.nav.selectedIndex = selectionIndexForDirectoryEnter();
      syncPreviewToSelection({ force: true });
      scheduleNearbyDirectoryRamWarm(currentNavigationSnapshot());
      renderDirectoriesPane();
      renderPreviewPane(true);
      syncButtons();
      kickVideoThumbsForPreview();
      kickImageThumbsForPreview();
      recordDirHistory();
    }
    return;
  }
  if (entry.kind === "tag") {
    openTagFolderEntry(entry);
    return;
  }

  if (entry.kind !== "dir" || !entry.node) {
    if (entry.kind === "file") {
      const rec = WS.fileById.get(entry.id);
      if (rec) {
        focusDirectoriesOnFileRecord(rec);
        WS.view.returnToPreviewPaneAfterFileClose = false;
      }
    }
    return;
  }
  if (isViewingTagFolder()) {
    pushTagViewContext(entry.node?.path || "");
    WS.view.tagFolderActiveMode = "";
    WS.view.tagFolderActiveTag = "";
    WS.view.tagFolderActiveAlbum = "";
    WS.view.tagFolderOriginPath = "";
  }

  if (searchResultsVisibleInDirectoriesPane()) {
    enterSearchResultContext(entry.node.path || "");
    WS.nav.dirNode = entry.node;
    syncBulkSelectionForCurrentDir();
    syncFavoritesUi();
    syncTagUiForCurrentDir();
    rebuildDirectoriesEntries();
    WS.nav.selectedIndex = selectionIndexForDirectoryEnter();
    syncPreviewToSelection({ force: true });
    finalizeDirectoryNavigationRender({
      animatePreview: true,
      recordHistory: true,
    }).catch(() => {});
    return;
  }

  if (WS.view.favoritesMode && WS.view.favoritesRootActive) {
    WS.view.favoritesRootActive = false;
    WS.view.favoritesAnchorPath = entry.node.path || "";
    WS.nav.dirNode = entry.node;
    syncBulkSelectionForCurrentDir();
    syncFavoritesUi();
    syncTagUiForCurrentDir();
    rebuildDirectoriesEntries();
    WS.nav.selectedIndex = selectionIndexForDirectoryEnter();
    syncPreviewToSelection({ force: true });
    finalizeDirectoryNavigationRender({
      animatePreview: true,
      recordHistory: true,
    }).catch(() => {});
    return;
  }

  if (WS.view.hiddenMode && WS.view.hiddenRootActive) {
    WS.view.hiddenRootActive = false;
    WS.view.hiddenAnchorPath = entry.node.path || "";
    WS.nav.dirNode = entry.node;
    syncBulkSelectionForCurrentDir();
    syncHiddenUi();
    syncTagUiForCurrentDir();
    rebuildDirectoriesEntries();
    WS.nav.selectedIndex = selectionIndexForDirectoryEnter();
    syncPreviewToSelection({ force: true });
    finalizeDirectoryNavigationRender({
      animatePreview: true,
      recordHistory: true,
    }).catch(() => {});
    return;
  }

  WS.nav.dirNode = entry.node;
  WS.view.aboveRootView = false;
  syncBulkSelectionForCurrentDir();
  syncFavoritesUi();
  syncHiddenUi();
  syncTagUiForCurrentDir();
  rebuildDirectoriesEntries();
  WS.nav.selectedIndex = selectionIndexForDirectoryEnter();
  syncPreviewToSelection({ force: true });
  finalizeDirectoryNavigationRender({
    animatePreview: true,
    recordHistory: true,
  }).catch(() => {});
}

function leaveDirectory() {
  TAG_EDIT_PATH = null;
  clearBulkTagPlaceholder();
  WS.view.previewFolderBridgeReturnState = null;
  clearPreviewQuickNavigationState();

  if (WS.view.aboveRootView) return;

  if (tryRestoreTagDirectoryContext()) return;

  if (isViewingTagFolder()) {
    exitTagFolderView();
    return;
  }

  if (searchResultsVisibleInDirectoriesPane()) return;
  if (WS.view.favoritesMode && WS.view.favoritesRootActive) return;
  if (WS.view.hiddenMode && WS.view.hiddenRootActive) return;

  if (searchBrowsingResultFolder()) {
    returnToSearchResults();
    return;
  }

  if (WS.view.favoritesMode && !WS.view.favoritesRootActive) {
    const cur = String(WS.nav.dirNode?.path || "");
    if (cur && cur === String(WS.view.favoritesAnchorPath || "")) {
      WS.view.favoritesRootActive = true;
      rebuildDirectoriesEntries();
      const idx = findDirEntryIndexByPath(cur);
      WS.nav.selectedIndex = findNearestSelectableIndex(idx >= 0 ? idx : 0, 1);
      syncPreviewToSelection({ force: true });
      finalizeDirectoryNavigationRender({ animatePreview: false }).catch(
        () => {},
      );
      return;
    }
  }

  if (WS.view.hiddenMode && !WS.view.hiddenRootActive) {
    const cur = String(WS.nav.dirNode?.path || "");
    if (cur && cur === String(WS.view.hiddenAnchorPath || "")) {
      WS.view.hiddenRootActive = true;
      rebuildDirectoriesEntries();
      const idx = findDirEntryIndexByPath(cur);
      WS.nav.selectedIndex = findNearestSelectableIndex(idx >= 0 ? idx : 0, 1);
      syncPreviewToSelection({ force: true });
      finalizeDirectoryNavigationRender({ animatePreview: false }).catch(
        () => {},
      );
      return;
    }
  }

  if (WS.nav.dirNode === WS.root) {
    if (!showRootViewEnabled()) return;
    WS.view.aboveRootView = true;
    rebuildDirectoriesEntries();
    WS.nav.selectedIndex = findNearestSelectableIndex(0, 1);
    syncPreviewToSelection({ force: true });
    finalizeDirectoryNavigationRender({
      animatePreview: false,
      recordHistory: true,
    }).catch(() => {});
    return;
  }

  if (!WS.nav.dirNode || !WS.nav.dirNode.parent) return;
  const child = WS.nav.dirNode;
  WS.nav.dirNode = WS.nav.dirNode.parent;
  WS.view.aboveRootView = false;

  syncBulkSelectionForCurrentDir();
  syncFavoritesUi();
  syncHiddenUi();
  syncTagUiForCurrentDir();
  rebuildDirectoriesEntries();

  let idx = 0;
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const e = WS.nav.entries[i];
    if (
      e.kind === "dir" &&
      (e.node === child || (child.path && e.node?.path === child.path))
    ) {
      idx = i;
      break;
    }
  }
  WS.nav.selectedIndex = findNearestSelectableIndex(idx, 1);
  syncPreviewToSelection({ force: true });
  WS.view.pendingDirScroll = "center-selected";
  finalizeDirectoryNavigationRender({
    animatePreview: false,
    recordHistory: true,
  }).catch(() => {});
}

function goDirHistory(delta) {
  if (!WS.view.dirHistory.length) return;
  const next = WS.view.dirHistoryIndex + delta;
  if (next < 0 || next >= WS.view.dirHistory.length) return;
  WS.view.dirHistoryIndex = next;
  restoreDirHistoryEntry(WS.view.dirHistory[next]);
}

function goDirUp() {
  const previewTarget = getPreviewTargetDir();
  if (
    String(WS.view.activePane || "") === "preview" &&
    previewTarget &&
    !previewTarget._skipTagFilters &&
    tryRestoreTagDirectoryContext(String(previewTarget.path || ""), {
      previewPortalRestore: true,
    })
  )
    return;
  if (tryRestoreTagDirectoryContext()) return;
  if (isViewingTagFolder()) {
    exitTagFolderView();
    return;
  }
  if (!WS.nav.dirNode) return;
  if (
    !WS.nav.dirNode.parent &&
    !(
      WS.nav.dirNode === WS.root &&
      !WS.view.aboveRootView &&
      showRootViewEnabled()
    )
  )
    return;
  leaveDirectory();
}

function getDirectoriesPathText() {
  if (!WS.root) return "—";
  if (WS.view.aboveRootView) return "root";
  if (isViewingTagFolder()) {
    return (
      buildTagContextPathText(
        String(WS.view.tagFolderActiveMode || ""),
        String(WS.view.tagFolderActiveTag || ""),
        String(WS.view.tagFolderOriginPath || ""),
        String(WS.view.tagFolderActiveAlbum || ""),
      ) ||
      dirDisplayName(WS.root) ||
      "root"
    );
  }
  if (searchResultsVisibleInDirectoriesPane()) return "search";
  if (WS.view.favoritesMode && WS.view.favoritesRootActive) return "favorites";
  if (WS.view.hiddenMode && WS.view.hiddenRootActive) return "hidden";
  if (!WS.nav.dirNode) return "—";
  if (WS.nav.dirNode === WS.root) return dirDisplayName(WS.root) || "root";
  const p = WS.nav.dirNode.path
    ? buildPortalAwareDirectoryPathText(String(WS.nav.dirNode.path || "")) ||
      displayPath(WS.nav.dirNode.path)
    : "root";
  return p || "root";
}

