function getVisibleDirPathsInEntries() {
  const set = new Set();
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (!entry || entry.kind !== "dir") continue;
    const p = String(entry.node?.path || "");
    if (p) set.add(p);
  }
  return set;
}

function getVisiblePreviewDirPaths() {
  const set = new Set();
  const cards = getPreviewSelectableCards();
  for (let i = 0; i < cards.length; i++) {
    const key = String(cards[i]?.dataset?.previewItemKey || "");
    if (key.startsWith("dir:")) set.add(key.slice(4));
  }
  return set;
}

function getVisibleFileIdsInEntries() {
  const set = new Set();
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (!entry || entry.kind !== "file") continue;
    const id = String(entry.id || "");
    if (id) set.add(id);
  }
  return set;
}

function getVisiblePreviewFileIds() {
  const set = new Set();
  const cards = getPreviewSelectableCards();
  for (let i = 0; i < cards.length; i++) {
    const key = String(cards[i]?.dataset?.previewItemKey || "");
    if (key.startsWith("file:")) set.add(key.slice(5));
  }
  return set;
}

function getSelectedPathsInCurrentDir() {
  const baseSet = getVisibleDirPathsInEntries();
  const previewSet = getVisiblePreviewDirPaths();
  return Array.from(WS.view.bulkTagSelectedPaths || []).filter((p) => {
    const value = String(p || "");
    return baseSet.has(value) || previewSet.has(value);
  });
}

function tagEntrySelectionKey(entry) {
  if (!entry || entry.kind !== "tag") return "";
  if (entry.placeholder) return "";
  if (entry.album && !entry.tag) {
    const album = normalizeTagAlbumName(entry.album);
    return album ? `tag-album:${album}` : "";
  }
  if (entry.special) {
    if (entry.special === "favorites") {
      return tagThumbnailKeyForEntry(entry);
    }
    return `special:${String(entry.special || "")}`;
  }
  const tag = String(entry.tag || "").trim();
  if (!tag) return "";
  return `tag:${tag}`;
}

function isTagEntryRenameActive(entry, state = TAG_ENTRY_RENAME_STATE) {
  if (!entry || entry.kind !== "tag" || entry.special || !state) return false;
  if (entry.placeholder) return !!state.placeholder;
  if (state.isAlbumEntry) {
    return (
      !!entry.album &&
      !entry.tag &&
      normalizeTagAlbumName(entry.album || "") ===
        normalizeTagAlbumName(state.album || state.label || "")
    );
  }
  return !!entry.tag && String(entry.tag || "") === String(state.tag || "");
}

function getVisibleTagFolderKeysInEntries() {
  const set = new Set();
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (!entry || entry.kind !== "tag") continue;
    const key = tagEntrySelectionKey(entry);
    if (key) set.add(key);
  }
  return set;
}

function getVisiblePreviewTagFolderKeys() {
  const set = new Set();
  const cards = getPreviewSelectableCards();
  for (let i = 0; i < cards.length; i++) {
    const key = String(cards[i]?.dataset?.previewItemKey || "");
    if (key.startsWith("tag:")) set.add(key.slice(4));
  }
  return set;
}

function getSelectedTagFolderKeysInCurrentView() {
  const baseSet = getVisibleTagFolderKeysInEntries();
  const previewSet = getVisiblePreviewTagFolderKeys();
  return Array.from(WS.view.bulkTagFolderSelectedKeys || []).filter((k) => {
    const value = String(k || "");
    return baseSet.has(value) || previewSet.has(value);
  });
}

function getSelectedTagEntriesInCurrentView() {
  const keys = new Set(getSelectedTagFolderKeysInCurrentView());
  if (!keys.size) return [];
  const out = [];
  const seen = new Set();
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (!entry || entry.kind !== "tag") continue;
    const key = tagEntrySelectionKey(entry);
    if (!key || !keys.has(key)) continue;
    out.push(entry);
    seen.add(key);
  }
  if (previewBodyEl && seen.size < keys.size) {
    const cards = previewBodyEl.querySelectorAll(
      ".previewTagFolderCard[data-preview-item-key]",
    );
    for (let i = 0; i < cards.length; i++) {
      const card = cards[i];
      const key = String(card?.dataset?.previewItemKey || "");
      if (!key.startsWith("tag:")) continue;
      const selectionKey = key.slice(4);
      if (!keys.has(selectionKey) || seen.has(selectionKey)) continue;
      const entry = card.__previewTagEntry || null;
      if (!entry) continue;
      out.push(entry);
      seen.add(selectionKey);
    }
  }
  return out;
}

function getSelectedFileIdsInCurrentView() {
  const baseSet = getVisibleFileIdsInEntries();
  const previewSet = getVisiblePreviewFileIds();
  return Array.from(WS.view.bulkFileSelectedIds || []).filter((id) => {
    const value = String(id || "");
    return baseSet.has(value) || previewSet.has(value);
  });
}

function getSelectedFileRecordsInCurrentView() {
  const selectedIds = new Set(
    getSelectedFileIdsInCurrentView().map((id) => String(id || "")),
  );
  if (!selectedIds.size) return [];
  const recs = [];
  for (const id of selectedIds) {
    const rec = WS.fileById.get(id);
    if (rec) recs.push(rec);
  }
  return recs;
}

function getLocalMediaRecordsForDirPath(dirPath) {
  const target = String(dirPath || "").replace(/^\/+|\/+$/g, "");
  const prefix = target ? target + "/" : "";
  const out = [];
  for (const rec of WS.fileById.values()) {
    if (!rec || !rec.file) continue;
    const rel = String(rec.relPath || "").replace(/\\/g, "/");
    if (target && !rel.startsWith(prefix)) continue;
    out.push(rec);
  }
  return out;
}

function joinNativePath(basePath, relPath) {
  const base = String(basePath || "");
  const rel = String(relPath || "").replace(/^\/+|\/+$/g, "");
  if (!rel) return base.replace(/[\/\\]+$/g, "");
  const sep = base.includes("\\") ? "\\" : "/";
  const cleanBase = base.replace(/[\/\\]+$/g, "");
  return cleanBase
    ? cleanBase + sep + rel.split("/").filter(Boolean).join(sep)
    : rel;
}

function getElectronApi() {
  if (typeof window === "undefined") return null;
  if (!window.electronAPI || typeof window.electronAPI !== "object")
    return null;
  return window.electronAPI;
}

function getNativePathForFile(file) {
  if (!file) return "";
  const electronApi = getElectronApi();
  if (electronApi && typeof electronApi.getPathForFile === "function") {
    try {
      const resolved = String(electronApi.getPathForFile(file) || "");
      if (resolved) return resolved;
    } catch {}
  }
  return String(file?.path || "");
}

function resolveAbsoluteDirectoryPath(dirPath) {
  const electronApi = getElectronApi();
  if (!electronApi) return "";

  const target = String(dirPath || "").replace(/^\/+|\/+$/g, "");
  const preferred = getLocalMediaRecordsForDirPath(target).sort(
    (a, b) => String(a?.relPath || "").length - String(b?.relPath || "").length,
  );
  const fallback = Array.from(WS.fileById.values())
    .filter((rec) => !!(rec && rec.file && rec.relPath))
    .sort(
      (a, b) =>
        String(a?.relPath || "").length - String(b?.relPath || "").length,
    );
  const records = [];
  const seen = new Set();
  for (const rec of preferred.concat(fallback)) {
    const key = `${String(rec?.id || "")}::${String(rec?.relPath || "")}`;
    if (seen.has(key)) continue;
    seen.add(key);
    records.push(rec);
  }
  if (!records.length) return "";

  for (let i = 0; i < records.length; i++) {
    const rec = records[i];
    const absFile = String(
      rec.nativePath || getNativePathForFile(rec.file) || "",
    );
    const relPath = String(rec.relPath || "").replace(/\\/g, "/");
    if (!absFile || !relPath) continue;

    const absNorm = absFile.replace(/\\/g, "/");
    if (!absNorm.toLowerCase().endsWith(relPath.toLowerCase())) continue;

    const relNative = relPath
      .split("/")
      .join(absFile.includes("\\") ? "\\" : "/");
    if (!relNative || absFile.length < relNative.length) continue;
    const rootAbs = absFile
      .slice(0, absFile.length - relNative.length)
      .replace(/[\/\\]+$/g, "");
    const targetAbs = target ? joinNativePath(rootAbs, target) : rootAbs;
    if (targetAbs) return targetAbs;
  }
  return "";
}

function thumbDiskCacheAvailable() {
  const electronApi = getElectronApi();
  return !!(
    electronApi &&
    typeof electronApi.readThumbCache === "function" &&
    typeof electronApi.writeThumbCache === "function"
  );
}

function currentThumbDiskScopeKey() {
  if (!thumbDiskCacheAvailable()) return "";
  if (THUMB_DISK_SCOPE_KEY) return THUMB_DISK_SCOPE_KEY;
  const absRoot = resolveAbsoluteDirectoryPath("");
  if (absRoot) {
    THUMB_DISK_SCOPE_KEY = `root:${absRoot}`;
    return THUMB_DISK_SCOPE_KEY;
  }
  const storageKey = String((WS.meta && WS.meta.storageKey) || "").trim();
  if (storageKey) {
    THUMB_DISK_SCOPE_KEY = `storage:${storageKey}`;
    return THUMB_DISK_SCOPE_KEY;
  }
  return "";
}

function thumbDiskRecordIdentity(rec) {
  if (!rec) return "";
  const nativePath = String(
    rec.nativePath || getNativePathForFile(rec.file) || "",
  );
  const relPath = String(rec.relPath || "");
  const size = Number.isFinite(Number(rec.size))
    ? Number(rec.size)
    : Number((rec.file && rec.file.size) || 0);
  const lastModified = Number.isFinite(Number(rec.lastModified))
    ? Number(rec.lastModified)
    : Number((rec.file && rec.file.lastModified) || 0);
  return `${String(rec.type || "")}|${nativePath || relPath}|${size}|${lastModified}`;
}

function serializeThumbDiskCrop(crop) {
  const normalized = normalizeVideoCrop(crop);
  if (!normalized) return "none";
  return [normalized.left, normalized.right, normalized.top, normalized.bottom]
    .map((value) => Number(value || 0).toFixed(4))
    .join(",");
}

function currentThumbProcessingCacheKey() {
  return THUMB_FILTER_KEY || buildThumbFilterKey();
}

function imageThumbDiskCacheKey(rec, mode) {
  if (!rec || rec.type !== "image") return "";
  const normalizedMode = String(mode || "medium");
  if (normalizedMode === "high" && !thumbFiltersActive(rec)) return "";
  return [
    THUMB_DISK_CACHE_SCHEMA_VERSION,
    "image",
    thumbDiskRecordIdentity(rec),
    `mode:${normalizedMode}`,
    `width:${imageThumbWidthForOption()}`,
    "variant:nav-neutral",
  ].join("###");
}

function videoThumbDiskCacheKey(rec, mode) {
  if (!rec || rec.type !== "video") return "";
  const normalizedMode = String(mode || "medium");
  return [
    THUMB_DISK_CACHE_SCHEMA_VERSION,
    "video",
    thumbDiskRecordIdentity(rec),
    `mode:${normalizedMode}`,
    `width:${videoThumbWidthForOption()}`,
    `frame:${String(metaGetVideoThumbnailTimeForRecord(rec) ?? "auto")}`,
    `crop:${serializeThumbDiskCrop(getVideoCropForRecord(rec))}`,
    "variant:nav-neutral",
  ].join("###");
}

async function readThumbDiskCacheUrl(scopeKey, cacheKey) {
  if (!scopeKey || !cacheKey || !thumbDiskCacheAvailable()) return "";
  const promiseKey = `${scopeKey}###${cacheKey}`;
  if (THUMB_DISK_READ_PROMISES.has(promiseKey)) {
    return THUMB_DISK_READ_PROMISES.get(promiseKey);
  }
  const electronApi = getElectronApi();
  const loadPromise = (async () => {
    try {
      const url = await electronApi.readThumbCache({
        scopeKey,
        cacheKey,
        ext: "jpg",
      });
      return String(url || "");
    } catch {
      return "";
    } finally {
      THUMB_DISK_READ_PROMISES.delete(promiseKey);
    }
  })();
  THUMB_DISK_READ_PROMISES.set(promiseKey, loadPromise);
  return loadPromise;
}

async function writeThumbDiskCacheUrl(scopeKey, cacheKey, blob) {
  if (!scopeKey || !cacheKey || !blob || !thumbDiskCacheAvailable()) return "";
  const promiseKey = `${scopeKey}###${cacheKey}`;
  if (THUMB_DISK_WRITE_PROMISES.has(promiseKey)) {
    return THUMB_DISK_WRITE_PROMISES.get(promiseKey);
  }
  const electronApi = getElectronApi();
  const writePromise = (async () => {
    try {
      const bytes = new Uint8Array(await blob.arrayBuffer());
      const url = await electronApi.writeThumbCache({
        scopeKey,
        cacheKey,
        ext: "jpg",
        bytes,
      });
      return String(url || "");
    } catch {
      return "";
    } finally {
      THUMB_DISK_WRITE_PROMISES.delete(promiseKey);
    }
  })();
  THUMB_DISK_WRITE_PROMISES.set(promiseKey, writePromise);
  return writePromise;
}

async function hydrateImageThumbFromDiskCache(rec, mode) {
  if (!rec || rec.type !== "image") return false;
  if (rec.thumbUrl && rec.thumbMode === mode) return true;
  const scopeKey = currentThumbDiskScopeKey();
  const cacheKey = imageThumbDiskCacheKey(rec, mode);
  if (!scopeKey || !cacheKey) return false;
  const cachedUrl = await readThumbDiskCacheUrl(scopeKey, cacheKey);
  if (!cachedUrl) return false;
  if (rec.thumbUrl && rec.thumbMode && rec.thumbMode !== "high") {
    try {
      URL.revokeObjectURL(rec.thumbUrl);
    } catch {}
  }
  rec.thumbUrl = cachedUrl;
  rec.thumbMode = mode;
  return true;
}

async function hydrateVideoThumbFromDiskCache(rec, mode) {
  if (!rec || rec.type !== "video") return false;
  if (rec.videoThumbUrl && rec.videoThumbMode === mode) return true;
  const scopeKey = currentThumbDiskScopeKey();
  const cacheKey = videoThumbDiskCacheKey(rec, mode);
  if (!scopeKey || !cacheKey) return false;
  const cachedUrl = await readThumbDiskCacheUrl(scopeKey, cacheKey);
  if (!cachedUrl) return false;
  if (rec.videoThumbUrl) {
    try {
      URL.revokeObjectURL(rec.videoThumbUrl);
    } catch {}
  }
  rec.videoThumbUrl = cachedUrl;
  rec.videoThumbMode = mode;
  return true;
}

async function persistImageThumbToDiskCache(rec, mode, blob) {
  const scopeKey = currentThumbDiskScopeKey();
  const cacheKey = imageThumbDiskCacheKey(rec, mode);
  if (!scopeKey || !cacheKey) return "";
  return writeThumbDiskCacheUrl(scopeKey, cacheKey, blob);
}

async function persistVideoThumbToDiskCache(rec, mode, blob) {
  const scopeKey = currentThumbDiskScopeKey();
  const cacheKey = videoThumbDiskCacheKey(rec, mode);
  if (!scopeKey || !cacheKey) return "";
  return writeThumbDiskCacheUrl(scopeKey, cacheKey, blob);
}

function currentImageThumbMode() {
  const mode =
    WS.meta && WS.meta.options
      ? String(WS.meta.options.imageThumbSize || "medium")
      : "medium";
  return normalizeThumbRenderModeValue(mode, "medium");
}

function imageThumbModeSkipsLoading(modeRaw = null) {
  const mode = normalizeThumbRenderModeValue(
    modeRaw == null ? currentImageThumbMode() : modeRaw,
    "medium",
  );
  return mode === "placeholder" || mode === "native";
}

function videoThumbModeSkipsLoading(modeRaw = null) {
  const mode = normalizeThumbRenderModeValue(
    modeRaw == null ? currentVideoThumbMode() : modeRaw,
    "medium",
  );
  return mode === "placeholder";
}

function previewStateForEntry(entry) {
  if (!entry || !isSelectableEntry(entry)) {
    return { kind: null, dirNode: null, fileId: null };
  }
  if (entry.kind === "dir") {
    return { kind: "dir", dirNode: entry.node || null, fileId: null };
  }
  if (entry.kind === "file") {
    return {
      kind: "file",
      dirNode: currentFilePreviewContextDir(),
      fileId: entry.id || null,
    };
  }
  if (entry.kind === "tag") {
    const node = makeTagPreviewNode(entry);
    return node
      ? { kind: "dir", dirNode: node, fileId: null }
      : { kind: null, dirNode: null, fileId: null };
  }
  return { kind: null, dirNode: null, fileId: null };
}

function currentFilePreviewContextDir() {
  const activePreviewDir =
    WS.preview && WS.preview.kind === "dir" ? WS.preview.dirNode : null;
  if (activePreviewDir) return activePreviewDir;
  if (isViewingTagFolder()) {
    const mode = String(WS.view.tagFolderActiveMode || "");
    const entry = {
      special:
        mode === "favorites" || mode === "hidden" || mode === "untagged"
          ? mode
          : "",
      album: mode === "album" ? String(WS.view.tagFolderActiveAlbum || "") : "",
      tag: mode === "tag" ? String(WS.view.tagFolderActiveTag || "") : "",
      label:
        mode === "favorites"
          ? "Favorites"
          : mode === "hidden"
            ? "Hidden"
            : mode === "untagged"
              ? "Untagged"
              : mode === "album"
                ? String(WS.view.tagFolderActiveAlbum || "Album")
                : String(WS.view.tagFolderActiveTag || "Tag"),
    };
    return makeTagPreviewNode(entry) || WS.nav.dirNode || WS.root || null;
  }
  return WS.nav.dirNode || WS.root || null;
}

function loadingScreensEnabled() {
  const opt = WS.meta && WS.meta.options ? WS.meta.options : null;
  return !!(opt && opt.loadingScreens);
}

function tagPortalNavigationContextActive() {
  if (isViewingTagFolder()) return true;
  const previewTarget = getPreviewTargetDir();
  if (previewTarget && previewTarget._skipTagFilters) return true;
  const selectedEntry = Array.isArray(WS.nav?.entries)
    ? WS.nav.entries[WS.nav.selectedIndex] || null
    : null;
  if (selectedEntry && selectedEntry.kind === "tag") return true;
  const stack = WS.view && Array.isArray(WS.view.tagNavStack)
    ? WS.view.tagNavStack
    : null;
  if (stack && stack.length) {
    const top = stack[stack.length - 1];
    const frameType = String(top?.type || "");
    if (frameType === "tag-view" || frameType === "tag-entry") return true;
  }
  return false;
}

function shouldDeferNonEssentialNavigationWork() {
  return !loadingScreensEnabled() && tagPortalNavigationContextActive();
}

function scoreInterfaceEnabled(opt = null) {
  const src = opt || (WS.meta && WS.meta.options ? WS.meta.options : null);
  return !(src && src.hardwareAcceleration === false);
}

function folderDepthRelativeToWorkspaceRoot(dirNode) {
  if (!dirNode) return 0;
  const rootPath = String(WS.root?.path || "");
  const dirPath = String(dirNode.path || "");
  const rootDepth = rootPath ? rootPath.split("/").filter(Boolean).length : 0;
  const dirDepth = dirPath ? dirPath.split("/").filter(Boolean).length : 0;
  return Math.max(0, dirDepth - rootDepth);
}

function folderThumbnailTitlesVisibleForNode(dirNode, opt = null) {
  return previewThumbnailVisibilityForDirNode(dirNode, opt).showTitle;
}

function previewFolderMenuButtonHiddenForNode(dirNode, opt = null) {
  return !previewThumbnailVisibilityForDirNode(dirNode, opt).showMenuButton;
}

function previewTagAndRootMenuButtonHidden(opt = null) {
  return !previewThumbnailVisibilityForKind("tag", opt).showMenuButton;
}

function previewFileMenuButtonHidden(opt = null) {
  return !previewThumbnailVisibilityForKind("file", opt).showMenuButton;
}

function currentItemMetadataVisibilityOptions() {
  return {
    preview: {
      file: previewThumbnailVisibilityForKind("file"),
      rootFolder: previewThumbnailVisibilityForKind("rootFolder"),
      subfolder: previewThumbnailVisibilityForKind("subfolder"),
      tag: previewThumbnailVisibilityForKind("tag"),
    },
    directories: {
      file: directoriesThumbnailVisibilityForKind("file"),
      rootFolder: directoriesThumbnailVisibilityForKind("rootFolder"),
      subfolder: directoriesThumbnailVisibilityForKind("subfolder"),
      tag: directoriesThumbnailVisibilityForKind("tag"),
    },
  };
}

function folderThumbnailKindForNode(dirNode) {
  return folderDepthRelativeToWorkspaceRoot(dirNode) <= 1
    ? "rootFolder"
    : "subfolder";
}

function resolveThumbnailVisibility(surface, kind, opt = null) {
  const src =
    opt || (WS.meta && WS.meta.options ? WS.meta.options : null) || {};
  const showScore = scoreInterfaceEnabled(src);
  const supportsPreview = (field) =>
    thumbnailVisibilityFieldSupported("preview", kind, field);
  const supportsDirectories = (field) =>
    thumbnailVisibilityFieldSupported("directories", kind, field);
  const resolvePreviewValue = (field, fallback) => {
    const key = thumbnailVisibilityPreviewOptionKey(kind, field);
    if (key && typeof src[key] === "boolean") return src[key];
    return fallback;
  };
  const resolveDirectoriesValue = (field, fallback) => {
    const key = thumbnailVisibilityDirectoriesOptionKey(kind, field);
    if (key && typeof src[key] === "boolean") return src[key];
    return fallback;
  };

  if (surface === "directories") {
    return {
      showScores:
        supportsDirectories("score") &&
        showScore &&
        resolveDirectoriesValue("score", !(src && src.showScores === false)),
      showItemCount:
        supportsDirectories("itemCount") &&
        resolveDirectoriesValue(
          "itemCount",
          !(src && src.showFolderItemCount === false),
        ),
      showSize:
        supportsDirectories("size") &&
        resolveDirectoriesValue("size", !(src && src.showFolderSize === false)),
      showTitle: true,
      showMenuButton: true,
      showItemTypeLabel:
        supportsDirectories("itemType") &&
        resolveDirectoriesValue(
          "itemType",
          !(src && src.showItemTypeLabel === false),
        ),
    };
  }

  const fallbackTitle = (() => {
    if (kind === "file") return !(src && src.showFileThumbnailTitles === false);
    if (kind === "tag") return !(src && src.showTagThumbnailTitles === false);
    if (kind === "subfolder")
      return !(src && src.showSubfolderThumbnailTitles === false);
    return !(src && src.showRootFolderThumbnailTitles === false);
  })();
  const fallbackMenu = (() => {
    if (kind === "file") return !(src && src.hideFileThumbnailMenuButton);
    if (kind === "tag")
      return !(src && src.hideTagAndRootFolderThumbnailMenuButton);
    if (kind === "subfolder")
      return !(src && src.hideSubfolderThumbnailMenuButton);
    return !(src && src.hideRootFolderThumbnailMenuButton);
  })();

  return {
    showScores:
      supportsPreview("score") &&
      showScore &&
      resolvePreviewValue("score", !(src && src.showScores === false)),
    showItemCount:
      supportsPreview("itemCount") &&
      resolvePreviewValue(
        "itemCount",
        !(src && src.showFolderItemCount === false),
      ),
    showSize:
      supportsPreview("size") &&
      resolvePreviewValue("size", !(src && src.showFolderSize === false)),
    showTitle:
      supportsPreview("title") && resolvePreviewValue("title", fallbackTitle),
    showMenuButton:
      supportsPreview("menuButton") &&
      resolvePreviewValue("menuButton", fallbackMenu),
    showItemTypeLabel:
      supportsPreview("itemType") &&
      resolvePreviewValue(
        "itemType",
        !(src && src.showItemTypeLabel === false),
      ),
  };
}

function previewThumbnailVisibilityForKind(kind, opt = null) {
  return resolveThumbnailVisibility("preview", kind, opt);
}

function directoriesThumbnailVisibilityForKind(kind, opt = null) {
  return resolveThumbnailVisibility("directories", kind, opt);
}

function previewThumbnailVisibilityForDirNode(dirNode, opt = null) {
  return previewThumbnailVisibilityForKind(
    folderThumbnailKindForNode(dirNode),
    opt,
  );
}

function directoriesThumbnailVisibilityForDirNode(dirNode, opt = null) {
  return directoriesThumbnailVisibilityForKind(
    folderThumbnailKindForNode(dirNode),
    opt,
  );
}

function folderItemTypeLabelForNode(dirNode) {
  if (!dirNode) return "Folder";
  return dirNode === WS.root ? "Root" : "Folder";
}

function fileItemTypeLabelForRecord(rec) {
  return toTitleCaps(String(rec?.type || "file"));
}

function tagItemTypeLabelForEntry(entry) {
  if (!entry) return "Tag";
  if (entry.special) {
    const special = String(entry.special || "")
      .trim()
      .toLowerCase();
    if (special === "favorites") return "Favorites";
    if (special === "hidden") return "Hidden";
    if (special === "untagged") return "Untagged";
    return toTitleCaps(special || "Tag");
  }
  if (entry.album && !entry.tag) return "Album";
  return "Tag";
}

function shouldAutoLoadFileThumbnails() {
  return true;
}

function thumbnailPushQueueEnabled() {
  return true;
}

function bumpThumbnailDemandToken() {
  WS.thumbnailDemandToken = ((Number(WS.thumbnailDemandToken) || 0) + 1) >>> 0;
  return WS.thumbnailDemandToken;
}

function currentThumbnailDemandToken() {
  return (Number(WS.thumbnailDemandToken) || 0) >>> 0;
}

function thumbnailRecordDesired(recordId) {
  const id = String(recordId || "");
  if (!id) return false;
  return !!(
    WS.thumbnailDesiredIds instanceof Set && WS.thumbnailDesiredIds.has(id)
  );
}

function thumbnailJobContextStillValid(jobToken, recordId, force = false) {
  if (force) return true;
  const token = (Number(jobToken) || 0) >>> 0;
  if (token !== currentThumbnailDemandToken()) return false;
  return thumbnailRecordDesired(recordId);
}

function revokeThumbnailUrlForRecord(rec) {
  if (!rec) return false;
  let changed = false;
  if (rec.thumbUrl) {
    try {
      URL.revokeObjectURL(rec.thumbUrl);
    } catch {}
    rec.thumbUrl = null;
    changed = true;
  }
  if (rec.videoThumbUrl) {
    try {
      URL.revokeObjectURL(rec.videoThumbUrl);
    } catch {}
    rec.videoThumbUrl = null;
    changed = true;
  }
  return changed;
}

function elementNearVisibleInContainer(container, el, overscanPx = 0) {
  if (!container || !el || !el.getBoundingClientRect) return false;
  const containerRect = container.getBoundingClientRect();
  const rect = el.getBoundingClientRect();
  const overscan = Math.max(0, Number(overscanPx) || 0);
  return (
    rect.bottom >= containerRect.top - overscan &&
    rect.top <= containerRect.bottom + overscan &&
    rect.right >= containerRect.left - overscan &&
    rect.left <= containerRect.right + overscan
  );
}

function addRecordToThumbnailDemand(set, rec) {
  const id = String(rec?.id || "");
  if (!id) return;
  set.add(id);
}

function addRecordsToThumbnailDemand(set, records) {
  const list = Array.isArray(records) ? records : [];
  for (let i = 0; i < list.length; i++)
    addRecordToThumbnailDemand(set, list[i]);
}

function getPreviewCardThumbnailDemandRecords(card) {
  if (!card) return [];
  const fileId = String(card.dataset?.fileId || "");
  if (fileId) {
    if (!shouldAutoLoadFileThumbnails()) return [];
    return [WS.fileById.get(fileId)].filter(Boolean);
  }
  if (card.__previewDirNode) {
    const leadInfo = getDisplayLeadPreviewForDir(
      card.__previewDirNode,
      "preview-dir",
    );
    return leadInfo && leadInfo.record ? [leadInfo.record] : [];
  }
  const dirPath = String(card.dataset?.dirPath || "");
  if (dirPath) {
    const dirNode = WS.dirByPath.get(dirPath);
    const leadInfo = dirNode
      ? getDisplayLeadPreviewForDir(dirNode, "preview-dir")
      : null;
    return leadInfo && leadInfo.record ? [leadInfo.record] : [];
  }
  if (card.__previewTagEntry)
    return collectVisibleThumbRecordsForTagEntry(card.__previewTagEntry);
  const inlinePreviewId = String(
    card.querySelector?.("[data-dir-preview-id]")?.dataset?.dirPreviewId || "",
  );
  return inlinePreviewId
    ? [WS.fileById.get(inlinePreviewId)].filter(Boolean)
    : [];
}

function getDirectoriesRowThumbnailDemandRecords(row) {
  if (!row) return [];
  const fileId = String(row.dataset?.fileId || "");
  if (fileId) {
    if (!shouldAutoLoadFileThumbnails()) return [];
    return [WS.fileById.get(fileId)].filter(Boolean);
  }
  if (row.__dirTagEntry)
    return collectVisibleThumbRecordsForTagEntry(row.__dirTagEntry);
  const dirPath = String(row.dataset?.dirPath || "");
  if (dirPath || row.__dirNode === WS.root) {
    const dirNode = row.__dirNode || WS.dirByPath.get(dirPath) || null;
    const leadInfo = dirNode
      ? getDisplayLeadPreviewForDir(dirNode, "dir")
      : null;
    return leadInfo && leadInfo.record ? [leadInfo.record] : [];
  }
  const inlinePreviewId = String(
    row.querySelector?.("[data-dir-preview-id]")?.dataset?.dirPreviewId || "",
  );
  return inlinePreviewId
    ? [WS.fileById.get(inlinePreviewId)].filter(Boolean)
    : [];
}

function collectPreviewThumbnailDemandIds() {
  const out = new Set();
  if (!WS.root || !previewBodyEl) return out;
  if (WS.preview.kind === "file" && WS.preview.fileId) {
    if (!shouldAutoLoadFileThumbnails()) return out;
    addRecordToThumbnailDemand(
      out,
      WS.fileById.get(String(WS.preview.fileId || "")),
    );
    return out;
  }
  if (!previewBodyEl.classList.contains("preview-grid")) return out;
  const overscan = Math.max(
    120,
    (Number(previewBodyEl.clientHeight) || 0) *
      THUMBNAIL_VIEWPORT_OVERSCAN_MULTIPLIER,
  );
  const cards = previewBodyEl.querySelectorAll("[data-preview-item-key]");
  for (let i = 0; i < cards.length; i++) {
    const card = cards[i];
    if (!elementNearVisibleInContainer(previewBodyEl, card, overscan)) continue;
    addRecordsToThumbnailDemand(
      out,
      getPreviewCardThumbnailDemandRecords(card),
    );
  }
  if (!out.size && shouldAutoLoadFileThumbnails()) {
    addRecordsToThumbnailDemand(
      out,
      getPriorityPreviewThumbRecords(THUMBNAIL_PREVIEW_WINDOW_LIMIT),
    );
  }
  return out;
}

function collectDirectoriesThumbnailDemandIds() {
  const out = new Set();
  if (!WS.root || !directoriesListEl) return out;
  const overscan = Math.max(
    120,
    (Number(directoriesListEl.clientHeight) || 0) *
      THUMBNAIL_VIEWPORT_OVERSCAN_MULTIPLIER,
  );
  const rows = directoriesListEl.querySelectorAll(".dirRow");
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    if (!elementNearVisibleInContainer(directoriesListEl, row, overscan))
      continue;
    addRecordsToThumbnailDemand(
      out,
      getDirectoriesRowThumbnailDemandRecords(row),
    );
  }
  if (!out.size && shouldAutoLoadFileThumbnails()) {
    addRecordsToThumbnailDemand(
      out,
      collectNavigationEntryWindowRecords(
        WS.nav.dirNode,
        THUMBNAIL_DIRECTORY_WINDOW_LIMIT,
      ),
    );
  }
  return out;
}

function collectThumbnailDemandIds() {
  const out = new Set();
  const previewIds = collectPreviewThumbnailDemandIds();
  const directoriesIds = collectDirectoriesThumbnailDemandIds();
  previewIds.forEach((id) => out.add(id));
  directoriesIds.forEach((id) => out.add(id));
  if (!out.size && WS.preview.kind === "dir" && WS.preview.dirNode) {
    addRecordsToThumbnailDemand(
      out,
      collectNavigationManifestRecords(
        WS.preview.dirNode,
        shouldAutoLoadFileThumbnails() ? 18 : 0,
        18,
      ),
    );
  }
  return out;
}

function syncThumbnailQueueToDemand(queue, desiredIds) {
  if (!Array.isArray(queue)) return;
  for (let i = queue.length - 1; i >= 0; i--) {
    const id = String(queue[i] || "");
    if (id && desiredIds.has(id)) continue;
    queue.splice(i, 1);
    if (WS.videoThumbQueuedIds instanceof Set)
      WS.videoThumbQueuedIds.delete(id);
    if (WS.imageThumbQueuedIds instanceof Set)
      WS.imageThumbQueuedIds.delete(id);
  }
}

function evictThumbnailUrlsOutsideDemand(desiredIds) {
  if (!WS.fileById || !WS.fileById.size) return;
  for (const rec of WS.fileById.values()) {
    const id = String(rec?.id || "");
    if (!id || desiredIds.has(id)) continue;
    revokeThumbnailUrlForRecord(rec);
  }
}

function flushThumbnailUiInvalidation() {
  THUMBNAIL_INVALIDATION_RAF = 0;
  if (!WS.root) return;
  const redrawDirectories = !!WS.thumbnailUiDirtyDirectories;
  const redrawPreview = !!WS.thumbnailUiDirtyPreview;
  WS.thumbnailUiDirtyDirectories = false;
  WS.thumbnailUiDirtyPreview = false;
  if (redrawDirectories)
    renderDirectoriesPane(true, { suppressSelectionReveal: true });
  if (redrawPreview) renderPreviewPane(false, true);
}

function scheduleThumbnailUiInvalidation(opts = null) {
  const options = opts && typeof opts === "object" ? opts : {};
  if (options.directories) WS.thumbnailUiDirtyDirectories = true;
  if (options.preview) WS.thumbnailUiDirtyPreview = true;
  if (THUMBNAIL_INVALIDATION_RAF) return;
  THUMBNAIL_INVALIDATION_RAF = requestAnimationFrame(
    flushThumbnailUiInvalidation,
  );
}

function recordVisibleInPreviewSurface(recordId) {
  const id = String(recordId || "");
  if (!id || !previewBodyEl) return false;
  if (WS.preview.kind === "file" && String(WS.preview.fileId || "") === id)
    return true;
  const nodes = previewBodyEl.querySelectorAll(
    "[data-dir-preview-id], .fileCard[data-file-id]",
  );
  for (let i = 0; i < nodes.length; i++) {
    const node = nodes[i];
    if (String(node.dataset?.dirPreviewId || node.dataset?.fileId || "") === id)
      return true;
  }
  return false;
}

function recordVisibleInDirectoriesSurface(recordId) {
  const id = String(recordId || "");
  if (!id || !directoriesEl) return false;
  const nodes = directoriesEl.querySelectorAll(
    "[data-dir-preview-id], .dirRow.fileRow[data-file-id]",
  );
  for (let i = 0; i < nodes.length; i++) {
    const node = nodes[i];
    if (String(node.dataset?.dirPreviewId || node.dataset?.fileId || "") === id)
      return true;
  }
  return false;
}

function notifyThumbnailRecordUpdated(rec) {
  if (!rec) return;
  const recId = String(rec.id || "");
  if (!recId) return;
  refreshDirectoryInlinePreviewThumbForRecord(rec);
  scheduleThumbnailUiInvalidation({
    directories:
      (WS.thumbnailDirectoriesDemandIds instanceof Set &&
        WS.thumbnailDirectoriesDemandIds.has(recId)) ||
      recordVisibleInDirectoriesSurface(recId),
    preview:
      (WS.thumbnailPreviewDemandIds instanceof Set &&
        WS.thumbnailPreviewDemandIds.has(recId)) ||
      recordVisibleInPreviewSurface(recId),
  });
}

function refreshThumbnailDemand() {
  THUMBNAIL_DEMAND_RAF = 0;
  if (!WS.root) return;
  const previewIds = collectPreviewThumbnailDemandIds();
  const directoriesIds = collectDirectoriesThumbnailDemandIds();
  const desiredIds = new Set();
  previewIds.forEach((id) => desiredIds.add(id));
  directoriesIds.forEach((id) => desiredIds.add(id));
  if (!desiredIds.size && WS.preview.kind === "dir" && WS.preview.dirNode) {
    addRecordsToThumbnailDemand(
      desiredIds,
      collectNavigationManifestRecords(
        WS.preview.dirNode,
        shouldAutoLoadFileThumbnails() ? 18 : 0,
        18,
      ),
    );
  }
  WS.thumbnailDesiredIds = desiredIds;
  WS.thumbnailPreviewDemandIds = previewIds;
  WS.thumbnailDirectoriesDemandIds = directoriesIds;
  evictThumbnailUrlsOutsideDemand(desiredIds);
  syncThumbnailQueueToDemand(WS.videoThumbPriorityQueue, desiredIds);
  syncThumbnailQueueToDemand(WS.videoThumbQueue, desiredIds);
  syncThumbnailQueueToDemand(WS.imageThumbPriorityQueue, desiredIds);
  syncThumbnailQueueToDemand(WS.imageThumbQueue, desiredIds);
  const videoMode = currentVideoThumbMode();
  const imageMode = currentImageThumbMode();
  desiredIds.forEach((id) => {
    const rec = WS.fileById.get(id);
    if (!rec) return;
    if (rec.type === "video") {
      if (
        !videoThumbModeSkipsLoading(videoMode) &&
        !(rec.videoThumbUrl && rec.videoThumbMode === videoMode)
      )
        enqueueVideoThumb(rec, { priority: true });
      return;
    }
    if (rec.type === "image" && !imageThumbModeSkipsLoading(imageMode)) {
      if (!(rec.thumbUrl && rec.thumbMode === imageMode))
        enqueueImageThumb(rec, { priority: true });
    }
  });
  drainVideoThumbQueue();
  drainImageThumbQueue();
}

function scheduleThumbnailDemandRefresh() {
  if (THUMBNAIL_DEMAND_RAF || THUMBNAIL_DEMAND_DEFER_TIMER) return;
  if (shouldDeferNonEssentialNavigationWork()) {
    THUMBNAIL_DEMAND_DEFER_TIMER = setTimeout(() => {
      THUMBNAIL_DEMAND_DEFER_TIMER = 0;
      if (THUMBNAIL_DEMAND_RAF) return;
      THUMBNAIL_DEMAND_RAF = requestAnimationFrame(refreshThumbnailDemand);
    }, 120);
    return;
  }
  THUMBNAIL_DEMAND_RAF = requestAnimationFrame(refreshThumbnailDemand);
}

function applyPreviewState(state) {
  const next = state && typeof state === "object" ? state : {};
  const prevKind = WS.preview.kind || null;
  const prevDirPath = String(WS.preview.dirNode?.path || "");
  const prevFileId = String(WS.preview.fileId || "");
  WS.preview.kind = next.kind || null;
  WS.preview.dirNode = next.dirNode || null;
  WS.preview.fileId = next.fileId || null;
  const nextKind = WS.preview.kind || null;
  const nextDirPath = String(WS.preview.dirNode?.path || "");
  const nextFileId = String(WS.preview.fileId || "");
  if (
    prevKind !== nextKind ||
    prevDirPath !== nextDirPath ||
    prevFileId !== nextFileId
  ) {
    notePreviewTargetChanged({
      kind: nextKind,
      dirNode: WS.preview.dirNode,
      fileId: nextFileId,
    });
  }
}

function currentNavigationSnapshot() {
  return {
    dirNode: WS.nav.dirNode,
    preview: {
      kind: WS.preview.kind,
      dirNode: WS.preview.dirNode,
      fileId: WS.preview.fileId,
    },
  };
}

async function runWithConcurrency(items, limit, worker) {
  const list = Array.isArray(items) ? items.slice() : [];
  if (!list.length) return;
  const concurrency = Math.max(1, Math.min(list.length, Number(limit) || 1));
  let index = 0;
  async function pump() {
    while (index < list.length) {
      const currentIndex = index++;
      await worker(list[currentIndex], currentIndex);
    }
  }
  const workers = [];
  for (let i = 0; i < concurrency; i++) workers.push(pump());
  await Promise.all(workers);
}

async function ensureNavigationThumbReady(rec) {
  if (!rec || !rec.id) return false;
  if (rec.type === "video") {
    const mode = currentVideoThumbMode();
    if (videoThumbModeSkipsLoading(mode)) return true;
    if (rec.videoThumbUrl && rec.videoThumbMode === mode) return true;
    const key = `video###${String(rec.id || "")}###${videoThumbDiskCacheKey(rec, mode)}`;
    if (NAV_THUMB_READY_PROMISES.has(key))
      return NAV_THUMB_READY_PROMISES.get(key);
    const promise = generateVideoThumb(rec, { force: true })
      .then(() => !!(rec.videoThumbUrl && rec.videoThumbMode === mode))
      .catch(() => false)
      .finally(() => {
        NAV_THUMB_READY_PROMISES.delete(key);
      });
    NAV_THUMB_READY_PROMISES.set(key, promise);
    return promise;
  }
  if (rec.type === "image") {
    const mode = currentImageThumbMode();
    if (imageThumbModeSkipsLoading(mode)) return true;
    if (rec.thumbUrl && rec.thumbMode === mode) return true;
    const key = `image###${String(rec.id || "")}###${imageThumbDiskCacheKey(rec, mode) || mode}`;
    if (NAV_THUMB_READY_PROMISES.has(key))
      return NAV_THUMB_READY_PROMISES.get(key);
    const promise = generateImageThumb(rec, { force: true })
      .then(() => !!(rec.thumbUrl && rec.thumbMode === mode))
      .catch(() => false)
      .finally(() => {
        NAV_THUMB_READY_PROMISES.delete(key);
      });
    NAV_THUMB_READY_PROMISES.set(key, promise);
    return promise;
  }
  return false;
}

function collectNavigationManifestRecords(
  dirNode,
  maxFiles = 0,
  maxChildLeadIds = 0,
) {
  if (!dirNode) return [];
  const manifest = getDirectoryNavManifest(dirNode);
  if (!manifest) return [];
  const out = [];
  const seen = new Set();
  const pushId = (id) => {
    const normalized = String(id || "");
    if (!normalized || seen.has(normalized)) return;
    const rec = WS.fileById.get(normalized);
    if (!rec) return;
    seen.add(normalized);
    out.push(rec);
  };
  const fileIds = Array.isArray(manifest.fileIds) ? manifest.fileIds : [];
  const childLeadIds = Array.isArray(manifest.childLeadRecordIds)
    ? manifest.childLeadRecordIds
    : [];
  const fileLimit = Math.max(0, Number(maxFiles) || 0);
  const childLimit = Math.max(0, Number(maxChildLeadIds) || 0);
  for (let i = 0; i < fileIds.length && i < fileLimit; i++) pushId(fileIds[i]);
  for (let i = 0; i < childLeadIds.length && i < childLimit; i++)
    pushId(childLeadIds[i]);
  return out;
}

function collectVisibleThumbRecordsForTagEntry(entry) {
  if (!entry || entry.placeholder) return [];
  const thumbMode = tagThumbnailKeyForEntry(entry)
    ? metaGetTagThumbnailModeByKey(tagThumbnailKeyForEntry(entry))
    : "single";
  if (thumbMode === "none") return [];
  const presetRec = getTagPresetPreviewRecordForEntry(entry);
  if (presetRec) return [presetRec];
  if (naturalAspectThumbnailCardsEnabled()) return [];
  const pool = getRecursivePreviewRecordsForTagEntry(
    entry,
    tagThumbnailPreviewSampleLimit(thumbMode),
  );
  if (!pool.length) return [];
  const scopePath = String(WS.nav.dirNode?.path || entry.originPath || "");
  const baseKey = entry.special
    ? `tag:${scopePath}:special:${entry.special}`
    : entry.album && !entry.tag
      ? `tag:${scopePath}:album:${String(entry.album || "")}`
      : `tag:${scopePath}:name:${String(entry.tag || "")}`;
  if (thumbMode === "single" || pool.length < 4) {
    const rec = pickRotatingPreviewRecordForKey(`${baseKey}:single`, pool);
    return rec ? [rec] : [];
  }
  const slots = pickRotatingPreviewSlotsForKey(baseKey, pool, 4);
  const out = [];
  const seen = new Set();
  for (let i = 0; i < slots.length; i++) {
    const rec = slots[i] && slots[i].rec ? slots[i].rec : null;
    const id = String(rec?.id || "");
    if (!id || seen.has(id)) continue;
    seen.add(id);
    out.push(rec);
  }
  return out;
}

function collectFullNavigationEntryRecords(
  dirNode,
  includeFiles = true,
  opts = null,
) {
  if (!dirNode) return [];
  const options = opts && typeof opts === "object" ? opts : {};
  const useCurrentViewEntries = !!options.useCurrentViewEntries;
  const previewEntries = getPreviewFolderAndFileEntries(dirNode, {
    includeFiles,
    useCurrentViewEntries,
  });
  const out = [];
  const seen = new Set();
  const addRecord = (rec) => {
    const id = String(rec?.id || "");
    if (!id || seen.has(id)) return;
    seen.add(id);
    out.push(rec);
  };
  const addEntryThumbRecords = (entry) => {
    if (!entry) return;
    if (entry.kind === "file") {
      addRecord(WS.fileById.get(String(entry.id || "")));
      return;
    }
    if (entry.kind === "dir" && entry.node) {
      const manifest = getDirectoryNavManifest(entry.node);
      const leadId = String(manifest?.leadRecordId || "");
      if (leadId) addRecord(WS.fileById.get(leadId));
      return;
    }
    if (entry.kind === "tag") {
      const records = collectVisibleThumbRecordsForTagEntry(entry);
      for (let i = 0; i < records.length; i++) addRecord(records[i]);
    }
  };

  const folderEntries = Array.isArray(previewEntries.folderEntries)
    ? previewEntries.folderEntries
    : [];
  for (let i = 0; i < folderEntries.length; i++)
    addEntryThumbRecords(folderEntries[i]);
  if (includeFiles) {
    const fileIds = Array.isArray(previewEntries.fileIds)
      ? previewEntries.fileIds
      : [];
    for (let i = 0; i < fileIds.length; i++)
      addRecord(WS.fileById.get(String(fileIds[i] || "")));
  }
  return out;
}

function collectNavigationEntryWindowRecords(
  dirNode,
  maxEntries = NAVIGATION_PREP_ENTRY_WINDOW,
  opts = null,
) {
  if (!dirNode || dirNode !== WS.nav.dirNode) return [];
  const options = opts && typeof opts === "object" ? opts : {};
  const includeFiles = options.includeFiles !== false;
  const entries = Array.isArray(WS.nav.entries) ? WS.nav.entries : [];
  if (!entries.length) return [];

  const entryLimit = Math.max(
    1,
    Number(maxEntries) || NAVIGATION_PREP_ENTRY_WINDOW,
  );
  const selectedIndex = clampNumber(
    Number(WS.nav.selectedIndex) || 0,
    0,
    Math.max(0, entries.length - 1),
    0,
  );
  let start = Math.max(0, selectedIndex - Math.floor(entryLimit / 3));
  if (start + entryLimit > entries.length)
    start = Math.max(0, entries.length - entryLimit);
  const endExclusive = Math.min(entries.length, start + entryLimit);

  const out = [];
  const seen = new Set();
  const addRecord = (rec) => {
    const id = String((rec && rec.id) || "");
    if (!id || seen.has(id)) return;
    seen.add(id);
    out.push(rec);
  };

  for (let i = start; i < endExclusive; i++) {
    const entry = entries[i];
    if (!entry) continue;
    if (entry.kind === "file") {
      if (!includeFiles) continue;
      addRecord(WS.fileById.get(String(entry.id || "")));
      continue;
    }
    if (entry.kind !== "dir" || !entry.node) continue;
    const manifest = getDirectoryNavManifest(entry.node);
    const leadId = String((manifest && manifest.leadRecordId) || "");
    if (!leadId) continue;
    addRecord(WS.fileById.get(leadId));
  }
  return out;
}

function collectNavigationSnapshotRecords(snapshot, opts = null) {
  const options = opts && typeof opts === "object" ? opts : {};
  const full = !!options.full;
  const out = [];
  const seen = new Set();
  const addRecord = (rec) => {
    const id = String((rec && rec.id) || "");
    if (!id || seen.has(id)) return;
    seen.add(id);
    out.push(rec);
  };
  const addRecords = (records) => {
    const list = Array.isArray(records) ? records : [];
    for (let i = 0; i < list.length; i++) addRecord(list[i]);
  };

  if (snapshot && snapshot.dirNode) {
    if (full) {
      addRecords(
        collectFullNavigationEntryRecords(
          snapshot.dirNode,
          shouldAutoLoadFileThumbnails(),
          { useCurrentViewEntries: true },
        ),
      );
    } else {
      const windowRecords = collectNavigationEntryWindowRecords(
        snapshot.dirNode,
        NAVIGATION_PREP_ENTRY_WINDOW,
        {
          includeFiles: shouldAutoLoadFileThumbnails(),
        },
      );
      if (windowRecords.length) addRecords(windowRecords);
      else
        addRecords(
          collectNavigationManifestRecords(
            snapshot.dirNode,
            shouldAutoLoadFileThumbnails() ? NAVIGATION_PREP_DIR_FILE_LIMIT : 0,
            NAVIGATION_PREP_CHILD_LEAD_LIMIT,
          ),
        );
    }
  }

  if (
    snapshot &&
    snapshot.preview &&
    snapshot.preview.kind === "dir" &&
    snapshot.preview.dirNode
  ) {
    if (full) {
      addRecords(
        collectFullNavigationEntryRecords(
          snapshot.preview.dirNode,
          shouldAutoLoadFileThumbnails(),
          {
            useCurrentViewEntries:
              snapshot.preview.dirNode === snapshot.dirNode,
          },
        ),
      );
    } else if (snapshot.preview.dirNode !== snapshot.dirNode) {
      addRecords(
        collectNavigationManifestRecords(
          snapshot.preview.dirNode,
          shouldAutoLoadFileThumbnails()
            ? NAVIGATION_PREP_PREVIEW_FILE_LIMIT
            : 0,
          NAVIGATION_PREP_PREVIEW_CHILD_LIMIT,
        ),
      );
    }
  } else if (
    snapshot &&
    snapshot.preview &&
    snapshot.preview.kind === "file" &&
    snapshot.preview.fileId
  ) {
    if (!shouldAutoLoadFileThumbnails()) return out;
    addRecord(WS.fileById.get(String(snapshot.preview.fileId || "")));
  }
  return out;
}

function collectNearbyDirectoryPaths(snapshot) {
  const out = [];
  const seen = new Set();
  const pushPath = (pathValue) => {
    const path = String(pathValue || "");
    if (seen.has(path)) return;
    seen.add(path);
    out.push(path);
  };
  const pushDir = (dirNode) => {
    if (!dirNode) return;
    pushPath(dirNode.path || "");
  };
  const pushChildDirs = (dirNode, limit = HOT_NAV_CHILD_LIMIT) => {
    if (!dirNode) return;
    const children = getChildDirsForNode(dirNode);
    for (let i = 0; i < children.length && i < limit; i++) pushDir(children[i]);
  };

  const navDir = snapshot && snapshot.dirNode ? snapshot.dirNode : null;
  const previewDir =
    snapshot && snapshot.preview && snapshot.preview.kind === "dir"
      ? snapshot.preview.dirNode
      : null;
  pushDir(navDir);
  pushDir(previewDir);
  if (navDir && navDir.parent) pushDir(navDir.parent);
  if (previewDir && previewDir.parent) pushDir(previewDir.parent);

  const selectedIndex = Number(WS.nav.selectedIndex || 0);
  const start = Math.max(0, selectedIndex - HOT_NAV_NEARBY_SIBLING_RADIUS);
  const end = Math.min(
    WS.nav.entries.length - 1,
    selectedIndex + HOT_NAV_NEARBY_SIBLING_RADIUS,
  );
  for (let i = start; i <= end; i++) {
    const entry = WS.nav.entries[i];
    if (!entry || entry.kind !== "dir" || !entry.node) continue;
    pushDir(entry.node);
  }

  const selectedEntry = WS.nav.entries[selectedIndex] || null;
  if (selectedEntry && selectedEntry.kind === "dir" && selectedEntry.node) {
    pushDir(selectedEntry.node);
    pushChildDirs(selectedEntry.node, HOT_NAV_CHILD_LIMIT);
  }

  pushChildDirs(navDir, HOT_NAV_CHILD_LIMIT);
  pushChildDirs(previewDir, Math.max(2, Math.floor(HOT_NAV_CHILD_LIMIT / 2)));
  return out;
}

function collectPinnedHotDirectoryPaths(rootNode = null) {
  const startNode = rootNode || WS.root;
  if (!startNode) return [];
  const scoreMemo = new Map();
  const scoreDir = (dirNode) => {
    if (!dirNode) return 0;
    const key = String(dirNode.path || "");
    if (scoreMemo.has(key)) return scoreMemo.get(key) || 0;
    let score =
      getOrderedFileIdsForDir(dirNode, false).length +
      getChildDirsForNode(dirNode).length;
    const children = getChildDirsForNode(dirNode);
    for (let i = 0; i < children.length; i++) score += scoreDir(children[i]);
    scoreMemo.set(key, score);
    return score;
  };
  const allDirs = [];
  const stack = [startNode];
  while (stack.length) {
    const dirNode = stack.pop();
    if (!dirNode) continue;
    allDirs.push(dirNode);
    const children = getChildDirsForNode(dirNode);
    for (let i = children.length - 1; i >= 0; i--) stack.push(children[i]);
  }
  allDirs.sort((a, b) => scoreDir(b) - scoreDir(a));
  const out = [];
  const seen = new Set();
  const pushPath = (dirNode) => {
    if (!dirNode) return;
    const path = String(dirNode.path || "");
    if (seen.has(path)) return;
    seen.add(path);
    out.push(path);
  };
  pushPath(startNode);
  for (
    let i = 0;
    i < allDirs.length && out.length < HOT_NAV_LARGE_DIR_LIMIT + 1;
    i++
  ) {
    pushPath(allDirs[i]);
  }
  return out;
}

function syncPinnedHotNavigationDirectories(rootNode = null) {
  PINNED_HOT_NAV_DIR_PATHS.clear();
  const paths = collectPinnedHotDirectoryPaths(rootNode || WS.root);
  for (let i = 0; i < paths.length; i++)
    PINNED_HOT_NAV_DIR_PATHS.add(String(paths[i] || ""));
  return paths;
}

function collectEffectiveHotDirectoryPaths(snapshot) {
  const paths = [];
  const seen = new Set();
  const pushPath = (pathValue) => {
    const path = String(pathValue || "");
    if (seen.has(path)) return;
    seen.add(path);
    paths.push(path);
  };
  PINNED_HOT_NAV_DIR_PATHS.forEach((path) => pushPath(path));
  const nearby = collectNearbyDirectoryPaths(snapshot);
  for (let i = 0; i < nearby.length; i++) pushPath(nearby[i]);
  return paths;
}

function rememberPinnedHotDecode(img, key) {
  if (!img || !key) return;
  if (PINNED_HOT_NAV_DECODE_CACHE.has(key))
    PINNED_HOT_NAV_DECODE_CACHE.delete(key);
  PINNED_HOT_NAV_DECODE_CACHE.set(key, img);
  while (PINNED_HOT_NAV_DECODE_CACHE.size > PINNED_HOT_NAV_DECODE_LIMIT) {
    const oldest = PINNED_HOT_NAV_DECODE_CACHE.keys().next();
    if (oldest && !oldest.done)
      PINNED_HOT_NAV_DECODE_CACHE.delete(oldest.value);
    else break;
  }
}

async function warmPinnedNavigationThumbDecode(rec) {
  if (!rec || !rec.id) return;
  const src =
    rec.type === "video"
      ? String(rec.videoThumbUrl || "")
      : String(rec.thumbUrl || "");
  if (!src) return;
  const key = `${String(rec.id || "")}###${src}`;
  if (PINNED_HOT_NAV_DECODE_CACHE.has(key)) {
    const img = PINNED_HOT_NAV_DECODE_CACHE.get(key);
    PINNED_HOT_NAV_DECODE_CACHE.delete(key);
    PINNED_HOT_NAV_DECODE_CACHE.set(key, img);
    return;
  }
  const img = new Image();
  img.decoding = "async";
  img.loading = "eager";
  img.src = src;
  try {
    if (typeof img.decode === "function") await img.decode();
  } catch {}
  rememberPinnedHotDecode(img, key);
}

function touchHotNavigationDirectoryPaths(paths) {
  const list = Array.isArray(paths) ? paths : [];
  for (let i = 0; i < list.length; i++) {
    const path = String(list[i] || "");
    if (HOT_NAV_DIR_PATHS.has(path)) HOT_NAV_DIR_PATHS.delete(path);
    HOT_NAV_DIR_PATHS.set(path, Date.now());
  }
  while (HOT_NAV_DIR_PATHS.size > HOT_NAV_MAX_DIRS) {
    const oldest = HOT_NAV_DIR_PATHS.keys().next();
    if (oldest && !oldest.done) HOT_NAV_DIR_PATHS.delete(oldest.value);
    else break;
  }
}

function releaseColdNavigationThumbs() {
  return;
}

async function warmNearbyDirectoriesInRam(snapshot) {
  const records = navigationSnapshotPendingRecords(snapshot, { full: true });
  if (!records.length) return;
  await runWithConcurrency(
    records,
    navigationThumbWorkerLimit("background"),
    ensureNavigationThumbReady,
  );
  releaseColdNavigationThumbs();
}

function scheduleNearbyDirectoryRamWarm(snapshot, delayMs = 0) {
  if (!thumbnailPushQueueEnabled()) return;
  const token = ++HOT_NAV_CACHE_TOKEN;
  if (HOT_NAV_CACHE_TIMER) {
    try {
      clearTimeout(HOT_NAV_CACHE_TIMER);
    } catch {}
  }
  const waitMs = shouldDeferNonEssentialNavigationWork()
    ? Math.max(180, Number(delayMs) || 0)
    : Math.max(0, Number(delayMs) || 0);
  HOT_NAV_CACHE_TIMER = setTimeout(() => {
    HOT_NAV_CACHE_TIMER = 0;
    if (token !== HOT_NAV_CACHE_TOKEN) return;
    warmNearbyDirectoriesInRam(snapshot).catch(() => {});
  }, waitMs);
}

function navigationSnapshotPendingRecords(snapshot, opts = null) {
  const options = opts && typeof opts === "object" ? opts : {};
  const records = collectNavigationSnapshotRecords(snapshot, options);
  return records.filter((rec) => {
    if (!rec) return false;
    if (rec.type === "video") {
      const mode = currentVideoThumbMode();
      if (videoThumbModeSkipsLoading(mode)) return false;
      return !(rec.videoThumbUrl && rec.videoThumbMode === mode);
    }
    if (rec.type === "image") {
      const mode = currentImageThumbMode();
      if (imageThumbModeSkipsLoading(mode)) return false;
      return !(rec.thumbUrl && rec.thumbMode === mode);
    }
    return false;
  });
}

async function ensureNavigationSnapshotReady(snapshot, opts = null) {
  const records = navigationSnapshotPendingRecords(snapshot, opts);
  if (!records.length) return;
  await runWithConcurrency(
    records,
    navigationThumbWorkerLimit("blocking"),
    ensureNavigationThumbReady,
  );
}

async function prepareInteractiveNavigationSnapshot(snapshot) {
  if (loadingScreensEnabled()) {
    return prepareNavigationSnapshot(
      snapshot,
      "Preparing directory thumbnails...",
    );
  }
  return true;
}

async function prepareNavigationSnapshot(
  snapshot,
  label = "Preparing thumbnails...",
) {
  if (!loadingScreensEnabled()) {
    scheduleNearbyDirectoryRamWarm(snapshot);
    return true;
  }
  const pending = navigationSnapshotPendingRecords(snapshot, { full: true });
  if (!pending.length) {
    scheduleNearbyDirectoryRamWarm(snapshot);
    return true;
  }
  const token = ++NAVIGATION_PREP_TOKEN;
  showBusyOverlay(label);
  try {
    await runWithConcurrency(
      pending,
      navigationThumbWorkerLimit("blocking"),
      ensureNavigationThumbReady,
    );
  } finally {
    if (token === NAVIGATION_PREP_TOKEN) hideBusyOverlay();
  }
  if (token === NAVIGATION_PREP_TOKEN) scheduleNearbyDirectoryRamWarm(snapshot);
  return token === NAVIGATION_PREP_TOKEN;
}

let NAVIGATION_RENDER_TOKEN = 0;
function cancelPendingNavigationRender() {
  NAVIGATION_RENDER_TOKEN++;
}

async function finalizeDirectoryNavigationRender(opts = null) {
  const options = opts && typeof opts === "object" ? opts : {};
  const animatePreview = options.animatePreview !== false;
  const keepDirectoriesScroll = !!options.keepDirectoriesScroll;
  const keepPreviewScroll = !!options.keepPreviewScroll;
  const activatePreviewSelectionAfterRender =
    !!options.activatePreviewSelection;
  const shouldRecordHistory = !!options.recordHistory;
  const snapshot = currentNavigationSnapshot();
  const token = ++NAVIGATION_RENDER_TOKEN;
  if (loadingScreensEnabled()) {
    await prepareNavigationSnapshot(
      snapshot,
      "Preparing directory thumbnails...",
    );
  } else {
    scheduleNearbyDirectoryRamWarm(snapshot);
  }
  if (token !== NAVIGATION_RENDER_TOKEN) return false;
  renderDirectoriesPane(keepDirectoriesScroll);
  renderPreviewPane(animatePreview, keepPreviewScroll);
  if (activatePreviewSelectionAfterRender && WS.view.activePane === "preview")
    activatePreviewPaneSelection();
  else updatePreviewSelectionClasses();
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  if (shouldRecordHistory) recordDirHistory();
  return true;
}

async function warmWorkspaceNavigationThumbsInBackground(
  rootNode = null,
  token = 0,
) {
  return;
}

function scheduleWorkspaceNavigationWarm(rootNode = null, delayMs = 1200) {
  return;
}

function notifyScrubMissingTools(missingTools) {
  const list = Array.from(
    new Set(
      (missingTools || []).map((v) => String(v || "").trim()).filter(Boolean),
    ),
  );
  if (!list.length) return;
  if (!notificationsEnabledForSource("generation")) return;
  const msg = `Scrub completed, but these tools are missing:\n\n${list.map((t) => `- ${t}`).join("\n")}`;
  showStatusMessage(`Scrub missing tools: ${list.join(", ")}`);
  try {
    if (typeof window !== "undefined" && typeof window.alert === "function") {
      window.alert(msg);
    }
  } catch {}
}

async function scrubFoldersByPaths(paths, opts = {}) {
  if (!WS.meta.fsRootHandle) {
    showStatusMessage("Scrub requires a writable folder.");
    return { ok: false, missingTools: [], failed: [], skipped: [] };
  }
  const list = Array.from(
    new Set((paths || []).map((p) => String(p || "")).filter(Boolean)),
  );
  if (!list.length) {
    showStatusMessage("No folders selected.");
    return { ok: false, missingTools: [], failed: [], skipped: [] };
  }
  const electronApi =
    typeof window !== "undefined" &&
    window.electronAPI &&
    typeof window.electronAPI.scrubFolder === "function"
      ? window.electronAPI
      : null;
  if (!electronApi) {
    showStatusMessage("Scrub is unavailable.");
    return { ok: false, missingTools: [], failed: [], skipped: [] };
  }

  const missingSet = new Set();
  const failed = [];
  const skipped = [];

  showBusyOverlay(
    list.length > 1 ? "Scrubbing folders..." : "Scrubbing folder...",
  );
  try {
    for (let i = 0; i < list.length; i++) {
      const relPath = list[i];
      const labelPath = displayPath(relPath || "");
      showBusyOverlay(
        `Scrubbing ${i + 1}/${list.length}: ${labelPath || relPath || "folder"}`,
      );
      const absPath = resolveAbsoluteDirectoryPath(relPath);
      if (!absPath) {
        skipped.push(relPath);
        continue;
      }
      let result = null;
      try {
        result = await electronApi.scrubFolder({ path: absPath });
      } catch (err) {
        result = {
          ok: false,
          error: err && err.message ? String(err.message) : "scrub_failed",
          missingTools: [],
        };
      }
      const missing =
        result && Array.isArray(result.missingTools) ? result.missingTools : [];
      for (const tool of missing) {
        const t = String(tool || "").trim();
        if (!t) continue;
        missingSet.add(t);
      }
      if (!result || !result.ok) {
        failed.push({
          path: relPath,
          error: String(result?.error || `exit_${result?.code ?? "unknown"}`),
        });
      }
    }
  } finally {
    hideBusyOverlay();
  }

  if (opts.refresh !== false && WS.meta.fsRootHandle) {
    await refreshWorkspaceFromRootHandle();
  }

  const okCount = list.length - failed.length - skipped.length;
  if (failed.length) {
    showStatusMessage(
      `Scrub finished with ${failed.length} error${failed.length === 1 ? "" : "s"}.`,
    );
  } else if (okCount > 0) {
    showStatusMessage(
      `Scrub complete for ${okCount} folder${okCount === 1 ? "" : "s"}.`,
    );
  } else {
    showStatusMessage("Scrub skipped.");
  }

  notifyScrubMissingTools(Array.from(missingSet));
  return {
    ok: failed.length === 0,
    missingTools: Array.from(missingSet),
    failed,
    skipped,
  };
}

function chooseLooseSetFolderNameFromRecords(records) {
  const names = [];
  for (const rec of records || []) {
    const name = String(rec?.name || "").trim();
    if (name) names.push(name);
  }
  if (!names.length) return "New Folder";
  names.sort((a, b) =>
    a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" }),
  );
  let first = names[0] || "New Folder";
  let base = first;
  if (first.includes(".") && !first.startsWith(".")) {
    base = first.slice(0, first.lastIndexOf("."));
  }
  base = normalizeFolderNameInput(base);
  return base || "New Folder";
}

async function entryExistsInDir(dirHandle, name) {
  if (!dirHandle || !name) return false;
  try {
    await dirHandle.getFileHandle(name);
    return true;
  } catch {}
  try {
    await dirHandle.getDirectoryHandle(name);
    return true;
  } catch {}
  return false;
}

function splitNameExtension(name) {
  const raw = String(name || "");
  if (raw.includes(".") && !raw.startsWith(".")) {
    const idx = raw.lastIndexOf(".");
    if (idx > 0) return { base: raw.slice(0, idx), ext: raw.slice(idx) };
  }
  return { base: raw, ext: "" };
}

async function uniqueDestNameInDir(dirHandle, name) {
  const { base, ext } = splitNameExtension(name);
  let candidate = `${base}${ext}`;
  let n = 2;
  while (await entryExistsInDir(dirHandle, candidate)) {
    candidate = `${base} (${n})${ext}`;
    n += 1;
  }
  return candidate;
}

async function uniqueDirNameInParent(parentHandle, name) {
  let candidate = String(name || "") || "Merged Items";
  let n = 2;
  while (await entryExistsInDir(parentHandle, candidate)) {
    candidate = `${name} (${n})`;
    n += 1;
  }
  return candidate;
}

function normalizeSetMergeFolderBase(name) {
  let base = String(name || "");
  const extIdx = base.lastIndexOf(".");
  if (extIdx > 0 && !base.startsWith(".")) base = base.slice(0, extIdx);
  base = base.replace(/_[0-9]+$/g, "");
  base = normalizeFolderNameInput(base);
  return base || "Merged Items";
}

async function chooseSetMergeOutputName(dirHandles) {
  const names = [];
  for (const handle of dirHandles || []) {
    if (!handle) continue;
    for await (const [name] of handle.entries()) {
      if (!name) continue;
      if (name === ".local-gallery") continue;
      names.push(name);
    }
  }
  if (!names.length) return "Merged Items";
  names.sort((a, b) =>
    a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" }),
  );
  const first = names[0] || "Merged Items";
  return normalizeSetMergeFolderBase(first);
}

async function moveEntryWithCollisionRename(
  srcDirHandle,
  entryHandle,
  entryName,
  destDirHandle,
  outInfo,
) {
  if (!srcDirHandle || !entryHandle || !destDirHandle) return false;
  const desiredName = await uniqueDestNameInDir(destDirHandle, entryName);
  if (typeof entryHandle.move === "function") {
    try {
      await entryHandle.move(destDirHandle, desiredName);
      if (outInfo && typeof outInfo === "object")
        outInfo.movedName = desiredName;
      return true;
    } catch {}
  }
  if (entryHandle.kind === "file") {
    try {
      const file = await entryHandle.getFile();
      const dstFile = await destDirHandle.getFileHandle(desiredName, {
        create: true,
      });
      const writable = await dstFile.createWritable();
      await writable.write(file);
      await writable.close();
      await srcDirHandle.removeEntry(entryName);
      if (outInfo && typeof outInfo === "object")
        outInfo.movedName = desiredName;
      return true;
    } catch {}
    return false;
  }
  if (entryHandle.kind === "directory") {
    try {
      const dstDir = await destDirHandle.getDirectoryHandle(desiredName, {
        create: true,
      });
      await copyDirectoryHandle(entryHandle, dstDir);
      await srcDirHandle.removeEntry(entryName, { recursive: true });
      if (outInfo && typeof outInfo === "object")
        outInfo.movedName = desiredName;
      return true;
    } catch {}
    return false;
  }
  return false;
}

function collapseNestedFolderPaths(paths) {
  const unique = Array.from(
    new Set((paths || []).map((p) => normalizeWorkspaceRelPath(p)).filter(Boolean)),
  );
  unique.sort((a, b) => {
    const depthA = a.split("/").filter(Boolean).length;
    const depthB = b.split("/").filter(Boolean).length;
    if (depthA !== depthB) return depthA - depthB;
    return a.localeCompare(b, undefined, {
      numeric: true,
      sensitivity: "base",
    });
  });
  const out = [];
  for (let i = 0; i < unique.length; i++) {
    const path = unique[i];
    if (out.some((parent) => path === parent || path.startsWith(parent + "/")))
      continue;
    out.push(path);
  }
  return out;
}

async function moveDirectoryOnDiskToParent(oldPath, destParentPath, newName) {
  const rootHandle = WS.meta.fsRootHandle;
  if (!rootHandle) throw new Error("No writable folder loaded.");
  const parts = String(oldPath || "")
    .split("/")
    .filter(Boolean);
  const oldName = parts.pop() || "";
  const srcParentPath = parts.join("/");
  if (!oldName) throw new Error("Folder path is unavailable.");
  const srcParentHandle = await getDirectoryHandleForPath(rootHandle, srcParentPath);
  const destParentHandle = await getDirectoryHandleForPath(
    rootHandle,
    destParentPath,
  );
  let existing = null;
  try {
    existing = await destParentHandle.getDirectoryHandle(newName);
  } catch {}
  if (existing) throw new Error("Target folder exists.");
  const srcHandle = await srcParentHandle.getDirectoryHandle(oldName);
  if (typeof srcHandle.move === "function") {
    try {
      await srcHandle.move(destParentHandle, newName);
      invalidateDirHandleCache(srcParentPath);
      invalidateDirHandleCache(destParentPath);
      return;
    } catch {}
  }
  const dstHandle = await destParentHandle.getDirectoryHandle(newName, {
    create: true,
  });
  await copyDirectoryHandle(srcHandle, dstHandle);
  await srcParentHandle.removeEntry(oldName, { recursive: true });
  invalidateDirHandleCache(srcParentPath);
  invalidateDirHandleCache(destParentPath);
}

async function persistDirtyMetadataNow() {
  if (WS.meta.storageMode === "fs") await metaSaveFsNow();
  else metaSaveLocalNow();
}

async function moveFolderPathsToTrash(paths) {
  if (!WS.meta.fsRootHandle) {
    showStatusMessage("Move to trash requires a writable folder.");
    return false;
  }
  const list = collapseNestedFolderPaths(paths).filter(
    (path) => path && !isPathInsideInternalTrash(path),
  );
  if (!list.length) {
    showStatusMessage("No folders selected.");
    return false;
  }
  const rootHandle = WS.meta.fsRootHandle;
  let trashHandle = null;
  try {
    trashHandle = await rootHandle.getDirectoryHandle(INTERNAL_TRASH_DIR_NAME, {
      create: true,
    });
  } catch {}
  if (!trashHandle) {
    showStatusMessage("Trash folder is unavailable.");
    return false;
  }
  const failed = [];
  const moved = [];
  showBusyOverlay("Moving folders to Trash...");
  try {
    for (let i = 0; i < list.length; i++) {
      const path = list[i];
      const parts = path.split("/").filter(Boolean);
      const folderName = parts.pop() || "";
      const parentPath = parts.join("/");
      if (!folderName || isInternalTrashDirName(folderName)) {
        failed.push(path);
        continue;
      }
      let parentHandle = null;
      let entryHandle = null;
      try {
        parentHandle = await getDirectoryHandleForPath(rootHandle, parentPath);
        entryHandle = await parentHandle.getDirectoryHandle(folderName);
      } catch {}
      if (!parentHandle || !entryHandle) {
        failed.push(path);
        continue;
      }
      try {
        const movedName = await uniqueDirNameInParent(trashHandle, folderName);
        const trashPath = `${INTERNAL_TRASH_DIR_NAME}/${movedName}`;
        await moveDirectoryOnDiskToParent(path, INTERNAL_TRASH_DIR_NAME, movedName);
        const dirNode = WS.dirByPath.get(path) || null;
        const trashRootNode =
          getInternalTrashRootNode() || ensureDirPath(INTERNAL_TRASH_DIR_NAME);
        if (dirNode && trashRootNode) {
          applyDirectoryMoveInMemory(dirNode, trashRootNode, movedName);
        } else {
          updateMetaPathsForRename(path, trashPath);
          updateViewStatePathsForRename(path, trashPath);
          updateFileRecordsForRename(path, trashPath);
        }
        metaTrackDirtyDocIds([
          META_DOC_IDS.scores,
          META_DOC_IDS.scoreHistory,
          META_DOC_IDS.tags,
          META_DOC_IDS.thumbnails,
          META_DOC_IDS.appearanceAssignments,
          META_DOC_IDS.trash,
        ]);
        metaSetTrashRestoreInfo(trashPath, path);
        moved.push(path);
      } catch {
        failed.push(path);
      }
    }
  } finally {
    hideBusyOverlay();
  }
  if (!moved.length && failed.length) {
    showStatusMessage("Move to trash failed.");
    return false;
  }
  await persistDirtyMetadataNow();
  await refreshWorkspaceFromRootHandle();
  if (failed.length) {
    showStatusMessage(
      `Moved ${moved.length} folder${moved.length === 1 ? "" : "s"} to Trash. ${failed.length} failed.`,
    );
  } else {
    showStatusMessage(
      `Moved ${moved.length} folder${moved.length === 1 ? "" : "s"} to Trash.`,
    );
  }
  return moved.length > 0;
}

async function putBackTrashFolderPaths(paths) {
  if (!WS.meta.fsRootHandle) {
    showStatusMessage("Put Back requires a writable folder.");
    return false;
  }
  const list = collapseNestedFolderPaths(paths).filter((path) =>
    isPutBackEligibleTrashPath(path),
  );
  if (!list.length) {
    showStatusMessage("No trashed folders selected.");
    return false;
  }
  const rootHandle = WS.meta.fsRootHandle;
  const failed = [];
  const skipped = [];
  const restored = [];
  showBusyOverlay("Putting folders back...");
  try {
    for (let i = 0; i < list.length; i++) {
      const trashPath = list[i];
      const restoreInfo = metaGetTrashRestoreInfo(trashPath);
      const originalPath = normalizeWorkspaceRelPath(restoreInfo?.originalPath);
      if (!originalPath) {
        skipped.push(trashPath);
        continue;
      }
      const parts = originalPath.split("/").filter(Boolean);
      const folderName = parts.pop() || "";
      const parentPath = parts.join("/");
      if (!folderName) {
        skipped.push(trashPath);
        continue;
      }
      let parentHandle = null;
      try {
        parentHandle = await getDirectoryHandleForPath(rootHandle, parentPath);
      } catch {}
      if (!parentHandle) {
        skipped.push(trashPath);
        continue;
      }
      try {
        if (await entryExistsInDir(parentHandle, folderName)) {
          skipped.push(trashPath);
          continue;
        }
        await moveDirectoryOnDiskToParent(trashPath, parentPath, folderName);
        const dirNode = WS.dirByPath.get(trashPath) || null;
        const restoreParentNode =
          WS.dirByPath.get(parentPath) || ensureDirPath(parentPath);
        if (dirNode) {
          applyDirectoryMoveInMemory(dirNode, restoreParentNode, folderName);
        } else {
          updateMetaPathsForRename(trashPath, originalPath);
          updateViewStatePathsForRename(trashPath, originalPath);
          updateFileRecordsForRename(trashPath, originalPath);
        }
        metaTrackDirtyDocIds([
          META_DOC_IDS.scores,
          META_DOC_IDS.scoreHistory,
          META_DOC_IDS.tags,
          META_DOC_IDS.thumbnails,
          META_DOC_IDS.appearanceAssignments,
          META_DOC_IDS.trash,
        ]);
        metaDeleteTrashRestoreInfo(trashPath);
        restored.push(trashPath);
      } catch {
        failed.push(trashPath);
      }
    }
  } finally {
    hideBusyOverlay();
  }
  if (!restored.length && (failed.length || skipped.length)) {
    showStatusMessage(
      failed.length
        ? `Put Back failed for ${failed.length} folder${failed.length === 1 ? "" : "s"}.`
        : "Put Back skipped.",
    );
    return false;
  }
  await persistDirtyMetadataNow();
  await refreshWorkspaceFromRootHandle();
  const parts = [];
  parts.push(
    `Put back ${restored.length} folder${restored.length === 1 ? "" : "s"}.`,
  );
  if (skipped.length)
    parts.push(`${skipped.length} skipped.`);
  if (failed.length)
    parts.push(`${failed.length} failed.`);
  showStatusMessage(parts.join(" "));
  return restored.length > 0;
}

async function deleteFolderPathsPermanently(paths) {
  if (!WS.meta.fsRootHandle) {
    showStatusMessage("Delete requires a writable folder.");
    return false;
  }

  const uniquePaths = Array.from(
    new Set((paths || []).map((p) => String(p || "").trim()).filter(Boolean)),
  );
  if (!uniquePaths.length) {
    showStatusMessage("No folders selected.");
    return false;
  }

  uniquePaths.sort((a, b) => {
    const depthA = a.split("/").filter(Boolean).length;
    const depthB = b.split("/").filter(Boolean).length;
    if (depthA !== depthB) return depthB - depthA;
    return a.localeCompare(b, undefined, {
      numeric: true,
      sensitivity: "base",
    });
  });

  const rootHandle = WS.meta.fsRootHandle;
  const targets = [];
  for (const path of uniquePaths) {
    const normalizedPath = normalizeWorkspaceRelPath(path);
    if (!normalizedPath) continue;
    const parts = normalizedPath.split("/").filter(Boolean);
    const folderName = parts.pop() || "";
    const parentPath = parts.join("/");
    if (!folderName) continue;
    if (folderName === ".local-gallery" || parts.includes(".local-gallery"))
      continue;

    let parentHandle = null;
    try {
      parentHandle = await getDirectoryHandleForPath(rootHandle, parentPath);
    } catch {}
    if (!parentHandle) continue;

    let entryHandle = null;
    try {
      entryHandle = await parentHandle.getDirectoryHandle(folderName);
    } catch {}
    if (!entryHandle) continue;

    targets.push({
      path: normalizedPath,
      parentPath,
      folderName,
      parentHandle,
      entryHandle,
    });
  }

  if (!targets.length) {
    showStatusMessage("No folders available.");
    return false;
  }

  const label =
    targets.length === 1
      ? "Deleting folder..."
      : `Deleting ${targets.length} folders...`;
  showBusyOverlay(label);
  let deleted = 0;
  let failed = 0;
  try {
    for (const t of targets) {
      try {
        await t.parentHandle.removeEntry(t.folderName, { recursive: true });
        deleted++;
        invalidateDirHandleCache(t.path);
        invalidateDirHandleCache(t.parentPath);
      } catch {
        failed++;
      }
    }
  } finally {
    hideBusyOverlay();
  }

  if (!deleted) {
    showStatusMessage("Delete failed.");
    return false;
  }

  try {
    await refreshWorkspaceFromRootHandle();
  } catch {}

  if (failed > 0) {
    showStatusMessage(
      `Deleted ${deleted} folder${deleted === 1 ? "" : "s"}. ${failed} failed.`,
    );
  } else {
    showStatusMessage(`Deleted ${deleted} folder${deleted === 1 ? "" : "s"}.`);
  }
  return true;
}

async function setMergeSelectedDirs() {
  if (!WS.meta.fsRootHandle) {
    showStatusMessage("Set Merge requires a writable folder.");
    return false;
  }
  const selectedPaths = getSelectedPathsInCurrentDir()
    .map((p) => String(p || ""))
    .filter(Boolean);
  if (!selectedPaths.length) {
    showStatusMessage("No folders selected.");
    return false;
  }
  const uniquePaths = Array.from(new Set(selectedPaths));
  const firstParts = uniquePaths[0].split("/").filter(Boolean);
  const parentPath = firstParts.slice(0, -1).join("/");
  for (const p of uniquePaths) {
    const parts = String(p || "")
      .split("/")
      .filter(Boolean);
    const parent = parts.slice(0, -1).join("/");
    if (parent !== parentPath) {
      showStatusMessage("Selected folders must be in the same parent folder.");
      return false;
    }
  }

  const rootHandle = WS.meta.fsRootHandle;
  let parentHandle = null;
  try {
    parentHandle = await getDirectoryHandleForPath(rootHandle, parentPath);
  } catch {}
  if (!parentHandle) {
    showStatusMessage("Folder handle unavailable.");
    return false;
  }

  const dirHandles = [];
  for (const p of uniquePaths) {
    try {
      dirHandles.push(await getDirectoryHandleForPath(rootHandle, p));
    } catch {}
  }
  if (!dirHandles.length) {
    showStatusMessage("No folders available.");
    return false;
  }

  const desiredBase = await chooseSetMergeOutputName(dirHandles);
  const tmpBase = `${desiredBase} (Merging)`;
  const tmpName = await uniqueDirNameInParent(parentHandle, tmpBase);
  let tmpHandle = null;
  try {
    tmpHandle = await parentHandle.getDirectoryHandle(tmpName, {
      create: true,
    });
  } catch {}
  if (!tmpHandle) {
    showStatusMessage("Failed to create merge folder.");
    return false;
  }

  for (let i = 0; i < dirHandles.length; i++) {
    const handle = dirHandles[i];
    const path = uniquePaths[i];
    if (!handle || !path) continue;
    for await (const [name, entryHandle] of handle.entries()) {
      if (!name || name === ".local-gallery") continue;
      const ok = await moveEntryWithCollisionRename(
        handle,
        entryHandle,
        name,
        tmpHandle,
      );
      if (!ok) {
        showStatusMessage(`Move failed for ${name}.`);
        return false;
      }
    }
    const folderName = path.split("/").filter(Boolean).pop();
    if (folderName) {
      try {
        await parentHandle.removeEntry(folderName, { recursive: true });
      } catch {}
    }
  }

  let finalName = desiredBase;
  if (await entryExistsInDir(parentHandle, finalName)) {
    finalName = await uniqueDirNameInParent(parentHandle, desiredBase);
  }

  const tmpPath = parentPath ? parentPath + "/" + tmpName : tmpName;
  try {
    await renameDirectoryOnDisk(tmpPath, finalName);
  } catch {
    showStatusMessage("Failed to finalize merged folder.");
    return false;
  }

  finalizeBulkSelectionAction();
  closeActionMenus();
  await refreshWorkspaceFromRootHandle();

  const finalPath = parentPath ? parentPath + "/" + finalName : finalName;
  const idx = findDirEntryIndexByPath(finalPath);
  if (idx >= 0) {
    WS.nav.selectedIndex = findNearestSelectableIndex(idx, 1);
    syncPreviewToSelection({ force: true });
    renderDirectoriesPane(true);
    renderPreviewPane(true);
    syncButtons();
    kickVideoThumbsForPreview();
    kickImageThumbsForPreview();
  }
  showStatusMessage("Set Merge complete.");
  return true;
}

async function moveFileToDirectoryHandle(srcDirHandle, dstDirHandle, name) {
  if (!srcDirHandle || !dstDirHandle) return false;
  const fname = String(name || "");
  if (!fname) return false;
  let fileHandle = null;
  try {
    fileHandle = await srcDirHandle.getFileHandle(fname);
  } catch {}
  if (!fileHandle) return false;
  if (typeof fileHandle.move === "function") {
    try {
      await fileHandle.move(dstDirHandle, fname);
      return true;
    } catch {}
  }
  try {
    const file = await fileHandle.getFile();
    const dstFile = await dstDirHandle.getFileHandle(fname, { create: true });
    const writable = await dstFile.createWritable();
    await writable.write(file);
    await writable.close();
    await srcDirHandle.removeEntry(fname);
    return true;
  } catch {}
  return false;
}

function updateFileRecordsForFileMoves(oldDirPath, newDirPath, fileIds) {
  const idSet = new Set((fileIds || []).map((id) => String(id || "")));
  if (!idSet.size) return;
  const idMap = new Map();
  const relPathMap = new Map();
  const nextFileById = new Map();
  const movedNewIds = [];

  for (const [id, rec] of WS.fileById.entries()) {
    const key = String(id || "");
    if (!idSet.has(key)) {
      nextFileById.set(id, rec);
      continue;
    }
    const oldRelPath = String(rec.relPath || "");
    const relPath = newDirPath ? newDirPath + "/" + rec.name : rec.name;
    rec.dirPath = newDirPath;
    rec.relPath = relPath;
    const nextId = fileKeyForRecord(rec, relPath);
    if (oldRelPath && relPath && oldRelPath !== relPath)
      relPathMap.set(oldRelPath, relPath);
    rec.id = nextId;
    if (nextId !== id) idMap.set(id, nextId);
    nextFileById.set(nextId, rec);
    movedNewIds.push(nextId);
  }

  WS.fileById = nextFileById;

  const oldNode = WS.dirByPath.get(String(oldDirPath || "")) || null;
  if (oldNode && Array.isArray(oldNode.childrenFiles)) {
    oldNode.childrenFiles = oldNode.childrenFiles.filter(
      (id) => !idSet.has(String(id || "")),
    );
  }

  const newNode = WS.dirByPath.get(String(newDirPath || "")) || null;
  if (newNode && Array.isArray(newNode.childrenFiles)) {
    for (const id of movedNewIds) {
      if (!newNode.childrenFiles.includes(id)) newNode.childrenFiles.push(id);
    }
  }

  invalidateDirMetricsCaches();
  remapFileIdsAcrossViewState(idMap);
  remapFolderThumbnailPresetValues(relPathMap);
}

async function looseSetMergeSelectedFiles() {
  if (!WS.meta.fsRootHandle) {
    showStatusMessage("Loose Set Merge requires a writable folder.");
    return false;
  }
  const records = getSelectedFileRecordsInCurrentView();
  if (!records.length) {
    showStatusMessage("No files selected.");
    return false;
  }
  const parentPath = String(records[0].dirPath || "");
  for (const rec of records) {
    if (String(rec.dirPath || "") !== parentPath) {
      showStatusMessage("Selected files must be in the same folder.");
      return false;
    }
  }

  const folderNameRaw = chooseLooseSetFolderNameFromRecords(records);
  const folderName = normalizeFolderNameInput(folderNameRaw);
  if (!isValidFolderName(folderName)) {
    showStatusMessage("Invalid folder name.");
    return false;
  }

  const rootHandle = WS.meta.fsRootHandle;
  let parentHandle = null;
  try {
    parentHandle = await getDirectoryHandleForPath(rootHandle, parentPath);
  } catch {}
  if (!parentHandle) {
    showStatusMessage("Folder handle unavailable.");
    return false;
  }

  let existing = null;
  try {
    existing = await parentHandle.getDirectoryHandle(folderName);
  } catch {}
  if (existing) {
    showStatusMessage("A folder with that name already exists.");
    return false;
  }
  existing = null;
  try {
    existing = await parentHandle.getFileHandle(folderName);
  } catch {}
  if (existing) {
    showStatusMessage("A file with that name already exists.");
    return false;
  }

  let tmpName = "";
  for (let i = 0; i < 24; i++) {
    const cand = `.grouping_tmp.${Math.random().toString(36).slice(2, 8)}`;
    let has = false;
    try {
      await parentHandle.getDirectoryHandle(cand);
      has = true;
    } catch {}
    if (!has) {
      try {
        await parentHandle.getFileHandle(cand);
        has = true;
      } catch {}
    }
    if (has) continue;
    tmpName = cand;
    break;
  }
  if (!tmpName) {
    showStatusMessage("Failed to create temporary folder.");
    return false;
  }

  let tmpHandle = null;
  try {
    tmpHandle = await parentHandle.getDirectoryHandle(tmpName, {
      create: true,
    });
  } catch {}
  if (!tmpHandle) {
    showStatusMessage("Failed to create temporary folder.");
    return false;
  }

  for (const rec of records) {
    const ok = await moveFileToDirectoryHandle(
      parentHandle,
      tmpHandle,
      rec.name,
    );
    if (!ok) {
      showStatusMessage(`Move failed for ${rec.name || "file"}.`);
      return false;
    }
  }

  const tmpPath = parentPath ? parentPath + "/" + tmpName : tmpName;
  try {
    await renameDirectoryOnDisk(tmpPath, folderName);
  } catch {
    showStatusMessage("Failed to rename folder.");
    return false;
  }

  const newDirPath = parentPath ? parentPath + "/" + folderName : folderName;
  ensureDirPath(newDirPath);
  updateFileRecordsForFileMoves(
    parentPath,
    newDirPath,
    records.map((r) => r.id),
  );
  metaComputeFingerprints();
  metaTrackDirtyDocIds([
    META_DOC_IDS.scores,
    META_DOC_IDS.tags,
    META_DOC_IDS.thumbnails,
    META_DOC_IDS.appearanceAssignments,
  ]);
  try {
    if (WS.meta.storageMode === "fs") await metaSaveFsNow();
    else metaSaveLocalNow();
  } catch {}

  finalizeBulkSelectionAction();
  closeActionMenus();
  rebuildDirectoriesEntries();
  const idx = findDirEntryIndexByPath(newDirPath);
  WS.nav.selectedIndex = findNearestSelectableIndex(
    idx >= 0 ? idx : WS.nav.selectedIndex,
    1,
  );
  syncPreviewToSelection({ force: true });
  renderDirectoriesPane(true);
  renderPreviewPane(true);
  syncButtons();
  kickVideoThumbsForPreview();
  kickImageThumbsForPreview();
  showStatusMessage("Loose Set Merge complete.");
  return true;
}

function closeActionMenus() {
  WS.view.bulkActionMenuOpen = false;
  WS.view.bulkActionMenuAnchorPath = "";
  WS.view.dirActionMenuPath = "";
  WS.view.fileActionMenuId = "";
  closeTagContextMenu();
  closePreviewContextMenu();
}

function findTagEntryIndexBySelectionKey(selectionKey) {
  const key = String(selectionKey || "");
  if (!key) return -1;
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (!entry || entry.kind !== "tag") continue;
    if (tagEntrySelectionKey(entry) === key) return i;
  }
  return -1;
}

function openBulkActionMenuForSelection(anchorKey) {
  const key = String(anchorKey || "");
  if (!key) return false;
  if (!WS.view.bulkSelectMode) return false;
  const selectedDirs = getSelectedPathsInCurrentDir();
  const selectedTags = getSelectedTagFolderKeysInCurrentView();
  const selCount =
    selectedDirs.length +
    selectedTags.length +
    getSelectedFileIdsInCurrentView().length;
  if (!selCount) return false;
  if (key.startsWith("dir:")) {
    const p = key.slice(4);
    if (!selectedDirs.includes(p)) return false;
  } else if (key.startsWith("tag:")) {
    const tagKey = key.slice(4);
    if (!selectedTags.includes(tagKey)) return false;
  } else if (key.startsWith("file:")) {
    const fileId = key.slice(5);
    if (!getSelectedFileIdsInCurrentView().includes(fileId)) return false;
  } else {
    return false;
  }
  if (WS.view.bulkActionMenuOpen && WS.view.bulkActionMenuAnchorPath === key) {
    closeActionMenus();
    renderDirectoriesPane(true);
    renderPreviewPane(false, true);
    syncButtons();
    return true;
  }
  WS.view.bulkActionMenuOpen = true;
  WS.view.bulkActionMenuAnchorPath = key;
  WS.view.dirActionMenuPath = "";
  WS.view.fileActionMenuId = "";
  TAG_EDIT_PATH = null;
  RENAME_EDIT_PATH = null;
  RENAME_EDIT_FILE_ID = null;
  clearBulkTagPlaceholder();

  let idx = -1;
  if (key.startsWith("dir:")) {
    idx = findDirEntryIndexByPath(key.slice(4));
  } else if (key.startsWith("tag:")) {
    idx = findTagEntryIndexBySelectionKey(key.slice(4));
  } else if (key.startsWith("file:")) {
    const id = key.slice(5);
    for (let i = 0; i < WS.nav.entries.length; i++) {
      const e = WS.nav.entries[i];
      if (e && e.kind === "file" && String(e.id || "") === id) {
        idx = i;
        break;
      }
    }
  }
  if (idx >= 0) {
    WS.nav.selectedIndex = findNearestSelectableIndex(idx, 1);
    syncPreviewToSelection({ force: true });
  }
  renderDirectoriesPane(true);
  renderPreviewPane(false, true);
  syncButtons();
  return true;
}

function openDirMenuForPath(path) {
  const p = String(path || "");
  const isRootPath = p === "" && !!WS.root;
  if (
    !isRootPath &&
    p === INTERNAL_TRASH_DIR_NAME &&
    WS.nav.dirNode === WS.root
  ) {
    return;
  }
  if (!p && !isRootPath) return;
  if (!isRootPath && openBulkActionMenuForSelection(`dir:${p}`)) return;
  WS.view.bulkActionMenuOpen = false;
  WS.view.dirActionMenuPath = isRootPath ? "__root__" : p;
  WS.view.fileActionMenuId = "";
  TAG_EDIT_PATH = null;
  RENAME_EDIT_PATH = null;
  RENAME_EDIT_FILE_ID = null;
  clearBulkTagPlaceholder();

  const idx = findDirEntryIndexByPath(p);
  if (idx >= 0) {
    WS.nav.selectedIndex = findNearestSelectableIndex(idx, 1);
    syncPreviewToSelection({ force: true });
  }
  renderDirectoriesPane(true);
  renderPreviewPane(false, true);
  syncButtons();
}

function openFileMenuForId(fileId) {
  const id = String(fileId || "");
  if (!id) return;
  if (openBulkActionMenuForSelection(`file:${id}`)) return;
  WS.view.bulkActionMenuOpen = false;
  WS.view.dirActionMenuPath = "";
  WS.view.fileActionMenuId = id;
  TAG_EDIT_PATH = null;
  RENAME_EDIT_PATH = null;
  RENAME_EDIT_FILE_ID = null;
  clearBulkTagPlaceholder();

  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (entry && entry.kind === "file" && String(entry.id || "") === id) {
      WS.nav.selectedIndex = findNearestSelectableIndex(i, 1);
      syncPreviewToSelection({ force: true });
      break;
    }
  }
  renderDirectoriesPane(true);
  renderPreviewPane(false, true);
  syncButtons();
}

async function runFileActionFromMenu(action, fileId, rowEl = null) {
  const id = String(fileId || "");
  if (!id || !action) return false;

  if (action === "loose-set-merge") {
    if (!WS.meta.fsRootHandle) {
      showStatusMessage("Loose Set Merge requires a writable folder.");
      return true;
    }
    await looseSetMergeSelectedFiles();
    return true;
  }

  const rec = WS.fileById.get(id);
  if (!rec) {
    showStatusMessage("Selected file is unavailable.");
    return true;
  }

  if (action === "edit-thumbnail") {
    openThumbnailCropEditor(rec);
    return true;
  }

  const setFolderThumbPath = parseFolderThumbnailAction(action);
  if (setFolderThumbPath !== null) {
    setFolderThumbnailTargetFromRecord(rec, setFolderThumbPath);
    return true;
  }

  if (action === "set-parent-thumbnail") {
    setParentThumbnailFromRecord(rec);
    return true;
  }

  if (action === "set-folder-thumbnail") {
    setFolderThumbnailFromRecord(rec);
    return true;
  }

  if (action === "set-root-thumbnail") {
    setRootThumbnailFromRecord(rec);
    return true;
  }

  const setTagThumbKey = parseTagThumbnailAction(action);
  if (setTagThumbKey) {
    setTagThumbnailFromRecordByKey(rec, setTagThumbKey);
    return true;
  }

  if (action === "rename-file") {
    if (!WS.meta.fsRootHandle) {
      showStatusMessage("Renaming files requires a writable folder.");
      return true;
    }
    if (
      !rowEl &&
      WS.view?.activePane === "preview" &&
      startPreviewFileRenameEdit(id)
    ) {
      return true;
    }
    RENAME_EDIT_FILE_ID = id;
    RENAME_EDIT_PATH = null;
    TAG_EDIT_PATH = null;
    renderDirectoriesPane(true);
    renderPreviewPane(false, true);
    syncButtons();
    focusSelectedDirectoryInlineInput(".renameEditInput");
    return true;
  }

  return false;
}

function entryKeyForSelection(entry) {
  if (!entry) return "";
  if (entry.kind === "dir") return `dir:${String(entry.node?.path || "")}`;
  if (entry.kind === "file") return `file:${String(entry.id || "")}`;
  if (entry.kind === "tag") return `tag:${tagEntrySelectionKey(entry)}`;
  if (entry.kind === "up") return `up:${directoriesScrollContextKey()}`;
  return "";
}

function findEntryIndexByKey(key) {
  if (!key) return -1;
  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (entryKeyForSelection(entry) === key) return i;
  }
  return -1;
}

function toggleEntrySelection(entry) {
  if (!entry) return;
  if (entry.kind === "dir") {
    const p = String(entry.node?.path || "");
    if (!p) return;
    if (WS.view.bulkTagSelectedPaths.has(p))
      WS.view.bulkTagSelectedPaths.delete(p);
    else WS.view.bulkTagSelectedPaths.add(p);
  } else if (entry.kind === "tag") {
    const key = tagEntrySelectionKey(entry);
    if (!key) return;
    if (WS.view.bulkTagFolderSelectedKeys.has(key))
      WS.view.bulkTagFolderSelectedKeys.delete(key);
    else WS.view.bulkTagFolderSelectedKeys.add(key);
  } else if (entry.kind === "file") {
    const id = String(entry.id || "");
    if (!id) return;
    if (WS.view.bulkFileSelectedIds.has(id))
      WS.view.bulkFileSelectedIds.delete(id);
    else WS.view.bulkFileSelectedIds.add(id);
  }
}

function addEntrySelection(entry) {
  if (!entry) return;
  if (entry.kind === "dir") {
    const p = String(entry.node?.path || "");
    if (p) WS.view.bulkTagSelectedPaths.add(p);
  } else if (entry.kind === "tag") {
    const key = tagEntrySelectionKey(entry);
    if (key) WS.view.bulkTagFolderSelectedKeys.add(key);
  } else if (entry.kind === "file") {
    const id = String(entry.id || "");
    if (id) WS.view.bulkFileSelectedIds.add(id);
  }
}

function togglePreviewCardBulkSelection(card) {
  if (!card) return;
  const kind = String(card.dataset.previewItemKind || "");
  const key = String(card.dataset.previewItemKey || "");
  if (kind === "dir" && key.startsWith("dir:")) {
    const p = key.slice(4);
    if (!p) return;
    if (WS.view.bulkTagSelectedPaths.has(p))
      WS.view.bulkTagSelectedPaths.delete(p);
    else WS.view.bulkTagSelectedPaths.add(p);
  } else if (kind === "file" && key.startsWith("file:")) {
    const id = key.slice(5);
    if (!id) return;
    if (WS.view.bulkFileSelectedIds.has(id))
      WS.view.bulkFileSelectedIds.delete(id);
    else WS.view.bulkFileSelectedIds.add(id);
  } else if (kind === "tag" && key.startsWith("tag:")) {
    const tagKey = key.slice(4);
    if (!tagKey) return;
    if (WS.view.bulkTagFolderSelectedKeys.has(tagKey))
      WS.view.bulkTagFolderSelectedKeys.delete(tagKey);
    else WS.view.bulkTagFolderSelectedKeys.add(tagKey);
  }
}

function addPreviewCardBulkSelection(card) {
  if (!card) return;
  const kind = String(card.dataset.previewItemKind || "");
  const key = String(card.dataset.previewItemKey || "");
  if (kind === "dir" && key.startsWith("dir:")) {
    const p = key.slice(4);
    if (p) WS.view.bulkTagSelectedPaths.add(p);
  } else if (kind === "file" && key.startsWith("file:")) {
    const id = key.slice(5);
    if (id) WS.view.bulkFileSelectedIds.add(id);
  } else if (kind === "tag" && key.startsWith("tag:")) {
    const tagKey = key.slice(4);
    if (tagKey) WS.view.bulkTagFolderSelectedKeys.add(tagKey);
  }
}

function addPreviewSelectionRange(anchorKey, targetKey, clearExisting = false) {
  const cards = getPreviewSelectableCards();
  if (!cards.length) return;
  let anchorIdx = -1;
  let targetIdx = -1;
  for (let i = 0; i < cards.length; i++) {
    const key = String(cards[i]?.dataset?.previewItemKey || "");
    if (key === anchorKey) anchorIdx = i;
    if (key === targetKey) targetIdx = i;
  }
  if (anchorIdx < 0 || targetIdx < 0) return;
  if (clearExisting) clearBulkTagSelection();
  WS.view.bulkSelectMode = true;
  const start = Math.min(anchorIdx, targetIdx);
  const end = Math.max(anchorIdx, targetIdx);
  for (let i = start; i <= end; i++) {
    addPreviewCardBulkSelection(cards[i]);
  }
}

function refreshBulkSelectionUiFromPreview() {
  renderDirectoriesPane(true);
  updatePreviewSelectionClasses();
  syncButtons();
}

function includeCurrentSelectionInBulkSet(excludeIndex = -1) {
  const curIdx = Number(WS.nav.selectedIndex);
  if (!Number.isFinite(curIdx) || curIdx < 0 || curIdx >= WS.nav.entries.length)
    return;
  if (curIdx === Number(excludeIndex)) return;
  const current = WS.nav.entries[curIdx];
  if (!current || !isSelectableEntry(current)) return;
  addEntrySelection(current);
}

function selectEntryRange(anchorIdx, targetIdx) {
  addEntrySelectionRange(anchorIdx, targetIdx, true);
}

function addEntrySelectionRange(anchorIdx, targetIdx, clearExisting = false) {
  if (anchorIdx < 0 || targetIdx < 0) return;
  const start = Math.min(anchorIdx, targetIdx);
  const end = Math.max(anchorIdx, targetIdx);
  if (clearExisting) clearBulkTagSelection();
  WS.view.bulkSelectMode = true;
  for (let i = start; i <= end; i++) {
    const entry = WS.nav.entries[i];
    if (!entry || !isSelectableEntry(entry)) continue;
    addEntrySelection(entry);
  }
}

function canTrackDirHistory() {
  if (!WS.root) return false;
  if (!WS.nav.dirNode) return false;
  if (searchResultsVisibleInDirectoriesPane()) return false;
  if (WS.view.favoritesMode || WS.view.hiddenMode) return false;
  return true;
}

function recordDirHistory() {
  if (!canTrackDirHistory()) return;
  const path = String(WS.nav.dirNode?.path || "");
  const aboveRoot = !!WS.view.aboveRootView;
  const selectedKey = entryKeyForSelection(
    WS.nav.entries[WS.nav.selectedIndex] || null,
  );
  const cur = WS.view.dirHistory[WS.view.dirHistoryIndex] || null;
  if (cur && cur.path === path && !!cur.aboveRoot === aboveRoot) {
    cur.selectedKey = selectedKey;
    return;
  }
  if (WS.view.dirHistoryIndex < WS.view.dirHistory.length - 1) {
    WS.view.dirHistory = WS.view.dirHistory.slice(
      0,
      WS.view.dirHistoryIndex + 1,
    );
  }
  WS.view.dirHistory.push({ path, aboveRoot, selectedKey });
  WS.view.dirHistoryIndex = WS.view.dirHistory.length - 1;
}

function initDirHistory() {
  WS.view.dirHistory = [];
  WS.view.dirHistoryIndex = -1;
  if (!WS.root || !WS.nav.dirNode) return;
  const path = String(WS.nav.dirNode?.path || "");
  const selectedKey = entryKeyForSelection(
    WS.nav.entries[WS.nav.selectedIndex] || null,
  );
  WS.view.dirHistory.push({
    path,
    aboveRoot: !!WS.view.aboveRootView,
    selectedKey,
  });
  WS.view.dirHistoryIndex = 0;
}

async function restoreDirHistoryEntry(entry) {
  if (!entry || !WS.root) return;
  clearTagNavigationStack();
  WS.view.tagFolderActiveMode = "";
  WS.view.tagFolderActiveTag = "";
  WS.view.tagFolderActiveAlbum = "";
  WS.view.tagFolderOriginPath = "";
  const node = WS.dirByPath.get(String(entry.path || "")) || WS.root;
  WS.nav.dirNode = node;
  WS.view.aboveRootView =
    !!entry.aboveRoot && node === WS.root && showRootViewEnabled();
  syncBulkSelectionForCurrentDir();
  syncFavoritesUi();
  syncHiddenUi();
  syncTagUiForCurrentDir();
  rebuildDirectoriesEntries();
  const idx = findEntryIndexByKey(String(entry.selectedKey || ""));
  WS.nav.selectedIndex = findNearestSelectableIndex(idx >= 0 ? idx : 0, 1);
  syncPreviewToSelection({ force: true });
  await finalizeDirectoryNavigationRender({
    animatePreview: true,
    keepDirectoriesScroll: true,
    keepPreviewScroll: true,
  });
}

function positionDropdownMenu(menuBtn, menuEl) {
  if (!menuBtn || !menuEl) return;
  menuEl.classList.add("fixed");
  menuEl.style.left = "0px";
  menuEl.style.top = "0px";
  menuEl.style.right = "auto";

  const btnRect = menuBtn.getBoundingClientRect();
  const menuRect = menuEl.getBoundingClientRect();

  let left = btnRect.right - menuRect.width;
  if (left < 8) left = 8;
  if (left + menuRect.width > window.innerWidth - 8) {
    left = Math.max(8, window.innerWidth - menuRect.width - 8);
  }

  let top = btnRect.bottom + 4;
  if (top + menuRect.height > window.innerHeight - 8) {
    top = btnRect.top - 4 - menuRect.height;
  }
  if (top < 8) top = 8;

  menuEl.style.left = `${left}px`;
  menuEl.style.top = `${top}px`;
}

function positionDropdownMenuAtPoint(menuEl, x, y) {
  if (!menuEl) return;
  menuEl.classList.add("fixed");
  menuEl.style.left = "0px";
  menuEl.style.top = "0px";
  menuEl.style.right = "auto";

  const menuRect = menuEl.getBoundingClientRect();
  let left = x;
  let top = y;

  if (left + menuRect.width > window.innerWidth - 8) {
    left = Math.max(8, window.innerWidth - menuRect.width - 8);
  }
  if (top + menuRect.height > window.innerHeight - 8) {
    top = Math.max(8, window.innerHeight - menuRect.height - 8);
  }

  left = Math.max(8, left);
  top = Math.max(8, top);

  menuEl.style.left = `${left}px`;
  menuEl.style.top = `${top}px`;
}

async function commitRenameEdit(path, inputEl) {
  if (RENAME_BUSY) return;
  const dirNode = WS.dirByPath.get(String(path || ""));
  if (!dirNode) {
    RENAME_EDIT_PATH = null;
    renderDirectoriesPane(true);
    return;
  }
  RENAME_BUSY = true;
  const ok = await renameFolderDirNode(dirNode, inputEl.value || "");
  RENAME_BUSY = false;
  if (ok) {
    RENAME_EDIT_PATH = null;
    closeActionMenus();
    renderDirectoriesPane(true);
    renderPreviewPane(false, true);
    syncButtons();
    return;
  }
  renderDirectoriesPane(true);
}

async function commitFileRenameEdit(fileId, inputEl) {
  if (RENAME_BUSY) return;
  const rec = WS.fileById.get(String(fileId || ""));
  if (!rec) {
    RENAME_EDIT_FILE_ID = null;
    renderDirectoriesPane(true);
    return;
  }
  RENAME_BUSY = true;
  const ok = await renameSingleFile(rec, inputEl.value || "");
  RENAME_BUSY = false;
  if (ok) {
    RENAME_EDIT_FILE_ID = null;
    closeActionMenus();
    renderDirectoriesPane(true);
    renderPreviewPane(false, true);
    syncButtons();
    kickVideoThumbsForPreview();
    kickImageThumbsForPreview();
    return;
  }
  renderDirectoriesPane(true);
}

function getDirectoriesWithTag(tag) {
  if (!tag) return [];
  if (!WS.nav.dirNode) return [];
  const children = getChildDirsForNodeBase(WS.nav.dirNode);
  if (!children.length) return [];
  return children.filter((d) => {
    const tags = metaGetUserTags(d.path || "");
    return tags.includes(tag);
  });
}

function gatherTagPathsForDirs(dirs) {
  const seen = new Set();
  const out = [];
  for (const dir of dirs || []) {
    const p = String(dir?.path || "");
    if (!p || seen.has(p)) continue;
    seen.add(p);
    out.push(p);
  }
  return out;
}

function closeTagContextMenu() {
  if (!tagActionMenuEl) return;
  tagActionMenuEl.classList.remove("open", "fixed");
  tagActionMenuEl.innerHTML = "";
  tagActionMenuEl.style.left = "";
  tagActionMenuEl.style.top = "";
  TAG_CONTEXT_MENU_STATE = null;
}

function closePreviewContextMenu() {
  if (!previewActionMenuEl) return;
  previewActionMenuEl.classList.remove("open", "fixed");
  previewActionMenuEl.innerHTML = "";
  previewActionMenuEl.style.left = "";
  previewActionMenuEl.style.top = "";
  PREVIEW_CONTEXT_MENU_STATE = null;
}

function openTagContextMenu(context) {
  if (!context || !tagActionMenuEl) return;
  const tag = String(context.tag || "").trim();
  const album = normalizeTagAlbumName(context.album || "");
  const tagKey = String(context.tagKey || "").trim();
  const paths = Array.isArray(context.paths) ? context.paths : [];
  const anchor = context.anchor;
  if (!tagKey || !anchor) return;
  const isAlbumEntry = !!album && !tag && !context.special;
  const canRename = !context.special && (!!tag || isAlbumEntry);
  const canDelete = !context.special && (!!tag || isAlbumEntry);
  const canHide = !!tag && !context.special;
  const thumbMode = metaGetTagThumbnailModeByKey(tagKey);
  const tagEntryForThumb =
    context.entry && context.entry.kind === "tag"
      ? context.entry
      : {
          kind: "tag",
          tag: String(context.tag || ""),
          album: normalizeTagAlbumName(context.album || ""),
          special: String(context.special || ""),
          label: String(context.label || context.tag || context.album || "Tag"),
          originPath: String(
            context.originPath || WS.nav?.dirNode?.path || "",
          ),
          placeholder: false,
        };
  const canAppearancePreset =
    !!tagKey && !context.special && (!!tag || isAlbumEntry);
  const canMediaFilter =
    !!tagKey && !context.special && (!!tag || isAlbumEntry);
  const isHidden = canHide && metaHasHiddenTagByKey(tagKey);
  const assignedAppearancePresetId = canAppearancePreset
    ? metaGetTagAppearancePresetIdByKey(tagKey)
    : "";
  const assignedMediaFilterValue = canMediaFilter
    ? metaGetTagMediaFilterByKey(tagKey)
    : [];
  const canSetRandomThumbnail = !!randomThumbnailCandidateForTagEntry(
    tagEntryForThumb,
  );
  closeTagContextMenu();
  closeActionMenus();
  const menu = tagActionMenuEl;
  if (canRename)
    menu.appendChild(
      createTagMenuButton("Rename tag", () => handleTagMenuAction("rename")),
    );
  if (canDelete)
    menu.appendChild(
      createTagMenuButton(
        isAlbumEntry ? "Delete tag album" : "Delete tag",
        () => handleTagMenuAction("delete"),
      ),
    );
  if (canHide)
    menu.appendChild(
      createTagMenuButton(isHidden ? "Unhide tag" : "Hide tag", () =>
        handleTagMenuAction("hidden"),
      ),
    );
  if (canAppearancePreset) {
    menu.appendChild(
      createTagMenuButton("Set media preset", () => {
        buildAppearancePresetChoiceMenu(menu, {
          currentPresetId: assignedAppearancePresetId,
          onBack: () => {
            openTagContextMenu(context);
          },
          onChoosePreset: (presetId) => {
            closeTagContextMenu();
            if (!metaSetTagAppearancePresetIdByKey(tagKey, presetId)) return;
            refreshAfterProcessingMetadataChange();
            showStatusMessage(
              `${isAlbumEntry ? "Tag album" : "Tag"} media preset: ${appearancePresetDisplayName(presetId)}.`,
            );
          },
          onRendered: () => {
            positionDropdownMenu(anchor, menu);
          },
        });
      }),
    );
  }
  if (canMediaFilter) {
    menu.appendChild(
      createTagMenuButton("Set content filter", () => {
        const reopenFilterMenu = (shouldReposition = false) => {
          buildTagMediaFilterChoiceMenu(menu, {
            title: `${isAlbumEntry ? "Tag album" : "Tag"} content filter`,
            currentValue: metaGetTagMediaFilterByKey(tagKey),
            onBack: () => {
              openTagContextMenu(context);
            },
            onChoose: (nextValue) => {
              const changed = metaSetTagMediaFilterByKey(tagKey, nextValue);
              if (changed) {
                metaScheduleSave();
                refreshAfterTagMetadataChange();
                showStatusMessage(
                  `${isAlbumEntry ? "Tag album" : "Tag"} content filter: ${describeTagMediaFilterValue(nextValue)}.`,
                );
              }
              reopenFilterMenu(false);
            },
            onRendered: shouldReposition
              ? () => {
                  positionDropdownMenu(anchor, menu);
                }
              : null,
          });
        };
        reopenFilterMenu(true);
      }),
    );
  }
  if (assignedAppearancePresetId) {
    menu.appendChild(
      createTagMenuButton("Clear media preset override", () =>
        handleTagMenuAction("appearance-preset-clear"),
      ),
    );
  }
  if (!isTagMediaFilterValueEmpty(assignedMediaFilterValue)) {
    menu.appendChild(
      createTagMenuButton("Clear content filter", () =>
        handleTagMenuAction("media-filter-clear"),
      ),
    );
  }
  if (thumbMode !== "none")
    menu.appendChild(
      createTagMenuButton("No thumbnail", () =>
        handleTagMenuAction("thumbnail-none"),
      ),
    );
  if (canSetRandomThumbnail)
    menu.appendChild(
      createTagMenuButton("Random thumbnail", () =>
        handleTagMenuAction("thumbnail-random"),
      ),
    );
  TAG_CONTEXT_MENU_STATE = {
    tag,
    album,
    isAlbumEntry,
    special: String(context.special || ""),
    entry: tagEntryForThumb,
    tagKey,
    anchor,
    label: context.label || tag || album,
    paths: paths.slice(),
    originPath: String(context.originPath || ""),
    canRename,
    canDelete,
    canHide,
    isHidden,
    canAppearancePreset,
    canMediaFilter,
  };
  requestAnimationFrame(() => {
    menu.classList.add("open");
    positionDropdownMenu(anchor, menu);
  });
}

function openTagEntryContextMenu(entry, anchor) {
  if (!entry || entry.kind !== "tag" || !anchor) return false;
  if (entry.placeholder) return false;
  const selectionKey = tagEntrySelectionKey(entry);
  const previewTagBulkKeys = selectionKey
    ? getPreviewTagMenuSelectionKeys(selectionKey)
    : [];
  const anchorInPreview = !!(
    previewBodyEl &&
    previewBodyEl.contains &&
    previewBodyEl.contains(anchor)
  );
  if (anchorInPreview && shouldUsePreviewBulkTagMenu(selectionKey)) {
    const selectedEntries = getSelectedTagEntriesInCurrentView();
    if (selectedEntries.length) {
      openPreviewBulkTagActionMenu(selectedEntries, selectionKey, { anchor });
      return true;
    }
  }
  if (selectionKey && openBulkActionMenuForSelection(`tag:${selectionKey}`))
    return true;
  const dirs = getDirsForTagEntry(entry);
  const paths = gatherTagPathsForDirs(dirs);
  const tagKey = tagThumbnailKeyForEntry(entry);
  openTagContextMenu({
    entry,
    tag: String(entry.tag || ""),
    album: String(entry.album || ""),
    tagKey,
    special: entry.special || "",
    label: String(entry.label || entry.tag || ""),
    anchor,
    paths,
    originPath: String(entry.originPath || ""),
  });
  return true;
}

function openPreviewContextMenu(x, y) {
  if (!previewActionMenuEl) return;
  closeActionMenus();

  const dirNode = getPreviewTargetDir();
  const ids = dirNode
    ? getPreviewFolderAndFileEntries(dirNode, {
        includeFiles: true,
        useCurrentViewEntries: true,
      }).fileIds
    : [];
  const canReverse =
    !!dirNode && canReorderFilesInDir(dirNode) && ids.length > 1;

  const menu = previewActionMenuEl;
  const btn = document.createElement("button");
  btn.type = "button";
  btn.textContent = "Reverse file order";
  if (!canReverse) btn.disabled = true;
  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!canReverse) return;
    if (reverseFilesInDir(dirNode, { visibleIds: ids })) {
      syncAfterDirOrderChange(null, { preserveSelection: true });
    }
    closePreviewContextMenu();
  });
  menu.appendChild(btn);
  PREVIEW_CONTEXT_MENU_STATE = { dirPath: String(dirNode?.path || "") };

  requestAnimationFrame(() => {
    menu.classList.add("open");
    positionDropdownMenuAtPoint(menu, x, y);
  });
}

function createDropdownMenuSubmenu(label, items) {
  const buttons = Array.isArray(items) ? items.filter(Boolean) : [];
  if (!buttons.length) return null;

  const wrap = document.createElement("div");
  wrap.className = "dropdownMenuSubmenu";
  wrap.addEventListener("click", (e) => e.stopPropagation());

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "dropdownMenuSubmenuTrigger";
  trigger.setAttribute("aria-haspopup", "menu");

  const labelSpan = document.createElement("span");
  labelSpan.textContent = String(label || "");
  const caretSpan = document.createElement("span");
  caretSpan.className = "dropdownMenuSubmenuCaret";
  caretSpan.setAttribute("aria-hidden", "true");
  caretSpan.textContent = ">";

  trigger.appendChild(labelSpan);
  trigger.appendChild(caretSpan);
  trigger.addEventListener("click", (e) => e.stopPropagation());

  const panel = document.createElement("div");
  panel.className = "dropdownMenu dropdownMenuSubmenuPanel";
  for (let i = 0; i < buttons.length; i++) panel.appendChild(buttons[i]);

  wrap.appendChild(trigger);
  wrap.appendChild(panel);
  return wrap;
}

function buildDropdownMenuSubmenuHtml(label, buttonsHtml) {
  if (!buttonsHtml) return "";
  return `
        <div class="dropdownMenuSubmenu">
          <button type="button" class="dropdownMenuSubmenuTrigger" aria-haspopup="menu">
            <span>${escapeHtml(String(label || ""))}</span>
            <span class="dropdownMenuSubmenuCaret" aria-hidden="true">&gt;</span>
          </button>
          <div class="dropdownMenu dropdownMenuSubmenuPanel">
            ${buttonsHtml}
          </div>
        </div>
      `;
}

function buildFolderThumbnailSubmenuHtml(options) {
  const cfg = options || {};
  let buttonsHtml = "";
  if (cfg.showUseDefaultThumbnail)
    buttonsHtml += `<button type="button" data-action="thumbnail-default">Use default thumbnail</button>`;
  if (cfg.showSetNoThumbnail)
    buttonsHtml += `<button type="button" data-action="thumbnail-none">No thumbnail</button>`;
  if (cfg.showSetRandomThumbnail)
    buttonsHtml += `<button type="button" data-action="thumbnail-random">Random thumbnail</button>`;
  return buildDropdownMenuSubmenuHtml("Thumbnail", buttonsHtml);
}

function buildFileThumbnailSubmenuHtml(
  thumbnailTargets,
  includeEditThumbnail = true,
) {
  const targets = Array.isArray(thumbnailTargets) ? thumbnailTargets : [];
  const buttonsHtml =
    targets
      .map((t) => {
        const label = String(t?.label || "");
        const action = String(t?.action || "");
        if (!label || !action) return "";
        return `<button type="button" data-action="${escapeHtml(action)}">${escapeHtml(label)}</button>`;
      })
      .join("") +
    (includeEditThumbnail
      ? `<button type="button" data-action="edit-thumbnail">Edit thumbnail</button>`
      : "");
  return buildDropdownMenuSubmenuHtml("Thumbnail", buttonsHtml);
}

function openPreviewFileActionMenu(rec, opts = {}) {
  if (!previewActionMenuEl || !rec) return;
  const fileId = String(rec.id || "");
  if (shouldUsePreviewBulkFileMenu(fileId)) {
    openPreviewBulkFileActionMenu(
      getPreviewFileMenuSelectionIds(fileId),
      fileId,
      opts,
    );
    return;
  }
  const selectedIds = getPreviewFileMenuSelectionIds(fileId);
  if (selectedIds.length > 1) {
    openPreviewBulkFileActionMenu(selectedIds, fileId, opts);
    return;
  }
  closeActionMenus();

  const menu = previewActionMenuEl;
  const thumbnailTargets = getThumbnailMenuTargetsForRecord(rec);

  const makeBtn = (label, action, disabled = false) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.textContent = String(label || "");
    btn.disabled = !!disabled;
    btn.setAttribute("data-action", String(action || ""));
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      closePreviewContextMenu();
      await runFileActionFromMenu(String(action || ""), fileId);
    });
    return btn;
  };

  const thumbnailButtons = [];
  for (let i = 0; i < thumbnailTargets.length; i++) {
    const t = thumbnailTargets[i];
    const label = String(t?.label || "");
    const action = String(t?.action || "");
    if (!label || !action) continue;
    thumbnailButtons.push(makeBtn(label, action));
  }
  thumbnailButtons.push(makeBtn("Edit thumbnail", "edit-thumbnail"));
  const thumbnailSubmenu = createDropdownMenuSubmenu(
    "Thumbnail",
    thumbnailButtons,
  );
  if (thumbnailSubmenu) menu.appendChild(thumbnailSubmenu);
  menu.appendChild(makeBtn("Rename", "rename-file"));
  PREVIEW_CONTEXT_MENU_STATE = { fileId };

  requestAnimationFrame(() => {
    menu.classList.add("open");
    if (opts.anchor) positionDropdownMenu(opts.anchor, menu);
    else
      positionDropdownMenuAtPoint(
        menu,
        Number(opts.x) || 0,
        Number(opts.y) || 0,
      );
  });
}

function buildFolderMenuState(dirNode) {
  const p = String(dirNode?.path || "");
  const isRootNode = !!dirNode && dirNode === WS.root;
  const isTrashRootPortal = isTrashRootPortalNode(dirNode);
  const menuContextDirNode = (() => {
    const previewTargetDir = getPreviewTargetDir();
    if (isInternalTrashDirNode(previewTargetDir)) return previewTargetDir;
    return WS.nav.dirNode;
  })();
  const isTrashRootContext = isInternalTrashDirNode(menuContextDirNode);
  const isTrashPutBackOnly =
    !isTrashRootPortal && isTrashRootContext && isPutBackEligibleTrashPath(p);
  const isFavorite = metaHasFavorite(p);
  const isHidden = metaHasHidden(p);
  const assignedAppearancePresetId = isRootNode
    ? effectiveActiveAppearancePresetId()
    : metaGetFolderAppearancePresetId(p);
  const canRename = !!WS.meta.fsRootHandle;
  const canBatchIndex = !!WS.meta.fsRootHandle;
  const canResetOrder = !!dirNode?.preserveOrder;
  const folderThumbMode = isRootNode
    ? getRootThumbnailMode()
    : metaGetFolderThumbnailMode(p);
  const canToggleFolderThumbMode = !!dirNode && (isRootNode || !!p);
  const hasPreset = isRootNode
    ? rootThumbnailHasPreset()
    : metaHasFolderThumbnailPreset(p);
  const hasRandomCandidate = !!randomThumbnailCandidateForDirNode(dirNode);
  return {
    path: p,
    isRootNode,
    isTrashRootPortal,
    isTrashPutBackOnly,
    isFavorite,
    isHidden,
    assignedAppearancePresetId,
    canRename,
    canBatchIndex,
    canResetOrder,
    showUseDefaultThumbnail:
      hasPreset || (isRootNode && !isRootThumbnailModeDefault(folderThumbMode)),
    showSetNoThumbnail: canToggleFolderThumbMode && folderThumbMode !== "none",
    showSetRandomThumbnail:
      canToggleFolderThumbMode && hasRandomCandidate,
    canMoveToTrash:
      !!p &&
      !!WS.meta.fsRootHandle &&
      !isTrashRootPortal &&
      !isPathInsideInternalTrash(p),
    canPutBack: isTrashPutBackOnly && !!WS.meta.fsRootHandle,
  };
}

function buildFolderActionMenuDom(
  menuEl,
  state,
  onAction,
  customHandlers = null,
) {
  if (!menuEl || !state || typeof onAction !== "function") return;
  const makeBtn = (label, action, disabled = false, className = "") => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.textContent = String(label || "");
    btn.disabled = !!disabled;
    if (className) btn.className = String(className);
    btn.setAttribute("data-action", String(action || ""));
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const handler =
        customHandlers && typeof customHandlers[action] === "function"
          ? customHandlers[action]
          : null;
      if (handler) {
        handler(e);
        return;
      }
      onAction(String(action || ""));
    });
    return btn;
  };
  const appendTwoCol = (leftBtn, rightBtn) => {
    const row = document.createElement("div");
    row.className = "menuTwoColRow";
    row.appendChild(leftBtn);
    row.appendChild(rightBtn);
    menuEl.appendChild(row);
  };
  const folderThumbnailButtons = [];
  if (state.isTrashRootPortal) return;
  if (state.isTrashPutBackOnly) {
    menuEl.appendChild(makeBtn("Put Back", "put-back", !state.canPutBack));
    return;
  }
  if (state.showUseDefaultThumbnail)
    folderThumbnailButtons.push(
      makeBtn("Use default thumbnail", "thumbnail-default"),
    );
  if (state.showSetNoThumbnail)
    folderThumbnailButtons.push(makeBtn("No thumbnail", "thumbnail-none"));
  if (state.showSetRandomThumbnail)
    folderThumbnailButtons.push(
      makeBtn("Random thumbnail", "thumbnail-random"),
    );
  if (state.isRootNode) {
    menuEl.appendChild(makeBtn("Set media preset", "appearance-preset-set"));
    menuEl.appendChild(makeBtn("Generate GIF", "generate-gif"));
    const rootThumbnailSubmenu = createDropdownMenuSubmenu(
      "Thumbnail",
      folderThumbnailButtons,
    );
    if (rootThumbnailSubmenu) menuEl.appendChild(rootThumbnailSubmenu);
    return;
  }
  if (scoreInterfaceEnabled()) {
    const scoreRow = document.createElement("div");
    scoreRow.className = "scoreRow";
    scoreRow.appendChild(makeBtn("+", "score-up"));
    scoreRow.appendChild(makeBtn("-", "score-down"));
    menuEl.appendChild(scoreRow);
  }

  appendTwoCol(
    makeBtn("Tag", "tag"),
    makeBtn("Rename", "rename", !state.canRename),
  );
  appendTwoCol(
    makeBtn("Index", "batch-index", !state.canBatchIndex),
    makeBtn(state.isFavorite ? "Unfavorite" : "Favorite", "favorite"),
  );
  menuEl.appendChild(makeBtn(state.isHidden ? "Unhide" : "Hide", "hidden"));
  menuEl.appendChild(makeBtn("Set media preset", "appearance-preset-set"));
  if (state.assignedAppearancePresetId) {
    menuEl.appendChild(
      makeBtn("Clear media preset override", "appearance-preset-clear"),
    );
  }
  if (state.canResetOrder)
    menuEl.appendChild(makeBtn("Reset order", "reset-order"));
  menuEl.appendChild(makeBtn("Generate GIF", "generate-gif"));
  const thumbnailSubmenu = createDropdownMenuSubmenu(
    "Thumbnail",
    folderThumbnailButtons,
  );
  if (thumbnailSubmenu) menuEl.appendChild(thumbnailSubmenu);
  menuEl.appendChild(
    makeBtn(
      "Move to trash",
      "move-to-trash",
      !state.canMoveToTrash,
      "destructiveAction",
    ),
  );
}

const GIF_EXPORT_MAX_SIDE = 640;
const GIF_EXPORT_SQUARE_SIZE = 640;
const GIF_EXPORT_ALPHA_THRESHOLD = 8;
const GIF_EXPORT_PALETTE_SIZE = 256;
const GIF_EXPORT_PALETTE_SAMPLE_CAP = 16000;

function waitForNextPaint() {
  return new Promise((resolve) => requestAnimationFrame(() => resolve()));
}

function getOrderedMediaFileIdsForDirAll(dirNode) {
  if (!dirNode) return [];
  let ids = [];
  if (randomSortAffectsFiles()) {
    ids = getRandomOrderForDir(dirNode);
  } else if (dirNode.preserveOrder) {
    ids = dirNode.childrenFiles.slice();
  } else {
    ids = dirNode.childrenFiles.slice();
    ids.sort((a, b) =>
      compareIndexedNames(
        WS.fileById.get(a)?.name || "",
        WS.fileById.get(b)?.name || "",
      ),
    );
  }
  return ids.filter((id) => {
    const rec = WS.fileById.get(id);
    return !!rec && (rec.type === "image" || rec.type === "video");
  });
}

function collectOrderedMediaRecordsForDirRecursive(dirNode, out = []) {
  if (!dirNode) return out;
  const fileIds = getOrderedMediaFileIdsForDirAll(dirNode);
  for (let i = 0; i < fileIds.length; i++) {
    const rec = WS.fileById.get(fileIds[i]);
    if (rec) out.push(rec);
  }
  const children = sortDirsForDisplay(
    Array.isArray(dirNode.childrenDirs) ? dirNode.childrenDirs : [],
  );
  for (let i = 0; i < children.length; i++) {
    collectOrderedMediaRecordsForDirRecursive(children[i], out);
  }
  return out;
}

function resolveOrderedUniqueDirNodesForPaths(paths) {
  const inputPaths = (paths || []).map((p) => String(p || "")).filter(Boolean);
  if (!inputPaths.length) return [];
  const wanted = new Set(inputPaths);
  const out = [];
  const seen = new Set();

  for (let i = 0; i < WS.nav.entries.length; i++) {
    const entry = WS.nav.entries[i];
    if (!entry || entry.kind !== "dir" || !entry.node) continue;
    const p = String(entry.node.path || "");
    if (!p || !wanted.has(p) || seen.has(p)) continue;
    seen.add(p);
    out.push(entry.node);
  }

  for (let i = 0; i < inputPaths.length; i++) {
    const p = inputPaths[i];
    if (!p || seen.has(p)) continue;
    const node = WS.dirByPath.get(p);
    if (!node) continue;
    seen.add(p);
    out.push(node);
  }
  return out;
}

function collectOrderedMediaRecordsForDirNodesRecursive(dirNodes) {
  const nodes = Array.isArray(dirNodes) ? dirNodes : [];
  const out = [];
  const seenRecordIds = new Set();
  for (let i = 0; i < nodes.length; i++) {
    const node = nodes[i];
    if (!node) continue;
    const collected = collectOrderedMediaRecordsForDirRecursive(node, []);
    for (let j = 0; j < collected.length; j++) {
      const rec = collected[j];
      const id = String(rec?.id || "");
      if (!id || seenRecordIds.has(id)) continue;
      seenRecordIds.add(id);
      out.push(rec);
    }
  }
  return out;
}

async function resolveAspectRatioForGifRecord(rec) {
  if (!rec) return 4 / 3;
  const known = Number(rec.previewAspect);
  if (!(Number.isFinite(known) && known > 0)) {
    const detected = await detectRecordPreviewAspect(rec);
    if (detected) rec.previewAspect = normalizePreviewAspect(detected, 4 / 3);
  }
  return getPreviewAspectForRecord(rec);
}

function gifAspectBucketKey(aspect) {
  return normalizePreviewAspect(aspect, 4 / 3).toFixed(3);
}

function approximateAspectFraction(aspect, maxDen = 64) {
  const target = normalizePreviewAspect(aspect, 4 / 3);
  let bestNum = Math.round(target);
  let bestDen = 1;
  let bestErr = Math.abs(target - bestNum);
  for (let den = 1; den <= maxDen; den++) {
    const num = Math.max(1, Math.round(target * den));
    const err = Math.abs(target - num / den);
    if (err < bestErr) {
      bestNum = num;
      bestDen = den;
      bestErr = err;
    }
  }
  return { num: bestNum, den: bestDen };
}

function gifAspectBucketLabel(aspect) {
  const ratio = normalizePreviewAspect(aspect, 4 / 3);
  const approx = approximateAspectFraction(ratio, 72);
  return `${approx.num}x${approx.den}`;
}

function gifAspectBucketDisplayLabel(bucket) {
  const explicit = String(bucket?.label || "").trim();
  if (explicit) return explicit;
  return gifAspectBucketLabel(bucket?.aspect || 4 / 3);
}

function gifFrameSizeForAspect(aspect) {
  const ratio = normalizePreviewAspect(aspect, 4 / 3);
  const maxSide = GIF_EXPORT_MAX_SIDE;
  if (ratio >= 1) {
    return {
      width: Math.max(2, Math.round(maxSide)),
      height: Math.max(2, Math.round(maxSide / ratio)),
    };
  }
  return {
    width: Math.max(2, Math.round(maxSide * ratio)),
    height: Math.max(2, Math.round(maxSide)),
  };
}

function gifFrameSizeForBucket(bucket) {
  if (bucket && bucket.square) {
    return { width: GIF_EXPORT_SQUARE_SIZE, height: GIF_EXPORT_SQUARE_SIZE };
  }
  return gifFrameSizeForAspect(bucket?.aspect || 4 / 3);
}

function buildMixedSquareGifBucket(records) {
  return {
    key: "__mixed_square__",
    aspect: 1,
    label: "mixed-square",
    square: true,
    records: Array.isArray(records) ? records.slice() : [],
  };
}

function buildAllInOneGifBucket(records, order) {
  const normalizedOrder = normalizeGifExportOrder(order);
  return {
    key: `__all_in_one__${normalizedOrder}`,
    aspect: 1,
    label:
      normalizedOrder === GIF_EXPORT_ORDER_ASPECT_RATIO
        ? "all-in-one-aspect-order"
        : "all-in-one-sort-order",
    square: true,
    allInOne: true,
    order: normalizedOrder,
    records: Array.isArray(records) ? records.slice() : [],
  };
}

function consolidateGifAspectBuckets(rawBuckets) {
  const normalized = (Array.isArray(rawBuckets) ? rawBuckets : [])
    .map((bucket) => {
      const records = Array.isArray(bucket?.records)
        ? bucket.records.filter(Boolean)
        : [];
      if (!records.length) return null;
      return {
        key: String(bucket?.key || gifAspectBucketKey(bucket?.aspect || 4 / 3)),
        aspect: normalizePreviewAspect(bucket?.aspect, 4 / 3),
        records,
      };
    })
    .filter(Boolean)
    .sort((a, b) => Number(a.aspect) - Number(b.aspect));

  if (normalized.length <= 1) return normalized;

  const counts = normalized.map((bucket) =>
    Math.max(0, Number(bucket.records.length || 0)),
  );
  const totalFrames = counts.reduce((sum, count) => sum + count, 0);
  if (totalFrames <= 0) return [];
  const maxCount = Math.max(...counts);
  if (maxCount <= 1) {
    return [
      buildMixedSquareGifBucket(normalized.flatMap((bucket) => bucket.records)),
    ];
  }

  const meanCount = totalFrames / normalized.length;
  const rareByShareThreshold = (1 / normalized.length) * 0.7;
  const rareByCountThreshold = Math.max(1, Math.floor(maxCount * 0.35));

  const kept = [];
  const mixedRecords = [];
  for (let i = 0; i < normalized.length; i++) {
    const bucket = normalized[i];
    const count = Math.max(0, Number(bucket.records.length || 0));
    const share = totalFrames > 0 ? count / totalFrames : 0;
    const singletonInSparseSet =
      count === 1 && normalized.length >= 5 && maxCount >= 2;
    const rareByRelativeShare =
      share <= rareByShareThreshold &&
      count <= rareByCountThreshold &&
      count < meanCount;
    if (singletonInSparseSet || rareByRelativeShare) {
      mixedRecords.push(...bucket.records);
      continue;
    }
    kept.push(bucket);
  }

  if (!mixedRecords.length) return normalized;
  if (!kept.length) return [buildMixedSquareGifBucket(mixedRecords)];

  const out = kept.slice();
  out.push(buildMixedSquareGifBucket(mixedRecords));
  out.sort((a, b) => {
    const aMixed = !!a.square;
    const bMixed = !!b.square;
    if (aMixed !== bMixed) return aMixed ? 1 : -1;
    return Number(a.aspect) - Number(b.aspect);
  });
  return out;
}

function sanitizeDownloadFileNamePart(input, fallback = "file") {
  const src = String(input || "")
    .replace(/[<>:"/\\|?*\x00-\x1f]/g, "_")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\.+$/g, "");
  return src || fallback;
}

function createEmptyGifPaletteBytes() {
  return new Uint8Array(GIF_EXPORT_PALETTE_SIZE * 3);
}

function gifPaletteColorKey(r, g, b) {
  return (
    (((Number(r) >>> 3) & 0x1f) << 10) |
    (((Number(g) >>> 3) & 0x1f) << 5) |
    ((Number(b) >>> 3) & 0x1f)
  );
}

function addGifPaletteSamplesFromRgba(histogram, rgba) {
  if (!(histogram instanceof Map) || !rgba || !rgba.length) return;
  const pixelCount = Math.max(0, Math.floor(rgba.length / 4));
  if (!pixelCount) return;
  const sampleStep = Math.max(
    1,
    Math.floor(pixelCount / GIF_EXPORT_PALETTE_SAMPLE_CAP),
  );
  for (let p = 0, i = 0; p < pixelCount; p += sampleStep, i = p * 4) {
    const a = rgba[i + 3];
    if (a < GIF_EXPORT_ALPHA_THRESHOLD) continue;
    const r = rgba[i];
    const g = rgba[i + 1];
    const b = rgba[i + 2];
    const key = gifPaletteColorKey(r, g, b);
    const existing = histogram.get(key);
    if (existing) {
      existing.count += 1;
      existing.rSum += r;
      existing.gSum += g;
      existing.bSum += b;
    } else {
      histogram.set(key, {
        count: 1,
        rSum: r,
        gSum: g,
        bSum: b,
      });
    }
  }
}

function gifPaletteEntriesFromHistogram(histogram) {
  const out = [];
  if (!(histogram instanceof Map)) return out;
  for (const entry of histogram.values()) {
    const count = Math.max(0, Number(entry?.count || 0));
    if (!count) continue;
    out.push({
      r: Math.round(Number(entry.rSum || 0) / count),
      g: Math.round(Number(entry.gSum || 0) / count),
      b: Math.round(Number(entry.bSum || 0) / count),
      count,
    });
  }
  return out;
}

function computeGifQuantBoxStats(colors) {
  const entries = Array.isArray(colors) ? colors : [];
  let rMin = 255;
  let rMax = 0;
  let gMin = 255;
  let gMax = 0;
  let bMin = 255;
  let bMax = 0;
  let weight = 0;
  for (let i = 0; i < entries.length; i++) {
    const c = entries[i];
    const r = Math.max(0, Math.min(255, Math.round(Number(c?.r || 0))));
    const g = Math.max(0, Math.min(255, Math.round(Number(c?.g || 0))));
    const b = Math.max(0, Math.min(255, Math.round(Number(c?.b || 0))));
    const count = Math.max(0, Number(c?.count || 0));
    if (r < rMin) rMin = r;
    if (r > rMax) rMax = r;
    if (g < gMin) gMin = g;
    if (g > gMax) gMax = g;
    if (b < bMin) bMin = b;
    if (b > bMax) bMax = b;
    weight += count;
  }
  if (!entries.length) {
    rMin = rMax = gMin = gMax = bMin = bMax = 0;
  }
  return {
    rMin,
    rMax,
    gMin,
    gMax,
    bMin,
    bMax,
    weight,
  };
}

function gifQuantBoxPriority(box) {
  const colors = Array.isArray(box?.colors) ? box.colors : [];
  if (colors.length <= 1) return 0;
  const stats = box.stats || computeGifQuantBoxStats(colors);
  const range = Math.max(
    stats.rMax - stats.rMin,
    stats.gMax - stats.gMin,
    stats.bMax - stats.bMin,
  );
  return range * Math.max(1, stats.weight);
}

function gifQuantBoxSplitChannel(stats) {
  const rRange = stats.rMax - stats.rMin;
  const gRange = stats.gMax - stats.gMin;
  const bRange = stats.bMax - stats.bMin;
  if (rRange >= gRange && rRange >= bRange) return "r";
  if (gRange >= rRange && gRange >= bRange) return "g";
  return "b";
}

function splitGifQuantBox(box) {
  const colors = Array.isArray(box?.colors) ? box.colors.slice() : [];
  if (colors.length <= 1) return null;
  const stats = box.stats || computeGifQuantBoxStats(colors);
  const channel = gifQuantBoxSplitChannel(stats);
  colors.sort((a, b) => Number(a?.[channel] || 0) - Number(b?.[channel] || 0));
  const totalWeight = Math.max(0, Number(stats.weight || 0));
  if (totalWeight <= 0) return null;
  let runningWeight = 0;
  let splitIndex = 1;
  for (let i = 0; i < colors.length; i++) {
    runningWeight += Math.max(0, Number(colors[i]?.count || 0));
    if (runningWeight >= totalWeight / 2) {
      splitIndex = i + 1;
      break;
    }
  }
  splitIndex = Math.max(1, Math.min(colors.length - 1, splitIndex));
  const leftColors = colors.slice(0, splitIndex);
  const rightColors = colors.slice(splitIndex);
  if (!leftColors.length || !rightColors.length) return null;
  return [
    { colors: leftColors, stats: computeGifQuantBoxStats(leftColors) },
    { colors: rightColors, stats: computeGifQuantBoxStats(rightColors) },
  ];
}

function buildAdaptiveGifPalette(histogram) {
  const sourceColors = gifPaletteEntriesFromHistogram(histogram);
  if (!sourceColors.length) {
    return {
      bytes: createEmptyGifPaletteBytes(),
      colors: [{ r: 0, g: 0, b: 0 }],
    };
  }

  let boxes = [
    {
      colors: sourceColors,
      stats: computeGifQuantBoxStats(sourceColors),
    },
  ];

  while (boxes.length < GIF_EXPORT_PALETTE_SIZE - 1) {
    let bestIndex = -1;
    let bestPriority = 0;
    for (let i = 0; i < boxes.length; i++) {
      const priority = gifQuantBoxPriority(boxes[i]);
      if (priority > bestPriority) {
        bestPriority = priority;
        bestIndex = i;
      }
    }
    if (bestIndex < 0) break;
    const split = splitGifQuantBox(boxes[bestIndex]);
    if (!split) break;
    boxes.splice(bestIndex, 1, split[0], split[1]);
  }

  const paletteColors = [{ r: 0, g: 0, b: 0 }];
  for (
    let i = 0;
    i < boxes.length && paletteColors.length < GIF_EXPORT_PALETTE_SIZE;
    i++
  ) {
    const colors = Array.isArray(boxes[i]?.colors) ? boxes[i].colors : [];
    let weight = 0;
    let rSum = 0;
    let gSum = 0;
    let bSum = 0;
    for (let j = 0; j < colors.length; j++) {
      const c = colors[j];
      const count = Math.max(0, Number(c?.count || 0));
      weight += count;
      rSum += Math.max(0, Math.min(255, Number(c?.r || 0))) * count;
      gSum += Math.max(0, Math.min(255, Number(c?.g || 0))) * count;
      bSum += Math.max(0, Math.min(255, Number(c?.b || 0))) * count;
    }
    if (!weight) continue;
    paletteColors.push({
      r: Math.round(rSum / weight),
      g: Math.round(gSum / weight),
      b: Math.round(bSum / weight),
    });
  }

  const bytes = createEmptyGifPaletteBytes();
  for (
    let i = 0;
    i < paletteColors.length && i < GIF_EXPORT_PALETTE_SIZE;
    i++
  ) {
    const color = paletteColors[i];
    bytes[i * 3 + 0] = Math.max(
      0,
      Math.min(255, Math.round(Number(color?.r || 0))),
    );
    bytes[i * 3 + 1] = Math.max(
      0,
      Math.min(255, Math.round(Number(color?.g || 0))),
    );
    bytes[i * 3 + 2] = Math.max(
      0,
      Math.min(255, Math.round(Number(color?.b || 0))),
    );
  }
  return {
    bytes,
    colors: paletteColors,
  };
}

function createGifPaletteIndexer(paletteInfo) {
  const colors = Array.isArray(paletteInfo?.colors)
    ? paletteInfo.colors
    : [{ r: 0, g: 0, b: 0 }];
  const cache = new Map();
  return (r, g, b) => {
    const key = gifPaletteColorKey(r, g, b);
    const existing = cache.get(key);
    if (existing != null) return existing;
    let bestIndex = 0;
    let bestDistance = Number.POSITIVE_INFINITY;
    for (let i = 0; i < colors.length; i++) {
      const color = colors[i];
      const dr = Number(r) - Number(color?.r || 0);
      const dg = Number(g) - Number(color?.g || 0);
      const db = Number(b) - Number(color?.b || 0);
      const distance = dr * dr + dg * dg + db * db;
      if (distance < bestDistance) {
        bestDistance = distance;
        bestIndex = i;
        if (distance === 0) break;
      }
    }
    cache.set(key, bestIndex);
    return bestIndex;
  };
}

function createByteCollector() {
  const parts = [];
  let total = 0;
  const pushBytes = (bytes) => {
    if (!bytes || !bytes.length) return;
    const typed = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);
    parts.push(typed);
    total += typed.length;
  };
  return {
    pushByte(value) {
      pushBytes([Number(value) & 0xff]);
    },
    pushWordLE(value) {
      const v = Number(value) & 0xffff;
      pushBytes([v & 0xff, (v >> 8) & 0xff]);
    },
    pushBytes,
    toUint8Array() {
      const out = new Uint8Array(total);
      let offset = 0;
      for (let i = 0; i < parts.length; i++) {
        out.set(parts[i], offset);
        offset += parts[i].length;
      }
      return out;
    },
  };
}

function gifPackLzwCodes(codes, minCodeSize = 8) {
  const clearCode = 1 << minCodeSize;
  const endCode = clearCode + 1;
  let codeSize = minCodeSize + 1;
  let nextCode = endCode + 1;
  let hasPrevCode = false;
  const out = [];
  let bitBuffer = 0;
  let bitCount = 0;

  const writeCode = (code) => {
    bitBuffer |= (Number(code) & ((1 << codeSize) - 1)) << bitCount;
    bitCount += codeSize;
    while (bitCount >= 8) {
      out.push(bitBuffer & 0xff);
      bitBuffer >>>= 8;
      bitCount -= 8;
    }
  };

  for (let i = 0; i < codes.length; i++) {
    const code = Number(codes[i]) || 0;
    writeCode(code);
    if (code === clearCode) {
      codeSize = minCodeSize + 1;
      nextCode = endCode + 1;
      hasPrevCode = false;
      continue;
    }
    if (code === endCode) break;
    if (hasPrevCode) {
      nextCode++;
      if (nextCode === 1 << codeSize && codeSize < 12) codeSize++;
    }
    hasPrevCode = true;
  }

  if (bitCount > 0) out.push(bitBuffer & 0xff);
  return Uint8Array.from(out);
}

function gifLzwEncodeIndices(indices, minCodeSize = 8) {
  const data =
    indices instanceof Uint8Array ? indices : Uint8Array.from(indices || []);
  const clearCode = 1 << minCodeSize;
  const endCode = clearCode + 1;
  let nextCode = endCode + 1;
  let encoderCodeSize = minCodeSize + 1;
  const dictionary = new Map();
  const codes = [clearCode];

  if (!data.length) {
    codes.push(endCode);
    return gifPackLzwCodes(codes, minCodeSize);
  }

  let prefixCode = data[0];
  for (let i = 1; i < data.length; i++) {
    const k = data[i];
    const key = (prefixCode << 8) | k;
    const existing = dictionary.get(key);
    if (existing != null) {
      prefixCode = existing;
      continue;
    }

    codes.push(prefixCode);
    if (nextCode < 4096) {
      dictionary.set(key, nextCode);
      nextCode++;
      if (nextCode === 1 << encoderCodeSize && encoderCodeSize < 12)
        encoderCodeSize++;
    } else {
      codes.push(clearCode);
      dictionary.clear();
      nextCode = endCode + 1;
      encoderCodeSize = minCodeSize + 1;
    }
    prefixCode = k;
  }

  codes.push(prefixCode);
  codes.push(endCode);
  return gifPackLzwCodes(codes, minCodeSize);
}

function gifWrapSubBlocks(dataBytes) {
  const data =
    dataBytes instanceof Uint8Array
      ? dataBytes
      : Uint8Array.from(dataBytes || []);
  const out = createByteCollector();
  let offset = 0;
  while (offset < data.length) {
    const chunk = Math.min(255, data.length - offset);
    out.pushByte(chunk);
    out.pushBytes(data.subarray(offset, offset + chunk));
    offset += chunk;
  }
  out.pushByte(0x00);
  return out.toUint8Array();
}

function createGifWriter(
  width,
  height,
  globalPalette = createEmptyGifPaletteBytes(),
) {
  const w = Math.max(1, Math.min(65535, Math.round(width || 1)));
  const h = Math.max(1, Math.min(65535, Math.round(height || 1)));
  const writer = createByteCollector();
  writer.pushBytes([0x47, 0x49, 0x46, 0x38, 0x39, 0x61]); // GIF89a
  writer.pushWordLE(w);
  writer.pushWordLE(h);
  writer.pushByte(0xf7); // global color table, 8-bit color resolution, 256-color table
  writer.pushByte(0x00); // background color index
  writer.pushByte(0x00); // pixel aspect ratio
  writer.pushBytes(globalPalette);

  return {
    addFrame(indexData, delayCs = 24) {
      const pixels =
        indexData instanceof Uint8Array
          ? indexData
          : Uint8Array.from(indexData || []);
      const frameDelay = Math.max(
        1,
        Math.min(65535, Math.round(delayCs || 24)),
      );
      writer.pushBytes([
        0x21,
        0xf9,
        0x04,
        0x00,
        frameDelay & 0xff,
        (frameDelay >> 8) & 0xff,
        0x00,
        0x00,
      ]);
      writer.pushByte(0x2c);
      writer.pushWordLE(0);
      writer.pushWordLE(0);
      writer.pushWordLE(w);
      writer.pushWordLE(h);
      writer.pushByte(0x00);
      writer.pushByte(8); // LZW minimum code size for 8-bit palette
      const lzwBytes = gifLzwEncodeIndices(pixels, 8);
      writer.pushBytes(gifWrapSubBlocks(lzwBytes));
    },
    finish() {
      writer.pushByte(0x3b);
      return writer.toUint8Array();
    },
  };
}

async function loadImageFrameSourceForGifRecord(rec) {
  if (!rec) return null;
  if (rec.file) {
    try {
      const bmp = await createImageBitmap(rec.file);
      return {
        source: bmp,
        width: Number(bmp.width) || 0,
        height: Number(bmp.height) || 0,
        cleanup() {
          try {
            bmp.close();
          } catch {}
        },
      };
    } catch {}
  }
  const src = ensureMediaUrl(rec);
  if (!src) return null;
  return await new Promise((resolve) => {
    const img = new Image();
    let settled = false;
    const done = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    img.onload = () => {
      done({
        source: img,
        width: Number(img.naturalWidth) || 0,
        height: Number(img.naturalHeight) || 0,
        cleanup() {
          try {
            img.src = "";
          } catch {}
        },
      });
    };
    img.onerror = () => done(null);
    img.src = src;
  });
}

async function loadVideoFrameSourceForGifRecord(rec) {
  if (!rec) return null;
  const src = ensureMediaUrl(rec);
  if (!src) return null;
  const v = document.createElement("video");
  v.preload = "auto";
  v.muted = true;
  v.playsInline = true;
  normalizeVideoPlaybackRate(v);
  v.crossOrigin = "anonymous";
  v.src = src;
  const cleanup = () => {
    try {
      v.pause();
    } catch {}
    try {
      v.removeAttribute("src");
    } catch {}
    try {
      v.load();
    } catch {}
  };
  try {
    await waitForVideoMetadata(v, 3000);
    await waitForVideoLoadedData(v, 2200);
    const seekTimes = computeVideoThumbSeekTimes(
      v.duration || 0,
      metaGetVideoThumbnailTimeForRecord(rec),
    );
    for (let i = 0; i < seekTimes.length; i++) {
      await seekVideoForThumb(v, seekTimes[i], 1800);
      if (!isVideoFrameLikelyBlank(v) || i === seekTimes.length - 1) break;
    }
    updateVideoCropFromElement(rec, v);
    return {
      source: v,
      width: Number(v.videoWidth) || 0,
      height: Number(v.videoHeight) || 0,
      cleanup,
    };
  } catch {
    cleanup();
    return null;
  }
}

async function loadGifFrameSourceForRecord(rec) {
  if (!rec) return null;
  if (rec.type === "video") return await loadVideoFrameSourceForGifRecord(rec);
  if (rec.type === "image") return await loadImageFrameSourceForGifRecord(rec);
  return null;
}

async function renderGifFrameRgbaBuffer(rec, canvas, ctx) {
  if (!rec || !canvas || !ctx) return null;
  const loaded = await loadGifFrameSourceForRecord(rec);
  if (!loaded) return null;
  try {
    const source = loaded.source;
    const srcW = Number(
      loaded.width ||
        source?.videoWidth ||
        source?.naturalWidth ||
        source?.width ||
        0,
    );
    const srcH = Number(
      loaded.height ||
        source?.videoHeight ||
        source?.naturalHeight ||
        source?.height ||
        0,
    );
    if (!(srcW > 0 && srcH > 0)) return null;
    const overlayCfg = resolveFolderOnlyMediaOverlayConfigForTarget(rec);
    renderFilteredToCanvas(
      ctx,
      source,
      srcW,
      srcH,
      canvas.width,
      canvas.height,
      "off",
      false,
      rec,
      { overlayConfig: overlayCfg },
    );
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const rgba = imageData && imageData.data ? imageData.data : null;
    return rgba && rgba.length ? rgba : null;
  } catch {
    return null;
  } finally {
    try {
      loaded.cleanup && loaded.cleanup();
    } catch {}
  }
}

function quantizeGifFrameRgbaToPalette(rgba, width, height, paletteIndexer) {
  const pixelCount = Math.max(
    0,
    Math.round(Number(width || 0) * Number(height || 0)),
  );
  if (
    !rgba ||
    !rgba.length ||
    !pixelCount ||
    typeof paletteIndexer !== "function"
  )
    return null;
  const idx = new Uint8Array(pixelCount);
  for (let p = 0, i = 0; p < pixelCount; p++, i += 4) {
    const a = rgba[i + 3];
    if (a < GIF_EXPORT_ALPHA_THRESHOLD) {
      idx[p] = 0;
      continue;
    }
    idx[p] = paletteIndexer(rgba[i], rgba[i + 1], rgba[i + 2]);
  }
  return idx;
}

async function writeGeneratedGifToDownloads(fileName, bytes) {
  const safeFileName = sanitizeDownloadFileNamePart(
    fileName || "local-gallery-export.gif",
    "local-gallery-export.gif",
  );
  const data =
    bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes || []);
  if (!data.length) return "";

  const electronApi = getElectronApi();
  if (electronApi && typeof electronApi.writeDownloadFile === "function") {
    try {
      return String(
        (await electronApi.writeDownloadFile({
          fileName: safeFileName,
          bytes: data,
        })) || "",
      );
    } catch {}
  }

  const blob = new Blob([data], { type: "image/gif" });
  const blobUrl = URL.createObjectURL(blob);
  try {
    const a = document.createElement("a");
    a.href = blobUrl;
    a.download = safeFileName;
    a.style.display = "none";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  } finally {
    try {
      URL.revokeObjectURL(blobUrl);
    } catch {}
  }
  return "";
}

function buildGifExportFileName(baseLabel, bucket, index, total) {
  const folderLabel = sanitizeDownloadFileNamePart(
    String(baseLabel || "folder"),
    "folder",
  );
  if (bucket?.allInOne) {
    const orderLabel = sanitizeDownloadFileNamePart(
      String(bucket?.order || GIF_EXPORT_ORDER_SORT),
      GIF_EXPORT_ORDER_SORT,
    );
    const frameCount = Math.max(1, Number(bucket?.records?.length || 1));
    return `${folderLabel}_all_in_one_${orderLabel}_${frameCount}f.gif`;
  }
  const aspectLabel = sanitizeDownloadFileNamePart(
    gifAspectBucketDisplayLabel(bucket),
    "aspect",
  );
  const frameCount = Math.max(1, Number(bucket?.records?.length || 1));
  const idxSuffix = total > 1 ? `_${String(index + 1).padStart(2, "0")}` : "";
  return `${folderLabel}_ratio_${aspectLabel}_${frameCount}f${idxSuffix}.gif`;
}

async function resolveGifAspectEntriesForRecords(records, progressLabel) {
  const entries = [];
  const list = Array.isArray(records) ? records : [];
  for (let i = 0; i < list.length; i++) {
    const rec = list[i];
    if (!rec) continue;
    if (progressLabel) {
      showBusyOverlay(`${progressLabel} ${i + 1}/${list.length}`);
    }
    const aspect = await resolveAspectRatioForGifRecord(rec);
    entries.push({
      rec,
      aspect: normalizePreviewAspect(aspect, 4 / 3),
      orderIndex: i,
    });
    if (i % 8 === 0) await waitForNextPaint();
  }
  return entries;
}

function sortGifAspectEntries(entries, order) {
  const normalizedOrder = normalizeGifExportOrder(order);
  const list = Array.isArray(entries) ? entries.slice() : [];
  if (normalizedOrder === GIF_EXPORT_ORDER_ASPECT_RATIO) {
    list.sort((a, b) => {
      const aspectDiff = Number(a?.aspect || 0) - Number(b?.aspect || 0);
      if (aspectDiff !== 0) return aspectDiff;
      return Number(a?.orderIndex || 0) - Number(b?.orderIndex || 0);
    });
    return list;
  }
  list.sort((a, b) => Number(a?.orderIndex || 0) - Number(b?.orderIndex || 0));
  return list;
}

async function buildGifExportBucketsForRecordSet(records, options = {}) {
  const mode = normalizeGifExportMode(options?.mode);
  const order = normalizeGifExportOrder(options?.order);
  if (mode === GIF_EXPORT_MODE_ALL_IN_ONE && order === GIF_EXPORT_ORDER_SORT) {
    return [buildAllInOneGifBucket(records, order)];
  }

  const aspectEntries = await resolveGifAspectEntriesForRecords(
    records,
    mode === GIF_EXPORT_MODE_ALL_IN_ONE
      ? "Generating GIF... ordering by aspect ratio."
      : "Generating GIFs... scanning aspect ratios.",
  );

  if (mode === GIF_EXPORT_MODE_ALL_IN_ONE) {
    const orderedEntries = sortGifAspectEntries(aspectEntries, order);
    return [
      buildAllInOneGifBucket(
        orderedEntries.map((entry) => entry.rec),
        order,
      ),
    ];
  }

  const bucketByKey = new Map();
  for (let i = 0; i < aspectEntries.length; i++) {
    const entry = aspectEntries[i];
    const key = gifAspectBucketKey(entry.aspect);
    let bucket = bucketByKey.get(key);
    if (!bucket) {
      bucket = { key, aspect: entry.aspect, records: [] };
      bucketByKey.set(key, bucket);
    }
    bucket.records.push(entry.rec);
  }
  return consolidateGifAspectBuckets(Array.from(bucketByKey.values()));
}

async function buildGifPaletteForBucket(
  bucket,
  canvas,
  ctx,
  bucketIndex,
  bucketTotal,
) {
  const records = Array.isArray(bucket?.records) ? bucket.records : [];
  const histogram = new Map();
  let sampledFrames = 0;
  const bucketLabel = gifAspectBucketDisplayLabel(bucket);
  for (let i = 0; i < records.length; i++) {
    showBusyOverlay(
      `Preparing GIF ${bucketIndex + 1}/${bucketTotal} (${bucketLabel}) palette ${i + 1}/${records.length}`,
    );
    const rgba = await renderGifFrameRgbaBuffer(records[i], canvas, ctx);
    if (!rgba || !rgba.length) continue;
    addGifPaletteSamplesFromRgba(histogram, rgba);
    sampledFrames++;
    if (i % 3 === 0) await waitForNextPaint();
  }
  if (!sampledFrames) return null;
  return buildAdaptiveGifPalette(histogram);
}

async function generateGifBucketsForRecordSet(orderedRecords, options = {}) {
  const records = Array.isArray(orderedRecords)
    ? orderedRecords.filter(Boolean)
    : [];
  const sourceLabel = String(options?.sourceLabel || "folder tree");
  const outputLabel = String(options?.outputLabel || "folder");
  const emptyStatus = String(
    options?.emptyStatus || `No media files found in ${sourceLabel}.`,
  );
  const mode = normalizeGifExportMode(options?.mode);
  const order = normalizeGifExportOrder(options?.order);
  const frameDelayCs = normalizeGifExportFrameDelayCs(options?.frameDelayCs);
  if (!records.length) {
    showStatusMessage(emptyStatus);
    return true;
  }

  try {
    showBusyOverlay("Generating GIFs... Preparing export.");
    await waitForNextPaint();
    const buckets = await buildGifExportBucketsForRecordSet(records, {
      mode,
      order,
    });
    if (!buckets.length) {
      showStatusMessage("No GIF buckets were created.");
      return true;
    }

    const generated = [];
    for (let b = 0; b < buckets.length; b++) {
      const bucket = buckets[b];
      const bucketLabel = gifAspectBucketDisplayLabel(bucket);
      const frameSize = gifFrameSizeForBucket(bucket);
      const canvas = document.createElement("canvas");
      canvas.width = frameSize.width;
      canvas.height = frameSize.height;
      const ctx = canvas.getContext("2d", { willReadFrequently: true });
      if (!ctx) continue;

      const paletteInfo = await buildGifPaletteForBucket(
        bucket,
        canvas,
        ctx,
        b,
        buckets.length,
      );
      if (!paletteInfo) continue;
      const paletteIndexer = createGifPaletteIndexer(paletteInfo);
      const writer = createGifWriter(
        canvas.width,
        canvas.height,
        paletteInfo.bytes,
      );
      let addedFrames = 0;
      for (let i = 0; i < bucket.records.length; i++) {
        showBusyOverlay(
          `Generating GIF ${b + 1}/${buckets.length} (${bucketLabel}) frame ${i + 1}/${bucket.records.length}`,
        );
        const rgba = await renderGifFrameRgbaBuffer(
          bucket.records[i],
          canvas,
          ctx,
        );
        const frameIndices = quantizeGifFrameRgbaToPalette(
          rgba,
          canvas.width,
          canvas.height,
          paletteIndexer,
        );
        if (!frameIndices || !frameIndices.length) continue;
        writer.addFrame(frameIndices, frameDelayCs);
        addedFrames++;
        if (i % 4 === 0) await waitForNextPaint();
      }

      if (!addedFrames) continue;
      const fileName = buildGifExportFileName(
        outputLabel,
        bucket,
        b,
        buckets.length,
      );
      const bytes = writer.finish();
      const savedPath = await writeGeneratedGifToDownloads(fileName, bytes);
      generated.push({
        fileName,
        savedPath,
        frames: addedFrames,
        aspectLabel: bucketLabel,
      });
      await waitForNextPaint();
    }

    if (!generated.length) {
      showStatusMessage("No GIFs were generated.");
      return true;
    }

    if (generated.length === 1) {
      const one = generated[0];
      showStatusMessage(
        `Generated GIF (${one.aspectLabel}, ${one.frames} frames, ${frameDelayCs} cs).`,
      );
      return true;
    }

    showStatusMessage(
      mode === GIF_EXPORT_MODE_ALL_IN_ONE
        ? `Generated all-in-one GIF (${generated[0]?.frames || 0} frames, ${frameDelayCs} cs).`
        : `Generated ${generated.length} GIFs across aspect-ratio buckets.`,
    );
    return true;
  } catch {
    showStatusMessage("GIF generation failed.");
    return true;
  } finally {
    hideBusyOverlay();
  }
}

async function generateGifBucketsForFolder(dirNode, options = {}) {
  if (!dirNode) return false;
  const orderedRecords = collectOrderedMediaRecordsForDirRecursive(dirNode, []);
  const outputLabel =
    dirDisplayName(dirNode) || String(dirNode?.name || "folder");
  return await generateGifBucketsForRecordSet(orderedRecords, {
    sourceLabel: "this folder tree",
    outputLabel,
    emptyStatus: "No media files found in this folder tree.",
    mode: options?.mode,
    order: options?.order,
    frameDelayCs: options?.frameDelayCs,
  });
}

async function generateGifBucketsForFolderSelection(paths, options = {}) {
  const dirNodes = resolveOrderedUniqueDirNodesForPaths(paths);
  if (!dirNodes.length) {
    showStatusMessage("No folders selected.");
    return true;
  }
  const orderedRecords =
    collectOrderedMediaRecordsForDirNodesRecursive(dirNodes);
  const outputLabel =
    dirNodes.length === 1
      ? dirDisplayName(dirNodes[0]) || String(dirNodes[0]?.name || "folder")
      : `selected_folders_${dirNodes.length}`;
  return await generateGifBucketsForRecordSet(orderedRecords, {
    sourceLabel: "selected folders",
    outputLabel,
    emptyStatus: "No media files found in selected folders.",
    mode: options?.mode,
    order: options?.order,
    frameDelayCs: options?.frameDelayCs,
  });
}

async function runFolderActionFromMenu(action, dirNode, options = {}) {
  const node = dirNode || null;
  const p = String(node?.path || "");
  const isRootNode = !!node && node === WS.root;
  if (!node || (!p && !isRootNode) || !action) return false;
  if (action === "move-to-trash") {
    if (isRootNode || !p || isPathInsideInternalTrash(p)) return true;
    await moveFolderPathsToTrash([p]);
    return true;
  }
  if (action === "put-back") {
    if (!isPutBackEligibleTrashPath(p)) return true;
    await putBackTrashFolderPaths([p]);
    return true;
  }
  if (action === "tag") {
    TAG_EDIT_PATH = p;
    RENAME_EDIT_PATH = null;
    selectDirectoryEntryByPath(p);
    renderDirectoriesPane(true);
    focusSelectedDirectoryInlineInput(".tagEditInput");
    return true;
  }
  if (action === "rename") {
    if (!WS.meta.fsRootHandle) {
      showStatusMessage("Rename requires a writable folder.");
      return true;
    }
    RENAME_EDIT_PATH = p;
    TAG_EDIT_PATH = null;
    selectDirectoryEntryByPath(p);
    renderDirectoriesPane(true);
    focusSelectedDirectoryInlineInput(".renameEditInput");
    return true;
  }
  if (action === "batch-index") {
    if (!WS.meta.fsRootHandle) {
      showStatusMessage("Renaming files requires a writable folder.");
      return true;
    }
    batchIndexFolderFiles(node);
    return true;
  }
  if (action === "reset-order") {
    resetDirFileOrder(node, {
      silent: node !== WS.nav.dirNode,
      selectId: null,
    });
    if (node !== WS.nav.dirNode) showStatusMessage("Order reset.");
    return true;
  }
  if (action === "generate-gif") {
    await generateGifBucketsForFolder(node, options);
    return true;
  }
  if (action === "favorite") {
    metaToggleFavorite(p);
    return true;
  }
  if (action === "hidden") {
    metaToggleHidden(p);
    return true;
  }
  if (action === "appearance-preset-clear") {
    if (isRootNode) return true;
    if (!metaClearFolderAppearancePreset(p)) return true;
    refreshAfterProcessingMetadataChange();
    showStatusMessage("Folder media preset reset to inherited.");
    return true;
  }
  if (
    action === "thumbnail-random" ||
    action === "thumbnail-rotate" ||
    action === "thumbnail-quad"
  ) {
    const changed = setRandomFolderThumbnailForNode(node);
    if (!changed) {
      showStatusMessage(
        isRootNode
          ? "No media files available for a random root thumbnail."
          : "No media files available for a random folder thumbnail.",
      );
      return true;
    }
    refreshThumbnailUiAfterMetadataChange();
    showStatusMessage(
      isRootNode
        ? "Root thumbnail set to a random file."
        : "Folder thumbnail set to a random file.",
    );
    return true;
  }
  if (action === "thumbnail-default") {
    const changed = isRootNode
      ? resetRootThumbnailToDefault()
      : metaClearFolderThumbnailPreset(p);
    if (!changed) return true;
    renderDirectoriesPane(true);
    renderPreviewPane(false, true);
    syncButtons();
    kickVideoThumbsForPreview();
    kickImageThumbsForPreview();
    showStatusMessage(
      isRootNode
        ? "Root thumbnail reset to default."
        : "Folder thumbnail reset to default.",
    );
    return true;
  }
  if (action === "thumbnail-none") {
    const changed = isRootNode
      ? setRootThumbnailMode("none")
      : metaSetFolderThumbnailNone(p);
    if (!changed) return true;
    refreshThumbnailUiAfterMetadataChange();
    showStatusMessage(
      isRootNode ? "Root thumbnail removed." : "Folder thumbnail removed.",
    );
    return true;
  }
  if (action === "score-up") {
    metaBumpScore(p, 1);
    return true;
  }
  if (action === "score-down") {
    metaBumpScore(p, -1);
    return true;
  }
  return false;
}

function getPreviewFolderMenuSelectionPaths(anchorPath) {
  const p = String(anchorPath || "");
  if (!p) return [];
  const selected = getSelectedPathsInCurrentDir();
  const canUseSelection =
    WS.view.bulkSelectMode && selected.length && selected.includes(p);
  if (!canUseSelection) return [p];
  const unique = Array.from(
    new Set(selected.map((v) => String(v || "")).filter(Boolean)),
  );
  return unique.length ? unique : [p];
}

function shouldUsePreviewBulkFolderMenu(anchorPath) {
  const selectedPaths = getPreviewFolderMenuSelectionPaths(anchorPath);
  return !!(
    WS.view.bulkSelectMode &&
    selectedPaths.length > 1 &&
    selectedPaths.includes(String(anchorPath || ""))
  );
}

